-- 1: Hello and goodbye
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-01', 'Hello and goodbye', '👋', 'Saludar y despedirse', 1, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"hello","translation":"hola","translations":{"es":"hola"}},{"id":"2","word":"hi","translation":"hola (informal)","translations":{"es":"hola (informal)"}},{"id":"3","word":"good morning","translation":"buenos días","translations":{"es":"buenos días"}},{"id":"4","word":"good afternoon","translation":"buenas tardes","translations":{"es":"buenas tardes"}},{"id":"5","word":"good evening","translation":"buenas noches (al saludar)","translations":{"es":"buenas noches (al saludar)"}},{"id":"6","word":"good night","translation":"buenas noches (al despedirse)","translations":{"es":"buenas noches (al despedirse)"}},{"id":"7","word":"goodbye","translation":"adiós","translations":{"es":"adiós"}},{"id":"8","word":"bye","translation":"chao / adiós (informal)","translations":{"es":"chao / adiós (informal)"}},{"id":"9","word":"see you later","translation":"hasta luego","translations":{"es":"hasta luego"}},{"id":"10","word":"see you tomorrow","translation":"hasta mañana","translations":{"es":"hasta mañana"}},{"id":"11","word":"take care","translation":"cuídate","translations":{"es":"cuídate"}},{"id":"12","word":"nice to meet you","translation":"mucho gusto","translations":{"es":"mucho gusto"}},{"id":"13","word":"fine","translation":"bien","translations":{"es":"bien"}},{"id":"14","word":"thanks","translation":"gracias","translations":{"es":"gracias"}},{"id":"15","word":"neighbor","translation":"vecino / vecina","translations":{"es":"vecino / vecina"}},{"id":"16","word":"name","translation":"nombre","translations":{"es":"nombre"}}],"grammar":[{"structure":"I am / you are","example":"I am Carmen. You are Linda.","en":"The verb \"to be\": I am, you are","es":"El verbo «to be» (ser/estar): I am, you are"},{"structure":"he is / she is","example":"She is my neighbor.","en":"\"To be\" with he and she","es":"«To be» con he (él) y she (ella)"},{"structure":"I''m / you''re / she''s","example":"I''m fine, thank you.","en":"Short forms (contractions) of \"to be\"","es":"Formas cortas (contracciones) de «to be»"},{"structure":"How are you?","example":"Hi, Linda! How are you?","en":"Asking how someone is","es":"Preguntar cómo está alguien"},{"structure":"Nice to meet you","example":"I''m Carmen. Nice to meet you.","en":"Meeting someone for the first time","es":"Conocer a alguien por primera vez"}],"tips":[{"en":"\"Hi\" is casual and \"hello\" is a little more formal. Both work almost everywhere in the United States.","es":"«Hi» es informal y «hello» un poco más formal. Los dos sirven casi en cualquier situación en Estados Unidos."},{"en":"\"How are you?\" is often just a greeting. A short answer like \"Good, thanks. And you?\" is perfect.","es":"«How are you?» muchas veces es solo un saludo. Una respuesta corta como «Good, thanks. And you?» es perfecta."},{"en":"\"Good night\" is only for saying goodbye at night or before bed. To greet someone in the evening, say \"Good evening\".","es":"«Good night» solo se usa para despedirse de noche o antes de dormir. Para saludar por la noche se dice «Good evening»."},{"en":"\"I\" is always written with a capital letter in English, even in the middle of a sentence.","es":"«I» (yo) siempre se escribe con mayúscula en inglés, incluso en medio de una oración."},{"en":"\"See you\" and \"Take care\" are friendly, everyday ways to say goodbye.","es":"«See you» y «Take care» son formas amables y cotidianas de despedirse."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"How are you?","translation":"¿Cómo estás?","translations":{"es":"¿Cómo estás?"}},{"phrase":"I''m fine, thank you.","translation":"Estoy bien, gracias.","translations":{"es":"Estoy bien, gracias."}},{"phrase":"And you?","translation":"¿Y tú?","translations":{"es":"¿Y tú?"}},{"phrase":"What''s your name?","translation":"¿Cómo te llamas?","translations":{"es":"¿Cómo te llamas?"}},{"phrase":"My name is Carmen.","translation":"Me llamo Carmen.","translations":{"es":"Me llamo Carmen."}},{"phrase":"Nice to meet you.","translation":"Mucho gusto.","translations":{"es":"Mucho gusto."}},{"phrase":"Nice to meet you too.","translation":"Igualmente, mucho gusto.","translations":{"es":"Igualmente, mucho gusto."}},{"phrase":"Have a nice day!","translation":"¡Que tengas un buen día!","translations":{"es":"¡Que tengas un buen día!"}},{"phrase":"See you later!","translation":"¡Hasta luego!","translations":{"es":"¡Hasta luego!"}},{"phrase":"How''s it going?","translation":"¿Qué tal?","translations":{"es":"¿Qué tal?"}},{"phrase":"Not bad, thanks.","translation":"Nada mal, gracias.","translations":{"es":"Nada mal, gracias."}},{"phrase":"Good night, sleep well.","translation":"Buenas noches, que descanses.","translations":{"es":"Buenas noches, que descanses."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"It''s 9 a.m. and you see your neighbor. What do you say?","options":["Good night!","Good evening!","Goodbye!","Good morning!"],"correct":3,"explanation":"In the morning we say \"Good morning\". \"Good night\" is only for saying goodbye at night.","translations":{"es":{"question":"Son las 9 de la mañana y ves a tu vecina. ¿Qué le dices?","explanation":"Por la mañana se dice «Good morning». «Good night» solo es para despedirse de noche."}}},{"id":"2","question":"Someone says \"How are you?\". What is a good answer?","options":["See you tomorrow.","Nice to meet you.","My name is Carmen.","I''m fine, thanks. And you?"],"correct":3,"explanation":"\"How are you?\" asks how you feel, so answer with \"I''m fine\" and ask back: \"And you?\"","translations":{"es":{"question":"Alguien te dice «How are you?». ¿Cuál es una buena respuesta?","explanation":"«How are you?» pregunta cómo estás, así que respondes «I''m fine» y devuelves la pregunta: «And you?»"}}},{"id":"3","question":"Choose the correct sentence.","options":["I are Carmen.","Me am Carmen.","I is Carmen.","I am Carmen."],"correct":3,"explanation":"With \"I\" the verb \"to be\" is always \"am\": I am.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"Con «I» (yo) el verbo «to be» siempre es «am»: I am."}}},{"id":"4","question":"You meet a person for the first time. What do you say?","options":["See you later.","Not bad.","Good night.","Nice to meet you."],"correct":3,"explanation":"\"Nice to meet you\" is what we say when we meet someone new.","translations":{"es":{"question":"Conoces a una persona por primera vez. ¿Qué dices?","explanation":"«Nice to meet you» es lo que se dice al conocer a alguien nuevo."}}},{"id":"5","question":"It''s 10 p.m. and you are going to bed. What do you say to your family?","options":["Hello!","Good morning!","Good afternoon!","Good night!"],"correct":3,"explanation":"Before going to bed we say \"Good night\".","translations":{"es":{"question":"Son las 10 de la noche y te vas a dormir. ¿Qué le dices a tu familia?","explanation":"Antes de dormir se dice «Good night»."}}},{"id":"6","question":"What is the short form of \"I am\"?","options":["I''r","Im","I''am","I''m"],"correct":3,"explanation":"The apostrophe replaces the letter \"a\": I am → I''m.","translations":{"es":{"question":"¿Cuál es la forma corta de «I am»?","explanation":"El apóstrofo reemplaza la letra «a»: I am → I''m."}}},{"id":"7","question":"Choose the correct sentence about Linda.","options":["She are my neighbor.","She be my neighbor.","She am my neighbor.","She is my neighbor."],"correct":3,"explanation":"With \"he\" and \"she\" the verb \"to be\" is \"is\".","translations":{"es":{"question":"Elige la oración correcta sobre Linda.","explanation":"Con «he» y «she» el verbo «to be» es «is»."}}},{"id":"8","question":"Which one is a friendly way to say goodbye?","options":["Nice to meet you.","Good morning!","How are you?","Take care!"],"correct":3,"explanation":"\"Take care\" means you wish the other person well when you leave.","translations":{"es":{"question":"¿Cuál es una forma amable de despedirse?","explanation":"«Take care» significa que le deseas lo mejor a la otra persona al despedirte."}}}]}'::jsonb, 3),
  ('story', 'A New Neighbor', '{"text":"Carmen is from Guadalajara, Mexico. Today she is in San Diego. Her daughter Laura lives here. It is eight in the morning, and Carmen is outside with her coffee. A woman opens the door of the next house. \"Good morning!\" says the woman. \"Hello! Good morning,\" says Carmen. \"I''m Linda. I''m your neighbor.\" \"Nice to meet you, Linda. My name is Carmen.\" \"Nice to meet you too, Carmen. How are you?\" \"I''m fine, thank you. And you?\" \"Very well, thanks. Welcome to San Diego!\" Carmen smiles. Her English is not perfect, but she is happy. Linda is nice. \"Have a nice day, Carmen!\" \"Thank you, Linda. See you later!\"","translation":"Carmen es de Guadalajara, México. Hoy está en San Diego. Su hija Laura vive aquí. Son las ocho de la mañana y Carmen está afuera con su café. Una mujer abre la puerta de la casa de al lado. «¡Buenos días!», dice la mujer. «¡Hola! Buenos días», dice Carmen. «Soy Linda. Soy tu vecina.» «Mucho gusto, Linda. Me llamo Carmen.» «Igualmente, Carmen. ¿Cómo estás?» «Estoy bien, gracias. ¿Y tú?» «Muy bien, gracias. ¡Bienvenida a San Diego!» Carmen sonríe. Su inglés no es perfecto, pero está feliz. Linda es amable. «¡Que tengas un buen día, Carmen!» «Gracias, Linda. ¡Hasta luego!»","translations":{"es":"Carmen es de Guadalajara, México. Hoy está en San Diego. Su hija Laura vive aquí. Son las ocho de la mañana y Carmen está afuera con su café. Una mujer abre la puerta de la casa de al lado. «¡Buenos días!», dice la mujer. «¡Hola! Buenos días», dice Carmen. «Soy Linda. Soy tu vecina.» «Mucho gusto, Linda. Me llamo Carmen.» «Igualmente, Carmen. ¿Cómo estás?» «Estoy bien, gracias. ¿Y tú?» «Muy bien, gracias. ¡Bienvenida a San Diego!» Carmen sonríe. Su inglés no es perfecto, pero está feliz. Linda es amable. «¡Que tengas un buen día, Carmen!» «Gracias, Linda. ¡Hasta luego!»"},"highlighted_words":["Good morning","Hello","neighbor","Nice to meet you","How are you","I''m fine","See you later"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["My","name","is","Carmen"],"translation":"Me llamo Carmen.","translations":{"es":"Me llamo Carmen."}},{"words":["How","are","you","today"],"translation":"¿Cómo estás hoy?","translations":{"es":"¿Cómo estás hoy?"}},{"words":["She","is","my","neighbor"],"translation":"Ella es mi vecina.","translations":{"es":"Ella es mi vecina."}},{"words":["Nice","to","meet","you","too"],"translation":"Igualmente, mucho gusto.","translations":{"es":"Igualmente, mucho gusto."}},{"words":["I","am","fine","thank","you"],"translation":"Estoy bien, gracias.","translations":{"es":"Estoy bien, gracias."}},{"words":["See","you","tomorrow","Linda"],"translation":"Hasta mañana, Linda.","translations":{"es":"Hasta mañana, Linda."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Buenos días","translations":{"es":"Buenos días"},"answer":"Good morning"},{"prompt":"Me llamo Carmen","translations":{"es":"Me llamo Carmen"},"answer":"My name is Carmen"},{"prompt":"Mucho gusto","translations":{"es":"Mucho gusto"},"answer":"Nice to meet you"},{"prompt":"Estoy bien, gracias","translations":{"es":"Estoy bien, gracias"},"answer":"I am fine, thank you"},{"prompt":"Ella es mi vecina","translations":{"es":"Ella es mi vecina"},"answer":"She is my neighbor"},{"prompt":"Hasta mañana","translations":{"es":"Hasta mañana"},"answer":"See you tomorrow"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 2: Please and thank you
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-02', 'Please and thank you', '🙏', 'Por favor y gracias', 2, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"please","translation":"por favor","translations":{"es":"por favor"}},{"id":"2","word":"thank you","translation":"gracias","translations":{"es":"gracias"}},{"id":"3","word":"thank you very much","translation":"muchas gracias","translations":{"es":"muchas gracias"}},{"id":"4","word":"you''re welcome","translation":"de nada","translations":{"es":"de nada"}},{"id":"5","word":"no problem","translation":"no hay problema","translations":{"es":"no hay problema"}},{"id":"6","word":"excuse me","translation":"disculpe / con permiso","translations":{"es":"disculpe / con permiso"}},{"id":"7","word":"sorry","translation":"perdón / lo siento","translations":{"es":"perdón / lo siento"}},{"id":"8","word":"of course","translation":"claro / por supuesto","translations":{"es":"claro / por supuesto"}},{"id":"9","word":"sure","translation":"claro / seguro","translations":{"es":"claro / seguro"}},{"id":"10","word":"yes","translation":"sí","translations":{"es":"sí"}},{"id":"11","word":"no","translation":"no","translations":{"es":"no"}},{"id":"12","word":"a coffee","translation":"un café","translations":{"es":"un café"}},{"id":"13","word":"a glass of water","translation":"un vaso de agua","translations":{"es":"un vaso de agua"}},{"id":"14","word":"slowly","translation":"despacio","translations":{"es":"despacio"}},{"id":"15","word":"again","translation":"otra vez / de nuevo","translations":{"es":"otra vez / de nuevo"}},{"id":"16","word":"help","translation":"ayuda / ayudar","translations":{"es":"ayuda / ayudar"}}],"grammar":[{"structure":"Can I…?","example":"Can I have a coffee, please?","en":"Asking for something with \"Can I…?\"","es":"Pedir algo con «Can I…?» (¿Puedo…?)"},{"structure":"Could you…?","example":"Could you repeat that, please?","en":"Polite requests with \"Could you…?\"","es":"Pedidos amables con «Could you…?» (¿Podría…?)"},{"structure":"please at the end","example":"A glass of water, please.","en":"\"Please\" usually goes at the end","es":"«Please» suele ir al final"},{"structure":"Excuse me / Sorry","example":"Excuse me, is this seat free?","en":"Getting attention vs. apologizing","es":"Llamar la atención vs. pedir perdón"},{"structure":"You''re welcome","example":"Thank you! — You''re welcome.","en":"Answering \"thank you\"","es":"Responder a «thank you»"}],"tips":[{"en":"Americans say \"please\" and \"thank you\" a lot, even in quick situations like buying a coffee.","es":"En Estados Unidos se dice mucho «please» y «thank you», incluso en situaciones rápidas como comprar un café."},{"en":"Use \"Excuse me\" before asking a stranger something, and \"Sorry\" when you make a small mistake or bump into someone.","es":"Usa «Excuse me» antes de preguntarle algo a un desconocido, y «Sorry» cuando cometes un pequeño error o chocas con alguien."},{"en":"\"No problem\" and \"Sure\" are very common, relaxed answers to \"thank you\".","es":"«No problem» y «Sure» son respuestas muy comunes y relajadas a «thank you»."},{"en":"If you don''t understand, say \"Sorry?\" or \"Could you repeat that, please?\" — people are used to it.","es":"Si no entiendes, di «Sorry?» o «Could you repeat that, please?»: la gente está acostumbrada."},{"en":"\"Could you…?\" sounds more polite than \"Can you…?\". Use it with people you don''t know.","es":"«Could you…?» suena más amable que «Can you…?». Úsalo con personas que no conoces."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Can I have a coffee, please?","translation":"¿Me da un café, por favor?","translations":{"es":"¿Me da un café, por favor?"}},{"phrase":"Here you go.","translation":"Aquí tiene.","translations":{"es":"Aquí tiene."}},{"phrase":"Thank you very much!","translation":"¡Muchas gracias!","translations":{"es":"¡Muchas gracias!"}},{"phrase":"You''re welcome.","translation":"De nada.","translations":{"es":"De nada."}},{"phrase":"Excuse me, can you help me?","translation":"Disculpe, ¿me puede ayudar?","translations":{"es":"Disculpe, ¿me puede ayudar?"}},{"phrase":"Could you repeat that, please?","translation":"¿Podría repetirlo, por favor?","translations":{"es":"¿Podría repetirlo, por favor?"}},{"phrase":"Could you speak more slowly?","translation":"¿Podría hablar más despacio?","translations":{"es":"¿Podría hablar más despacio?"}},{"phrase":"Sorry, I don''t understand.","translation":"Perdón, no entiendo.","translations":{"es":"Perdón, no entiendo."}},{"phrase":"I''m sorry, I''m late.","translation":"Perdón, llego tarde.","translations":{"es":"Perdón, llego tarde."}},{"phrase":"No problem!","translation":"¡No hay problema!","translations":{"es":"¡No hay problema!"}},{"phrase":"Yes, please.","translation":"Sí, por favor.","translations":{"es":"Sí, por favor."}},{"phrase":"No, thank you.","translation":"No, gracias.","translations":{"es":"No, gracias."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"The cashier gives you your change. What do you say?","options":["Excuse me!","Thank you!","Sorry!","You''re welcome!"],"correct":1,"explanation":"When someone gives you something, you say \"Thank you\".","translations":{"es":{"question":"El cajero te da tu cambio. ¿Qué dices?","explanation":"Cuando alguien te da algo, dices «Thank you»."}}},{"id":"2","question":"Someone says \"Thank you!\" to you. What do you answer?","options":["You''re welcome.","Excuse me.","Please.","Thank you."],"correct":0,"explanation":"\"You''re welcome\" is the usual answer to \"thank you\". \"No problem\" also works.","translations":{"es":{"question":"Alguien te dice «Thank you!». ¿Qué respondes?","explanation":"«You''re welcome» es la respuesta habitual a «thank you». «No problem» también sirve."}}},{"id":"3","question":"You want to ask a stranger a question. How do you start?","options":["Good night…","Excuse me…","Bye…","You''re welcome…"],"correct":1,"explanation":"\"Excuse me\" is the polite way to get someone''s attention.","translations":{"es":{"question":"Quieres hacerle una pregunta a un desconocido. ¿Cómo empiezas?","explanation":"«Excuse me» es la forma amable de llamar la atención de alguien."}}},{"id":"4","question":"You step on someone''s foot by accident. What do you say?","options":["Of course!","Sorry!","You''re welcome!","Please!"],"correct":1,"explanation":"\"Sorry\" is for apologizing after a small mistake.","translations":{"es":{"question":"Pisas a alguien sin querer. ¿Qué dices?","explanation":"«Sorry» es para pedir perdón después de un pequeño error."}}},{"id":"5","question":"The person speaks very fast. What can you say?","options":["Could you speak more slowly, please?","Speak, thank you.","You speak slowly, please.","Could you speak more fast, please?"],"correct":0,"explanation":"\"Could you speak more slowly, please?\" is a polite request.","translations":{"es":{"question":"La persona habla muy rápido. ¿Qué puedes decir?","explanation":"«Could you speak more slowly, please?» es un pedido amable."}}},{"id":"6","question":"Where does \"please\" usually go?","options":["Can I have water, please?","Can I please water have?","Can please I have water?","Please can water I have?"],"correct":0,"explanation":"\"Please\" usually goes at the end of the request.","translations":{"es":{"question":"¿Dónde va normalmente «please»?","explanation":"«Please» normalmente va al final del pedido."}}},{"id":"7","question":"A waiter asks: \"More coffee?\" You want more. What do you say?","options":["Sorry, yes.","No, please.","Yes, please.","Yes, you''re welcome."],"correct":2,"explanation":"To accept something offered, say \"Yes, please\". To refuse, \"No, thank you\".","translations":{"es":{"question":"Un mesero pregunta: «More coffee?». Quieres más. ¿Qué dices?","explanation":"Para aceptar algo que te ofrecen, di «Yes, please». Para rechazarlo, «No, thank you»."}}},{"id":"8","question":"Which request is the most polite?","options":["You help me.","Help, now.","Could you help me, please?","Help me."],"correct":2,"explanation":"\"Could you…, please?\" is very polite.","translations":{"es":{"question":"¿Qué pedido es el más amable?","explanation":"«Could you…, please?» es muy amable."}}}]}'::jsonb, 3),
  ('story', 'Coffee, Please', '{"text":"Carmen is at a small coffee shop near Laura''s house. There are many people. A young man is at the counter. \"Hi! What can I get you?\" he asks. Carmen is a little nervous. \"Hello. Can I have a coffee, please?\" \"Sure! Small, medium or large?\" Carmen doesn''t understand. \"Sorry? Could you repeat that, please?\" The young man smiles and speaks slowly. \"Small… medium… or large?\" \"Oh! Small, please.\" \"Of course. That''s three dollars.\" Carmen gives him the money. \"Here you go. Thank you very much!\" \"You''re welcome. Have a nice day!\" Carmen sits by the window with her coffee. It is a small coffee, but it is a big success.","translation":"Carmen está en una pequeña cafetería cerca de la casa de Laura. Hay mucha gente. Un joven está en el mostrador. «¡Hola! ¿Qué le sirvo?», pregunta. Carmen está un poco nerviosa. «Hola. ¿Me da un café, por favor?» «¡Claro! ¿Pequeño, mediano o grande?» Carmen no entiende. «¿Perdón? ¿Podría repetirlo, por favor?» El joven sonríe y habla despacio. «Pequeño… mediano… ¿o grande?» «¡Ah! Pequeño, por favor.» «Por supuesto. Son tres dólares.» Carmen le da el dinero. «Aquí tiene. ¡Muchas gracias!» «De nada. ¡Que tenga un buen día!» Carmen se sienta junto a la ventana con su café. Es un café pequeño, pero es un gran éxito.","translations":{"es":"Carmen está en una pequeña cafetería cerca de la casa de Laura. Hay mucha gente. Un joven está en el mostrador. «¡Hola! ¿Qué le sirvo?», pregunta. Carmen está un poco nerviosa. «Hola. ¿Me da un café, por favor?» «¡Claro! ¿Pequeño, mediano o grande?» Carmen no entiende. «¿Perdón? ¿Podría repetirlo, por favor?» El joven sonríe y habla despacio. «Pequeño… mediano… ¿o grande?» «¡Ah! Pequeño, por favor.» «Por supuesto. Son tres dólares.» Carmen le da el dinero. «Aquí tiene. ¡Muchas gracias!» «De nada. ¡Que tenga un buen día!» Carmen se sienta junto a la ventana con su café. Es un café pequeño, pero es un gran éxito."},"highlighted_words":["Can I have a coffee, please","Sure","Sorry","Could you repeat that, please","Of course","Here you go","Thank you very much","You''re welcome"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Can","I","have","a","coffee","please"],"translation":"¿Me da un café, por favor?","translations":{"es":"¿Me da un café, por favor?"}},{"words":["Could","you","repeat","that","please"],"translation":"¿Podría repetirlo, por favor?","translations":{"es":"¿Podría repetirlo, por favor?"}},{"words":["Thank","you","very","much"],"translation":"Muchas gracias.","translations":{"es":"Muchas gracias."}},{"words":["Excuse","me","can","you","help","me"],"translation":"Disculpe, ¿me puede ayudar?","translations":{"es":"Disculpe, ¿me puede ayudar?"}},{"words":["Sorry","I","do","not","understand"],"translation":"Perdón, no entiendo.","translations":{"es":"Perdón, no entiendo."}},{"words":["Could","you","speak","more","slowly"],"translation":"¿Podría hablar más despacio?","translations":{"es":"¿Podría hablar más despacio?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Muchas gracias","translations":{"es":"Muchas gracias"},"answer":"Thank you very much"},{"prompt":"Disculpe","translations":{"es":"Disculpe"},"answer":"Excuse me"},{"prompt":"¿Me da un café, por favor?","translations":{"es":"¿Me da un café, por favor?"},"answer":"Can I have a coffee, please"},{"prompt":"Sí, por favor","translations":{"es":"Sí, por favor"},"answer":"Yes, please"},{"prompt":"No, gracias","translations":{"es":"No, gracias"},"answer":"No, thank you"},{"prompt":"¿Podría ayudarme, por favor?","translations":{"es":"¿Podría ayudarme, por favor?"},"answer":"Could you help me, please"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 3: Days, months and dates
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
