insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"Monday","translation":"lunes","translations":{"es":"lunes"}},{"id":"2","word":"Tuesday","translation":"martes","translations":{"es":"martes"}},{"id":"3","word":"Wednesday","translation":"miércoles","translations":{"es":"miércoles"}},{"id":"4","word":"Thursday","translation":"jueves","translations":{"es":"jueves"}},{"id":"5","word":"Friday","translation":"viernes","translations":{"es":"viernes"}},{"id":"6","word":"Saturday","translation":"sábado","translations":{"es":"sábado"}},{"id":"7","word":"Sunday","translation":"domingo","translations":{"es":"domingo"}},{"id":"8","word":"January","translation":"enero","translations":{"es":"enero"}},{"id":"9","word":"February","translation":"febrero","translations":{"es":"febrero"}},{"id":"10","word":"March","translation":"marzo","translations":{"es":"marzo"}},{"id":"11","word":"April","translation":"abril","translations":{"es":"abril"}},{"id":"12","word":"May","translation":"mayo","translations":{"es":"mayo"}},{"id":"13","word":"June","translation":"junio","translations":{"es":"junio"}},{"id":"14","word":"July","translation":"julio","translations":{"es":"julio"}},{"id":"15","word":"August","translation":"agosto","translations":{"es":"agosto"}},{"id":"16","word":"September","translation":"septiembre","translations":{"es":"septiembre"}},{"id":"17","word":"October","translation":"octubre","translations":{"es":"octubre"}},{"id":"18","word":"November","translation":"noviembre","translations":{"es":"noviembre"}},{"id":"19","word":"December","translation":"diciembre","translations":{"es":"diciembre"}},{"id":"20","word":"today","translation":"hoy","translations":{"es":"hoy"}},{"id":"21","word":"tomorrow","translation":"mañana","translations":{"es":"mañana"}},{"id":"22","word":"yesterday","translation":"ayer","translations":{"es":"ayer"}},{"id":"23","word":"weekend","translation":"fin de semana","translations":{"es":"fin de semana"}},{"id":"24","word":"birthday","translation":"cumpleaños","translations":{"es":"cumpleaños"}}],"grammar":[{"structure":"on + day / date","example":"My class is on Monday. Leo''s birthday is on May 12th.","en":"\"On\" with days and dates","es":"«On» con días y fechas"},{"structure":"in + month / year","example":"Laura''s birthday is in October.","en":"\"In\" with months and years","es":"«In» con meses y años"},{"structure":"Capital letters","example":"Monday, Tuesday, January, February","en":"Days and months always start with a capital letter","es":"Los días y los meses siempre empiezan con mayúscula"},{"structure":"first, second, third…","example":"Today is the third of June.","en":"Ordinal numbers for dates","es":"Números ordinales para las fechas"},{"structure":"What day is today?","example":"What day is today? — It''s Friday.","en":"Asking about the day and the date","es":"Preguntar el día y la fecha"}],"tips":[{"en":"In the US, dates are written month first: 5/12 means May 12th, not December 5th.","es":"En Estados Unidos las fechas se escriben con el mes primero: 5/12 significa 12 de mayo, no 5 de diciembre."},{"en":"Americans say \"May twelfth\" or \"May twelve\". Both are common in conversation.","es":"En Estados Unidos se dice «May twelfth» o «May twelve». Las dos formas son comunes al hablar."},{"en":"The week usually starts on Sunday on American calendars.","es":"En los calendarios estadounidenses la semana suele empezar el domingo."},{"en":"\"The weekend\" is Saturday and Sunday. \"Weekdays\" are Monday to Friday.","es":"«The weekend» es sábado y domingo. Los «weekdays» son de lunes a viernes."},{"en":"Don''t forget: on Monday, in May, in 2025.","es":"No lo olvides: on Monday, in May, in 2025."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What day is today?","translation":"¿Qué día es hoy?","translations":{"es":"¿Qué día es hoy?"}},{"phrase":"Today is Monday.","translation":"Hoy es lunes.","translations":{"es":"Hoy es lunes."}},{"phrase":"What''s the date today?","translation":"¿Qué fecha es hoy?","translations":{"es":"¿Qué fecha es hoy?"}},{"phrase":"It''s the third of June.","translation":"Es tres de junio.","translations":{"es":"Es tres de junio."}},{"phrase":"When is your birthday?","translation":"¿Cuándo es tu cumpleaños?","translations":{"es":"¿Cuándo es tu cumpleaños?"}},{"phrase":"My birthday is in October.","translation":"Mi cumpleaños es en octubre.","translations":{"es":"Mi cumpleaños es en octubre."}},{"phrase":"See you on Friday!","translation":"¡Nos vemos el viernes!","translations":{"es":"¡Nos vemos el viernes!"}},{"phrase":"Have a nice weekend!","translation":"¡Que tengas un buen fin de semana!","translations":{"es":"¡Que tengas un buen fin de semana!"}},{"phrase":"Happy birthday!","translation":"¡Feliz cumpleaños!","translations":{"es":"¡Feliz cumpleaños!"}},{"phrase":"I''m free on Saturday.","translation":"Estoy libre el sábado.","translations":{"es":"Estoy libre el sábado."}},{"phrase":"Next week.","translation":"La próxima semana.","translations":{"es":"La próxima semana."}},{"phrase":"Every Sunday.","translation":"Todos los domingos.","translations":{"es":"Todos los domingos."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"My class is ___ Monday.\"","options":["at","on","in","of"],"correct":1,"explanation":"We use \"on\" with days: on Monday, on Friday.","translations":{"es":{"question":"Completa: «My class is ___ Monday.»","explanation":"Con los días se usa «on»: on Monday, on Friday."}}},{"id":"2","question":"Complete: \"Her birthday is ___ October.\"","options":["in","on","at","to"],"correct":0,"explanation":"We use \"in\" with months: in October.","translations":{"es":{"question":"Completa: «Her birthday is ___ October.»","explanation":"Con los meses se usa «in»: in October."}}},{"id":"3","question":"Which day comes after Tuesday?","options":["Monday","Wednesday","Thursday","Sunday"],"correct":1,"explanation":"Monday, Tuesday, Wednesday, Thursday…","translations":{"es":{"question":"¿Qué día viene después de Tuesday?","explanation":"Monday, Tuesday, Wednesday, Thursday…"}}},{"id":"4","question":"In the US, what does 7/4 mean?","options":["April 7th","July 4th","July 7th","April 4th"],"correct":1,"explanation":"American dates put the month first: 7/4 is July 4th, Independence Day.","translations":{"es":{"question":"En Estados Unidos, ¿qué significa 7/4?","explanation":"Las fechas estadounidenses ponen el mes primero: 7/4 es el 4 de julio, el Día de la Independencia."}}},{"id":"5","question":"Which one is written correctly?","options":["Friday, march 3rd","friday, march 3rd","Friday, March 3rd","friday, March 3rd"],"correct":2,"explanation":"Days and months always have a capital letter in English.","translations":{"es":{"question":"¿Cuál está bien escrito?","explanation":"En inglés los días y los meses siempre llevan mayúscula."}}},{"id":"6","question":"What is \"the weekend\"?","options":["Only Friday","Monday to Friday","Saturday and Sunday","Only Sunday"],"correct":2,"explanation":"The weekend is Saturday and Sunday.","translations":{"es":{"question":"¿Qué es «the weekend»?","explanation":"El fin de semana es sábado y domingo."}}},{"id":"7","question":"Today is Thursday. What day was yesterday?","options":["Friday","Tuesday","Wednesday","Saturday"],"correct":2,"explanation":"Yesterday is the day before today: Wednesday comes before Thursday.","translations":{"es":{"question":"Hoy es jueves. ¿Qué día fue ayer?","explanation":"Ayer es el día anterior a hoy: Wednesday va antes de Thursday."}}},{"id":"8","question":"It''s your friend''s birthday. What do you say?","options":["Nice birthday!","Good birthday!","Happy birthday!","Have a birthday!"],"correct":2,"explanation":"We say \"Happy birthday!\"","translations":{"es":{"question":"Es el cumpleaños de tu amiga. ¿Qué le dices?","explanation":"Se dice «Happy birthday!»"}}}]}'::jsonb, 3),
  ('story', 'A Busy Calendar', '{"text":"It is Sunday evening. Carmen and Laura are in the kitchen with a big calendar. \"Mom, what day is today?\" asks Laura. \"Today is Sunday, the third of May.\" \"Okay. Your English class is on Monday and Wednesday. On Tuesday you are with Leo after school.\" Carmen writes everything in Spanish and in English. \"And Friday?\" \"Friday is free. On Saturday we have a party.\" \"A party? Why?\" Laura laughs. \"Mom! Leo''s birthday is on May ninth!\" \"Of course! My grandson is eight years old!\" Carmen looks at the calendar again. May is a busy month, but it is a happy month too.","translation":"Es domingo por la noche. Carmen y Laura están en la cocina con un calendario grande. «Mamá, ¿qué día es hoy?», pregunta Laura. «Hoy es domingo, tres de mayo.» «Bueno. Tu clase de inglés es el lunes y el miércoles. El martes estás con Leo después de la escuela.» Carmen lo escribe todo en español y en inglés. «¿Y el viernes?» «El viernes está libre. El sábado tenemos una fiesta.» «¿Una fiesta? ¿Por qué?» Laura se ríe. «¡Mamá! ¡El cumpleaños de Leo es el nueve de mayo!» «¡Claro! ¡Mi nieto cumple ocho años!» Carmen vuelve a mirar el calendario. Mayo es un mes muy ocupado, pero también es un mes feliz.","translations":{"es":"Es domingo por la noche. Carmen y Laura están en la cocina con un calendario grande. «Mamá, ¿qué día es hoy?», pregunta Laura. «Hoy es domingo, tres de mayo.» «Bueno. Tu clase de inglés es el lunes y el miércoles. El martes estás con Leo después de la escuela.» Carmen lo escribe todo en español y en inglés. «¿Y el viernes?» «El viernes está libre. El sábado tenemos una fiesta.» «¿Una fiesta? ¿Por qué?» Laura se ríe. «¡Mamá! ¡El cumpleaños de Leo es el nueve de mayo!» «¡Claro! ¡Mi nieto cumple ocho años!» Carmen vuelve a mirar el calendario. Mayo es un mes muy ocupado, pero también es un mes feliz."},"highlighted_words":["Sunday","what day is today","on Monday","Tuesday","Friday","Saturday","birthday","May"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["My","class","is","on","Monday"],"translation":"Mi clase es el lunes.","translations":{"es":"Mi clase es el lunes."}},{"words":["Her","birthday","is","in","October"],"translation":"Su cumpleaños es en octubre.","translations":{"es":"Su cumpleaños es en octubre."}},{"words":["What","day","is","today"],"translation":"¿Qué día es hoy?","translations":{"es":"¿Qué día es hoy?"}},{"words":["I","am","free","on","Saturday"],"translation":"Estoy libre el sábado.","translations":{"es":"Estoy libre el sábado."}},{"words":["Have","a","nice","weekend"],"translation":"Que tengas un buen fin de semana.","translations":{"es":"Que tengas un buen fin de semana."}},{"words":["Today","is","the","third","of","June"],"translation":"Hoy es tres de junio.","translations":{"es":"Hoy es tres de junio."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Hoy es viernes","translations":{"es":"Hoy es viernes"},"answer":"Today is Friday"},{"prompt":"Feliz cumpleaños","translations":{"es":"Feliz cumpleaños"},"answer":"Happy birthday"},{"prompt":"Nos vemos el lunes","translations":{"es":"Nos vemos el lunes"},"answer":"See you on Monday"},{"prompt":"Mi cumpleaños es en mayo","translations":{"es":"Mi cumpleaños es en mayo"},"answer":"My birthday is in May"},{"prompt":"¿Qué día es hoy?","translations":{"es":"¿Qué día es hoy?"},"answer":"What day is today"},{"prompt":"Estoy libre mañana","translations":{"es":"Estoy libre mañana"},"answer":"I am free tomorrow"}]}'::jsonb, 6)
) as v(type, title, content, ord);

