insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"zero","translation":"cero","translations":{"es":"cero"}},{"id":"2","word":"one","translation":"uno","translations":{"es":"uno"}},{"id":"3","word":"two","translation":"dos","translations":{"es":"dos"}},{"id":"4","word":"three","translation":"tres","translations":{"es":"tres"}},{"id":"5","word":"four","translation":"cuatro","translations":{"es":"cuatro"}},{"id":"6","word":"five","translation":"cinco","translations":{"es":"cinco"}},{"id":"7","word":"six","translation":"seis","translations":{"es":"seis"}},{"id":"8","word":"seven","translation":"siete","translations":{"es":"siete"}},{"id":"9","word":"eight","translation":"ocho","translations":{"es":"ocho"}},{"id":"10","word":"nine","translation":"nueve","translations":{"es":"nueve"}},{"id":"11","word":"ten","translation":"diez","translations":{"es":"diez"}},{"id":"12","word":"eleven","translation":"once","translations":{"es":"once"}},{"id":"13","word":"twelve","translation":"doce","translations":{"es":"doce"}},{"id":"14","word":"fifteen","translation":"quince","translations":{"es":"quince"}},{"id":"15","word":"twenty","translation":"veinte","translations":{"es":"veinte"}},{"id":"16","word":"thirty","translation":"treinta","translations":{"es":"treinta"}},{"id":"17","word":"fifty","translation":"cincuenta","translations":{"es":"cincuenta"}},{"id":"18","word":"one hundred","translation":"cien","translations":{"es":"cien"}},{"id":"19","word":"one thousand","translation":"mil","translations":{"es":"mil"}},{"id":"20","word":"phone number","translation":"número de teléfono","translations":{"es":"número de teléfono"}},{"id":"21","word":"address","translation":"dirección","translations":{"es":"dirección"}},{"id":"22","word":"dollar","translation":"dólar","translations":{"es":"dólar"}}],"grammar":[{"structure":"one, two, three…","example":"I have two children.","en":"Cardinal numbers","es":"Números cardinales"},{"structure":"noun + s (plural)","example":"one book, three books","en":"Regular plurals add -s","es":"Los plurales regulares agregan -s"},{"structure":"How many…?","example":"How many brothers do you have?","en":"Asking about quantity","es":"Preguntar por cantidades"},{"structure":"How old are you? — I''m 58.","example":"How old is Leo? — He''s eight.","en":"Age uses \"to be\"","es":"La edad se dice con «to be» (no con «have»)"},{"structure":"-teen vs -ty","example":"fifteen (15) / fifty (50)","en":"Teens and tens sound similar","es":"Los «-teen» y los «-ty» suenan parecido"}],"tips":[{"en":"In English you are an age: \"I am 58\", never \"I have 58 years\".","es":"En inglés uno «es» una edad: «I am 58», nunca «I have 58 years»."},{"en":"Stress the end in -teen numbers (fif-TEEN) and the start in -ty numbers (FIF-ty).","es":"En los números -teen el acento va al final (fif-TEEN) y en los -ty al principio (FIF-ty)."},{"en":"Phone numbers are said one digit at a time: 6-1-9, 5-5-5…","es":"Los números de teléfono se dicen dígito por dígito: 6-1-9, 5-5-5…"},{"en":"Americans use a period for decimals and a comma for thousands: $1,250.50","es":"En Estados Unidos se usa punto para los decimales y coma para los miles: $1,250.50"},{"en":"Zero is often said \"oh\" in phone numbers and addresses: 2-0-5 → \"two oh five\".","es":"El cero se suele decir «oh» en teléfonos y direcciones: 2-0-5 → «two oh five»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"How old are you?","translation":"¿Cuántos años tienes?","translations":{"es":"¿Cuántos años tienes?"}},{"phrase":"I''m fifty-eight years old.","translation":"Tengo cincuenta y ocho años.","translations":{"es":"Tengo cincuenta y ocho años."}},{"phrase":"What''s your phone number?","translation":"¿Cuál es tu número de teléfono?","translations":{"es":"¿Cuál es tu número de teléfono?"}},{"phrase":"My number is 619-555-0142.","translation":"Mi número es 619-555-0142.","translations":{"es":"Mi número es 619-555-0142."}},{"phrase":"How many children do you have?","translation":"¿Cuántos hijos tienes?","translations":{"es":"¿Cuántos hijos tienes?"}},{"phrase":"I have two children.","translation":"Tengo dos hijos.","translations":{"es":"Tengo dos hijos."}},{"phrase":"How much is it?","translation":"¿Cuánto cuesta?","translations":{"es":"¿Cuánto cuesta?"}},{"phrase":"It''s twenty dollars.","translation":"Son veinte dólares.","translations":{"es":"Son veinte dólares."}},{"phrase":"What''s your address?","translation":"¿Cuál es tu dirección?","translations":{"es":"¿Cuál es tu dirección?"}},{"phrase":"Can you write it down, please?","translation":"¿Me lo puede escribir, por favor?","translations":{"es":"¿Me lo puede escribir, por favor?"}},{"phrase":"Fifteen or fifty?","translation":"¿Quince o cincuenta?","translations":{"es":"¿Quince o cincuenta?"}},{"phrase":"One more time, please.","translation":"Una vez más, por favor.","translations":{"es":"Una vez más, por favor."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say your age correctly?","options":["I have 58 years.","Me 58 years.","I have 58 years old.","I am 58 years old."],"correct":3,"explanation":"In English age uses \"to be\": I am 58 (years old).","translations":{"es":{"question":"¿Cómo dices tu edad correctamente?","explanation":"En inglés la edad se dice con «to be»: I am 58 (years old)."}}},{"id":"2","question":"Which number is \"fifty\"?","options":["500","15","5","50"],"correct":3,"explanation":"Fifty is 50. Fifteen is 15.","translations":{"es":{"question":"¿Qué número es «fifty»?","explanation":"Fifty es 50. Fifteen es 15."}}},{"id":"3","question":"Complete: \"I have three ___.\"","options":["book","a book","bookes","books"],"correct":3,"explanation":"More than one: add -s. One book, three books.","translations":{"es":{"question":"Completa: «I have three ___.»","explanation":"Más de uno: se agrega -s. One book, three books."}}},{"id":"4","question":"Which question asks about quantity?","options":["How old are you?","What''s your name?","Where are you?","How many children do you have?"],"correct":3,"explanation":"\"How many…?\" asks about quantity.","translations":{"es":{"question":"¿Qué pregunta pregunta por una cantidad?","explanation":"«How many…?» pregunta por una cantidad."}}},{"id":"5","question":"How do you write 1,500 in words?","options":["fifteen thousand","one hundred fifty","one thousand fifty","one thousand five hundred"],"correct":3,"explanation":"1,500 = one thousand five hundred (or \"fifteen hundred\").","translations":{"es":{"question":"¿Cómo se escribe 1,500 en palabras?","explanation":"1,500 = one thousand five hundred (o «fifteen hundred»)."}}},{"id":"6","question":"How do people usually read the phone number 205-3344?","options":["twenty five, thirty-four","two hundred five, thirty-three forty-four","two zero five thousand","two oh five, three three four four"],"correct":3,"explanation":"Phone numbers are read digit by digit, and 0 is often \"oh\".","translations":{"es":{"question":"¿Cómo se suele leer el número de teléfono 205-3344?","explanation":"Los teléfonos se leen dígito por dígito y el 0 se suele decir «oh»."}}},{"id":"7","question":"What''s the number after twelve?","options":["eleven","twenty","thirty","thirteen"],"correct":3,"explanation":"12 twelve, 13 thirteen.","translations":{"es":{"question":"¿Qué número sigue después de twelve?","explanation":"12 twelve, 13 thirteen."}}},{"id":"8","question":"In the US, what is $3.50?","options":["three hundred fifty dollars","thirty-five dollars","three thousand fifty dollars","three dollars and fifty cents"],"correct":3,"explanation":"The period separates dollars and cents: $3.50 = three dollars and fifty cents.","translations":{"es":{"question":"En Estados Unidos, ¿qué es $3.50?","explanation":"El punto separa dólares y centavos: $3.50 = tres dólares con cincuenta centavos."}}}]}'::jsonb, 3),
  ('story', 'Fifteen or Fifty?', '{"text":"Carmen is at the post office with Leo. She wants to send a small box to her sister in Mexico. \"How much is it?\" she asks. \"Fifteen dollars,\" says the man. Carmen hears \"fifty\". \"Fifty? That''s a lot!\" Leo laughs. \"No, Grandma. Fifteen. One, five.\" \"Ah, fifteen! Okay.\" The man needs her phone number and her address. \"My number is six one nine, five five five, oh one four two.\" \"And your address?\" \"Two hundred ten Palm Street.\" \"Perfect. Thank you!\" Outside, Carmen says to Leo: \"English numbers are difficult. Fifteen, fifty, sixteen, sixty…\" \"Don''t worry, Grandma. You are a good student. And I''m a good teacher!\" Leo is eight years old, and he is very proud.","translation":"Carmen está en la oficina de correos con Leo. Quiere mandarle una caja pequeña a su hermana en México. «¿Cuánto cuesta?», pregunta. «Quince dólares», dice el hombre. Carmen oye «cincuenta». «¿Cincuenta? ¡Es mucho!» Leo se ríe. «No, abuela. Quince. Uno, cinco.» «¡Ah, quince! Bueno.» El hombre necesita su número de teléfono y su dirección. «Mi número es seis uno nueve, cinco cinco cinco, cero uno cuatro dos.» «¿Y su dirección?» «Palm Street doscientos diez.» «Perfecto. ¡Gracias!» Afuera, Carmen le dice a Leo: «Los números en inglés son difíciles. Fifteen, fifty, sixteen, sixty…» «No te preocupes, abuela. Eres una buena alumna. ¡Y yo soy un buen maestro!» Leo tiene ocho años y está muy orgulloso.","translations":{"es":"Carmen está en la oficina de correos con Leo. Quiere mandarle una caja pequeña a su hermana en México. «¿Cuánto cuesta?», pregunta. «Quince dólares», dice el hombre. Carmen oye «cincuenta». «¿Cincuenta? ¡Es mucho!» Leo se ríe. «No, abuela. Quince. Uno, cinco.» «¡Ah, quince! Bueno.» El hombre necesita su número de teléfono y su dirección. «Mi número es seis uno nueve, cinco cinco cinco, cero uno cuatro dos.» «¿Y su dirección?» «Palm Street doscientos diez.» «Perfecto. ¡Gracias!» Afuera, Carmen le dice a Leo: «Los números en inglés son difíciles. Fifteen, fifty, sixteen, sixty…» «No te preocupes, abuela. Eres una buena alumna. ¡Y yo soy un buen maestro!» Leo tiene ocho años y está muy orgulloso."},"highlighted_words":["How much is it","Fifteen","fifty","phone number","address","eight years old"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","am","fifty-eight","years","old"],"translation":"Tengo cincuenta y ocho años.","translations":{"es":"Tengo cincuenta y ocho años."}},{"words":["How","many","children","do","you","have"],"translation":"¿Cuántos hijos tienes?","translations":{"es":"¿Cuántos hijos tienes?"}},{"words":["What","is","your","phone","number"],"translation":"¿Cuál es tu número de teléfono?","translations":{"es":"¿Cuál es tu número de teléfono?"}},{"words":["It","is","twenty","dollars"],"translation":"Son veinte dólares.","translations":{"es":"Son veinte dólares."}},{"words":["I","have","three","grandchildren"],"translation":"Tengo tres nietos.","translations":{"es":"Tengo tres nietos."}},{"words":["How","much","is","the","box"],"translation":"¿Cuánto cuesta la caja?","translations":{"es":"¿Cuánto cuesta la caja?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Cuántos años tienes?","translations":{"es":"¿Cuántos años tienes?"},"answer":"How old are you"},{"prompt":"Tengo dos hijos","translations":{"es":"Tengo dos hijos"},"answer":"I have two children"},{"prompt":"¿Cuánto cuesta?","translations":{"es":"¿Cuánto cuesta?"},"answer":"How much is it"},{"prompt":"Son quince dólares","translations":{"es":"Son quince dólares"},"answer":"It is fifteen dollars"},{"prompt":"¿Cuál es tu dirección?","translations":{"es":"¿Cuál es tu dirección?"},"answer":"What is your address"},{"prompt":"Él tiene ocho años","translations":{"es":"Él tiene ocho años"},"answer":"He is eight years old"}]}'::jsonb, 6)
) as v(type, title, content, ord);

