select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"red","translation":"rojo","translations":{"es":"rojo"}},{"id":"2","word":"blue","translation":"azul","translations":{"es":"azul"}},{"id":"3","word":"green","translation":"verde","translations":{"es":"verde"}},{"id":"4","word":"yellow","translation":"amarillo","translations":{"es":"amarillo"}},{"id":"5","word":"black","translation":"negro","translations":{"es":"negro"}},{"id":"6","word":"white","translation":"blanco","translations":{"es":"blanco"}},{"id":"7","word":"pink","translation":"rosado","translations":{"es":"rosado"}},{"id":"8","word":"purple","translation":"morado","translations":{"es":"morado"}},{"id":"9","word":"orange","translation":"naranja / anaranjado","translations":{"es":"naranja / anaranjado"}},{"id":"10","word":"gray","translation":"gris","translations":{"es":"gris"}},{"id":"11","word":"brown","translation":"café / marrón","translations":{"es":"café / marrón"}},{"id":"12","word":"first name","translation":"nombre","translations":{"es":"nombre"}},{"id":"13","word":"last name","translation":"apellido","translations":{"es":"apellido"}},{"id":"14","word":"friendly","translation":"amigable","translations":{"es":"amigable"}},{"id":"15","word":"kind","translation":"amable / bondadoso","translations":{"es":"amable / bondadoso"}},{"id":"16","word":"funny","translation":"divertido / gracioso","translations":{"es":"divertido / gracioso"}},{"id":"17","word":"shy","translation":"tímido","translations":{"es":"tímido"}},{"id":"18","word":"patient","translation":"paciente","translations":{"es":"paciente"}},{"id":"19","word":"smart","translation":"inteligente","translations":{"es":"inteligente"}},{"id":"20","word":"quiet","translation":"callado / tranquilo","translations":{"es":"callado / tranquilo"}}],"grammar":[{"structure":"adjective + noun","example":"a red car, a kind woman","en":"Adjectives go before the noun","es":"Los adjetivos van antes del sustantivo"},{"structure":"adjectives don''t change","example":"a blue shirt, two blue shirts","en":"Adjectives have no plural or gender","es":"Los adjetivos no tienen plural ni género"},{"structure":"be + adjective","example":"Linda is friendly. They are funny.","en":"Describing with \"to be\"","es":"Describir con «to be»"},{"structure":"What''s your favorite…?","example":"What''s your favorite color?","en":"Asking about favorites","es":"Preguntar por favoritos"},{"structure":"How do you spell…?","example":"How do you spell your last name?","en":"Spelling names","es":"Deletrear nombres"}],"tips":[{"en":"\"First name\" is your name (Carmen). \"Last name\" is your family name (Ruiz). In the US, most people use only one last name.","es":"«First name» es tu nombre (Carmen). «Last name» es tu apellido (Ruiz). En Estados Unidos la mayoría usa un solo apellido."},{"en":"Practice spelling your name with the English alphabet: it''s one of the most useful skills on the phone.","es":"Practica deletrear tu nombre con el alfabeto en inglés: es de lo más útil por teléfono."},{"en":"\"Nice\" and \"kind\" are both positive. \"Kind\" means good to other people.","es":"«Nice» y «kind» son positivos. «Kind» significa bondadoso con los demás."},{"en":"Remember: \"a red dress\", not \"a dress red\".","es":"Recuerda: «a red dress», no «a dress red»."},{"en":"\"Gray\" is the American spelling; British English writes \"grey\".","es":"«Gray» es la ortografía estadounidense; en inglés británico se escribe «grey»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What''s your last name?","translation":"¿Cuál es tu apellido?","translations":{"es":"¿Cuál es tu apellido?"}},{"phrase":"How do you spell it?","translation":"¿Cómo se deletrea?","translations":{"es":"¿Cómo se deletrea?"}},{"phrase":"R-U-I-Z.","translation":"R-U-I-Z.","translations":{"es":"R-U-I-Z."}},{"phrase":"What''s your favorite color?","translation":"¿Cuál es tu color favorito?","translations":{"es":"¿Cuál es tu color favorito?"}},{"phrase":"My favorite color is green.","translation":"Mi color favorito es el verde.","translations":{"es":"Mi color favorito es el verde."}},{"phrase":"She is very friendly.","translation":"Ella es muy amigable.","translations":{"es":"Ella es muy amigable."}},{"phrase":"He''s a little shy.","translation":"Él es un poco tímido.","translations":{"es":"Él es un poco tímido."}},{"phrase":"You''re so funny!","translation":"¡Eres muy gracioso!","translations":{"es":"¡Eres muy gracioso!"}},{"phrase":"I like your blue dress.","translation":"Me gusta tu vestido azul.","translations":{"es":"Me gusta tu vestido azul."}},{"phrase":"What is she like?","translation":"¿Cómo es ella? (personalidad)","translations":{"es":"¿Cómo es ella? (personalidad)"}},{"phrase":"She''s kind and patient.","translation":"Es amable y paciente.","translations":{"es":"Es amable y paciente."}},{"phrase":"Please call me Carmen.","translation":"Por favor, llámame Carmen.","translations":{"es":"Por favor, llámame Carmen."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct order.","options":["a car red","a red car","red a car","a reds car"],"correct":1,"explanation":"In English the adjective goes before the noun.","translations":{"es":{"question":"Elige el orden correcto.","explanation":"En inglés el adjetivo va antes del sustantivo."}}},{"id":"2","question":"Choose the correct plural.","options":["two green bag","two greens bags","two green bags","two bags greens"],"correct":2,"explanation":"Adjectives never take -s. Only the noun does: green bags.","translations":{"es":{"question":"Elige el plural correcto.","explanation":"Los adjetivos nunca llevan -s. Solo el sustantivo: green bags."}}},{"id":"3","question":"Carmen Ruiz: what is her last name?","options":["Carmen","Mrs.","Ruiz","Carmen Ruiz"],"correct":2,"explanation":"The last name is the family name: Ruiz.","translations":{"es":{"question":"Carmen Ruiz: ¿cuál es su «last name»?","explanation":"El «last name» es el apellido: Ruiz."}}},{"id":"4","question":"A person who doesn''t talk much with new people is…","options":["funny","loud","shy","friendly"],"correct":2,"explanation":"\"Shy\" describes someone who is nervous with new people.","translations":{"es":{"question":"Una persona que no habla mucho con gente nueva es…","explanation":"«Shy» (tímido) describe a alguien nervioso con gente nueva."}}},{"id":"5","question":"Mix blue and yellow. What color is it?","options":["green","brown","purple","orange"],"correct":0,"explanation":"Blue + yellow = green.","translations":{"es":{"question":"Mezcla azul y amarillo. ¿Qué color sale?","explanation":"Azul + amarillo = verde."}}},{"id":"6","question":"Which question asks about personality?","options":["What is she like?","Where is she?","What does she like?","How old is she?"],"correct":0,"explanation":"\"What is she like?\" asks about personality. \"What does she like?\" asks about her tastes.","translations":{"es":{"question":"¿Qué pregunta es sobre la personalidad?","explanation":"«What is she like?» pregunta por la personalidad. «What does she like?» pregunta qué le gusta."}}},{"id":"7","question":"Complete: \"Linda ___ very kind.\"","options":["be","is","are","am"],"correct":1,"explanation":"Linda = she → is.","translations":{"es":{"question":"Completa: «Linda ___ very kind.»","explanation":"Linda = she → is."}}},{"id":"8","question":"How do you ask someone to spell their name?","options":["How do you spell your name?","What spell is your name?","How do you write you name?","How you spell name?"],"correct":0,"explanation":"\"How do you spell…?\" is the standard question.","translations":{"es":{"question":"¿Cómo le pides a alguien que deletree su nombre?","explanation":"«How do you spell…?» es la pregunta estándar."}}}]}'::jsonb, 3),
  ('story', 'The Name Tag', '{"text":"Today is Carmen''s first day of English class. The classroom is small and bright, with yellow walls and blue chairs. The teacher is Mr. Park. He is tall, friendly and very patient. \"Welcome! Please write your first name on a name tag.\" Carmen takes a red marker and writes CARMEN. Next to her is a young woman with a green jacket. \"Hi, I''m Ana. I''m from Brazil.\" \"Nice to meet you, Ana. I''m Carmen, from Mexico.\" Mr. Park asks, \"Carmen, what''s your last name?\" \"Ruiz.\" \"How do you spell it?\" \"R-U-I-Z.\" \"Thank you!\" Ana is funny and talks a lot. Carmen is a little shy, but she is happy. Her new class is full of kind people.","translation":"Hoy es el primer día de la clase de inglés de Carmen. El salón es pequeño y luminoso, con paredes amarillas y sillas azules. El profesor es el señor Park. Es alto, amigable y muy paciente. «¡Bienvenidos! Por favor, escriban su nombre en una etiqueta.» Carmen toma un marcador rojo y escribe CARMEN. A su lado hay una joven con una chaqueta verde. «Hola, soy Ana. Soy de Brasil.» «Mucho gusto, Ana. Soy Carmen, de México.» El señor Park pregunta: «Carmen, ¿cuál es tu apellido?» «Ruiz.» «¿Cómo se deletrea?» «R-U-I-Z.» «¡Gracias!» Ana es divertida y habla mucho. Carmen es un poco tímida, pero está feliz. Su nueva clase está llena de gente amable.","translations":{"es":"Hoy es el primer día de la clase de inglés de Carmen. El salón es pequeño y luminoso, con paredes amarillas y sillas azules. El profesor es el señor Park. Es alto, amigable y muy paciente. «¡Bienvenidos! Por favor, escriban su nombre en una etiqueta.» Carmen toma un marcador rojo y escribe CARMEN. A su lado hay una joven con una chaqueta verde. «Hola, soy Ana. Soy de Brasil.» «Mucho gusto, Ana. Soy Carmen, de México.» El señor Park pregunta: «Carmen, ¿cuál es tu apellido?» «Ruiz.» «¿Cómo se deletrea?» «R-U-I-Z.» «¡Gracias!» Ana es divertida y habla mucho. Carmen es un poco tímida, pero está feliz. Su nueva clase está llena de gente amable."},"highlighted_words":["yellow","blue","friendly","patient","first name","red","green","last name","How do you spell it","funny","shy","kind"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["My","favorite","color","is","green"],"translation":"Mi color favorito es el verde.","translations":{"es":"Mi color favorito es el verde."}},{"words":["She","is","kind","and","patient"],"translation":"Ella es amable y paciente.","translations":{"es":"Ella es amable y paciente."}},{"words":["I","like","your","blue","dress"],"translation":"Me gusta tu vestido azul.","translations":{"es":"Me gusta tu vestido azul."}},{"words":["How","do","you","spell","your","name"],"translation":"¿Cómo se deletrea tu nombre?","translations":{"es":"¿Cómo se deletrea tu nombre?"}},{"words":["He","is","a","little","shy"],"translation":"Él es un poco tímido.","translations":{"es":"Él es un poco tímido."}},{"words":["What","is","your","last","name"],"translation":"¿Cuál es tu apellido?","translations":{"es":"¿Cuál es tu apellido?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Mi color favorito es el azul","translations":{"es":"Mi color favorito es el azul"},"answer":"My favorite color is blue"},{"prompt":"Ella es muy amigable","translations":{"es":"Ella es muy amigable"},"answer":"She is very friendly"},{"prompt":"¿Cuál es tu apellido?","translations":{"es":"¿Cuál es tu apellido?"},"answer":"What is your last name"},{"prompt":"Tengo un auto rojo","translations":{"es":"Tengo un auto rojo"},"answer":"I have a red car"},{"prompt":"Él es divertido","translations":{"es":"Él es divertido"},"answer":"He is funny"},{"prompt":"¿Cómo se deletrea?","translations":{"es":"¿Cómo se deletrea?"},"answer":"How do you spell it"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 6: The family
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-06', 'The family', '👨‍👩‍👧‍👦', 'La familia', 6, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"mother","translation":"madre","translations":{"es":"madre"}},{"id":"2","word":"father","translation":"padre","translations":{"es":"padre"}},{"id":"3","word":"parents","translation":"padres (papá y mamá)","translations":{"es":"padres (papá y mamá)"}},{"id":"4","word":"daughter","translation":"hija","translations":{"es":"hija"}},{"id":"5","word":"son","translation":"hijo","translations":{"es":"hijo"}},{"id":"6","word":"children","translation":"hijos / niños","translations":{"es":"hijos / niños"}},{"id":"7","word":"sister","translation":"hermana","translations":{"es":"hermana"}},{"id":"8","word":"brother","translation":"hermano","translations":{"es":"hermano"}},{"id":"9","word":"grandmother","translation":"abuela","translations":{"es":"abuela"}},{"id":"10","word":"grandfather","translation":"abuelo","translations":{"es":"abuelo"}},{"id":"11","word":"grandson","translation":"nieto","translations":{"es":"nieto"}},{"id":"12","word":"granddaughter","translation":"nieta","translations":{"es":"nieta"}},{"id":"13","word":"husband","translation":"esposo","translations":{"es":"esposo"}},{"id":"14","word":"wife","translation":"esposa","translations":{"es":"esposa"}},{"id":"15","word":"aunt","translation":"tía","translations":{"es":"tía"}},{"id":"16","word":"uncle","translation":"tío","translations":{"es":"tío"}},{"id":"17","word":"cousin","translation":"primo / prima","translations":{"es":"primo / prima"}},{"id":"18","word":"son-in-law","translation":"yerno","translations":{"es":"yerno"}},{"id":"19","word":"relatives","translation":"parientes","translations":{"es":"parientes"}}],"grammar":[{"structure":"my, your, his, her, our, their","example":"Her husband is Mike. Their son is Leo.","en":"Possessive adjectives","es":"Adjetivos posesivos"},{"structure":"name + ''s","example":"Laura''s son, Carmen''s daughter","en":"Possession with ''s","es":"Posesión con ''s (de alguien)"},{"structure":"his vs. her","example":"Leo and his dog. Laura and her car.","en":"\"His\" for a man, \"her\" for a woman (the owner)","es":"«His» si el dueño es hombre, «her» si es mujer"},{"structure":"Do you have…? — Yes, I do.","example":"Do you have brothers or sisters?","en":"Asking about family with \"have\"","es":"Preguntar por la familia con «have»"},{"structure":"Who is…?","example":"Who is that? — That''s my sister.","en":"Asking about people","es":"Preguntar quién es alguien"}],"tips":[{"en":"In Spanish \"su\" can mean his, her or their. In English you must choose: his (a man''s), her (a woman''s), their (several people''s).","es":"En español «su» puede ser de él, de ella o de ellos. En inglés hay que elegir: his (de él), her (de ella), their (de ellos)."},{"en":"\"Parents\" means mother and father, not all your relatives. For all of them, say \"relatives\" or \"family\".","es":"«Parents» significa padre y madre, no todos tus parientes. Para todos, di «relatives» o «family»."},{"en":"\"In-law\" means family through marriage: mother-in-law, son-in-law, sister-in-law.","es":"«In-law» indica familia política: mother-in-law (suegra), son-in-law (yerno), sister-in-law (cuñada)."},{"en":"Kids often call their grandparents \"Grandma\" and \"Grandpa\".","es":"Los niños suelen llamar a sus abuelos «Grandma» y «Grandpa»."},{"en":"\"Children\" is the plural of \"child\": one child, two children.","es":"«Children» es el plural de «child»: one child, two children."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"This is my family.","translation":"Esta es mi familia.","translations":{"es":"Esta es mi familia."}},{"phrase":"Do you have any children?","translation":"¿Tienes hijos?","translations":{"es":"¿Tienes hijos?"}},{"phrase":"I have a daughter and a son.","translation":"Tengo una hija y un hijo.","translations":{"es":"Tengo una hija y un hijo."}},{"phrase":"Who is that?","translation":"¿Quién es esa persona?","translations":{"es":"¿Quién es esa persona?"}},{"phrase":"That''s my brother.","translation":"Ese es mi hermano.","translations":{"es":"Ese es mi hermano."}},{"phrase":"Her husband is very nice.","translation":"Su esposo (de ella) es muy simpático.","translations":{"es":"Su esposo (de ella) es muy simpático."}},{"phrase":"Their son is eight.","translation":"Su hijo (de ellos) tiene ocho años.","translations":{"es":"Su hijo (de ellos) tiene ocho años."}},{"phrase":"Are you married?","translation":"¿Estás casado/a?","translations":{"es":"¿Estás casado/a?"}},{"phrase":"I''m a widow.","translation":"Soy viuda.","translations":{"es":"Soy viuda."}},{"phrase":"My family lives in Mexico.","translation":"Mi familia vive en México.","translations":{"es":"Mi familia vive en México."}},{"phrase":"I miss my sister.","translation":"Extraño a mi hermana.","translations":{"es":"Extraño a mi hermana."}},{"phrase":"We are a big family.","translation":"Somos una familia grande.","translations":{"es":"Somos una familia grande."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Laura is Carmen''s daughter. Carmen is Laura''s…","options":["sister","aunt","mother","grandmother"],"correct":2,"explanation":"If Laura is her daughter, Carmen is Laura''s mother.","translations":{"es":{"question":"Laura es la hija de Carmen. Carmen es la ___ de Laura.","explanation":"Si Laura es su hija, Carmen es la madre de Laura."}}},{"id":"2","question":"Complete: \"Mike loves ___ son.\"","options":["their","her","his","its"],"correct":2,"explanation":"Mike is a man, so it''s \"his son\".","translations":{"es":{"question":"Completa: «Mike loves ___ son.»","explanation":"Mike es hombre, así que es «his son»."}}},{"id":"3","question":"Complete: \"Laura and ___ husband live in San Diego.\"","options":["his","she","her","hers"],"correct":2,"explanation":"The husband belongs to Laura, a woman: \"her husband\".","translations":{"es":{"question":"Completa: «Laura and ___ husband live in San Diego.»","explanation":"El esposo es de Laura, una mujer: «her husband»."}}},{"id":"4","question":"How do you say \"el hijo de Laura\"?","options":["Laura son","Laura''s son","the son of Laura''s","son''s Laura"],"correct":1,"explanation":"We usually use ''s: Laura''s son.","translations":{"es":{"question":"¿Cómo se dice «el hijo de Laura»?","explanation":"Normalmente se usa ''s: Laura''s son."}}},{"id":"5","question":"Your mother''s brother is your…","options":["uncle","grandfather","cousin","nephew"],"correct":0,"explanation":"Your parents'' brothers are your uncles.","translations":{"es":{"question":"El hermano de tu madre es tu…","explanation":"Los hermanos de tus padres son tus tíos (uncles)."}}},{"id":"6","question":"What is the plural of \"child\"?","options":["children","childrens","childs","childes"],"correct":0,"explanation":"\"Child\" has an irregular plural: children.","translations":{"es":{"question":"¿Cuál es el plural de «child»?","explanation":"«Child» tiene un plural irregular: children."}}},{"id":"7","question":"\"Parents\" means…","options":["all your relatives","mother and father","brothers and sisters","grandparents"],"correct":1,"explanation":"Parents = mother and father. Other family members are \"relatives\".","translations":{"es":{"question":"«Parents» significa…","explanation":"Parents = mamá y papá. Los demás familiares son «relatives»."}}},{"id":"8","question":"Mike is Laura''s husband. For Carmen, Mike is her…","options":["son-in-law","son","brother-in-law","grandson"],"correct":0,"explanation":"Your daughter''s husband is your son-in-law.","translations":{"es":{"question":"Mike es el esposo de Laura. Para Carmen, Mike es su…","explanation":"El esposo de tu hija es tu yerno (son-in-law)."}}}]}'::jsonb, 3),
  ('story', 'Family Photos', '{"text":"It is Sunday afternoon. Linda visits Carmen, and Carmen shows her some family photos. \"Who is that?\" asks Linda. \"That''s my daughter, Laura, with her husband, Mike. And this is their son, Leo.\" \"Your grandson is so cute!\" \"Thank you! He is eight. He is funny and very smart.\" \"And this photo?\" \"These are my sisters in Guadalajara, Rosa and Teresa. Rosa''s children are in this photo too.\" \"Do you have a big family?\" \"Oh yes. Many aunts, uncles and cousins.\" Linda smiles. \"My family is small. I have one brother in Texas.\" Carmen looks at the photos and says quietly, \"I miss my sisters.\" Linda takes her hand. \"Now you have a neighbor too.\"","translation":"Es domingo por la tarde. Linda visita a Carmen y Carmen le muestra unas fotos de la familia. «¿Quién es esa?», pregunta Linda. «Es mi hija, Laura, con su esposo, Mike. Y este es su hijo, Leo.» «¡Tu nieto es precioso!» «¡Gracias! Tiene ocho años. Es divertido y muy inteligente.» «¿Y esta foto?» «Son mis hermanas en Guadalajara, Rosa y Teresa. Los hijos de Rosa también están en esta foto.» «¿Tienes una familia grande?» «Ay, sí. Muchos tíos, tías y primos.» Linda sonríe. «Mi familia es pequeña. Tengo un hermano en Texas.» Carmen mira las fotos y dice en voz baja: «Extraño a mis hermanas.» Linda le toma la mano. «Ahora también tienes una vecina.»","translations":{"es":"Es domingo por la tarde. Linda visita a Carmen y Carmen le muestra unas fotos de la familia. «¿Quién es esa?», pregunta Linda. «Es mi hija, Laura, con su esposo, Mike. Y este es su hijo, Leo.» «¡Tu nieto es precioso!» «¡Gracias! Tiene ocho años. Es divertido y muy inteligente.» «¿Y esta foto?» «Son mis hermanas en Guadalajara, Rosa y Teresa. Los hijos de Rosa también están en esta foto.» «¿Tienes una familia grande?» «Ay, sí. Muchos tíos, tías y primos.» Linda sonríe. «Mi familia es pequeña. Tengo un hermano en Texas.» Carmen mira las fotos y dice en voz baja: «Extraño a mis hermanas.» Linda le toma la mano. «Ahora también tienes una vecina.»"},"highlighted_words":["Who is that","daughter","her husband","their son","grandson","sisters","Rosa''s children","aunts","uncles","cousins","brother","I miss my sisters"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["This","is","my","family"],"translation":"Esta es mi familia.","translations":{"es":"Esta es mi familia."}},{"words":["Her","husband","is","very","nice"],"translation":"Su esposo es muy simpático.","translations":{"es":"Su esposo es muy simpático."}},{"words":["Do","you","have","any","children"],"translation":"¿Tienes hijos?","translations":{"es":"¿Tienes hijos?"}},{"words":["Leo","is","Laura''s","son"],"translation":"Leo es el hijo de Laura.","translations":{"es":"Leo es el hijo de Laura."}},{"words":["My","family","lives","in","Mexico"],"translation":"Mi familia vive en México.","translations":{"es":"Mi familia vive en México."}},{"words":["I","have","two","sisters","and","a","brother"],"translation":"Tengo dos hermanas y un hermano.","translations":{"es":"Tengo dos hermanas y un hermano."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Esta es mi hija","translations":{"es":"Esta es mi hija"},"answer":"This is my daughter"},{"prompt":"Su hijo (de ella) tiene ocho","translations":{"es":"Su hijo (de ella) tiene ocho"},"answer":"Her son is eight"},{"prompt":"Tengo dos hermanas","translations":{"es":"Tengo dos hermanas"},"answer":"I have two sisters"},{"prompt":"¿Quién es esa persona?","translations":{"es":"¿Quién es esa persona?"},"answer":"Who is that"},{"prompt":"Extraño a mi familia","translations":{"es":"Extraño a mi familia"},"answer":"I miss my family"},{"prompt":"¿Tienes hijos?","translations":{"es":"¿Tienes hijos?"},"answer":"Do you have children"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 7: At home
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-07', 'At home', '🏠', 'En casa', 7, true)
  returning id
