insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"house","translation":"casa","translations":{"es":"casa"}},{"id":"2","word":"home","translation":"hogar / casa","translations":{"es":"hogar / casa"}},{"id":"3","word":"apartment","translation":"departamento / apartamento","translations":{"es":"departamento / apartamento"}},{"id":"4","word":"kitchen","translation":"cocina","translations":{"es":"cocina"}},{"id":"5","word":"bedroom","translation":"dormitorio / recámara","translations":{"es":"dormitorio / recámara"}},{"id":"6","word":"bathroom","translation":"baño","translations":{"es":"baño"}},{"id":"7","word":"living room","translation":"sala","translations":{"es":"sala"}},{"id":"8","word":"dining room","translation":"comedor","translations":{"es":"comedor"}},{"id":"9","word":"garden","translation":"jardín","translations":{"es":"jardín"}},{"id":"10","word":"garage","translation":"garaje / cochera","translations":{"es":"garaje / cochera"}},{"id":"11","word":"door","translation":"puerta","translations":{"es":"puerta"}},{"id":"12","word":"window","translation":"ventana","translations":{"es":"ventana"}},{"id":"13","word":"stairs","translation":"escaleras","translations":{"es":"escaleras"}},{"id":"14","word":"key","translation":"llave","translations":{"es":"llave"}},{"id":"15","word":"floor","translation":"piso / suelo","translations":{"es":"piso / suelo"}},{"id":"16","word":"big","translation":"grande","translations":{"es":"grande"}},{"id":"17","word":"small","translation":"pequeño","translations":{"es":"pequeño"}}],"grammar":[{"structure":"there is + singular","example":"There is a big kitchen.","en":"\"There is\" for one thing","es":"«There is» para una cosa (hay)"},{"structure":"there are + plural","example":"There are two bedrooms.","en":"\"There are\" for several things","es":"«There are» para varias cosas (hay)"},{"structure":"Is there…? / Are there…?","example":"Is there a garden? — Yes, there is.","en":"Questions with there is / there are","es":"Preguntas con there is / there are"},{"structure":"There isn''t / There aren''t","example":"There isn''t a garage.","en":"Negative forms","es":"Formas negativas"},{"structure":"a / an","example":"a house, an apartment","en":"\"An\" before a vowel sound","es":"«An» delante de sonido de vocal"}],"tips":[{"en":"Spanish \"hay\" is \"there is\" (one) or \"there are\" (more than one) in English.","es":"«Hay» en español es «there is» (uno) o «there are» (más de uno) en inglés."},{"en":"\"House\" is the building; \"home\" is the place where you live and feel comfortable.","es":"«House» es el edificio; «home» es el lugar donde vives y te sientes en casa."},{"en":"Say \"at home\" (en casa) and \"go home\" (ir a casa), without \"to\".","es":"Se dice «at home» (en casa) y «go home» (ir a casa), sin «to»."},{"en":"In the US, the first floor is the ground floor.","es":"En Estados Unidos, el «first floor» es la planta baja."},{"en":"\"Apartment\" is American English. In British English it''s \"flat\".","es":"«Apartment» es inglés estadounidense. En inglés británico se dice «flat»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Welcome to my home!","translation":"¡Bienvenido a mi casa!","translations":{"es":"¡Bienvenido a mi casa!"}},{"phrase":"Come in, please.","translation":"Pasa, por favor.","translations":{"es":"Pasa, por favor."}},{"phrase":"There are three bedrooms.","translation":"Hay tres dormitorios.","translations":{"es":"Hay tres dormitorios."}},{"phrase":"There is a small garden.","translation":"Hay un jardín pequeño.","translations":{"es":"Hay un jardín pequeño."}},{"phrase":"Where is the bathroom?","translation":"¿Dónde está el baño?","translations":{"es":"¿Dónde está el baño?"}},{"phrase":"It''s upstairs, on the left.","translation":"Está arriba, a la izquierda.","translations":{"es":"Está arriba, a la izquierda."}},{"phrase":"Is there a garage?","translation":"¿Hay garaje?","translations":{"es":"¿Hay garaje?"}},{"phrase":"No, there isn''t.","translation":"No, no hay.","translations":{"es":"No, no hay."}},{"phrase":"Make yourself at home.","translation":"Siéntete como en tu casa.","translations":{"es":"Siéntete como en tu casa."}},{"phrase":"I''m at home.","translation":"Estoy en casa.","translations":{"es":"Estoy en casa."}},{"phrase":"I''m going home.","translation":"Me voy a casa.","translations":{"es":"Me voy a casa."}},{"phrase":"Here are your keys.","translation":"Aquí están tus llaves.","translations":{"es":"Aquí están tus llaves."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"There ___ two bathrooms.\"","options":["be","am","are","is"],"correct":2,"explanation":"Two bathrooms = plural → there are.","translations":{"es":{"question":"Completa: «There ___ two bathrooms.»","explanation":"Two bathrooms = plural → there are."}}},{"id":"2","question":"Complete: \"There ___ a big kitchen.\"","options":["is","have","has","are"],"correct":0,"explanation":"One kitchen = singular → there is.","translations":{"es":{"question":"Completa: «There ___ a big kitchen.»","explanation":"One kitchen = singular → there is."}}},{"id":"3","question":"Choose the correct question.","options":["Has a garden?","Is there a garden?","Is a garden there have?","There is a garden?"],"correct":1,"explanation":"To ask, put \"is\" first: Is there…?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Para preguntar se pone «is» primero: Is there…?"}}},{"id":"4","question":"Where do you usually cook?","options":["in the garage","in the kitchen","in the bathroom","in the bedroom"],"correct":1,"explanation":"We cook in the kitchen.","translations":{"es":{"question":"¿Dónde sueles cocinar?","explanation":"Se cocina en la cocina (kitchen)."}}},{"id":"5","question":"Choose: \"___ apartment\"","options":["an","one an","the an","a"],"correct":0,"explanation":"\"Apartment\" starts with a vowel sound, so we use \"an\".","translations":{"es":{"question":"Elige: «___ apartment»","explanation":"«Apartment» empieza con sonido de vocal, así que se usa «an»."}}},{"id":"6","question":"How do you say \"Estoy en casa\"?","options":["I''m at home.","I''m to home.","I''m at the house home.","I''m in home."],"correct":0,"explanation":"We say \"at home\".","translations":{"es":{"question":"¿Cómo se dice «Estoy en casa»?","explanation":"Se dice «at home»."}}},{"id":"7","question":"A guest arrives. What do you say?","options":["Where is the bathroom?","Come in, please. Make yourself at home.","There is a door.","Go home, please."],"correct":1,"explanation":"\"Come in\" and \"Make yourself at home\" are warm ways to receive guests.","translations":{"es":{"question":"Llega un invitado. ¿Qué dices?","explanation":"«Come in» y «Make yourself at home» son formas cálidas de recibir invitados."}}},{"id":"8","question":"Choose the correct negative.","options":["There aren''t any chairs.","There not chairs.","There no are chairs.","There isn''t any chairs."],"correct":0,"explanation":"Chairs are plural → there aren''t.","translations":{"es":{"question":"Elige la negación correcta.","explanation":"Chairs es plural → there aren''t."}}}]}'::jsonb, 3),
  ('story', 'A Small Apartment', '{"text":"Carmen lives with Laura''s family now, but she wants her own place. Today she visits an apartment with Linda. The apartment is on the second floor. \"Come in, please,\" says the manager. \"There is a living room with a big window. There are two bedrooms and one bathroom.\" Carmen looks around. The kitchen is small, but it is clean and bright. \"Is there a garden?\" asks Carmen. \"No, there isn''t. But there is a small balcony.\" Carmen goes to the balcony. There are flowers and a little table. \"I can have my coffee here every morning,\" she says. Linda smiles. \"And my house is only five minutes away.\" Carmen holds the key. It is a small apartment, but maybe it can be her new home.","translation":"Ahora Carmen vive con la familia de Laura, pero quiere tener su propio lugar. Hoy visita un departamento con Linda. El departamento está en el segundo piso. «Pasen, por favor», dice el administrador. «Hay una sala con una ventana grande. Hay dos dormitorios y un baño.» Carmen mira alrededor. La cocina es pequeña, pero está limpia y luminosa. «¿Hay jardín?», pregunta Carmen. «No, no hay. Pero hay un balcón pequeño.» Carmen va al balcón. Hay flores y una mesita. «Aquí puedo tomar mi café todas las mañanas», dice. Linda sonríe. «Y mi casa está a solo cinco minutos.» Carmen sostiene la llave. Es un departamento pequeño, pero quizás pueda ser su nuevo hogar.","translations":{"es":"Ahora Carmen vive con la familia de Laura, pero quiere tener su propio lugar. Hoy visita un departamento con Linda. El departamento está en el segundo piso. «Pasen, por favor», dice el administrador. «Hay una sala con una ventana grande. Hay dos dormitorios y un baño.» Carmen mira alrededor. La cocina es pequeña, pero está limpia y luminosa. «¿Hay jardín?», pregunta Carmen. «No, no hay. Pero hay un balcón pequeño.» Carmen va al balcón. Hay flores y una mesita. «Aquí puedo tomar mi café todas las mañanas», dice. Linda sonríe. «Y mi casa está a solo cinco minutos.» Carmen sostiene la llave. Es un departamento pequeño, pero quizás pueda ser su nuevo hogar."},"highlighted_words":["apartment","Come in, please","There is","There are","bedrooms","bathroom","kitchen","Is there a garden","No, there isn''t","key","home"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["There","are","three","bedrooms"],"translation":"Hay tres dormitorios.","translations":{"es":"Hay tres dormitorios."}},{"words":["Is","there","a","garden"],"translation":"¿Hay jardín?","translations":{"es":"¿Hay jardín?"}},{"words":["The","kitchen","is","small","but","clean"],"translation":"La cocina es pequeña pero limpia.","translations":{"es":"La cocina es pequeña pero limpia."}},{"words":["Where","is","the","bathroom"],"translation":"¿Dónde está el baño?","translations":{"es":"¿Dónde está el baño?"}},{"words":["Make","yourself","at","home"],"translation":"Siéntete como en tu casa.","translations":{"es":"Siéntete como en tu casa."}},{"words":["There","is","a","big","window"],"translation":"Hay una ventana grande.","translations":{"es":"Hay una ventana grande."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Hay un jardín","translations":{"es":"Hay un jardín"},"answer":"There is a garden"},{"prompt":"Hay dos baños","translations":{"es":"Hay dos baños"},"answer":"There are two bathrooms"},{"prompt":"¿Dónde está la cocina?","translations":{"es":"¿Dónde está la cocina?"},"answer":"Where is the kitchen"},{"prompt":"Estoy en casa","translations":{"es":"Estoy en casa"},"answer":"I am at home"},{"prompt":"Pasa, por favor","translations":{"es":"Pasa, por favor"},"answer":"Come in, please"},{"prompt":"¿Hay garaje?","translations":{"es":"¿Hay garaje?"},"answer":"Is there a garage"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 8: Countries and nationalities
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-08', 'Countries and nationalities', '🌍', 'Países y nacionalidades', 8, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"country","translation":"país","translations":{"es":"país"}},{"id":"2","word":"Mexico","translation":"México","translations":{"es":"México"}},{"id":"3","word":"Mexican","translation":"mexicano / mexicana","translations":{"es":"mexicano / mexicana"}},{"id":"4","word":"the United States","translation":"Estados Unidos","translations":{"es":"Estados Unidos"}},{"id":"5","word":"American","translation":"estadounidense","translations":{"es":"estadounidense"}},{"id":"6","word":"Spain","translation":"España","translations":{"es":"España"}},{"id":"7","word":"Spanish","translation":"español (idioma / de España)","translations":{"es":"español (idioma / de España)"}},{"id":"8","word":"Brazil","translation":"Brasil","translations":{"es":"Brasil"}},{"id":"9","word":"Brazilian","translation":"brasileño","translations":{"es":"brasileño"}},{"id":"10","word":"Japan","translation":"Japón","translations":{"es":"Japón"}},{"id":"11","word":"Japanese","translation":"japonés","translations":{"es":"japonés"}},{"id":"12","word":"Canada","translation":"Canadá","translations":{"es":"Canadá"}},{"id":"13","word":"Canadian","translation":"canadiense","translations":{"es":"canadiense"}},{"id":"14","word":"English","translation":"inglés (idioma)","translations":{"es":"inglés (idioma)"}},{"id":"15","word":"Portuguese","translation":"portugués","translations":{"es":"portugués"}},{"id":"16","word":"language","translation":"idioma","translations":{"es":"idioma"}},{"id":"17","word":"city","translation":"ciudad","translations":{"es":"ciudad"}}],"grammar":[{"structure":"Where are you from? — I''m from…","example":"Where are you from? — I''m from Mexico.","en":"Asking where someone is from","es":"Preguntar de dónde es alguien"},{"structure":"Nationalities with a capital letter","example":"She is Brazilian. He speaks Japanese.","en":"Nationalities and languages are capitalized","es":"Nacionalidades e idiomas van con mayúscula"},{"structure":"I''m not / she isn''t / they aren''t","example":"I''m not American. She isn''t from Spain.","en":"Negative of \"to be\"","es":"Negativo de «to be»"},{"structure":"Are you…? — Yes, I am. / No, I''m not.","example":"Are you Mexican? — Yes, I am.","en":"Yes/no questions with \"to be\"","es":"Preguntas de sí/no con «to be»"},{"structure":"speak + language","example":"I speak Spanish and a little English.","en":"Talking about languages","es":"Hablar de idiomas"}],"tips":[{"en":"In English, nationalities and languages always start with a capital letter: Mexican, Spanish, English.","es":"En inglés las nacionalidades y los idiomas siempre van con mayúscula: Mexican, Spanish, English."},{"en":"\"Spanish\" is both the language and the nationality of Spain. People from Mexico are \"Mexican\" and speak Spanish.","es":"«Spanish» es el idioma y también la nacionalidad de España. Los de México son «Mexican» y hablan Spanish."},{"en":"Short answers are very natural: \"Are you Mexican?\" — \"Yes, I am.\" Don''t say just \"Yes, I''m.\"","es":"Las respuestas cortas son muy naturales: «Are you Mexican?» — «Yes, I am.» No digas «Yes, I''m.»"},{"en":"\"American\" usually means from the United States.","es":"«American» normalmente significa de Estados Unidos."},{"en":"\"A little\" is useful and humble: \"I speak a little English.\"","es":"«A little» es útil y humilde: «I speak a little English.» (hablo un poco de inglés)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Where are you from?","translation":"¿De dónde eres?","translations":{"es":"¿De dónde eres?"}},{"phrase":"I''m from Mexico.","translation":"Soy de México.","translations":{"es":"Soy de México."}},{"phrase":"I''m Mexican.","translation":"Soy mexicana.","translations":{"es":"Soy mexicana."}},{"phrase":"Which city?","translation":"¿De qué ciudad?","translations":{"es":"¿De qué ciudad?"}},{"phrase":"I''m from Guadalajara.","translation":"Soy de Guadalajara.","translations":{"es":"Soy de Guadalajara."}},{"phrase":"What languages do you speak?","translation":"¿Qué idiomas hablas?","translations":{"es":"¿Qué idiomas hablas?"}},{"phrase":"I speak Spanish and a little English.","translation":"Hablo español y un poco de inglés.","translations":{"es":"Hablo español y un poco de inglés."}},{"phrase":"Are you American?","translation":"¿Eres estadounidense?","translations":{"es":"¿Eres estadounidense?"}},{"phrase":"No, I''m not. I''m Canadian.","translation":"No. Soy canadiense.","translations":{"es":"No. Soy canadiense."}},{"phrase":"Your English is very good!","translation":"¡Tu inglés es muy bueno!","translations":{"es":"¡Tu inglés es muy bueno!"}},{"phrase":"I''m learning English.","translation":"Estoy aprendiendo inglés.","translations":{"es":"Estoy aprendiendo inglés."}},{"phrase":"Welcome to the United States!","translation":"¡Bienvenido a Estados Unidos!","translations":{"es":"¡Bienvenido a Estados Unidos!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Ana is from Brazil. She is…","options":["brazilian","Brazilian","Brazil","Brazilish"],"correct":1,"explanation":"The nationality is \"Brazilian\", with a capital B.","translations":{"es":{"question":"Ana es de Brasil. Ella es…","explanation":"La nacionalidad es «Brazilian», con B mayúscula."}}},{"id":"2","question":"Choose the correct answer: \"Are you Mexican?\"","options":["Yes, I am.","Yes, am I.","Yes, I''m.","Yes, I is."],"correct":0,"explanation":"The short answer is \"Yes, I am\". The contraction is not used at the end.","translations":{"es":{"question":"Elige la respuesta correcta: «Are you Mexican?»","explanation":"La respuesta corta es «Yes, I am». La contracción no se usa al final."}}},{"id":"3","question":"Complete: \"Kenji ___ from Mexico. He''s from Japan.\"","options":["don''t","isn''t","aren''t","am not"],"correct":1,"explanation":"He → is not → isn''t.","translations":{"es":{"question":"Completa: «Kenji ___ from Mexico. He''s from Japan.»","explanation":"He → is not → isn''t."}}},{"id":"4","question":"Which is correct?","options":["I speak spanish.","I speak Spanish.","I speak the Spanish.","I speak Spain."],"correct":1,"explanation":"Languages have a capital letter and no \"the\": I speak Spanish.","translations":{"es":{"question":"¿Cuál es correcto?","explanation":"Los idiomas llevan mayúscula y no llevan «the»: I speak Spanish."}}},{"id":"5","question":"People from the United States are usually called…","options":["American","United","USA","Statish"],"correct":0,"explanation":"People from the US are \"American\".","translations":{"es":{"question":"A la gente de Estados Unidos normalmente se le dice…","explanation":"Los de Estados Unidos son «American»."}}},{"id":"6","question":"How do you ask about someone''s origin?","options":["Where are you from?","Where you are from?","Where do you from?","From where you are?"],"correct":0,"explanation":"The question is \"Where are you from?\"","translations":{"es":{"question":"¿Cómo preguntas de dónde es alguien?","explanation":"La pregunta es «Where are you from?»"}}},{"id":"7","question":"What language do people speak in Brazil?","options":["Spanish","English","Portuguese","Brazilian"],"correct":2,"explanation":"In Brazil people speak Portuguese.","translations":{"es":{"question":"¿Qué idioma se habla en Brasil?","explanation":"En Brasil se habla portugués."}}},{"id":"8","question":"Complete: \"We ___ from Mexico.\"","options":["be","is","are","am"],"correct":2,"explanation":"We → are.","translations":{"es":{"question":"Completa: «We ___ from Mexico.»","explanation":"We → are."}}}]}'::jsonb, 3),
  ('story', 'The World in One Classroom', '{"text":"In Carmen''s English class there are students from many countries. Mr. Park asks everybody, \"Where are you from?\" Ana says, \"I''m from Brazil. I''m Brazilian. I speak Portuguese.\" A quiet man says, \"I''m Kenji. I''m from Japan. I speak Japanese and a little English.\" \"And you, Carmen?\" \"I''m from Mexico, from Guadalajara. I speak Spanish.\" \"Are you from Canada, Mr. Park?\" asks Ana. \"No, I''m not. I''m American. But my parents are from Korea.\" Carmen thinks: Mexico, Brazil, Japan, Korea, the United States… The world is in one small classroom. Kenji smiles at her. \"Your English is very good, Carmen.\" \"Thank you! I''m learning.\"","translation":"En la clase de inglés de Carmen hay estudiantes de muchos países. El señor Park les pregunta a todos: «¿De dónde son?». Ana dice: «Soy de Brasil. Soy brasileña. Hablo portugués.» Un hombre callado dice: «Soy Kenji. Soy de Japón. Hablo japonés y un poco de inglés.» «¿Y tú, Carmen?» «Soy de México, de Guadalajara. Hablo español.» «¿Usted es de Canadá, señor Park?», pregunta Ana. «No. Soy estadounidense. Pero mis padres son de Corea.» Carmen piensa: México, Brasil, Japón, Corea, Estados Unidos… El mundo está en un salón pequeño. Kenji le sonríe. «Tu inglés es muy bueno, Carmen.» «¡Gracias! Estoy aprendiendo.»","translations":{"es":"En la clase de inglés de Carmen hay estudiantes de muchos países. El señor Park les pregunta a todos: «¿De dónde son?». Ana dice: «Soy de Brasil. Soy brasileña. Hablo portugués.» Un hombre callado dice: «Soy Kenji. Soy de Japón. Hablo japonés y un poco de inglés.» «¿Y tú, Carmen?» «Soy de México, de Guadalajara. Hablo español.» «¿Usted es de Canadá, señor Park?», pregunta Ana. «No. Soy estadounidense. Pero mis padres son de Corea.» Carmen piensa: México, Brasil, Japón, Corea, Estados Unidos… El mundo está en un salón pequeño. Kenji le sonríe. «Tu inglés es muy bueno, Carmen.» «¡Gracias! Estoy aprendiendo.»"},"highlighted_words":["countries","Where are you from","Brazilian","Portuguese","Japanese","Mexico","Spanish","No, I''m not","American","Your English is very good"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Where","are","you","from"],"translation":"¿De dónde eres?","translations":{"es":"¿De dónde eres?"}},{"words":["I","am","from","Guadalajara","Mexico"],"translation":"Soy de Guadalajara, México.","translations":{"es":"Soy de Guadalajara, México."}},{"words":["She","is","not","from","Spain"],"translation":"Ella no es de España.","translations":{"es":"Ella no es de España."}},{"words":["I","speak","a","little","English"],"translation":"Hablo un poco de inglés.","translations":{"es":"Hablo un poco de inglés."}},{"words":["Are","you","Canadian"],"translation":"¿Eres canadiense?","translations":{"es":"¿Eres canadiense?"}},{"words":["My","parents","are","from","Korea"],"translation":"Mis padres son de Corea.","translations":{"es":"Mis padres son de Corea."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Soy de México","translations":{"es":"Soy de México"},"answer":"I am from Mexico"},{"prompt":"¿De dónde eres?","translations":{"es":"¿De dónde eres?"},"answer":"Where are you from"},{"prompt":"Ella es brasileña","translations":{"es":"Ella es brasileña"},"answer":"She is Brazilian"},{"prompt":"Hablo español","translations":{"es":"Hablo español"},"answer":"I speak Spanish"},{"prompt":"Estoy aprendiendo inglés","translations":{"es":"Estoy aprendiendo inglés"},"answer":"I am learning English"},{"prompt":"Él no es estadounidense","translations":{"es":"Él no es estadounidense"},"answer":"He is not American"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 9: Everyday expressions (1)
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-09', 'Everyday expressions (1)', '💬', 'Expresiones cotidianas (1)', 9, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"I know","translation":"sé / lo sé","translations":{"es":"sé / lo sé"}},{"id":"2","word":"I don''t know","translation":"no sé","translations":{"es":"no sé"}},{"id":"3","word":"I understand","translation":"entiendo","translations":{"es":"entiendo"}},{"id":"4","word":"I think so","translation":"creo que sí","translations":{"es":"creo que sí"}},{"id":"5","word":"I don''t think so","translation":"creo que no","translations":{"es":"creo que no"}},{"id":"6","word":"maybe","translation":"quizás / tal vez","translations":{"es":"quizás / tal vez"}},{"id":"7","word":"really?","translation":"¿en serio?","translations":{"es":"¿en serio?"}},{"id":"8","word":"me too","translation":"yo también","translations":{"es":"yo también"}},{"id":"9","word":"me neither","translation":"yo tampoco","translations":{"es":"yo tampoco"}},{"id":"10","word":"okay","translation":"está bien / de acuerdo","translations":{"es":"está bien / de acuerdo"}},{"id":"11","word":"great","translation":"genial","translations":{"es":"genial"}},{"id":"12","word":"wait","translation":"esperar","translations":{"es":"esperar"}},{"id":"13","word":"need","translation":"necesitar","translations":{"es":"necesitar"}},{"id":"14","word":"want","translation":"querer","translations":{"es":"querer"}},{"id":"15","word":"like","translation":"gustar","translations":{"es":"gustar"}},{"id":"16","word":"every day","translation":"todos los días","translations":{"es":"todos los días"}}],"grammar":[{"structure":"I / you / we / they + verb","example":"I drink coffee every morning.","en":"Present simple for habits","es":"Presente simple para hábitos"},{"structure":"don''t + verb","example":"I don''t understand.","en":"Negative: do not → don''t","es":"Negativo: do not → don''t"},{"structure":"Do you…? — Yes, I do. / No, I don''t.","example":"Do you like tea? — Yes, I do.","en":"Questions with \"do\"","es":"Preguntas con «do»"},{"structure":"I think so / I don''t think so","example":"Is it open? — I think so.","en":"Giving an opinion briefly","es":"Dar una opinión breve"},{"structure":"I need / I want","example":"I need help. I want a coffee.","en":"Expressing needs and wishes","es":"Expresar necesidades y deseos"}],"tips":[{"en":"\"I don''t know\" and \"I don''t understand\" are two of the most useful sentences for a beginner. Practice them!","es":"«I don''t know» y «I don''t understand» son dos de las frases más útiles para un principiante. ¡Practícalas!"},{"en":"In questions, \"do\" goes first and the main verb stays simple: Do you speak English? (not \"Do you speaks…\").","es":"En las preguntas, «do» va primero y el verbo principal queda simple: Do you speak English? (no «Do you speaks…»)."},{"en":"\"Okay\" (OK) is used all the time to agree or to show you understand.","es":"«Okay» (OK) se usa todo el tiempo para estar de acuerdo o mostrar que entendiste."},{"en":"\"Really?\" shows surprise or interest, like \"¿En serio?\".","es":"«Really?» muestra sorpresa o interés, como «¿En serio?»."},{"en":"\"Me too\" agrees with a positive sentence; \"Me neither\" agrees with a negative one.","es":"«Me too» (yo también) va con frases afirmativas; «Me neither» (yo tampoco) con negativas."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I don''t understand.","translation":"No entiendo.","translations":{"es":"No entiendo."}},{"phrase":"I don''t know.","translation":"No sé.","translations":{"es":"No sé."}},{"phrase":"Do you speak Spanish?","translation":"¿Hablas español?","translations":{"es":"¿Hablas español?"}},{"phrase":"Yes, I do.","translation":"Sí.","translations":{"es":"Sí."}},{"phrase":"No, I don''t.","translation":"No.","translations":{"es":"No."}},{"phrase":"What does this mean?","translation":"¿Qué significa esto?","translations":{"es":"¿Qué significa esto?"}},{"phrase":"How do you say \"cuchara\" in English?","translation":"¿Cómo se dice «cuchara» en inglés?","translations":{"es":"¿Cómo se dice «cuchara» en inglés?"}},{"phrase":"Wait a minute, please.","translation":"Espera un minuto, por favor.","translations":{"es":"Espera un minuto, por favor."}},{"phrase":"That''s great!","translation":"¡Qué bien!","translations":{"es":"¡Qué bien!"}},{"phrase":"Me too!","translation":"¡Yo también!","translations":{"es":"¡Yo también!"}},{"phrase":"I need help.","translation":"Necesito ayuda.","translations":{"es":"Necesito ayuda."}},{"phrase":"No worries.","translation":"No te preocupes.","translations":{"es":"No te preocupes."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct negative.","options":["I not understand.","I doesn''t understand.","I no understand.","I don''t understand."],"correct":3,"explanation":"With I/you/we/they the negative is \"don''t\" + verb.","translations":{"es":{"question":"Elige la negación correcta.","explanation":"Con I/you/we/they la negación es «don''t» + verbo."}}},{"id":"2","question":"Choose the correct question.","options":["Do you speaks English?","You speak English?","Speak you English?","Do you speak English?"],"correct":3,"explanation":"Questions start with \"Do\" and the verb stays simple.","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Las preguntas empiezan con «Do» y el verbo queda simple."}}},{"id":"3","question":"\"I love chocolate.\" — You love it too. What do you say?","options":["Me neither!","Maybe.","I don''t think so.","Me too!"],"correct":3,"explanation":"To agree with a positive sentence: \"Me too\".","translations":{"es":{"question":"«I love chocolate.» — A ti también te encanta. ¿Qué dices?","explanation":"Para coincidir con una frase afirmativa: «Me too»."}}},{"id":"4","question":"\"I don''t like snow.\" — You don''t like it either. What do you say?","options":["Me too.","Really great.","Yes, I do.","Me neither."],"correct":3,"explanation":"To agree with a negative sentence: \"Me neither\".","translations":{"es":{"question":"«I don''t like snow.» — A ti tampoco te gusta. ¿Qué dices?","explanation":"Para coincidir con una frase negativa: «Me neither»."}}},{"id":"5","question":"You don''t know a word. What do you ask?","options":["What means this?","What this mean?","What is mean this?","What does this mean?"],"correct":3,"explanation":"\"What does this mean?\" is the natural question.","translations":{"es":{"question":"No conoces una palabra. ¿Qué preguntas?","explanation":"«What does this mean?» es la pregunta natural."}}},{"id":"6","question":"Short answer: \"Do you like coffee?\" (you do)","options":["Yes, I am.","Yes, I like.","Yes, do I.","Yes, I do."],"correct":3,"explanation":"Answer with the helper verb: Yes, I do.","translations":{"es":{"question":"Respuesta corta: «Do you like coffee?» (sí te gusta)","explanation":"Se responde con el auxiliar: Yes, I do."}}},{"id":"7","question":"Someone tells you surprising news. What can you say?","options":["Me neither.","Wait a minute.","No problem.","Really?"],"correct":3,"explanation":"\"Really?\" shows surprise.","translations":{"es":{"question":"Alguien te cuenta una noticia sorprendente. ¿Qué puedes decir?","explanation":"«Really?» muestra sorpresa."}}},{"id":"8","question":"Complete: \"We ___ coffee every morning.\"","options":["drinking","drinks","to drink","drink"],"correct":3,"explanation":"With \"we\" the present simple has no -s: we drink.","translations":{"es":{"question":"Completa: «We ___ coffee every morning.»","explanation":"Con «we» el presente simple no lleva -s: we drink."}}}]}'::jsonb, 3),
  ('story', 'How Do You Say…?', '{"text":"Every day after class, Carmen and Ana drink coffee together. They practice English. Today Carmen has a question. \"How do you say ''cuchara'' in English?\" Ana thinks. \"Spoon. I think so… Yes, spoon.\" \"And what does ''awesome'' mean? My grandson says it every day.\" Ana laughs. \"It means ''great'' or ''very good''.\" \"Okay! This coffee is awesome!\" A waiter comes to the table. He speaks very fast. Carmen and Ana look at each other. \"Sorry, I don''t understand,\" says Carmen. The waiter speaks again, slowly: \"Do you need anything else?\" \"Oh! No, thank you. We don''t need anything.\" Ana says, \"I love this place.\" \"Me too!\" says Carmen. \"And I love our English practice.\"","translation":"Todos los días después de clase, Carmen y Ana toman café juntas. Practican inglés. Hoy Carmen tiene una pregunta. «¿Cómo se dice “cuchara” en inglés?» Ana piensa. «Spoon. Creo que sí… Sí, spoon.» «¿Y qué significa “awesome”? Mi nieto lo dice todos los días.» Ana se ríe. «Significa “genial” o “muy bueno”.» «¡Bueno! ¡Este café es awesome!» Un mesero viene a la mesa. Habla muy rápido. Carmen y Ana se miran. «Perdón, no entiendo», dice Carmen. El mesero habla otra vez, despacio: «¿Necesitan algo más?» «¡Ah! No, gracias. No necesitamos nada.» Ana dice: «Me encanta este lugar.» «¡A mí también!», dice Carmen. «Y me encanta nuestra práctica de inglés.»","translations":{"es":"Todos los días después de clase, Carmen y Ana toman café juntas. Practican inglés. Hoy Carmen tiene una pregunta. «¿Cómo se dice “cuchara” en inglés?» Ana piensa. «Spoon. Creo que sí… Sí, spoon.» «¿Y qué significa “awesome”? Mi nieto lo dice todos los días.» Ana se ríe. «Significa “genial” o “muy bueno”.» «¡Bueno! ¡Este café es awesome!» Un mesero viene a la mesa. Habla muy rápido. Carmen y Ana se miran. «Perdón, no entiendo», dice Carmen. El mesero habla otra vez, despacio: «¿Necesitan algo más?» «¡Ah! No, gracias. No necesitamos nada.» Ana dice: «Me encanta este lugar.» «¡A mí también!», dice Carmen. «Y me encanta nuestra práctica de inglés.»"},"highlighted_words":["Every day","How do you say","I think so","what does","mean","Okay","I don''t understand","Do you need","Me too"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","do","not","understand"],"translation":"No entiendo.","translations":{"es":"No entiendo."}},{"words":["Do","you","speak","Spanish"],"translation":"¿Hablas español?","translations":{"es":"¿Hablas español?"}},{"words":["What","does","this","word","mean"],"translation":"¿Qué significa esta palabra?","translations":{"es":"¿Qué significa esta palabra?"}},{"words":["We","drink","coffee","every","day"],"translation":"Tomamos café todos los días.","translations":{"es":"Tomamos café todos los días."}},{"words":["I","need","help","with","my","homework"],"translation":"Necesito ayuda con mi tarea.","translations":{"es":"Necesito ayuda con mi tarea."}},{"words":["How","do","you","say","spoon","in","Spanish"],"translation":"¿Cómo se dice «spoon» en español?","translations":{"es":"¿Cómo se dice «spoon» en español?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"No sé","translations":{"es":"No sé"},"answer":"I do not know"},{"prompt":"Necesito ayuda","translations":{"es":"Necesito ayuda"},"answer":"I need help"},{"prompt":"¿Hablas inglés?","translations":{"es":"¿Hablas inglés?"},"answer":"Do you speak English"},{"prompt":"¿Qué significa?","translations":{"es":"¿Qué significa?"},"answer":"What does it mean"},{"prompt":"Yo también","translations":{"es":"Yo también"},"answer":"Me too"},{"prompt":"Espera un minuto, por favor","translations":{"es":"Espera un minuto, por favor"},"answer":"Wait a minute, please"}]}'::jsonb, 6)
) as v(type, title, content, ord);

