insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"work","translation":"trabajar / trabajo","translations":{"es":"trabajar / trabajo"}},{"id":"2","word":"live","translation":"vivir","translations":{"es":"vivir"}},{"id":"3","word":"go","translation":"ir","translations":{"es":"ir"}},{"id":"4","word":"watch","translation":"mirar / ver (TV)","translations":{"es":"mirar / ver (TV)"}},{"id":"5","word":"play","translation":"jugar / tocar (instrumento)","translations":{"es":"jugar / tocar (instrumento)"}},{"id":"6","word":"drink","translation":"beber / tomar","translations":{"es":"beber / tomar"}},{"id":"7","word":"eat","translation":"comer","translations":{"es":"comer"}},{"id":"8","word":"read","translation":"leer","translations":{"es":"leer"}},{"id":"9","word":"cook","translation":"cocinar","translations":{"es":"cocinar"}},{"id":"10","word":"walk","translation":"caminar","translations":{"es":"caminar"}},{"id":"11","word":"sleep","translation":"dormir","translations":{"es":"dormir"}},{"id":"12","word":"school","translation":"escuela","translations":{"es":"escuela"}},{"id":"13","word":"always","translation":"siempre","translations":{"es":"siempre"}},{"id":"14","word":"never","translation":"nunca","translations":{"es":"nunca"}},{"id":"15","word":"early","translation":"temprano","translations":{"es":"temprano"}},{"id":"16","word":"late","translation":"tarde","translations":{"es":"tarde"}}],"grammar":[{"structure":"he / she / it + verb-s","example":"Leo plays soccer. Linda works at a school.","en":"Present simple with he, she, it: add -s","es":"Presente simple con he, she, it: se agrega -s"},{"structure":"-es after -o, -sh, -ch, -x","example":"She goes, he watches, she fixes","en":"Spelling: -es endings","es":"Ortografía: terminaciones en -es"},{"structure":"has (not \"haves\")","example":"Laura has a new car.","en":"\"Have\" becomes \"has\"","es":"«Have» se convierte en «has»"},{"structure":"doesn''t + verb","example":"Mike doesn''t drink coffee.","en":"Negative with he/she/it","es":"Negativo con he/she/it"},{"structure":"Does he…? — Yes, he does.","example":"Does Leo like school? — Yes, he does.","en":"Questions with he/she/it","es":"Preguntas con he/she/it"}],"tips":[{"en":"The -s with he/she/it is the most common mistake in English. Say it out loud: she works, he lives, it rains.","es":"La -s con he/she/it es el error más común en inglés. Dilo en voz alta: she works, he lives, it rains."},{"en":"With \"doesn''t\" and \"does\", the verb loses its -s: She doesn''t work. Does she work?","es":"Con «doesn''t» y «does», el verbo pierde la -s: She doesn''t work. Does she work?"},{"en":"\"What do you do?\" asks about your job, not what you are doing right now.","es":"«What do you do?» pregunta a qué te dedicas, no qué estás haciendo ahora."},{"en":"\"How''s it going?\", \"What''s up?\" and \"How are things?\" are casual greetings among friends.","es":"«How''s it going?», «What''s up?» y «How are things?» son saludos informales entre amigos."},{"en":"\"Have a good one!\" is a very common, friendly goodbye in the US.","es":"«Have a good one!» es una despedida muy común y amable en Estados Unidos."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What do you do?","translation":"¿A qué te dedicas?","translations":{"es":"¿A qué te dedicas?"}},{"phrase":"She works at a hospital.","translation":"Ella trabaja en un hospital.","translations":{"es":"Ella trabaja en un hospital."}},{"phrase":"Where does he live?","translation":"¿Dónde vive él?","translations":{"es":"¿Dónde vive él?"}},{"phrase":"He lives near here.","translation":"Vive cerca de aquí.","translations":{"es":"Vive cerca de aquí."}},{"phrase":"Does she speak Spanish?","translation":"¿Ella habla español?","translations":{"es":"¿Ella habla español?"}},{"phrase":"Yes, she does.","translation":"Sí, habla.","translations":{"es":"Sí, habla."}},{"phrase":"He doesn''t like vegetables.","translation":"No le gustan las verduras.","translations":{"es":"No le gustan las verduras."}},{"phrase":"What''s up?","translation":"¿Qué onda? / ¿Qué tal?","translations":{"es":"¿Qué onda? / ¿Qué tal?"}},{"phrase":"Not much.","translation":"Nada nuevo.","translations":{"es":"Nada nuevo."}},{"phrase":"Have a good one!","translation":"¡Que te vaya bien!","translations":{"es":"¡Que te vaya bien!"}},{"phrase":"It depends.","translation":"Depende.","translations":{"es":"Depende."}},{"phrase":"Good luck!","translation":"¡Buena suerte!","translations":{"es":"¡Buena suerte!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Leo ___ soccer on Saturdays.\"","options":["to play","plays","playing","play"],"correct":1,"explanation":"Leo = he → add -s: plays.","translations":{"es":{"question":"Completa: «Leo ___ soccer on Saturdays.»","explanation":"Leo = he → se agrega -s: plays."}}},{"id":"2","question":"Complete: \"Laura ___ a new car.\"","options":["has","is have","haves","have"],"correct":0,"explanation":"With he/she/it, \"have\" becomes \"has\".","translations":{"es":{"question":"Completa: «Laura ___ a new car.»","explanation":"Con he/she/it, «have» se convierte en «has»."}}},{"id":"3","question":"Choose the correct negative.","options":["Mike doesn''t drink coffee.","Mike not drink coffee.","Mike doesn''t drinks coffee.","Mike don''t drink coffee."],"correct":0,"explanation":"He → doesn''t + verb without -s.","translations":{"es":{"question":"Elige la negación correcta.","explanation":"He → doesn''t + verbo sin -s."}}},{"id":"4","question":"Choose the correct question.","options":["She lives here does?","Does she lives here?","Does she live here?","Do she live here?"],"correct":2,"explanation":"She → Does + verb without -s.","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"She → Does + verbo sin -s."}}},{"id":"5","question":"Complete: \"My grandson ___ TV every evening.\"","options":["watch","watching","watches","watchs"],"correct":2,"explanation":"Verbs ending in -ch add -es: watches.","translations":{"es":{"question":"Completa: «My grandson ___ TV every evening.»","explanation":"Los verbos que terminan en -ch agregan -es: watches."}}},{"id":"6","question":"Someone asks \"What do you do?\". What do they want to know?","options":["Your name","Where you live","Your job","What you are doing now"],"correct":2,"explanation":"\"What do you do?\" asks about your work.","translations":{"es":{"question":"Alguien pregunta «What do you do?». ¿Qué quiere saber?","explanation":"«What do you do?» pregunta por tu trabajo."}}},{"id":"7","question":"Short answer: \"Does Linda work at a school?\" (yes)","options":["Yes, does she.","Yes, she do.","Yes, she does.","Yes, she works."],"correct":2,"explanation":"Use the helper verb: Yes, she does.","translations":{"es":{"question":"Respuesta corta: «Does Linda work at a school?» (sí)","explanation":"Se usa el auxiliar: Yes, she does."}}},{"id":"8","question":"Complete: \"She ___ to work by bus.\"","options":["goes","go","going","gos"],"correct":0,"explanation":"\"Go\" ends in -o, so it takes -es: goes.","translations":{"es":{"question":"Completa: «She ___ to work by bus.»","explanation":"«Go» termina en -o, así que lleva -es: goes."}}}]}'::jsonb, 3),
  ('story', 'A Day in the Family', '{"text":"In Carmen''s new class, the homework is easy: write about your family. Carmen sits at the kitchen table and writes. \"My daughter Laura is a nurse. She works at a hospital. She goes to work very early, at six. Her husband, Mike, is a mechanic. He fixes cars all day. He doesn''t drink coffee, he always drinks tea. My grandson Leo goes to school near the house. He plays soccer and he watches cartoons. He never eats vegetables! And me? I live in San Diego now. I cook, I walk on the beach, and I study English.\" Leo reads it. \"Grandma, it''s perfect! But I eat vegetables… sometimes.\" Carmen laughs. \"Sometimes is not every day, my love.\"","translation":"En la nueva clase de Carmen la tarea es fácil: escribir sobre tu familia. Carmen se sienta a la mesa de la cocina y escribe. «Mi hija Laura es enfermera. Trabaja en un hospital. Se va a trabajar muy temprano, a las seis. Su esposo, Mike, es mecánico. Arregla autos todo el día. No toma café, siempre toma té. Mi nieto Leo va a la escuela cerca de la casa. Juega fútbol y ve caricaturas. ¡Nunca come verduras! ¿Y yo? Ahora vivo en San Diego. Cocino, camino por la playa y estudio inglés.» Leo lo lee. «¡Abuela, está perfecto! Pero sí como verduras… a veces.» Carmen se ríe. «A veces no es todos los días, mi amor.»","translations":{"es":"En la nueva clase de Carmen la tarea es fácil: escribir sobre tu familia. Carmen se sienta a la mesa de la cocina y escribe. «Mi hija Laura es enfermera. Trabaja en un hospital. Se va a trabajar muy temprano, a las seis. Su esposo, Mike, es mecánico. Arregla autos todo el día. No toma café, siempre toma té. Mi nieto Leo va a la escuela cerca de la casa. Juega fútbol y ve caricaturas. ¡Nunca come verduras! ¿Y yo? Ahora vivo en San Diego. Cocino, camino por la playa y estudio inglés.» Leo lo lee. «¡Abuela, está perfecto! Pero sí como verduras… a veces.» Carmen se ríe. «A veces no es todos los días, mi amor.»"},"highlighted_words":["She works","goes","early","fixes","He doesn''t drink","always drinks","plays","watches","never eats","I live","I cook","I walk"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["She","works","at","a","hospital"],"translation":"Ella trabaja en un hospital.","translations":{"es":"Ella trabaja en un hospital."}},{"words":["He","does","not","drink","coffee"],"translation":"Él no toma café.","translations":{"es":"Él no toma café."}},{"words":["Does","she","speak","Spanish"],"translation":"¿Ella habla español?","translations":{"es":"¿Ella habla español?"}},{"words":["Leo","plays","soccer","on","Saturdays"],"translation":"Leo juega fútbol los sábados.","translations":{"es":"Leo juega fútbol los sábados."}},{"words":["Where","does","your","daughter","live"],"translation":"¿Dónde vive tu hija?","translations":{"es":"¿Dónde vive tu hija?"}},{"words":["My","grandson","never","eats","vegetables"],"translation":"Mi nieto nunca come verduras.","translations":{"es":"Mi nieto nunca come verduras."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Ella trabaja en una escuela","translations":{"es":"Ella trabaja en una escuela"},"answer":"She works at a school"},{"prompt":"Él vive cerca de aquí","translations":{"es":"Él vive cerca de aquí"},"answer":"He lives near here"},{"prompt":"¿Él habla inglés?","translations":{"es":"¿Él habla inglés?"},"answer":"Does he speak English"},{"prompt":"A ella no le gusta el café","translations":{"es":"A ella no le gusta el café"},"answer":"She does not like coffee"},{"prompt":"Leo va a la escuela","translations":{"es":"Leo va a la escuela"},"answer":"Leo goes to school"},{"prompt":"Mi hija tiene un auto","translations":{"es":"Mi hija tiene un auto"},"answer":"My daughter has a car"}]}'::jsonb, 6)
) as v(type, title, content, ord);

