select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"head","translation":"cabeza","translations":{"es":"cabeza"}},{"id":"2","word":"hair","translation":"pelo / cabello","translations":{"es":"pelo / cabello"}},{"id":"3","word":"face","translation":"cara","translations":{"es":"cara"}},{"id":"4","word":"eyes","translation":"ojos","translations":{"es":"ojos"}},{"id":"5","word":"ears","translation":"orejas / oídos","translations":{"es":"orejas / oídos"}},{"id":"6","word":"nose","translation":"nariz","translations":{"es":"nariz"}},{"id":"7","word":"mouth","translation":"boca","translations":{"es":"boca"}},{"id":"8","word":"teeth","translation":"dientes","translations":{"es":"dientes"}},{"id":"9","word":"neck","translation":"cuello","translations":{"es":"cuello"}},{"id":"10","word":"shoulder","translation":"hombro","translations":{"es":"hombro"}},{"id":"11","word":"arm","translation":"brazo","translations":{"es":"brazo"}},{"id":"12","word":"hand","translation":"mano","translations":{"es":"mano"}},{"id":"13","word":"back","translation":"espalda","translations":{"es":"espalda"}},{"id":"14","word":"stomach","translation":"estómago / panza","translations":{"es":"estómago / panza"}},{"id":"15","word":"leg","translation":"pierna","translations":{"es":"pierna"}},{"id":"16","word":"knee","translation":"rodilla","translations":{"es":"rodilla"}},{"id":"17","word":"feet","translation":"pies","translations":{"es":"pies"}},{"id":"18","word":"headache","translation":"dolor de cabeza","translations":{"es":"dolor de cabeza"}},{"id":"19","word":"cold","translation":"resfriado / frío","translations":{"es":"resfriado / frío"}}],"grammar":[{"structure":"have / has","example":"I have brown eyes. She has long hair.","en":"Describing people with have/has","es":"Describir personas con have/has"},{"structure":"my … hurts / my … hurt","example":"My back hurts. My feet hurt.","en":"Talking about pain","es":"Hablar de dolor"},{"structure":"I have a headache / a cold","example":"I have a headache.","en":"Common health problems with \"have\"","es":"Problemas de salud comunes con «have»"},{"structure":"Irregular plurals","example":"one foot → two feet, one tooth → two teeth","en":"Some body words have irregular plurals","es":"Algunas partes del cuerpo tienen plural irregular"},{"structure":"What''s wrong?","example":"What''s wrong? — My knee hurts.","en":"Asking about a problem","es":"Preguntar qué le pasa a alguien"}],"tips":[{"en":"In English we use \"my\", not \"the\": \"My head hurts\" (not \"The head hurts me\").","es":"En inglés se usa «my», no «the»: «My head hurts» (no «The head hurts me»)."},{"en":"\"Hair\" is usually uncountable: \"She has long hair\" (no \"a\", no -s).","es":"«Hair» normalmente es incontable: «She has long hair» (sin «a» y sin -s)."},{"en":"\"-ache\" means continuous pain: headache, stomachache, backache, toothache.","es":"«-ache» significa dolor continuo: headache (cabeza), stomachache (estómago), backache (espalda), toothache (muela)."},{"en":"\"I feel sick\" can mean you feel ill or that you want to vomit; context tells you which.","es":"«I feel sick» puede significar que te sientes mal o que tienes náuseas; el contexto lo aclara."},{"en":"\"Get well soon!\" is what you say or write to someone who is sick.","es":"«Get well soon!» es lo que se dice o escribe a alguien enfermo (¡que te mejores!)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What''s wrong?","translation":"¿Qué te pasa?","translations":{"es":"¿Qué te pasa?"}},{"phrase":"My back hurts.","translation":"Me duele la espalda.","translations":{"es":"Me duele la espalda."}},{"phrase":"I have a headache.","translation":"Me duele la cabeza.","translations":{"es":"Me duele la cabeza."}},{"phrase":"I have a cold.","translation":"Tengo un resfriado.","translations":{"es":"Tengo un resfriado."}},{"phrase":"I don''t feel well.","translation":"No me siento bien.","translations":{"es":"No me siento bien."}},{"phrase":"Take a rest.","translation":"Descansa.","translations":{"es":"Descansa."}},{"phrase":"Get well soon!","translation":"¡Que te mejores!","translations":{"es":"¡Que te mejores!"}},{"phrase":"She has blue eyes.","translation":"Tiene ojos azules.","translations":{"es":"Tiene ojos azules."}},{"phrase":"He has short black hair.","translation":"Tiene el pelo corto y negro.","translations":{"es":"Tiene el pelo corto y negro."}},{"phrase":"Wash your hands.","translation":"Lávate las manos.","translations":{"es":"Lávate las manos."}},{"phrase":"Be careful!","translation":"¡Ten cuidado!","translations":{"es":"¡Ten cuidado!"}},{"phrase":"I feel much better.","translation":"Me siento mucho mejor.","translations":{"es":"Me siento mucho mejor."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say \"Me duele la espalda\"?","options":["The back hurts me.","My back hurts.","I hurt the back.","My back hurt me."],"correct":1,"explanation":"English uses \"my\" + body part + \"hurts\".","translations":{"es":{"question":"¿Cómo se dice «Me duele la espalda»?","explanation":"En inglés se usa «my» + parte del cuerpo + «hurts»."}}},{"id":"2","question":"What is the plural of \"foot\"?","options":["feets","foots","feet","footes"],"correct":2,"explanation":"\"Foot\" has an irregular plural: feet.","translations":{"es":{"question":"¿Cuál es el plural de «foot»?","explanation":"«Foot» tiene plural irregular: feet."}}},{"id":"3","question":"Choose the correct sentence.","options":["She has long hairs.","She has a long hair.","She has long hair.","She is long hair."],"correct":2,"explanation":"\"Hair\" (on your head) is uncountable: long hair.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"«Hair» (de la cabeza) es incontable: long hair."}}},{"id":"4","question":"You see with your…","options":["ears","hands","eyes","knees"],"correct":2,"explanation":"We see with our eyes and hear with our ears.","translations":{"es":{"question":"Ves con tus…","explanation":"Vemos con los ojos (eyes) y oímos con los oídos (ears)."}}},{"id":"5","question":"Your friend is sick. What do you write?","options":["Nice to meet you!","Have a good one!","Get well soon!","Happy birthday!"],"correct":2,"explanation":"\"Get well soon!\" wishes someone a quick recovery.","translations":{"es":{"question":"Tu amiga está enferma. ¿Qué le escribes?","explanation":"«Get well soon!» le desea a alguien una pronta recuperación."}}},{"id":"6","question":"Complete: \"My feet ___.\"","options":["hurt","hurting","hurts","are hurt me"],"correct":0,"explanation":"\"Feet\" is plural, so the verb has no -s: my feet hurt.","translations":{"es":{"question":"Completa: «My feet ___.»","explanation":"«Feet» es plural, así que el verbo va sin -s: my feet hurt."}}},{"id":"7","question":"Which one is a pain in your head?","options":["backache","headache","stomachache","toothache"],"correct":1,"explanation":"Head + ache = headache.","translations":{"es":{"question":"¿Cuál es un dolor en la cabeza?","explanation":"Head + ache = headache."}}},{"id":"8","question":"Someone looks sad and tired. What can you ask?","options":["What''s wrong?","Where are you from?","What do you do?","How old are you?"],"correct":0,"explanation":"\"What''s wrong?\" asks about a problem.","translations":{"es":{"question":"Alguien se ve triste y cansado. ¿Qué puedes preguntar?","explanation":"«What''s wrong?» pregunta qué problema tiene."}}}]}'::jsonb, 3),
  ('story', 'A Bad Back', '{"text":"This morning Carmen gets up slowly. Her back hurts. She has a headache too. Leo comes into the kitchen. \"Grandma, what''s wrong?\" \"Oh, my back hurts, and I have a headache. I don''t feel well.\" Leo puts his small hand on her shoulder. \"Take a rest, Grandma. I can make breakfast.\" Carmen smiles. Leo makes toast and a cup of tea. It is not perfect, but it is made with love. In the afternoon Linda calls. \"I have a cold,\" says Linda. \"My nose is red and my eyes hurt.\" \"Oh no! Get well soon, Linda!\" \"You too!\" In the evening, Carmen feels much better. \"Leo,\" she says, \"you are a very good nurse, like your mother.\"","translation":"Esta mañana Carmen se levanta despacio. Le duele la espalda. También le duele la cabeza. Leo entra a la cocina. «Abuela, ¿qué te pasa?» «Ay, me duele la espalda y me duele la cabeza. No me siento bien.» Leo pone su mano pequeña en el hombro de ella. «Descansa, abuela. Yo puedo hacer el desayuno.» Carmen sonríe. Leo hace pan tostado y una taza de té. No es perfecto, pero está hecho con amor. En la tarde llama Linda. «Tengo un resfriado», dice Linda. «Tengo la nariz roja y me duelen los ojos.» «¡Ay, no! ¡Que te mejores, Linda!» «¡Tú también!» En la noche, Carmen se siente mucho mejor. «Leo», dice, «eres un muy buen enfermero, como tu mamá.»","translations":{"es":"Esta mañana Carmen se levanta despacio. Le duele la espalda. También le duele la cabeza. Leo entra a la cocina. «Abuela, ¿qué te pasa?» «Ay, me duele la espalda y me duele la cabeza. No me siento bien.» Leo pone su mano pequeña en el hombro de ella. «Descansa, abuela. Yo puedo hacer el desayuno.» Carmen sonríe. Leo hace pan tostado y una taza de té. No es perfecto, pero está hecho con amor. En la tarde llama Linda. «Tengo un resfriado», dice Linda. «Tengo la nariz roja y me duelen los ojos.» «¡Ay, no! ¡Que te mejores, Linda!» «¡Tú también!» En la noche, Carmen se siente mucho mejor. «Leo», dice, «eres un muy buen enfermero, como tu mamá.»"},"highlighted_words":["Her back hurts","headache","what''s wrong","I don''t feel well","hand","shoulder","Take a rest","I have a cold","nose","eyes","Get well soon","feels much better"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["My","back","hurts","a","lot"],"translation":"Me duele mucho la espalda.","translations":{"es":"Me duele mucho la espalda."}},{"words":["I","have","a","terrible","headache"],"translation":"Tengo un dolor de cabeza terrible.","translations":{"es":"Tengo un dolor de cabeza terrible."}},{"words":["She","has","long","black","hair"],"translation":"Ella tiene el pelo largo y negro.","translations":{"es":"Ella tiene el pelo largo y negro."}},{"words":["What","is","wrong","with","your","knee"],"translation":"¿Qué le pasa a tu rodilla?","translations":{"es":"¿Qué le pasa a tu rodilla?"}},{"words":["I","feel","much","better","today"],"translation":"Hoy me siento mucho mejor.","translations":{"es":"Hoy me siento mucho mejor."}},{"words":["Wash","your","hands","before","dinner"],"translation":"Lávate las manos antes de cenar.","translations":{"es":"Lávate las manos antes de cenar."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Me duele la espalda","translations":{"es":"Me duele la espalda"},"answer":"My back hurts"},{"prompt":"Me duele la cabeza","translations":{"es":"Me duele la cabeza"},"answer":"I have a headache"},{"prompt":"Ella tiene ojos azules","translations":{"es":"Ella tiene ojos azules"},"answer":"She has blue eyes"},{"prompt":"No me siento bien","translations":{"es":"No me siento bien"},"answer":"I do not feel well"},{"prompt":"Que te mejores","translations":{"es":"Que te mejores"},"answer":"Get well soon"},{"prompt":"Me duelen los pies","translations":{"es":"Me duelen los pies"},"answer":"My feet hurt"}]}'::jsonb, 6)
) as v(type, title, content, ord);

