insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"teacher","translation":"maestro / profesor","translations":{"es":"maestro / profesor"}},{"id":"2","word":"doctor","translation":"médico / doctor","translations":{"es":"médico / doctor"}},{"id":"3","word":"nurse","translation":"enfermero / enfermera","translations":{"es":"enfermero / enfermera"}},{"id":"4","word":"mechanic","translation":"mecánico","translations":{"es":"mecánico"}},{"id":"5","word":"cook","translation":"cocinero","translations":{"es":"cocinero"}},{"id":"6","word":"baker","translation":"panadero","translations":{"es":"panadero"}},{"id":"7","word":"engineer","translation":"ingeniero","translations":{"es":"ingeniero"}},{"id":"8","word":"lawyer","translation":"abogado","translations":{"es":"abogado"}},{"id":"9","word":"salesperson","translation":"vendedor","translations":{"es":"vendedor"}},{"id":"10","word":"cashier","translation":"cajero","translations":{"es":"cajero"}},{"id":"11","word":"driver","translation":"conductor / chofer","translations":{"es":"conductor / chofer"}},{"id":"12","word":"accountant","translation":"contador","translations":{"es":"contador"}},{"id":"13","word":"hairdresser","translation":"peluquero / estilista","translations":{"es":"peluquero / estilista"}},{"id":"14","word":"office","translation":"oficina","translations":{"es":"oficina"}},{"id":"15","word":"boss","translation":"jefe / jefa","translations":{"es":"jefe / jefa"}},{"id":"16","word":"retired","translation":"jubilado","translations":{"es":"jubilado"}},{"id":"17","word":"part-time","translation":"medio tiempo","translations":{"es":"medio tiempo"}}],"grammar":[{"structure":"a / an + job","example":"She is a nurse. He is an engineer.","en":"Jobs need \"a\" or \"an\"","es":"Las profesiones llevan «a» o «an»"},{"structure":"What do you do?","example":"What do you do? — I''m a teacher.","en":"Asking about someone''s job","es":"Preguntar a qué se dedica alguien"},{"structure":"work at / work in / work for","example":"I work at a bakery. She works in a hospital. He works for a big company.","en":"Prepositions with \"work\"","es":"Preposiciones con «work»"},{"structure":"retired / unemployed / part-time","example":"I''m retired. She works part-time.","en":"Describing your work situation","es":"Describir tu situación laboral"},{"structure":"like + verb-ing","example":"I like working with people.","en":"Talking about what you like in a job","es":"Hablar de lo que te gusta de un trabajo"}],"tips":[{"en":"Never forget the article: \"I''m a teacher\", not \"I''m teacher\". This is very different from Spanish.","es":"No olvides el artículo: «I''m a teacher», no «I''m teacher». Es muy diferente del español."},{"en":"Many job names don''t change for men and women: a teacher, a doctor, a nurse.","es":"Muchas profesiones no cambian para hombres y mujeres: a teacher, a doctor, a nurse."},{"en":"\"Retired\" (jubilado) is a common and respected answer to \"What do you do?\".","es":"«Retired» (jubilado/a) es una respuesta común y respetada a «What do you do?»."},{"en":"\"Job\" is a specific position; \"work\" is more general: I love my job. I go to work.","es":"«Job» es un puesto concreto; «work» es más general: I love my job. I go to work."},{"en":"In the US, people often ask \"What do you do?\" soon after meeting. It''s normal small talk.","es":"En Estados Unidos es común preguntar «What do you do?» poco después de conocerse. Es charla normal."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What do you do?","translation":"¿A qué te dedicas?","translations":{"es":"¿A qué te dedicas?"}},{"phrase":"I''m a nurse.","translation":"Soy enfermera.","translations":{"es":"Soy enfermera."}},{"phrase":"Where do you work?","translation":"¿Dónde trabajas?","translations":{"es":"¿Dónde trabajas?"}},{"phrase":"I work at a bakery.","translation":"Trabajo en una panadería.","translations":{"es":"Trabajo en una panadería."}},{"phrase":"I''m retired.","translation":"Estoy jubilada.","translations":{"es":"Estoy jubilada."}},{"phrase":"I was a teacher for thirty years.","translation":"Fui maestra durante treinta años.","translations":{"es":"Fui maestra durante treinta años."}},{"phrase":"Do you like your job?","translation":"¿Te gusta tu trabajo?","translations":{"es":"¿Te gusta tu trabajo?"}},{"phrase":"I love working with children.","translation":"Me encanta trabajar con niños.","translations":{"es":"Me encanta trabajar con niños."}},{"phrase":"She works part-time.","translation":"Ella trabaja medio tiempo.","translations":{"es":"Ella trabaja medio tiempo."}},{"phrase":"He works from home.","translation":"Él trabaja desde casa.","translations":{"es":"Él trabaja desde casa."}},{"phrase":"It''s a hard job.","translation":"Es un trabajo duro.","translations":{"es":"Es un trabajo duro."}},{"phrase":"What time do you start work?","translation":"¿A qué hora empiezas a trabajar?","translations":{"es":"¿A qué hora empiezas a trabajar?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence.","options":["She is nurse.","She is an nurse.","She nurse is.","She is a nurse."],"correct":3,"explanation":"Jobs need an article in English: a nurse.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"En inglés las profesiones llevan artículo: a nurse."}}},{"id":"2","question":"Complete: \"He is ___ engineer.\"","options":["the a","a","one","an"],"correct":3,"explanation":"\"Engineer\" starts with a vowel sound → an.","translations":{"es":{"question":"Completa: «He is ___ engineer.»","explanation":"«Engineer» empieza con sonido de vocal → an."}}},{"id":"3","question":"Who fixes cars?","options":["a baker","a lawyer","a nurse","a mechanic"],"correct":3,"explanation":"A mechanic fixes cars.","translations":{"es":{"question":"¿Quién arregla autos?","explanation":"Un mecánico (mechanic) arregla autos."}}},{"id":"4","question":"Who makes bread?","options":["a driver","an accountant","a cashier","a baker"],"correct":3,"explanation":"A baker makes bread in a bakery.","translations":{"es":{"question":"¿Quién hace pan?","explanation":"Un panadero (baker) hace pan en una panadería (bakery)."}}},{"id":"5","question":"You don''t work anymore because of your age. You are…","options":["busy","a boss","part-time","retired"],"correct":3,"explanation":"\"Retired\" means you stopped working, usually because of age.","translations":{"es":{"question":"Ya no trabajas por tu edad. Estás…","explanation":"«Retired» significa que dejaste de trabajar, normalmente por la edad."}}},{"id":"6","question":"Complete: \"I work ___ a big company.\"","options":["from","to","of","for"],"correct":3,"explanation":"We say \"work for\" a company (the employer).","translations":{"es":{"question":"Completa: «I work ___ a big company.»","explanation":"Se dice «work for» una empresa (el empleador)."}}},{"id":"7","question":"Which answer fits \"What do you do?\"","options":["I''m fine, thanks.","I''m from Mexico.","I''m doing homework.","I''m an accountant."],"correct":3,"explanation":"The question asks about your job.","translations":{"es":{"question":"¿Qué respuesta va con «What do you do?»?","explanation":"La pregunta es sobre tu trabajo."}}},{"id":"8","question":"Complete: \"I like ___ with people.\"","options":["to working","work","works","working"],"correct":3,"explanation":"After \"like\" we often use verb + -ing: I like working.","translations":{"es":{"question":"Completa: «I like ___ with people.»","explanation":"Después de «like» se suele usar verbo + -ing: I like working."}}}]}'::jsonb, 3),
  ('story', 'Thirty Years of Teaching', '{"text":"At the park, Carmen meets Linda''s friend Tom. Tom is a driver. He drives a school bus. \"Nice to meet you, Carmen. What do you do?\" Carmen thinks for a moment. \"I''m retired. I was a teacher in Mexico for thirty years.\" \"A teacher! That''s a hard job.\" \"Yes, but I love working with children.\" Linda says, \"Carmen is a great cook too. Her tamales are amazing.\" Tom laughs. \"My wife is a baker. She works at a bakery on Fifth Avenue. Maybe she needs a cook.\" \"Really?\" says Carmen. \"I don''t want a full-time job, but part-time… maybe.\" Tom writes a phone number on a paper. \"Call her. Her name is Grace.\" Carmen puts the paper in her bag. Maybe retired is not forever.","translation":"En el parque, Carmen conoce a Tom, un amigo de Linda. Tom es chofer. Maneja un autobús escolar. «Mucho gusto, Carmen. ¿A qué te dedicas?» Carmen piensa un momento. «Estoy jubilada. Fui maestra en México durante treinta años.» «¡Maestra! Es un trabajo duro.» «Sí, pero me encanta trabajar con niños.» Linda dice: «Carmen también es una gran cocinera. Sus tamales son increíbles.» Tom se ríe. «Mi esposa es panadera. Trabaja en una panadería en la Quinta Avenida. Quizás necesita una cocinera.» «¿En serio?», dice Carmen. «No quiero un trabajo de tiempo completo, pero de medio tiempo… quizás.» Tom escribe un número de teléfono en un papel. «Llámala. Se llama Grace.» Carmen guarda el papel en su bolsa. Quizás jubilada no es para siempre.","translations":{"es":"En el parque, Carmen conoce a Tom, un amigo de Linda. Tom es chofer. Maneja un autobús escolar. «Mucho gusto, Carmen. ¿A qué te dedicas?» Carmen piensa un momento. «Estoy jubilada. Fui maestra en México durante treinta años.» «¡Maestra! Es un trabajo duro.» «Sí, pero me encanta trabajar con niños.» Linda dice: «Carmen también es una gran cocinera. Sus tamales son increíbles.» Tom se ríe. «Mi esposa es panadera. Trabaja en una panadería en la Quinta Avenida. Quizás necesita una cocinera.» «¿En serio?», dice Carmen. «No quiero un trabajo de tiempo completo, pero de medio tiempo… quizás.» Tom escribe un número de teléfono en un papel. «Llámala. Se llama Grace.» Carmen guarda el papel en su bolsa. Quizás jubilada no es para siempre."},"highlighted_words":["a driver","What do you do","I''m retired","a teacher","a hard job","I love working with children","cook","baker","works at a bakery","part-time"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["What","do","you","do"],"translation":"¿A qué te dedicas?","translations":{"es":"¿A qué te dedicas?"}},{"words":["My","daughter","is","a","nurse"],"translation":"Mi hija es enfermera.","translations":{"es":"Mi hija es enfermera."}},{"words":["He","works","for","a","big","company"],"translation":"Él trabaja para una empresa grande.","translations":{"es":"Él trabaja para una empresa grande."}},{"words":["I","love","working","with","children"],"translation":"Me encanta trabajar con niños.","translations":{"es":"Me encanta trabajar con niños."}},{"words":["She","works","part-time","at","a","bakery"],"translation":"Ella trabaja medio tiempo en una panadería.","translations":{"es":"Ella trabaja medio tiempo en una panadería."}},{"words":["I","was","a","teacher","for","thirty","years"],"translation":"Fui maestra durante treinta años.","translations":{"es":"Fui maestra durante treinta años."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Estoy jubilada","translations":{"es":"Estoy jubilada"},"answer":"I am retired"},{"prompt":"Ella es maestra","translations":{"es":"Ella es maestra"},"answer":"She is a teacher"},{"prompt":"¿Dónde trabajas?","translations":{"es":"¿Dónde trabajas?"},"answer":"Where do you work"},{"prompt":"Él es ingeniero","translations":{"es":"Él es ingeniero"},"answer":"He is an engineer"},{"prompt":"Trabajo en una panadería","translations":{"es":"Trabajo en una panadería"},"answer":"I work at a bakery"},{"prompt":"¿Te gusta tu trabajo?","translations":{"es":"¿Te gusta tu trabajo?"},"answer":"Do you like your job"}]}'::jsonb, 6)
) as v(type, title, content, ord);

