insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"furniture","translation":"muebles","translations":{"es":"muebles"}},{"id":"2","word":"sofa","translation":"sofá / sillón","translations":{"es":"sofá / sillón"}},{"id":"3","word":"armchair","translation":"sillón individual","translations":{"es":"sillón individual"}},{"id":"4","word":"table","translation":"mesa","translations":{"es":"mesa"}},{"id":"5","word":"chair","translation":"silla","translations":{"es":"silla"}},{"id":"6","word":"bed","translation":"cama","translations":{"es":"cama"}},{"id":"7","word":"lamp","translation":"lámpara","translations":{"es":"lámpara"}},{"id":"8","word":"closet","translation":"clóset / armario","translations":{"es":"clóset / armario"}},{"id":"9","word":"shelf","translation":"estante / repisa","translations":{"es":"estante / repisa"}},{"id":"10","word":"drawer","translation":"cajón","translations":{"es":"cajón"}},{"id":"11","word":"mirror","translation":"espejo","translations":{"es":"espejo"}},{"id":"12","word":"rug","translation":"tapete / alfombra","translations":{"es":"tapete / alfombra"}},{"id":"13","word":"fridge","translation":"refrigerador","translations":{"es":"refrigerador"}},{"id":"14","word":"stove","translation":"estufa","translations":{"es":"estufa"}},{"id":"15","word":"sink","translation":"fregadero / lavabo","translations":{"es":"fregadero / lavabo"}},{"id":"16","word":"next to","translation":"al lado de","translations":{"es":"al lado de"}},{"id":"17","word":"under","translation":"debajo de","translations":{"es":"debajo de"}},{"id":"18","word":"behind","translation":"detrás de","translations":{"es":"detrás de"}}],"grammar":[{"structure":"in / on / under","example":"The keys are on the table. The cat is under the bed.","en":"Basic prepositions of place","es":"Preposiciones de lugar básicas"},{"structure":"next to / between / behind / in front of","example":"The lamp is next to the sofa.","en":"More prepositions of place","es":"Más preposiciones de lugar"},{"structure":"Where is…? / Where are…?","example":"Where are my glasses?","en":"Asking where things are","es":"Preguntar dónde están las cosas"},{"structure":"It''s / They''re","example":"It''s in the drawer. They''re on the shelf.","en":"Answering about location","es":"Responder dónde está algo"},{"structure":"need / don''t need","example":"I need a table. I don''t need a TV.","en":"Talking about what you need","es":"Hablar de lo que necesitas"}],"tips":[{"en":"\"On\" is for surfaces (on the table, on the wall), \"in\" is for inside something (in the box, in the drawer).","es":"«On» es para superficies (on the table, on the wall) e «in» para dentro de algo (in the box, in the drawer)."},{"en":"\"Furniture\" is uncountable: \"some furniture\" or \"a piece of furniture\", never \"furnitures\".","es":"«Furniture» (muebles) es incontable: «some furniture» o «a piece of furniture», nunca «furnitures»."},{"en":"\"Glasses\" (lentes) is always plural: \"Where are my glasses?\"","es":"«Glasses» (lentes) siempre va en plural: «Where are my glasses?»"},{"en":"\"Closet\" is a small room or cabinet for clothes. In British English it''s often \"wardrobe\".","es":"«Closet» es el armario o vestidor. En inglés británico se suele decir «wardrobe»."},{"en":"Used furniture is cheap at \"yard sales\" and \"thrift stores\" in the US.","es":"En Estados Unidos los muebles usados son baratos en las «yard sales» (ventas de garaje) y las «thrift stores»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Where are my glasses?","translation":"¿Dónde están mis lentes?","translations":{"es":"¿Dónde están mis lentes?"}},{"phrase":"They''re on the table.","translation":"Están en la mesa.","translations":{"es":"Están en la mesa."}},{"phrase":"The keys are in the drawer.","translation":"Las llaves están en el cajón.","translations":{"es":"Las llaves están en el cajón."}},{"phrase":"Put it next to the sofa.","translation":"Ponlo al lado del sofá.","translations":{"es":"Ponlo al lado del sofá."}},{"phrase":"The cat is under the bed.","translation":"El gato está debajo de la cama.","translations":{"es":"El gato está debajo de la cama."}},{"phrase":"I need a new table.","translation":"Necesito una mesa nueva.","translations":{"es":"Necesito una mesa nueva."}},{"phrase":"Can you help me move the sofa?","translation":"¿Me ayudas a mover el sofá?","translations":{"es":"¿Me ayudas a mover el sofá?"}},{"phrase":"It''s too heavy.","translation":"Es demasiado pesado.","translations":{"es":"Es demasiado pesado."}},{"phrase":"Where do you want the lamp?","translation":"¿Dónde quieres la lámpara?","translations":{"es":"¿Dónde quieres la lámpara?"}},{"phrase":"Between the bed and the window.","translation":"Entre la cama y la ventana.","translations":{"es":"Entre la cama y la ventana."}},{"phrase":"The room looks great!","translation":"¡El cuarto se ve genial!","translations":{"es":"¡El cuarto se ve genial!"}},{"phrase":"It''s a little crowded.","translation":"Está un poco lleno.","translations":{"es":"Está un poco lleno."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"The book is ___ the shelf.\"","options":["in","at","on","under"],"correct":2,"explanation":"A shelf is a surface → on the shelf.","translations":{"es":{"question":"Completa: «The book is ___ the shelf.»","explanation":"Una repisa es una superficie → on the shelf."}}},{"id":"2","question":"Complete: \"My socks are ___ the drawer.\"","options":["in","between","on","at"],"correct":0,"explanation":"Inside something → in the drawer.","translations":{"es":{"question":"Completa: «My socks are ___ the drawer.»","explanation":"Dentro de algo → in the drawer."}}},{"id":"3","question":"Which sentence is correct?","options":["I need some new furniture.","I need new furnitures.","I need some new furnitures.","I need a furniture."],"correct":0,"explanation":"\"Furniture\" is uncountable: some furniture.","translations":{"es":{"question":"¿Qué oración es correcta?","explanation":"«Furniture» es incontable: some furniture."}}},{"id":"4","question":"Where do you keep milk cold?","options":["under the bed","in the fridge","in the closet","on the stove"],"correct":1,"explanation":"The fridge keeps food cold.","translations":{"es":{"question":"¿Dónde mantienes fría la leche?","explanation":"El refrigerador (fridge) mantiene fría la comida."}}},{"id":"5","question":"Choose the correct question.","options":["Where are my keys?","Where are my key?","Where is my keys?","Where my keys are?"],"correct":0,"explanation":"\"Keys\" is plural → Where are…?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"«Keys» es plural → Where are…?"}}},{"id":"6","question":"The lamp is ___ the bed and the window.","options":["between","next","under to","behind of"],"correct":0,"explanation":"\"Between\" = in the middle of two things.","translations":{"es":{"question":"La lámpara está ___ la cama y la ventana.","explanation":"«Between» = en medio de dos cosas."}}},{"id":"7","question":"You look at yourself in a…","options":["drawer","mirror","sink","rug"],"correct":1,"explanation":"A mirror shows your reflection.","translations":{"es":{"question":"Te miras en un…","explanation":"Un espejo (mirror) muestra tu reflejo."}}},{"id":"8","question":"The sofa is very heavy. What do you say?","options":["It''s too heavy. Can you help me?","It''s too easy.","It''s under heavy.","It''s next to."],"correct":0,"explanation":"\"Too heavy\" = more than you can carry alone.","translations":{"es":{"question":"El sofá pesa mucho. ¿Qué dices?","explanation":"«Too heavy» = más de lo que puedes cargar solo."}}}]}'::jsonb, 3),
  ('story', 'Moving Day', '{"text":"Today is moving day! Carmen has her new apartment. Mike and Leo help her with the furniture. \"Where do you want the sofa, Mom?\" asks Mike. \"In front of the window, please.\" Mike and Leo carry the sofa. \"It''s too heavy!\" says Leo. Next to the sofa there is a small table and a lamp. In the bedroom, the bed is between two windows, and there is a big mirror behind the door. \"Grandma, where are your glasses?\" asks Leo. Carmen looks on the table, in her bag, under the chair… Leo laughs. \"They''re on your head!\" Everybody laughs. At the end of the day, the apartment is a little crowded, but it looks great. Carmen makes coffee in her new kitchen. Her first coffee at home.","translation":"¡Hoy es el día de la mudanza! Carmen ya tiene su nuevo departamento. Mike y Leo la ayudan con los muebles. «¿Dónde quieres el sofá, suegra?», pregunta Mike. «Frente a la ventana, por favor.» Mike y Leo cargan el sofá. «¡Pesa demasiado!», dice Leo. Al lado del sofá hay una mesita y una lámpara. En el dormitorio, la cama está entre dos ventanas y hay un espejo grande detrás de la puerta. «Abuela, ¿dónde están tus lentes?», pregunta Leo. Carmen busca en la mesa, en su bolsa, debajo de la silla… Leo se ríe. «¡Los tienes en la cabeza!» Todos se ríen. Al final del día, el departamento está un poco lleno, pero se ve genial. Carmen prepara café en su nueva cocina. Su primer café en casa.","translations":{"es":"¡Hoy es el día de la mudanza! Carmen ya tiene su nuevo departamento. Mike y Leo la ayudan con los muebles. «¿Dónde quieres el sofá, suegra?», pregunta Mike. «Frente a la ventana, por favor.» Mike y Leo cargan el sofá. «¡Pesa demasiado!», dice Leo. Al lado del sofá hay una mesita y una lámpara. En el dormitorio, la cama está entre dos ventanas y hay un espejo grande detrás de la puerta. «Abuela, ¿dónde están tus lentes?», pregunta Leo. Carmen busca en la mesa, en su bolsa, debajo de la silla… Leo se ríe. «¡Los tienes en la cabeza!» Todos se ríen. Al final del día, el departamento está un poco lleno, pero se ve genial. Carmen prepara café en su nueva cocina. Su primer café en casa."},"highlighted_words":["furniture","sofa","In front of","too heavy","Next to","lamp","between","mirror","behind","where are your glasses","on the table","under the chair","crowded"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["The","keys","are","in","the","drawer"],"translation":"Las llaves están en el cajón.","translations":{"es":"Las llaves están en el cajón."}},{"words":["Put","the","lamp","next","to","the","sofa"],"translation":"Pon la lámpara al lado del sofá.","translations":{"es":"Pon la lámpara al lado del sofá."}},{"words":["Where","are","my","glasses"],"translation":"¿Dónde están mis lentes?","translations":{"es":"¿Dónde están mis lentes?"}},{"words":["The","cat","is","under","the","bed"],"translation":"El gato está debajo de la cama.","translations":{"es":"El gato está debajo de la cama."}},{"words":["I","need","a","new","table","for","the","kitchen"],"translation":"Necesito una mesa nueva para la cocina.","translations":{"es":"Necesito una mesa nueva para la cocina."}},{"words":["The","mirror","is","behind","the","door"],"translation":"El espejo está detrás de la puerta.","translations":{"es":"El espejo está detrás de la puerta."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"El libro está en la mesa","translations":{"es":"El libro está en la mesa"},"answer":"The book is on the table"},{"prompt":"¿Dónde están mis llaves?","translations":{"es":"¿Dónde están mis llaves?"},"answer":"Where are my keys"},{"prompt":"Necesito un sofá nuevo","translations":{"es":"Necesito un sofá nuevo"},"answer":"I need a new sofa"},{"prompt":"Es demasiado pesado","translations":{"es":"Es demasiado pesado"},"answer":"It is too heavy"},{"prompt":"El gato está debajo de la cama","translations":{"es":"El gato está debajo de la cama"},"answer":"The cat is under the bed"},{"prompt":"La lámpara está al lado de la cama","translations":{"es":"La lámpara está al lado de la cama"},"answer":"The lamp is next to the bed"}]}'::jsonb, 6)
) as v(type, title, content, ord);

