insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"dog","translation":"perro","translations":{"es":"perro"}},{"id":"2","word":"cat","translation":"gato","translations":{"es":"gato"}},{"id":"3","word":"bird","translation":"pájaro","translations":{"es":"pájaro"}},{"id":"4","word":"fish","translation":"pez / pescado","translations":{"es":"pez / pescado"}},{"id":"5","word":"horse","translation":"caballo","translations":{"es":"caballo"}},{"id":"6","word":"cow","translation":"vaca","translations":{"es":"vaca"}},{"id":"7","word":"chicken","translation":"gallina / pollo","translations":{"es":"gallina / pollo"}},{"id":"8","word":"pig","translation":"cerdo","translations":{"es":"cerdo"}},{"id":"9","word":"rabbit","translation":"conejo","translations":{"es":"conejo"}},{"id":"10","word":"mouse","translation":"ratón","translations":{"es":"ratón"}},{"id":"11","word":"lion","translation":"león","translations":{"es":"león"}},{"id":"12","word":"elephant","translation":"elefante","translations":{"es":"elefante"}},{"id":"13","word":"monkey","translation":"mono","translations":{"es":"mono"}},{"id":"14","word":"bear","translation":"oso","translations":{"es":"oso"}},{"id":"15","word":"seal","translation":"foca","translations":{"es":"foca"}},{"id":"16","word":"pet","translation":"mascota","translations":{"es":"mascota"}},{"id":"17","word":"puppy","translation":"cachorro","translations":{"es":"cachorro"}},{"id":"18","word":"zoo","translation":"zoológico","translations":{"es":"zoológico"}}],"grammar":[{"structure":"can + verb","example":"Birds can fly. Dogs can swim.","en":"\"Can\" for ability","es":"«Can» para habilidades (poder / saber)"},{"structure":"can''t + verb","example":"Penguins can''t fly.","en":"Negative: cannot → can''t","es":"Negativo: cannot → can''t"},{"structure":"Can you…? — Yes, I can. / No, I can''t.","example":"Can you swim? — Yes, I can.","en":"Questions with \"can\"","es":"Preguntas con «can»"},{"structure":"can + verb (no -s, no \"to\")","example":"She can cook. (not \"she cans cook\")","en":"\"Can\" never changes","es":"«Can» nunca cambia"},{"structure":"Do you have a pet?","example":"Do you have a pet? — Yes, I have a cat.","en":"Talking about pets","es":"Hablar de mascotas"}],"tips":[{"en":"\"Can\" works for every person: I can, she can, they can. No -s and no \"to\" after it.","es":"«Can» sirve para todas las personas: I can, she can, they can. Sin -s y sin «to» después."},{"en":"\"Can\" also means \"saber hacer algo\": \"I can swim\" = Sé nadar.","es":"«Can» también significa «saber hacer algo»: «I can swim» = Sé nadar."},{"en":"In the US, many people treat pets like family members. A dog is often \"he\" or \"she\", not \"it\".","es":"En Estados Unidos muchas personas tratan a sus mascotas como de la familia. A un perro se le dice «he» o «she», no «it»."},{"en":"\"Puppy\" is a baby dog and \"kitten\" a baby cat.","es":"«Puppy» es un cachorro de perro y «kitten» un gatito."},{"en":"Pronunciation: \"can\" is short and quick; \"can''t\" is longer and stressed.","es":"Pronunciación: «can» es corto y rápido; «can''t» es más largo y con más fuerza."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Do you have a pet?","translation":"¿Tienes mascota?","translations":{"es":"¿Tienes mascota?"}},{"phrase":"I have a dog. His name is Max.","translation":"Tengo un perro. Se llama Max.","translations":{"es":"Tengo un perro. Se llama Max."}},{"phrase":"Can you swim?","translation":"¿Sabes nadar?","translations":{"es":"¿Sabes nadar?"}},{"phrase":"Yes, I can.","translation":"Sí, sé.","translations":{"es":"Sí, sé."}},{"phrase":"No, I can''t.","translation":"No, no sé.","translations":{"es":"No, no sé."}},{"phrase":"Birds can fly.","translation":"Los pájaros pueden volar.","translations":{"es":"Los pájaros pueden volar."}},{"phrase":"Is he friendly?","translation":"¿Es amigable? (el perro)","translations":{"es":"¿Es amigable? (el perro)"}},{"phrase":"Can I pet him?","translation":"¿Puedo acariciarlo?","translations":{"es":"¿Puedo acariciarlo?"}},{"phrase":"I''m afraid of dogs.","translation":"Les tengo miedo a los perros.","translations":{"es":"Les tengo miedo a los perros."}},{"phrase":"What a cute puppy!","translation":"¡Qué cachorro tan lindo!","translations":{"es":"¡Qué cachorro tan lindo!"}},{"phrase":"Let''s go to the zoo.","translation":"Vamos al zoológico.","translations":{"es":"Vamos al zoológico."}},{"phrase":"Don''t feed the animals.","translation":"No alimentes a los animales.","translations":{"es":"No alimentes a los animales."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence.","options":["She can swims.","She can swim.","She cans swim.","She can to swim."],"correct":1,"explanation":"\"Can\" doesn''t change, and the verb after it has no -s and no \"to\".","translations":{"es":{"question":"Elige la oración correcta.","explanation":"«Can» no cambia, y el verbo que le sigue no lleva -s ni «to»."}}},{"id":"2","question":"Which animal can fly?","options":["a bird","a cow","a fish","a pig"],"correct":0,"explanation":"Birds can fly.","translations":{"es":{"question":"¿Qué animal puede volar?","explanation":"Los pájaros (birds) pueden volar."}}},{"id":"3","question":"Short answer: \"Can you cook?\" (yes)","options":["Yes, I can.","Yes, I cook.","Yes, I do.","Yes, can I."],"correct":0,"explanation":"Answer with \"can\": Yes, I can.","translations":{"es":{"question":"Respuesta corta: «Can you cook?» (sí)","explanation":"Se responde con «can»: Yes, I can."}}},{"id":"4","question":"Complete: \"Penguins ___ fly.\"","options":["don''t can","can''t","not can","doesn''t"],"correct":1,"explanation":"The negative of \"can\" is \"can''t\".","translations":{"es":{"question":"Completa: «Penguins ___ fly.»","explanation":"El negativo de «can» es «can''t»."}}},{"id":"5","question":"A baby dog is a…","options":["puppy","kitten","chicken","mouse"],"correct":0,"explanation":"A puppy is a baby dog; a kitten is a baby cat.","translations":{"es":{"question":"Un perro bebé es un…","explanation":"Un «puppy» es un cachorro de perro; un «kitten» es un gatito."}}},{"id":"6","question":"You want to touch your neighbor''s dog. What do you ask?","options":["Can I pet him?","Can I him pet?","I can pet him?","Do I can pet him?"],"correct":0,"explanation":"Questions: Can + I + verb?","translations":{"es":{"question":"Quieres tocar al perro de tu vecino. ¿Qué preguntas?","explanation":"Preguntas: Can + I + verbo?"}}},{"id":"7","question":"How do you say \"Sé nadar\"?","options":["I know swim.","I can swim.","I swim know.","I can to swim."],"correct":1,"explanation":"For abilities English uses \"can\": I can swim.","translations":{"es":{"question":"¿Cómo se dice «Sé nadar»?","explanation":"Para habilidades el inglés usa «can»: I can swim."}}},{"id":"8","question":"Where can you see lions and elephants in a city?","options":["at the bank","at the bakery","at the zoo","at school"],"correct":2,"explanation":"Wild animals live at the zoo in the city.","translations":{"es":{"question":"¿Dónde puedes ver leones y elefantes en una ciudad?","explanation":"En la ciudad, los animales salvajes están en el zoológico (zoo)."}}}]}'::jsonb, 3),
  ('story', 'A Day at the Zoo', '{"text":"On Saturday, Carmen goes to the San Diego Zoo with Leo. The zoo is very big. \"Grandma, look! The monkeys can climb so fast!\" Carmen smiles. \"And look at the elephants. They are enormous.\" Near the water there are seals. \"Can seals swim?\" asks Carmen. \"Yes, they can! And they can sleep in the water,\" says Leo. He knows everything about animals. They see lions, bears and many birds. \"Grandma, can you swim?\" \"Yes, I can. But I can''t climb like a monkey!\" Leo laughs. At the exit, there is a family with a puppy. \"What a cute puppy!\" says Carmen. \"Can I pet him?\" \"Of course. He''s very friendly.\" Leo looks at Carmen. \"Grandma… can we have a pet?\" \"Ask your mother!\"","translation":"El sábado, Carmen va al zoológico de San Diego con Leo. El zoológico es muy grande. «¡Abuela, mira! ¡Los monos pueden trepar muy rápido!» Carmen sonríe. «Y mira los elefantes. Son enormes.» Cerca del agua hay focas. «¿Las focas saben nadar?», pregunta Carmen. «¡Sí! ¡Y pueden dormir en el agua!», dice Leo. Sabe todo sobre los animales. Ven leones, osos y muchos pájaros. «Abuela, ¿tú sabes nadar?» «Sí, sé. ¡Pero no puedo trepar como un mono!» Leo se ríe. A la salida hay una familia con un cachorro. «¡Qué cachorro tan lindo!», dice Carmen. «¿Puedo acariciarlo?» «Claro. Es muy amigable.» Leo mira a Carmen. «Abuela… ¿podemos tener una mascota?» «¡Pregúntale a tu mamá!»","translations":{"es":"El sábado, Carmen va al zoológico de San Diego con Leo. El zoológico es muy grande. «¡Abuela, mira! ¡Los monos pueden trepar muy rápido!» Carmen sonríe. «Y mira los elefantes. Son enormes.» Cerca del agua hay focas. «¿Las focas saben nadar?», pregunta Carmen. «¡Sí! ¡Y pueden dormir en el agua!», dice Leo. Sabe todo sobre los animales. Ven leones, osos y muchos pájaros. «Abuela, ¿tú sabes nadar?» «Sí, sé. ¡Pero no puedo trepar como un mono!» Leo se ríe. A la salida hay una familia con un cachorro. «¡Qué cachorro tan lindo!», dice Carmen. «¿Puedo acariciarlo?» «Claro. Es muy amigable.» Leo mira a Carmen. «Abuela… ¿podemos tener una mascota?» «¡Pregúntale a tu mamá!»"},"highlighted_words":["Zoo","monkeys","can climb","elephants","seals","Can seals swim","they can","lions","bears","birds","can you swim","I can''t climb","puppy","Can I pet him","pet"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Birds","can","fly","very","high"],"translation":"Los pájaros pueden volar muy alto.","translations":{"es":"Los pájaros pueden volar muy alto."}},{"words":["Can","you","swim"],"translation":"¿Sabes nadar?","translations":{"es":"¿Sabes nadar?"}},{"words":["I","have","a","dog","and","two","cats"],"translation":"Tengo un perro y dos gatos.","translations":{"es":"Tengo un perro y dos gatos."}},{"words":["Penguins","cannot","fly"],"translation":"Los pingüinos no pueden volar.","translations":{"es":"Los pingüinos no pueden volar."}},{"words":["Do","you","have","a","pet"],"translation":"¿Tienes mascota?","translations":{"es":"¿Tienes mascota?"}},{"words":["Can","I","pet","your","dog"],"translation":"¿Puedo acariciar a tu perro?","translations":{"es":"¿Puedo acariciar a tu perro?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Sé nadar","translations":{"es":"Sé nadar"},"answer":"I can swim"},{"prompt":"¿Tienes mascota?","translations":{"es":"¿Tienes mascota?"},"answer":"Do you have a pet"},{"prompt":"Los pájaros pueden volar","translations":{"es":"Los pájaros pueden volar"},"answer":"Birds can fly"},{"prompt":"No sé cocinar","translations":{"es":"No sé cocinar"},"answer":"I cannot cook"},{"prompt":"Mi perro es muy amigable","translations":{"es":"Mi perro es muy amigable"},"answer":"My dog is very friendly"},{"prompt":"¿Puedes ayudarme?","translations":{"es":"¿Puedes ayudarme?"},"answer":"Can you help me"}]}'::jsonb, 6)
) as v(type, title, content, ord);

