insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"breakfast","translation":"desayuno","translations":{"es":"desayuno"}},{"id":"2","word":"lunch","translation":"almuerzo / comida","translations":{"es":"almuerzo / comida"}},{"id":"3","word":"dinner","translation":"cena","translations":{"es":"cena"}},{"id":"4","word":"bread","translation":"pan","translations":{"es":"pan"}},{"id":"5","word":"rice","translation":"arroz","translations":{"es":"arroz"}},{"id":"6","word":"beans","translation":"frijoles","translations":{"es":"frijoles"}},{"id":"7","word":"egg","translation":"huevo","translations":{"es":"huevo"}},{"id":"8","word":"cheese","translation":"queso","translations":{"es":"queso"}},{"id":"9","word":"meat","translation":"carne","translations":{"es":"carne"}},{"id":"10","word":"soup","translation":"sopa","translations":{"es":"sopa"}},{"id":"11","word":"sugar","translation":"azúcar","translations":{"es":"azúcar"}},{"id":"12","word":"salt","translation":"sal","translations":{"es":"sal"}},{"id":"13","word":"milk","translation":"leche","translations":{"es":"leche"}},{"id":"14","word":"juice","translation":"jugo","translations":{"es":"jugo"}},{"id":"15","word":"tea","translation":"té","translations":{"es":"té"}},{"id":"16","word":"water","translation":"agua","translations":{"es":"agua"}},{"id":"17","word":"hungry","translation":"hambriento (tener hambre)","translations":{"es":"hambriento (tener hambre)"}},{"id":"18","word":"thirsty","translation":"sediento (tener sed)","translations":{"es":"sediento (tener sed)"}},{"id":"19","word":"delicious","translation":"delicioso","translations":{"es":"delicioso"}}],"grammar":[{"structure":"countable / uncountable","example":"an egg, two eggs / some rice, some milk","en":"Countable and uncountable nouns","es":"Sustantivos contables e incontables"},{"structure":"some (affirmative)","example":"I need some milk and some apples.","en":"\"Some\" in affirmative sentences","es":"«Some» en oraciones afirmativas"},{"structure":"any (negatives and questions)","example":"We don''t have any bread. Do you have any eggs?","en":"\"Any\" in negatives and questions","es":"«Any» en negaciones y preguntas"},{"structure":"I''d like…","example":"I''d like a sandwich, please.","en":"Polite way to order","es":"Forma amable de pedir"},{"structure":"How much / How many","example":"How much sugar? How many eggs?","en":"Quantity: uncountable vs. countable","es":"Cantidad: incontable vs. contable"}],"tips":[{"en":"You can count eggs and apples, but not milk, rice or bread: say \"some bread\" or \"a loaf of bread\".","es":"Puedes contar huevos y manzanas, pero no leche, arroz o pan: se dice «some bread» o «a loaf of bread»."},{"en":"\"I''d like\" (I would like) is softer and more polite than \"I want\".","es":"«I''d like» (me gustaría) es más suave y amable que «I want» (quiero)."},{"en":"In the US, \"dinner\" is the evening meal, usually around 6 or 7 p.m. — earlier than in Mexico.","es":"En Estados Unidos, «dinner» es la comida de la noche, normalmente a las 6 o 7: más temprano que en México."},{"en":"\"Lunch\" is the midday meal; it''s often quick and light.","es":"«Lunch» es la comida del mediodía; suele ser rápida y ligera."},{"en":"\"Chicken\" is both the animal and the meat; \"fish\" too.","es":"«Chicken» es el animal y la carne; «fish» también."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''m hungry.","translation":"Tengo hambre.","translations":{"es":"Tengo hambre."}},{"phrase":"I''m thirsty.","translation":"Tengo sed.","translations":{"es":"Tengo sed."}},{"phrase":"What''s for dinner?","translation":"¿Qué hay de cenar?","translations":{"es":"¿Qué hay de cenar?"}},{"phrase":"I''d like a cup of tea, please.","translation":"Quisiera una taza de té, por favor.","translations":{"es":"Quisiera una taza de té, por favor."}},{"phrase":"Do we have any eggs?","translation":"¿Tenemos huevos?","translations":{"es":"¿Tenemos huevos?"}},{"phrase":"We don''t have any milk.","translation":"No tenemos leche.","translations":{"es":"No tenemos leche."}},{"phrase":"Can you pass the salt, please?","translation":"¿Me pasas la sal, por favor?","translations":{"es":"¿Me pasas la sal, por favor?"}},{"phrase":"This is delicious!","translation":"¡Esto está delicioso!","translations":{"es":"¡Esto está delicioso!"}},{"phrase":"Would you like some more?","translation":"¿Quieres más?","translations":{"es":"¿Quieres más?"}},{"phrase":"No, thanks. I''m full.","translation":"No, gracias. Estoy lleno/a.","translations":{"es":"No, gracias. Estoy lleno/a."}},{"phrase":"Breakfast is ready!","translation":"¡El desayuno está listo!","translations":{"es":"¡El desayuno está listo!"}},{"phrase":"Enjoy your meal!","translation":"¡Buen provecho!","translations":{"es":"¡Buen provecho!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence.","options":["I need two breads.","I need some bread.","I need some breads.","I need a bread."],"correct":1,"explanation":"\"Bread\" is uncountable: some bread.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"«Bread» es incontable: some bread."}}},{"id":"2","question":"Complete: \"We don''t have ___ milk.\"","options":["any","many","a","some"],"correct":0,"explanation":"In negative sentences we use \"any\".","translations":{"es":{"question":"Completa: «We don''t have ___ milk.»","explanation":"En oraciones negativas se usa «any»."}}},{"id":"3","question":"How do you say \"Tengo hambre\"?","options":["I''m hungry.","I''m hunger.","I have hunger.","I have hungry."],"correct":0,"explanation":"English uses \"to be\": I''m hungry, I''m thirsty.","translations":{"es":{"question":"¿Cómo se dice «Tengo hambre»?","explanation":"El inglés usa «to be»: I''m hungry, I''m thirsty."}}},{"id":"4","question":"Which is the most polite way to order?","options":["I want coffee.","I''d like a coffee, please.","Coffee now.","Give me coffee."],"correct":1,"explanation":"\"I''d like…, please\" is polite.","translations":{"es":{"question":"¿Cuál es la forma más amable de pedir?","explanation":"«I''d like…, please» es amable."}}},{"id":"5","question":"Complete: \"How ___ eggs do you need?\"","options":["many","some","any","much"],"correct":0,"explanation":"Eggs are countable → How many.","translations":{"es":{"question":"Completa: «How ___ eggs do you need?»","explanation":"Los huevos son contables → How many."}}},{"id":"6","question":"Complete: \"How ___ sugar do you want?\"","options":["some","a","much","many"],"correct":2,"explanation":"Sugar is uncountable → How much.","translations":{"es":{"question":"Completa: «How ___ sugar do you want?»","explanation":"El azúcar es incontable → How much."}}},{"id":"7","question":"You can''t eat more. What do you say?","options":["Breakfast is ready.","I''m thirsty.","No, thanks. I''m full.","Yes, I''m hungry."],"correct":2,"explanation":"\"I''m full\" means you ate enough.","translations":{"es":{"question":"Ya no puedes comer más. ¿Qué dices?","explanation":"«I''m full» significa que ya comiste suficiente."}}},{"id":"8","question":"What is the evening meal called?","options":["lunch","snack","dinner","breakfast"],"correct":2,"explanation":"Breakfast (morning), lunch (midday), dinner (evening).","translations":{"es":{"question":"¿Cómo se llama la comida de la noche?","explanation":"Breakfast (mañana), lunch (mediodía), dinner (noche)."}}}]}'::jsonb, 3),
  ('story', 'Tamales for Everyone', '{"text":"Grace, the baker, calls Carmen. \"Can you make tamales for our bakery on Friday?\" Carmen is very excited. On Thursday she goes to the supermarket with Laura. \"We need some corn flour, some meat and some cheese,\" says Carmen. \"Do we need any beans?\" asks Laura. \"Yes, a big bag of beans. And we don''t have any salt at home.\" In the evening, the kitchen smells wonderful. Leo comes in. \"I''m hungry! What''s for dinner?\" \"Tamales, but only one for you. The rest are for the bakery!\" On Friday, Grace tries a tamale. \"This is delicious! Can you make one hundred for next week?\" Carmen laughs. \"One hundred? I need a lot of corn flour!\"","translation":"Grace, la panadera, llama a Carmen. «¿Puedes hacer tamales para nuestra panadería el viernes?» Carmen está muy emocionada. El jueves va al supermercado con Laura. «Necesitamos harina de maíz, carne y queso», dice Carmen. «¿Necesitamos frijoles?», pregunta Laura. «Sí, una bolsa grande de frijoles. Y no tenemos sal en casa.» En la noche, la cocina huele maravilloso. Entra Leo. «¡Tengo hambre! ¿Qué hay de cenar?» «Tamales, pero solo uno para ti. ¡Los demás son para la panadería!» El viernes, Grace prueba un tamal. «¡Está delicioso! ¿Puedes hacer cien para la próxima semana?» Carmen se ríe. «¿Cien? ¡Necesito mucha harina de maíz!»","translations":{"es":"Grace, la panadera, llama a Carmen. «¿Puedes hacer tamales para nuestra panadería el viernes?» Carmen está muy emocionada. El jueves va al supermercado con Laura. «Necesitamos harina de maíz, carne y queso», dice Carmen. «¿Necesitamos frijoles?», pregunta Laura. «Sí, una bolsa grande de frijoles. Y no tenemos sal en casa.» En la noche, la cocina huele maravilloso. Entra Leo. «¡Tengo hambre! ¿Qué hay de cenar?» «Tamales, pero solo uno para ti. ¡Los demás son para la panadería!» El viernes, Grace prueba un tamal. «¡Está delicioso! ¿Puedes hacer cien para la próxima semana?» Carmen se ríe. «¿Cien? ¡Necesito mucha harina de maíz!»"},"highlighted_words":["baker","some corn flour","some meat","some cheese","any beans","beans","we don''t have any salt","I''m hungry","What''s for dinner","delicious"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","a","cup","of","tea"],"translation":"Quisiera una taza de té.","translations":{"es":"Quisiera una taza de té."}},{"words":["We","do","not","have","any","milk"],"translation":"No tenemos leche.","translations":{"es":"No tenemos leche."}},{"words":["Do","you","have","any","eggs"],"translation":"¿Tienes huevos?","translations":{"es":"¿Tienes huevos?"}},{"words":["This","soup","is","delicious"],"translation":"Esta sopa está deliciosa.","translations":{"es":"Esta sopa está deliciosa."}},{"words":["Can","you","pass","the","salt","please"],"translation":"¿Me pasas la sal, por favor?","translations":{"es":"¿Me pasas la sal, por favor?"}},{"words":["We","need","some","bread","for","breakfast"],"translation":"Necesitamos pan para el desayuno.","translations":{"es":"Necesitamos pan para el desayuno."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Tengo hambre","translations":{"es":"Tengo hambre"},"answer":"I am hungry"},{"prompt":"Tengo sed","translations":{"es":"Tengo sed"},"answer":"I am thirsty"},{"prompt":"Esto está delicioso","translations":{"es":"Esto está delicioso"},"answer":"This is delicious"},{"prompt":"Necesitamos arroz","translations":{"es":"Necesitamos arroz"},"answer":"We need some rice"},{"prompt":"¿Qué hay de cenar?","translations":{"es":"¿Qué hay de cenar?"},"answer":"What is for dinner"},{"prompt":"No, gracias. Estoy llena","translations":{"es":"No, gracias. Estoy llena"},"answer":"No, thank you. I am full"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 16: Clothes
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-16', 'Clothes', '👕', 'La ropa', 16, true)
  returning id
