insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"shirt","translation":"camisa","translations":{"es":"camisa"}},{"id":"2","word":"T-shirt","translation":"playera / camiseta","translations":{"es":"playera / camiseta"}},{"id":"3","word":"blouse","translation":"blusa","translations":{"es":"blusa"}},{"id":"4","word":"sweater","translation":"suéter","translations":{"es":"suéter"}},{"id":"5","word":"jacket","translation":"chaqueta / chamarra","translations":{"es":"chaqueta / chamarra"}},{"id":"6","word":"coat","translation":"abrigo","translations":{"es":"abrigo"}},{"id":"7","word":"dress","translation":"vestido","translations":{"es":"vestido"}},{"id":"8","word":"skirt","translation":"falda","translations":{"es":"falda"}},{"id":"9","word":"pants","translation":"pantalones","translations":{"es":"pantalones"}},{"id":"10","word":"jeans","translation":"jeans / pantalón de mezclilla","translations":{"es":"jeans / pantalón de mezclilla"}},{"id":"11","word":"shoes","translation":"zapatos","translations":{"es":"zapatos"}},{"id":"12","word":"sneakers","translation":"tenis (zapatos)","translations":{"es":"tenis (zapatos)"}},{"id":"13","word":"socks","translation":"calcetines","translations":{"es":"calcetines"}},{"id":"14","word":"hat","translation":"sombrero / gorro","translations":{"es":"sombrero / gorro"}},{"id":"15","word":"scarf","translation":"bufanda","translations":{"es":"bufanda"}},{"id":"16","word":"size","translation":"talla","translations":{"es":"talla"}},{"id":"17","word":"expensive","translation":"caro","translations":{"es":"caro"}},{"id":"18","word":"cheap","translation":"barato","translations":{"es":"barato"}}],"grammar":[{"structure":"this / that (singular)","example":"I like this dress. That jacket is nice.","en":"\"This\" (near) and \"that\" (far)","es":"«This» (cerca) y «that» (lejos)"},{"structure":"these / those (plural)","example":"These shoes are comfortable. Those jeans are expensive.","en":"Plural forms","es":"Formas en plural"},{"structure":"How much is / are…?","example":"How much is this shirt? How much are these socks?","en":"Asking prices","es":"Preguntar precios"},{"structure":"Can I try it on?","example":"Can I try these pants on?","en":"Trying clothes in a store","es":"Probarse ropa en la tienda"},{"structure":"wear","example":"She always wears a hat.","en":"\"Wear\" = to have clothes on","es":"«Wear» = llevar puesto"}],"tips":[{"en":"Some clothes are always plural: pants, jeans, shorts, glasses, pajamas. Say \"these pants are…\".","es":"Algunas prendas siempre van en plural: pants, jeans, shorts, glasses, pajamas. Se dice «these pants are…»."},{"en":"In American English, \"pants\" are trousers. (In British English, \"pants\" can mean underwear!)","es":"En inglés estadounidense, «pants» son pantalones. (¡En inglés británico «pants» puede significar ropa interior!)"},{"en":"\"Wear\" is for clothes you have on; \"carry\" is for things in your hands, like a bag.","es":"«Wear» es para ropa que llevas puesta; «carry» para cosas en las manos, como una bolsa."},{"en":"\"Fitting room\" is where you try clothes on in a store.","es":"El «fitting room» es el probador de la tienda."},{"en":"US clothing sizes are different from Mexico''s: ask \"What size is this?\" or check the label.","es":"Las tallas en Estados Unidos son distintas a las de México: pregunta «What size is this?» o revisa la etiqueta."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"How much is this sweater?","translation":"¿Cuánto cuesta este suéter?","translations":{"es":"¿Cuánto cuesta este suéter?"}},{"phrase":"How much are these shoes?","translation":"¿Cuánto cuestan estos zapatos?","translations":{"es":"¿Cuánto cuestan estos zapatos?"}},{"phrase":"Can I try it on?","translation":"¿Me lo puedo probar?","translations":{"es":"¿Me lo puedo probar?"}},{"phrase":"Where is the fitting room?","translation":"¿Dónde está el probador?","translations":{"es":"¿Dónde está el probador?"}},{"phrase":"What size are you?","translation":"¿Qué talla eres?","translations":{"es":"¿Qué talla eres?"}},{"phrase":"Do you have it in a medium?","translation":"¿Lo tiene en mediana?","translations":{"es":"¿Lo tiene en mediana?"}},{"phrase":"It''s too small.","translation":"Me queda chico.","translations":{"es":"Me queda chico."}},{"phrase":"It fits perfectly!","translation":"¡Me queda perfecto!","translations":{"es":"¡Me queda perfecto!"}},{"phrase":"I like that blue dress.","translation":"Me gusta ese vestido azul.","translations":{"es":"Me gusta ese vestido azul."}},{"phrase":"These jeans are on sale.","translation":"Estos jeans están en oferta.","translations":{"es":"Estos jeans están en oferta."}},{"phrase":"I''ll take it.","translation":"Me lo llevo.","translations":{"es":"Me lo llevo."}},{"phrase":"Just looking, thanks.","translation":"Solo estoy viendo, gracias.","translations":{"es":"Solo estoy viendo, gracias."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"The shoes are next to you. You say:","options":["This shoes are comfortable.","These shoes are comfortable.","That shoes are comfortable.","Those shoe is comfortable."],"correct":1,"explanation":"Near + plural → these.","translations":{"es":{"question":"Los zapatos están junto a ti. Dices:","explanation":"Cerca + plural → these."}}},{"id":"2","question":"The jacket is far, in the window. You say:","options":["I like that jacket.","I like this jacket.","I like those jacket.","I like these jacket."],"correct":0,"explanation":"Far + singular → that.","translations":{"es":{"question":"La chaqueta está lejos, en la vitrina. Dices:","explanation":"Lejos + singular → that."}}},{"id":"3","question":"Choose the correct question.","options":["How much are these pants?","How much is these pants?","How much this pants?","How many is these pants?"],"correct":0,"explanation":"\"Pants\" is plural → How much are these pants?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"«Pants» es plural → How much are these pants?"}}},{"id":"4","question":"A salesperson asks \"Can I help you?\" and you only want to look. You say:","options":["I''ll take it.","Yes, I''m a medium.","Just looking, thanks.","It''s too small."],"correct":2,"explanation":"\"Just looking, thanks\" is the polite answer.","translations":{"es":{"question":"Un vendedor pregunta «Can I help you?» y solo quieres mirar. Dices:","explanation":"«Just looking, thanks» es la respuesta amable."}}},{"id":"5","question":"Complete: \"She always ___ a hat.\"","options":["puts","carries","wears","dresses"],"correct":2,"explanation":"\"Wear\" is for clothes and accessories on your body: she wears a hat.","translations":{"es":{"question":"Completa: «She always ___ a hat.»","explanation":"«Wear» es para la ropa y accesorios que llevas puestos: she wears a hat."}}},{"id":"6","question":"Where do you try clothes on?","options":["in the drawer","in the kitchen","in the fitting room","at the cashier"],"correct":2,"explanation":"The fitting room is for trying on clothes.","translations":{"es":{"question":"¿Dónde te pruebas la ropa?","explanation":"El probador (fitting room) es para probarse ropa."}}},{"id":"7","question":"The dress is perfect for you. You say:","options":["It''s too small.","How much are they?","It fits perfectly! I''ll take it.","Just looking."],"correct":2,"explanation":"\"It fits\" = it is the right size. \"I''ll take it\" = I''ll buy it.","translations":{"es":{"question":"El vestido te queda perfecto. Dices:","explanation":"«It fits» = es de tu talla. «I''ll take it» = me lo llevo."}}},{"id":"8","question":"In American English, \"pants\" means…","options":["trousers","shorts","underwear","socks"],"correct":0,"explanation":"In the US, pants = trousers.","translations":{"es":{"question":"En inglés estadounidense, «pants» significa…","explanation":"En Estados Unidos, pants = pantalones."}}}]}'::jsonb, 3),
  ('story', 'A Dress for the Party', '{"text":"Carmen needs a dress for Leo''s birthday party. She goes to a store with Laura. \"Can I help you?\" asks the salesperson. \"Just looking, thanks,\" says Carmen. Then she sees a blue dress. \"Laura, look at that dress!\" \"It''s beautiful, Mom. Try it on.\" \"Excuse me, can I try this dress on? Do you have it in a medium?\" \"Sure. The fitting room is over there.\" The dress is too small. The salesperson brings a large. This time it fits perfectly. \"How much is it?\" \"Forty dollars. It''s on sale.\" \"I''ll take it!\" At the cashier, Laura sees some red socks for Leo. \"And how much are these socks?\" \"Five dollars.\" Carmen laughs. \"A blue dress for me and red socks for Leo. We are ready for the party!\"","translation":"Carmen necesita un vestido para la fiesta de cumpleaños de Leo. Va a una tienda con Laura. «¿Le puedo ayudar?», pregunta la vendedora. «Solo estoy viendo, gracias», dice Carmen. Entonces ve un vestido azul. «¡Laura, mira ese vestido!» «Está precioso, mamá. Pruébatelo.» «Disculpe, ¿me puedo probar este vestido? ¿Lo tiene en mediana?» «Claro. El probador está por allá.» El vestido le queda chico. La vendedora trae una grande. Esta vez le queda perfecto. «¿Cuánto cuesta?» «Cuarenta dólares. Está en oferta.» «¡Me lo llevo!» En la caja, Laura ve unos calcetines rojos para Leo. «¿Y cuánto cuestan estos calcetines?» «Cinco dólares.» Carmen se ríe. «Un vestido azul para mí y calcetines rojos para Leo. ¡Estamos listos para la fiesta!»","translations":{"es":"Carmen necesita un vestido para la fiesta de cumpleaños de Leo. Va a una tienda con Laura. «¿Le puedo ayudar?», pregunta la vendedora. «Solo estoy viendo, gracias», dice Carmen. Entonces ve un vestido azul. «¡Laura, mira ese vestido!» «Está precioso, mamá. Pruébatelo.» «Disculpe, ¿me puedo probar este vestido? ¿Lo tiene en mediana?» «Claro. El probador está por allá.» El vestido le queda chico. La vendedora trae una grande. Esta vez le queda perfecto. «¿Cuánto cuesta?» «Cuarenta dólares. Está en oferta.» «¡Me lo llevo!» En la caja, Laura ve unos calcetines rojos para Leo. «¿Y cuánto cuestan estos calcetines?» «Cinco dólares.» Carmen se ríe. «Un vestido azul para mí y calcetines rojos para Leo. ¡Estamos listos para la fiesta!»"},"highlighted_words":["dress","Just looking, thanks","that dress","Try it on","can I try this dress on","medium","fitting room","too small","fits perfectly","How much is it","on sale","I''ll take it","these socks"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["How","much","is","this","sweater"],"translation":"¿Cuánto cuesta este suéter?","translations":{"es":"¿Cuánto cuesta este suéter?"}},{"words":["Can","I","try","these","jeans","on"],"translation":"¿Me puedo probar estos jeans?","translations":{"es":"¿Me puedo probar estos jeans?"}},{"words":["Those","shoes","are","too","expensive"],"translation":"Esos zapatos son demasiado caros.","translations":{"es":"Esos zapatos son demasiado caros."}},{"words":["Do","you","have","it","in","a","large"],"translation":"¿Lo tiene en grande?","translations":{"es":"¿Lo tiene en grande?"}},{"words":["She","always","wears","a","hat"],"translation":"Ella siempre usa sombrero.","translations":{"es":"Ella siempre usa sombrero."}},{"words":["The","dress","fits","perfectly"],"translation":"El vestido le queda perfecto.","translations":{"es":"El vestido le queda perfecto."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Cuánto cuesta este vestido?","translations":{"es":"¿Cuánto cuesta este vestido?"},"answer":"How much is this dress"},{"prompt":"Estos zapatos son baratos","translations":{"es":"Estos zapatos son baratos"},"answer":"These shoes are cheap"},{"prompt":"¿Me lo puedo probar?","translations":{"es":"¿Me lo puedo probar?"},"answer":"Can I try it on"},{"prompt":"Me queda chico","translations":{"es":"Me queda chico"},"answer":"It is too small"},{"prompt":"Me gusta esa chaqueta","translations":{"es":"Me gusta esa chaqueta"},"answer":"I like that jacket"},{"prompt":"¿Dónde está el probador?","translations":{"es":"¿Dónde está el probador?"},"answer":"Where is the fitting room"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 17: Fruits and vegetables
with m as (
