insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"apple","translation":"manzana","translations":{"es":"manzana"}},{"id":"2","word":"banana","translation":"plátano","translations":{"es":"plátano"}},{"id":"3","word":"orange","translation":"naranja","translations":{"es":"naranja"}},{"id":"4","word":"lemon","translation":"limón amarillo","translations":{"es":"limón amarillo"}},{"id":"5","word":"lime","translation":"limón verde","translations":{"es":"limón verde"}},{"id":"6","word":"mango","translation":"mango","translations":{"es":"mango"}},{"id":"7","word":"grapes","translation":"uvas","translations":{"es":"uvas"}},{"id":"8","word":"strawberries","translation":"fresas","translations":{"es":"fresas"}},{"id":"9","word":"watermelon","translation":"sandía","translations":{"es":"sandía"}},{"id":"10","word":"tomato","translation":"jitomate / tomate","translations":{"es":"jitomate / tomate"}},{"id":"11","word":"onion","translation":"cebolla","translations":{"es":"cebolla"}},{"id":"12","word":"potato","translation":"papa","translations":{"es":"papa"}},{"id":"13","word":"carrot","translation":"zanahoria","translations":{"es":"zanahoria"}},{"id":"14","word":"lettuce","translation":"lechuga","translations":{"es":"lechuga"}},{"id":"15","word":"broccoli","translation":"brócoli","translations":{"es":"brócoli"}},{"id":"16","word":"avocado","translation":"aguacate","translations":{"es":"aguacate"}},{"id":"17","word":"corn","translation":"maíz / elote","translations":{"es":"maíz / elote"}},{"id":"18","word":"fresh","translation":"fresco","translations":{"es":"fresco"}},{"id":"19","word":"ripe","translation":"maduro","translations":{"es":"maduro"}}],"grammar":[{"structure":"like / love / hate + noun","example":"I love mangoes. Leo hates broccoli.","en":"Talking about likes and dislikes","es":"Hablar de gustos"},{"structure":"like + verb-ing","example":"I like cooking with fresh vegetables.","en":"Likes with activities","es":"Gustos con actividades"},{"structure":"don''t / doesn''t like","example":"Mike doesn''t like onions.","en":"Negative likes","es":"Lo que no gusta"},{"structure":"Plural for food in general","example":"I like apples. (all apples in general)","en":"General statements use the plural","es":"Las afirmaciones generales usan el plural"},{"structure":"a pound of / a bunch of / a bag of","example":"a pound of tomatoes, a bunch of bananas","en":"Quantities at the market","es":"Cantidades en el mercado"}],"tips":[{"en":"In Spanish \"me gustan las manzanas\" — in English the person comes first: \"I like apples\" (no \"the\").","es":"En español «me gustan las manzanas»; en inglés la persona va primero: «I like apples» (sin «the»)."},{"en":"In the US, fruits and vegetables are sold by the pound (lb). One pound is about 450 grams.","es":"En Estados Unidos las frutas y verduras se venden por libra (lb). Una libra son unos 450 gramos."},{"en":"\"Produce\" is the section of the supermarket with fresh fruits and vegetables.","es":"«Produce» es la sección del supermercado con frutas y verduras frescas."},{"en":"\"Farmers'' markets\" sell fresh local produce, usually on weekends.","es":"Los «farmers'' markets» venden productos frescos de la región, normalmente los fines de semana."},{"en":"\"Avocado\" and \"tomato\" come from Nahuatl words — your Spanish helps here!","es":"«Avocado» y «tomato» vienen de palabras en náhuatl: ¡aquí tu español te ayuda!"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I love mangoes.","translation":"Me encantan los mangos.","translations":{"es":"Me encantan los mangos."}},{"phrase":"I don''t like onions.","translation":"No me gustan las cebollas.","translations":{"es":"No me gustan las cebollas."}},{"phrase":"Do you like avocados?","translation":"¿Te gustan los aguacates?","translations":{"es":"¿Te gustan los aguacates?"}},{"phrase":"How much are the tomatoes?","translation":"¿A cuánto están los jitomates?","translations":{"es":"¿A cuánto están los jitomates?"}},{"phrase":"Two dollars a pound.","translation":"Dos dólares la libra.","translations":{"es":"Dos dólares la libra."}},{"phrase":"A bunch of bananas, please.","translation":"Un racimo de plátanos, por favor.","translations":{"es":"Un racimo de plátanos, por favor."}},{"phrase":"Are these ripe?","translation":"¿Estos están maduros?","translations":{"es":"¿Estos están maduros?"}},{"phrase":"They''re very fresh.","translation":"Están muy frescos.","translations":{"es":"Están muy frescos."}},{"phrase":"Where is the produce section?","translation":"¿Dónde está la sección de frutas y verduras?","translations":{"es":"¿Dónde está la sección de frutas y verduras?"}},{"phrase":"Eat your vegetables!","translation":"¡Cómete las verduras!","translations":{"es":"¡Cómete las verduras!"}},{"phrase":"I hate broccoli.","translation":"Odio el brócoli.","translations":{"es":"Odio el brócoli."}},{"phrase":"Fruit is good for you.","translation":"La fruta es buena para la salud.","translations":{"es":"La fruta es buena para la salud."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say \"Me gustan las manzanas\"?","options":["Me like apples.","Apples like me.","I like the apples to me.","I like apples."],"correct":3,"explanation":"The person is the subject: I like apples.","translations":{"es":{"question":"¿Cómo se dice «Me gustan las manzanas»?","explanation":"La persona es el sujeto: I like apples."}}},{"id":"2","question":"Complete: \"Mike ___ like onions.\"","options":["isn''t","don''t","not","doesn''t"],"correct":3,"explanation":"He → doesn''t + verb.","translations":{"es":{"question":"Completa: «Mike ___ like onions.»","explanation":"He → doesn''t + verbo."}}},{"id":"3","question":"Which is a green citrus fruit?","options":["orange","lemon","banana","lime"],"correct":3,"explanation":"In the US a \"lime\" is green and a \"lemon\" is yellow.","translations":{"es":{"question":"¿Cuál es un cítrico verde?","explanation":"En Estados Unidos «lime» es el limón verde y «lemon» el amarillo."}}},{"id":"4","question":"Complete: \"I like ___ with fresh vegetables.\"","options":["cook","cooks","to cooking","cooking"],"correct":3,"explanation":"Like + verb-ing: I like cooking.","translations":{"es":{"question":"Completa: «I like ___ with fresh vegetables.»","explanation":"Like + verbo-ing: I like cooking."}}},{"id":"5","question":"About how many grams is one pound?","options":["1,000","100","250","450"],"correct":3,"explanation":"One pound is about 450 grams.","translations":{"es":{"question":"¿Cuántos gramos tiene aproximadamente una libra?","explanation":"Una libra son unos 450 gramos."}}},{"id":"6","question":"A banana is yellow and soft. It is…","options":["green","expensive","fresh juice","ripe"],"correct":3,"explanation":"\"Ripe\" means ready to eat.","translations":{"es":{"question":"Un plátano está amarillo y suave. Está…","explanation":"«Ripe» significa maduro, listo para comer."}}},{"id":"7","question":"Which one is a vegetable?","options":["watermelon","mango","grapes","carrot"],"correct":3,"explanation":"A carrot is a vegetable. The others are fruits.","translations":{"es":{"question":"¿Cuál es una verdura?","explanation":"La zanahoria (carrot) es verdura. Las demás son frutas."}}},{"id":"8","question":"Short answer: \"Do you like avocados?\" (yes)","options":["Yes, I can.","Yes, I am.","Yes, I like.","Yes, I do."],"correct":3,"explanation":"Short answer with \"do\": Yes, I do.","translations":{"es":{"question":"Respuesta corta: «Do you like avocados?» (sí)","explanation":"Respuesta corta con «do»: Yes, I do."}}}]}'::jsonb, 3),
  ('story', 'The Farmers'' Market', '{"text":"Every Sunday there is a farmers'' market near Carmen''s apartment. Today she goes with Linda. There are many colors: red tomatoes, green limes, orange carrots and yellow bananas. \"I love farmers'' markets,\" says Linda. \"Everything is so fresh.\" Carmen stops at a table with mangoes. \"How much are the mangoes?\" \"Two for three dollars,\" says the farmer. \"Are they ripe?\" \"Yes, they''re perfect today.\" Carmen buys four mangoes, a bunch of cilantro and a pound of tomatoes. Linda buys lettuce and strawberries. \"Do you like avocados, Linda?\" \"I love them! But I don''t like onions.\" \"No onions? Then my guacamole is not for you!\" Linda laughs. \"Okay, okay. For your guacamole, I can try.\"","translation":"Todos los domingos hay un mercado de productores cerca del departamento de Carmen. Hoy va con Linda. Hay muchos colores: jitomates rojos, limones verdes, zanahorias anaranjadas y plátanos amarillos. «Me encantan los mercados de productores», dice Linda. «Todo está tan fresco.» Carmen se detiene en una mesa con mangos. «¿A cuánto están los mangos?» «Dos por tres dólares», dice el agricultor. «¿Están maduros?» «Sí, hoy están perfectos.» Carmen compra cuatro mangos, un manojo de cilantro y una libra de jitomates. Linda compra lechuga y fresas. «¿Te gustan los aguacates, Linda?» «¡Me encantan! Pero no me gusta la cebolla.» «¿Sin cebolla? ¡Entonces mi guacamole no es para ti!» Linda se ríe. «Bueno, bueno. Por tu guacamole, lo puedo intentar.»","translations":{"es":"Todos los domingos hay un mercado de productores cerca del departamento de Carmen. Hoy va con Linda. Hay muchos colores: jitomates rojos, limones verdes, zanahorias anaranjadas y plátanos amarillos. «Me encantan los mercados de productores», dice Linda. «Todo está tan fresco.» Carmen se detiene en una mesa con mangos. «¿A cuánto están los mangos?» «Dos por tres dólares», dice el agricultor. «¿Están maduros?» «Sí, hoy están perfectos.» Carmen compra cuatro mangos, un manojo de cilantro y una libra de jitomates. Linda compra lechuga y fresas. «¿Te gustan los aguacates, Linda?» «¡Me encantan! Pero no me gusta la cebolla.» «¿Sin cebolla? ¡Entonces mi guacamole no es para ti!» Linda se ríe. «Bueno, bueno. Por tu guacamole, lo puedo intentar.»"},"highlighted_words":["farmers'' market","tomatoes","limes","carrots","bananas","I love","fresh","How much are the mangoes","ripe","a pound of tomatoes","lettuce","strawberries","Do you like avocados","I don''t like onions"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","love","fresh","mangoes"],"translation":"Me encantan los mangos frescos.","translations":{"es":"Me encantan los mangos frescos."}},{"words":["Mike","does","not","like","onions"],"translation":"A Mike no le gusta la cebolla.","translations":{"es":"A Mike no le gusta la cebolla."}},{"words":["How","much","are","the","tomatoes"],"translation":"¿A cuánto están los jitomates?","translations":{"es":"¿A cuánto están los jitomates?"}},{"words":["Do","you","like","strawberries"],"translation":"¿Te gustan las fresas?","translations":{"es":"¿Te gustan las fresas?"}},{"words":["A","pound","of","carrots","please"],"translation":"Una libra de zanahorias, por favor.","translations":{"es":"Una libra de zanahorias, por favor."}},{"words":["I","like","cooking","with","fresh","vegetables"],"translation":"Me gusta cocinar con verduras frescas.","translations":{"es":"Me gusta cocinar con verduras frescas."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Me gustan las manzanas","translations":{"es":"Me gustan las manzanas"},"answer":"I like apples"},{"prompt":"No me gusta la cebolla","translations":{"es":"No me gusta la cebolla"},"answer":"I do not like onions"},{"prompt":"¿Te gustan los mangos?","translations":{"es":"¿Te gustan los mangos?"},"answer":"Do you like mangoes"},{"prompt":"Estos plátanos están maduros","translations":{"es":"Estos plátanos están maduros"},"answer":"These bananas are ripe"},{"prompt":"¿A cuánto están los aguacates?","translations":{"es":"¿A cuánto están los aguacates?"},"answer":"How much are the avocados"},{"prompt":"Leo odia el brócoli","translations":{"es":"Leo odia el brócoli"},"answer":"Leo hates broccoli"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 18: Sports
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-18', 'Sports', '⚽', 'Los deportes', 18, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"soccer","translation":"fútbol","translations":{"es":"fútbol"}},{"id":"2","word":"football","translation":"fútbol americano","translations":{"es":"fútbol americano"}},{"id":"3","word":"baseball","translation":"béisbol","translations":{"es":"béisbol"}},{"id":"4","word":"basketball","translation":"básquetbol","translations":{"es":"básquetbol"}},{"id":"5","word":"tennis","translation":"tenis","translations":{"es":"tenis"}},{"id":"6","word":"swimming","translation":"natación","translations":{"es":"natación"}},{"id":"7","word":"running","translation":"correr (deporte)","translations":{"es":"correr (deporte)"}},{"id":"8","word":"yoga","translation":"yoga","translations":{"es":"yoga"}},{"id":"9","word":"gym","translation":"gimnasio","translations":{"es":"gimnasio"}},{"id":"10","word":"team","translation":"equipo","translations":{"es":"equipo"}},{"id":"11","word":"game","translation":"partido / juego","translations":{"es":"partido / juego"}},{"id":"12","word":"win","translation":"ganar","translations":{"es":"ganar"}},{"id":"13","word":"lose","translation":"perder","translations":{"es":"perder"}},{"id":"14","word":"coach","translation":"entrenador","translations":{"es":"entrenador"}},{"id":"15","word":"usually","translation":"normalmente","translations":{"es":"normalmente"}},{"id":"16","word":"often","translation":"a menudo","translations":{"es":"a menudo"}},{"id":"17","word":"sometimes","translation":"a veces","translations":{"es":"a veces"}},{"id":"18","word":"twice","translation":"dos veces","translations":{"es":"dos veces"}}],"grammar":[{"structure":"always / usually / often / sometimes / never","example":"Leo always plays soccer on Saturdays.","en":"Adverbs of frequency","es":"Adverbios de frecuencia"},{"structure":"adverb before the main verb","example":"I sometimes go swimming.","en":"Position: before the verb…","es":"Posición: antes del verbo…"},{"structure":"be + adverb","example":"He is always tired after the game.","en":"…but after \"to be\"","es":"…pero después de «to be»"},{"structure":"play / go / do + sport","example":"play soccer, go swimming, do yoga","en":"Which verb goes with each sport","es":"Qué verbo va con cada deporte"},{"structure":"How often…?","example":"How often do you exercise? — Three times a week.","en":"Asking about frequency","es":"Preguntar con qué frecuencia"}],"tips":[{"en":"\"Soccer\" is American English for fútbol. In the US, \"football\" is American football.","es":"«Soccer» es el fútbol en inglés estadounidense. En Estados Unidos, «football» es el fútbol americano."},{"en":"Use \"play\" with ball games (play tennis), \"go\" with -ing activities (go running), and \"do\" with others (do yoga).","es":"Usa «play» con juegos de pelota (play tennis), «go» con actividades en -ing (go running) y «do» con las demás (do yoga)."},{"en":"\"Once\" = one time, \"twice\" = two times, then \"three times\", \"four times\"…","es":"«Once» = una vez, «twice» = dos veces, luego «three times», «four times»…"},{"en":"\"Work out\" means to exercise, usually at a gym.","es":"«Work out» significa hacer ejercicio, normalmente en el gimnasio."},{"en":"Americans love watching sports on TV: football, baseball and basketball are the most popular.","es":"A los estadounidenses les encanta ver deportes en la TV: el fútbol americano, el béisbol y el básquetbol son los más populares."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Do you play any sports?","translation":"¿Practicas algún deporte?","translations":{"es":"¿Practicas algún deporte?"}},{"phrase":"I go swimming twice a week.","translation":"Voy a nadar dos veces por semana.","translations":{"es":"Voy a nadar dos veces por semana."}},{"phrase":"How often do you exercise?","translation":"¿Qué tan seguido haces ejercicio?","translations":{"es":"¿Qué tan seguido haces ejercicio?"}},{"phrase":"I never go to the gym.","translation":"Nunca voy al gimnasio.","translations":{"es":"Nunca voy al gimnasio."}},{"phrase":"I usually walk in the morning.","translation":"Normalmente camino en la mañana.","translations":{"es":"Normalmente camino en la mañana."}},{"phrase":"Who''s winning?","translation":"¿Quién va ganando?","translations":{"es":"¿Quién va ganando?"}},{"phrase":"What''s the score?","translation":"¿Cómo va el marcador?","translations":{"es":"¿Cómo va el marcador?"}},{"phrase":"Go, team, go!","translation":"¡Vamos, equipo!","translations":{"es":"¡Vamos, equipo!"}},{"phrase":"Good game!","translation":"¡Buen partido!","translations":{"es":"¡Buen partido!"}},{"phrase":"We won!","translation":"¡Ganamos!","translations":{"es":"¡Ganamos!"}},{"phrase":"They lost three to one.","translation":"Perdieron tres a uno.","translations":{"es":"Perdieron tres a uno."}},{"phrase":"I''m a big fan.","translation":"Soy muy fan.","translations":{"es":"Soy muy fan."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct order.","options":["I walk in the morning always.","Always I walk in the morning.","I always walk in the morning.","I walk always in the morning."],"correct":2,"explanation":"Frequency adverbs go before the main verb.","translations":{"es":{"question":"Elige el orden correcto.","explanation":"Los adverbios de frecuencia van antes del verbo principal."}}},{"id":"2","question":"Choose the correct order with \"to be\".","options":["Always he is tired.","He is tired always.","He is always tired.","He always is tired."],"correct":2,"explanation":"With \"to be\", the adverb goes after: is always.","translations":{"es":{"question":"Elige el orden correcto con «to be».","explanation":"Con «to be», el adverbio va después: is always."}}},{"id":"3","question":"Complete: \"I ___ yoga on Tuesdays.\"","options":["go","make","do","play"],"correct":2,"explanation":"We \"do\" yoga.","translations":{"es":{"question":"Completa: «I ___ yoga on Tuesdays.»","explanation":"Con yoga se usa «do»."}}},{"id":"4","question":"Complete: \"Leo ___ soccer every Saturday.\"","options":["goes","plays","makes","does"],"correct":1,"explanation":"Ball games use \"play\": he plays soccer.","translations":{"es":{"question":"Completa: «Leo ___ soccer every Saturday.»","explanation":"Los juegos de pelota usan «play»: he plays soccer."}}},{"id":"5","question":"\"Twice a week\" means…","options":["two times a week","every day","never","one time a week"],"correct":0,"explanation":"Twice = two times.","translations":{"es":{"question":"«Twice a week» significa…","explanation":"Twice = dos veces."}}},{"id":"6","question":"In the US, what is \"soccer\"?","options":["fútbol","béisbol","básquetbol","fútbol americano"],"correct":0,"explanation":"Soccer = fútbol. Football = American football.","translations":{"es":{"question":"En Estados Unidos, ¿qué es «soccer»?","explanation":"Soccer = fútbol. Football = fútbol americano."}}},{"id":"7","question":"How do you ask about frequency?","options":["When often you go to the gym?","How often do you go to the gym?","How much times you gym?","How many do you go to the gym?"],"correct":1,"explanation":"\"How often…?\" asks about frequency.","translations":{"es":{"question":"¿Cómo preguntas por la frecuencia?","explanation":"«How often…?» pregunta por la frecuencia."}}},{"id":"8","question":"Your team scores more goals. Your team…","options":["wins","coaches","plays","loses"],"correct":0,"explanation":"More goals = you win.","translations":{"es":{"question":"Tu equipo mete más goles. Tu equipo…","explanation":"Más goles = ganas (win)."}}}]}'::jsonb, 3),
  ('story', 'Saturday Soccer', '{"text":"Leo always plays soccer on Saturday mornings. His team is called the Blue Sharks. Laura usually works on Saturdays, so Carmen often takes Leo to the game. Today the Blue Sharks play against the Red Tigers. Carmen sits with the other parents. She doesn''t know all the rules, but she shouts with everybody: \"Go, Sharks, go!\" A father next to her asks, \"Do you play any sports?\" \"Me? I sometimes go swimming, and I walk on the beach every morning. But I never run!\" At the end, the coach shouts, \"We won! Three to two!\" Leo runs to his grandmother. \"Grandma, did you see my goal?\" \"Of course! You are the best player.\" Leo is always happy after a game, but today he is very happy.","translation":"Leo siempre juega fútbol los sábados en la mañana. Su equipo se llama los Tiburones Azules. Laura normalmente trabaja los sábados, así que Carmen a menudo lleva a Leo al partido. Hoy los Tiburones Azules juegan contra los Tigres Rojos. Carmen se sienta con los demás papás. No conoce todas las reglas, pero grita con todos: «¡Vamos, Tiburones!» Un papá a su lado le pregunta: «¿Usted practica algún deporte?» «¿Yo? A veces voy a nadar y camino por la playa todas las mañanas. ¡Pero nunca corro!» Al final, el entrenador grita: «¡Ganamos! ¡Tres a dos!» Leo corre hacia su abuela. «Abuela, ¿viste mi gol?» «¡Claro! Eres el mejor jugador.» Leo siempre está contento después de un partido, pero hoy está muy contento.","translations":{"es":"Leo siempre juega fútbol los sábados en la mañana. Su equipo se llama los Tiburones Azules. Laura normalmente trabaja los sábados, así que Carmen a menudo lleva a Leo al partido. Hoy los Tiburones Azules juegan contra los Tigres Rojos. Carmen se sienta con los demás papás. No conoce todas las reglas, pero grita con todos: «¡Vamos, Tiburones!» Un papá a su lado le pregunta: «¿Usted practica algún deporte?» «¿Yo? A veces voy a nadar y camino por la playa todas las mañanas. ¡Pero nunca corro!» Al final, el entrenador grita: «¡Ganamos! ¡Tres a dos!» Leo corre hacia su abuela. «Abuela, ¿viste mi gol?» «¡Claro! Eres el mejor jugador.» Leo siempre está contento después de un partido, pero hoy está muy contento."},"highlighted_words":["always plays soccer","team","usually works","often takes","game","Do you play any sports","sometimes go swimming","every morning","I never run","coach","We won","is always happy"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","usually","walk","in","the","morning"],"translation":"Normalmente camino en la mañana.","translations":{"es":"Normalmente camino en la mañana."}},{"words":["He","is","always","tired","after","work"],"translation":"Siempre está cansado después del trabajo.","translations":{"es":"Siempre está cansado después del trabajo."}},{"words":["How","often","do","you","go","swimming"],"translation":"¿Qué tan seguido vas a nadar?","translations":{"es":"¿Qué tan seguido vas a nadar?"}},{"words":["Leo","plays","soccer","every","Saturday"],"translation":"Leo juega fútbol todos los sábados.","translations":{"es":"Leo juega fútbol todos los sábados."}},{"words":["I","never","go","to","the","gym"],"translation":"Nunca voy al gimnasio.","translations":{"es":"Nunca voy al gimnasio."}},{"words":["We","go","running","twice","a","week"],"translation":"Salimos a correr dos veces por semana.","translations":{"es":"Salimos a correr dos veces por semana."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Siempre camino por la playa","translations":{"es":"Siempre camino por la playa"},"answer":"I always walk on the beach"},{"prompt":"¿Practicas algún deporte?","translations":{"es":"¿Practicas algún deporte?"},"answer":"Do you play any sports"},{"prompt":"A veces voy a nadar","translations":{"es":"A veces voy a nadar"},"answer":"I sometimes go swimming"},{"prompt":"Ganamos","translations":{"es":"Ganamos"},"answer":"We won"},{"prompt":"Ella hace yoga dos veces por semana","translations":{"es":"Ella hace yoga dos veces por semana"},"answer":"She does yoga twice a week"},{"prompt":"Él nunca corre","translations":{"es":"Él nunca corre"},"answer":"He never runs"}]}'::jsonb, 6)
) as v(type, title, content, ord);

