insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"world","translation":"mundo","translations":{"es":"mundo"}},{"id":"2","word":"Earth","translation":"la Tierra","translations":{"es":"la Tierra"}},{"id":"3","word":"sun","translation":"sol","translations":{"es":"sol"}},{"id":"4","word":"moon","translation":"luna","translations":{"es":"luna"}},{"id":"5","word":"star","translation":"estrella","translations":{"es":"estrella"}},{"id":"6","word":"planet","translation":"planeta","translations":{"es":"planeta"}},{"id":"7","word":"sky","translation":"cielo","translations":{"es":"cielo"}},{"id":"8","word":"ocean","translation":"océano","translations":{"es":"océano"}},{"id":"9","word":"mountain","translation":"montaña","translations":{"es":"montaña"}},{"id":"10","word":"river","translation":"río","translations":{"es":"río"}},{"id":"11","word":"desert","translation":"desierto","translations":{"es":"desierto"}},{"id":"12","word":"island","translation":"isla","translations":{"es":"isla"}},{"id":"13","word":"beach","translation":"playa","translations":{"es":"playa"}},{"id":"14","word":"bigger","translation":"más grande","translations":{"es":"más grande"}},{"id":"15","word":"smaller","translation":"más pequeño","translations":{"es":"más pequeño"}},{"id":"16","word":"hotter","translation":"más caliente","translations":{"es":"más caliente"}},{"id":"17","word":"colder","translation":"más frío","translations":{"es":"más frío"}},{"id":"18","word":"farther","translation":"más lejos","translations":{"es":"más lejos"}}],"grammar":[{"structure":"short adjective + -er + than","example":"The sun is bigger than the moon.","en":"Comparatives with short adjectives","es":"Comparativos con adjetivos cortos"},{"structure":"more + long adjective + than","example":"Mexico City is more crowded than San Diego.","en":"Comparatives with long adjectives","es":"Comparativos con adjetivos largos"},{"structure":"good → better, bad → worse, far → farther","example":"The weather here is better than in winter.","en":"Irregular comparatives","es":"Comparativos irregulares"},{"structure":"-y → -ier","example":"happy → happier, easy → easier","en":"Spelling changes","es":"Cambios de ortografía"},{"structure":"as … as","example":"The ocean is as blue as the sky.","en":"Saying two things are equal","es":"Decir que dos cosas son iguales"}],"tips":[{"en":"\"Than\" (que) is different from \"then\" (entonces). Bigger than, not bigger then.","es":"«Than» (que) es distinto de «then» (entonces). Bigger than, no bigger then."},{"en":"One-syllable adjectives take -er (tall → taller); long ones use \"more\" (beautiful → more beautiful).","es":"Los adjetivos de una sílaba llevan -er (tall → taller); los largos usan «more» (beautiful → more beautiful)."},{"en":"Double the last letter after a short vowel: big → bigger, hot → hotter.","es":"Se duplica la última letra después de una vocal corta: big → bigger, hot → hotter."},{"en":"\"Earth\" is our planet; \"world\" is all the countries and people.","es":"«Earth» es nuestro planeta; «world» es el conjunto de países y personas."},{"en":"Americans measure distance in miles: 1 mile ≈ 1.6 kilometers.","es":"En Estados Unidos la distancia se mide en millas: 1 milla ≈ 1.6 kilómetros."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Look at the stars!","translation":"¡Mira las estrellas!","translations":{"es":"¡Mira las estrellas!"}},{"phrase":"The sun is bigger than the Earth.","translation":"El sol es más grande que la Tierra.","translations":{"es":"El sol es más grande que la Tierra."}},{"phrase":"The moon is beautiful tonight.","translation":"La luna está hermosa esta noche.","translations":{"es":"La luna está hermosa esta noche."}},{"phrase":"Mars is colder than Earth.","translation":"Marte es más frío que la Tierra.","translations":{"es":"Marte es más frío que la Tierra."}},{"phrase":"Which is bigger?","translation":"¿Cuál es más grande?","translations":{"es":"¿Cuál es más grande?"}},{"phrase":"The Pacific is the biggest ocean.","translation":"El Pacífico es el océano más grande.","translations":{"es":"El Pacífico es el océano más grande."}},{"phrase":"It''s farther than I think.","translation":"Está más lejos de lo que pienso.","translations":{"es":"Está más lejos de lo que pienso."}},{"phrase":"Your English is better every day.","translation":"Tu inglés es mejor cada día.","translations":{"es":"Tu inglés es mejor cada día."}},{"phrase":"It''s as big as a house!","translation":"¡Es tan grande como una casa!","translations":{"es":"¡Es tan grande como una casa!"}},{"phrase":"How far is it?","translation":"¿Qué tan lejos está?","translations":{"es":"¿Qué tan lejos está?"}},{"phrase":"About fifty miles.","translation":"Como a cincuenta millas.","translations":{"es":"Como a cincuenta millas."}},{"phrase":"What a beautiful sky!","translation":"¡Qué cielo tan bonito!","translations":{"es":"¡Qué cielo tan bonito!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"The sun is ___ than the moon.\"","options":["more big","biger","bigger","big"],"correct":2,"explanation":"Big → bigger (double the g).","translations":{"es":{"question":"Completa: «The sun is ___ than the moon.»","explanation":"Big → bigger (se duplica la g)."}}},{"id":"2","question":"Complete: \"This city is ___ than my town.\"","options":["more beautiful","most beautiful","beautifuler","beautiful more"],"correct":0,"explanation":"Long adjectives use \"more\": more beautiful.","translations":{"es":{"question":"Completa: «This city is ___ than my town.»","explanation":"Los adjetivos largos usan «more»: more beautiful."}}},{"id":"3","question":"What is the comparative of \"good\"?","options":["better","more good","gooder","best"],"correct":0,"explanation":"Good → better (irregular).","translations":{"es":{"question":"¿Cuál es el comparativo de «good»?","explanation":"Good → better (irregular)."}}},{"id":"4","question":"Choose the correct word: \"She is taller ___ me.\"","options":["that","than","then","as"],"correct":1,"explanation":"Comparisons use \"than\".","translations":{"es":{"question":"Elige la palabra correcta: «She is taller ___ me.»","explanation":"Las comparaciones usan «than»."}}},{"id":"5","question":"What is the comparative of \"easy\"?","options":["easier","more easy","easyer","easiest"],"correct":0,"explanation":"-y becomes -ier: easier.","translations":{"es":{"question":"¿Cuál es el comparativo de «easy»?","explanation":"La -y cambia a -ier: easier."}}},{"id":"6","question":"A big area of sand with very little rain is a…","options":["desert","river","island","ocean"],"correct":0,"explanation":"That''s a desert.","translations":{"es":{"question":"Una gran zona de arena con muy poca lluvia es un…","explanation":"Es un desierto (desert)."}}},{"id":"7","question":"Complete: \"Today is as hot ___ yesterday.\"","options":["than","as","like","that"],"correct":1,"explanation":"Equality: as … as.","translations":{"es":{"question":"Completa: «Today is as hot ___ yesterday.»","explanation":"Igualdad: as … as."}}},{"id":"8","question":"One mile is about…","options":["1.6 kilometers","1 kilometer","10 kilometers","500 meters"],"correct":0,"explanation":"1 mile ≈ 1.6 km.","translations":{"es":{"question":"Una milla es aproximadamente…","explanation":"1 milla ≈ 1.6 km."}}}]}'::jsonb, 3),
  ('story', 'Stars in the Desert', '{"text":"Mike takes the family to the desert for a weekend. The desert is about one hundred miles from San Diego. At night the sky is very dark. \"Look at the stars, Grandma!\" says Leo. There are thousands of stars. The sky here is clearer than in the city. \"In Guadalajara the sky is not as dark as this,\" says Carmen. Leo has a book about planets. \"Grandma, the sun is bigger than the Earth. And Jupiter is bigger than all the other planets.\" \"Really? And which is hotter, the sun or the desert?\" Leo laughs. \"The sun, Grandma! Much hotter!\" It is colder at night, so they sit close together. Carmen thinks: the world is bigger than I imagined, but tonight my world is here, with my family.","translation":"Mike lleva a la familia al desierto un fin de semana. El desierto está como a cien millas de San Diego. En la noche el cielo está muy oscuro. «¡Mira las estrellas, abuela!», dice Leo. Hay miles de estrellas. Aquí el cielo está más despejado que en la ciudad. «En Guadalajara el cielo no es tan oscuro como este», dice Carmen. Leo tiene un libro sobre planetas. «Abuela, el sol es más grande que la Tierra. Y Júpiter es más grande que todos los demás planetas.» «¿En serio? ¿Y qué es más caliente, el sol o el desierto?» Leo se ríe. «¡El sol, abuela! ¡Mucho más caliente!» En la noche hace más frío, así que se sientan muy juntos. Carmen piensa: el mundo es más grande de lo que imaginaba, pero esta noche mi mundo está aquí, con mi familia.","translations":{"es":"Mike lleva a la familia al desierto un fin de semana. El desierto está como a cien millas de San Diego. En la noche el cielo está muy oscuro. «¡Mira las estrellas, abuela!», dice Leo. Hay miles de estrellas. Aquí el cielo está más despejado que en la ciudad. «En Guadalajara el cielo no es tan oscuro como este», dice Carmen. Leo tiene un libro sobre planetas. «Abuela, el sol es más grande que la Tierra. Y Júpiter es más grande que todos los demás planetas.» «¿En serio? ¿Y qué es más caliente, el sol o el desierto?» Leo se ríe. «¡El sol, abuela! ¡Mucho más caliente!» En la noche hace más frío, así que se sientan muy juntos. Carmen piensa: el mundo es más grande de lo que imaginaba, pero esta noche mi mundo está aquí, con mi familia."},"highlighted_words":["desert","miles","sky","stars","clearer than","not as dark as","planets","the sun is bigger than the Earth","hotter","colder","world"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["The","sun","is","bigger","than","the","Earth"],"translation":"El sol es más grande que la Tierra.","translations":{"es":"El sol es más grande que la Tierra."}},{"words":["Your","English","is","better","every","day"],"translation":"Tu inglés es mejor cada día.","translations":{"es":"Tu inglés es mejor cada día."}},{"words":["The","desert","is","hotter","than","the","beach"],"translation":"El desierto es más caliente que la playa.","translations":{"es":"El desierto es más caliente que la playa."}},{"words":["This","city","is","more","expensive","than","my","town"],"translation":"Esta ciudad es más cara que mi pueblo.","translations":{"es":"Esta ciudad es más cara que mi pueblo."}},{"words":["The","sky","is","as","blue","as","the","ocean"],"translation":"El cielo es tan azul como el océano.","translations":{"es":"El cielo es tan azul como el océano."}},{"words":["How","far","is","the","mountain"],"translation":"¿Qué tan lejos está la montaña?","translations":{"es":"¿Qué tan lejos está la montaña?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"La luna está hermosa","translations":{"es":"La luna está hermosa"},"answer":"The moon is beautiful"},{"prompt":"México es más grande que España","translations":{"es":"México es más grande que España"},"answer":"Mexico is bigger than Spain"},{"prompt":"Hoy hace más frío que ayer","translations":{"es":"Hoy hace más frío que ayer"},"answer":"Today is colder than yesterday"},{"prompt":"Mira las estrellas","translations":{"es":"Mira las estrellas"},"answer":"Look at the stars"},{"prompt":"¿Qué tan lejos está?","translations":{"es":"¿Qué tan lejos está?"},"answer":"How far is it"},{"prompt":"Mi inglés es mejor ahora","translations":{"es":"Mi inglés es mejor ahora"},"answer":"My English is better now"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 20: The city
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-20', 'The city', '🏙️', 'La ciudad', 20, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"street","translation":"calle","translations":{"es":"calle"}},{"id":"2","word":"avenue","translation":"avenida","translations":{"es":"avenida"}},{"id":"3","word":"block","translation":"cuadra","translations":{"es":"cuadra"}},{"id":"4","word":"corner","translation":"esquina","translations":{"es":"esquina"}},{"id":"5","word":"traffic light","translation":"semáforo","translations":{"es":"semáforo"}},{"id":"6","word":"crosswalk","translation":"paso peatonal","translations":{"es":"paso peatonal"}},{"id":"7","word":"downtown","translation":"el centro","translations":{"es":"el centro"}},{"id":"8","word":"library","translation":"biblioteca","translations":{"es":"biblioteca"}},{"id":"9","word":"bank","translation":"banco","translations":{"es":"banco"}},{"id":"10","word":"pharmacy","translation":"farmacia","translations":{"es":"farmacia"}},{"id":"11","word":"supermarket","translation":"supermercado","translations":{"es":"supermercado"}},{"id":"12","word":"post office","translation":"oficina de correos","translations":{"es":"oficina de correos"}},{"id":"13","word":"park","translation":"parque","translations":{"es":"parque"}},{"id":"14","word":"church","translation":"iglesia","translations":{"es":"iglesia"}},{"id":"15","word":"turn left","translation":"dar vuelta a la izquierda","translations":{"es":"dar vuelta a la izquierda"}},{"id":"16","word":"turn right","translation":"dar vuelta a la derecha","translations":{"es":"dar vuelta a la derecha"}},{"id":"17","word":"go straight","translation":"seguir derecho","translations":{"es":"seguir derecho"}},{"id":"18","word":"across from","translation":"enfrente de","translations":{"es":"enfrente de"}}],"grammar":[{"structure":"Imperatives","example":"Go straight. Turn left at the light.","en":"Giving directions with the imperative","es":"Dar indicaciones con el imperativo"},{"structure":"Don''t + verb","example":"Don''t cross here.","en":"Negative imperative","es":"Imperativo negativo"},{"structure":"Excuse me, where is…? / How do I get to…?","example":"Excuse me, how do I get to the library?","en":"Asking for directions","es":"Pedir indicaciones"},{"structure":"on the corner of / across from / around the corner","example":"The bank is across from the park.","en":"Location in the city","es":"Ubicación en la ciudad"},{"structure":"Is there a … near here?","example":"Is there a pharmacy near here?","en":"Looking for places nearby","es":"Buscar lugares cercanos"}],"tips":[{"en":"In the US, people give directions in \"blocks\": \"It''s two blocks away.\"","es":"En Estados Unidos las indicaciones se dan en cuadras («blocks»): «It''s two blocks away.»"},{"en":"\"Downtown\" means the city center.","es":"«Downtown» significa el centro de la ciudad."},{"en":"A \"drugstore\" or \"pharmacy\" sells medicine, but also snacks, cosmetics and more.","es":"Una «drugstore» o «pharmacy» vende medicinas, pero también botanas, cosméticos y más."},{"en":"Cross the street at the \"crosswalk\" and wait for the walk signal: jaywalking can get you a ticket.","es":"Cruza la calle por el paso peatonal («crosswalk») y espera la señal: cruzar por donde no se debe puede costar una multa."},{"en":"If you don''t understand directions, ask: \"Can you show me on the map?\"","es":"Si no entiendes las indicaciones, pregunta: «Can you show me on the map?»"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Excuse me, where is the library?","translation":"Disculpe, ¿dónde está la biblioteca?","translations":{"es":"Disculpe, ¿dónde está la biblioteca?"}},{"phrase":"How do I get to downtown?","translation":"¿Cómo llego al centro?","translations":{"es":"¿Cómo llego al centro?"}},{"phrase":"Go straight for two blocks.","translation":"Siga derecho dos cuadras.","translations":{"es":"Siga derecho dos cuadras."}},{"phrase":"Turn left at the traffic light.","translation":"Dé vuelta a la izquierda en el semáforo.","translations":{"es":"Dé vuelta a la izquierda en el semáforo."}},{"phrase":"It''s on your right.","translation":"Está a su derecha.","translations":{"es":"Está a su derecha."}},{"phrase":"It''s across from the bank.","translation":"Está enfrente del banco.","translations":{"es":"Está enfrente del banco."}},{"phrase":"It''s on the corner of Main and Fifth.","translation":"Está en la esquina de Main y la Quinta.","translations":{"es":"Está en la esquina de Main y la Quinta."}},{"phrase":"Is there a pharmacy near here?","translation":"¿Hay una farmacia cerca de aquí?","translations":{"es":"¿Hay una farmacia cerca de aquí?"}},{"phrase":"It''s just around the corner.","translation":"Está a la vuelta de la esquina.","translations":{"es":"Está a la vuelta de la esquina."}},{"phrase":"Is it far?","translation":"¿Está lejos?","translations":{"es":"¿Está lejos?"}},{"phrase":"It''s a five-minute walk.","translation":"Está a cinco minutos caminando.","translations":{"es":"Está a cinco minutos caminando."}},{"phrase":"Can you show me on the map?","translation":"¿Me lo puede mostrar en el mapa?","translations":{"es":"¿Me lo puede mostrar en el mapa?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you ask for directions politely?","options":["Where bank?","Excuse me, how do I get to the bank?","Give me the bank.","You go bank?"],"correct":1,"explanation":"Start with \"Excuse me\" and ask \"How do I get to…?\"","translations":{"es":{"question":"¿Cómo pides indicaciones amablemente?","explanation":"Empieza con «Excuse me» y pregunta «How do I get to…?»"}}},{"id":"2","question":"Choose the negative imperative.","options":["Not cross here.","No cross here.","Don''t cross here.","Doesn''t cross here."],"correct":2,"explanation":"Negative imperative: Don''t + verb.","translations":{"es":{"question":"Elige el imperativo negativo.","explanation":"Imperativo negativo: Don''t + verbo."}}},{"id":"3","question":"\"It''s across from the park\" means…","options":["It''s behind the park.","It''s inside the park.","It''s on the other side of the street from the park.","It''s far from the park."],"correct":2,"explanation":"\"Across from\" = enfrente de.","translations":{"es":{"question":"«It''s across from the park» significa…","explanation":"«Across from» = enfrente de."}}},{"id":"4","question":"Where do you borrow books?","options":["at the bank","at the pharmacy","at the library","at the church"],"correct":2,"explanation":"The library lends books.","translations":{"es":{"question":"¿Dónde pides libros prestados?","explanation":"La biblioteca (library) presta libros."}}},{"id":"5","question":"\"Downtown\" is…","options":["a small town","the countryside","the city center","a downstairs room"],"correct":2,"explanation":"Downtown = el centro de la ciudad.","translations":{"es":{"question":"«Downtown» es…","explanation":"Downtown = el centro de la ciudad."}}},{"id":"6","question":"Complete: \"___ left at the traffic light.\"","options":["Turn","Turning","Turns","To turn"],"correct":0,"explanation":"Imperatives use the base verb: Turn left.","translations":{"es":{"question":"Completa: «___ left at the traffic light.»","explanation":"El imperativo usa el verbo base: Turn left."}}},{"id":"7","question":"Where do you cross the street safely?","options":["behind a bus","at the crosswalk","in the middle of the block","at the library"],"correct":1,"explanation":"Use the crosswalk and wait for the signal.","translations":{"es":{"question":"¿Dónde cruzas la calle con seguridad?","explanation":"Usa el paso peatonal y espera la señal."}}},{"id":"8","question":"\"It''s just around the corner\" means…","options":["It''s closed.","It''s very close.","It''s very far.","It''s on the map."],"correct":1,"explanation":"\"Around the corner\" = muy cerca.","translations":{"es":{"question":"«It''s just around the corner» significa…","explanation":"«Around the corner» = muy cerca."}}}]}'::jsonb, 3),
  ('story', 'Lost Downtown', '{"text":"Carmen has an appointment at the public library downtown. She takes the bus alone for the first time. When she gets off, she doesn''t know where to go. She sees a woman with a dog. \"Excuse me, how do I get to the library?\" \"Go straight for two blocks. Then turn left at the traffic light. The library is on your right, across from the church.\" \"Thank you! Is it far?\" \"No, it''s a five-minute walk.\" Carmen walks two blocks. She waits at the crosswalk, turns left at the traffic light and… there is the church! Across from it is a big building: the library. Carmen smiles. Her first time downtown alone, and she isn''t lost. In the library there is a sign: FREE ENGLISH CONVERSATION — WEDNESDAYS.","translation":"Carmen tiene una cita en la biblioteca pública del centro. Toma el autobús sola por primera vez. Cuando se baja, no sabe a dónde ir. Ve a una mujer con un perro. «Disculpe, ¿cómo llego a la biblioteca?» «Siga derecho dos cuadras. Luego dé vuelta a la izquierda en el semáforo. La biblioteca está a su derecha, enfrente de la iglesia.» «¡Gracias! ¿Está lejos?» «No, está a cinco minutos caminando.» Carmen camina dos cuadras. Espera en el paso peatonal, da vuelta a la izquierda en el semáforo y… ¡ahí está la iglesia! Enfrente hay un edificio grande: la biblioteca. Carmen sonríe. Su primera vez sola en el centro, y no está perdida. En la biblioteca hay un letrero: CONVERSACIÓN EN INGLÉS GRATIS — MIÉRCOLES.","translations":{"es":"Carmen tiene una cita en la biblioteca pública del centro. Toma el autobús sola por primera vez. Cuando se baja, no sabe a dónde ir. Ve a una mujer con un perro. «Disculpe, ¿cómo llego a la biblioteca?» «Siga derecho dos cuadras. Luego dé vuelta a la izquierda en el semáforo. La biblioteca está a su derecha, enfrente de la iglesia.» «¡Gracias! ¿Está lejos?» «No, está a cinco minutos caminando.» Carmen camina dos cuadras. Espera en el paso peatonal, da vuelta a la izquierda en el semáforo y… ¡ahí está la iglesia! Enfrente hay un edificio grande: la biblioteca. Carmen sonríe. Su primera vez sola en el centro, y no está perdida. En la biblioteca hay un letrero: CONVERSACIÓN EN INGLÉS GRATIS — MIÉRCOLES."},"highlighted_words":["library","downtown","how do I get to","Go straight","blocks","turn left at the traffic light","on your right","across from the church","Is it far","five-minute walk","crosswalk"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["How","do","I","get","to","the","library"],"translation":"¿Cómo llego a la biblioteca?","translations":{"es":"¿Cómo llego a la biblioteca?"}},{"words":["Go","straight","for","two","blocks"],"translation":"Siga derecho dos cuadras.","translations":{"es":"Siga derecho dos cuadras."}},{"words":["Turn","right","at","the","traffic","light"],"translation":"Dé vuelta a la derecha en el semáforo.","translations":{"es":"Dé vuelta a la derecha en el semáforo."}},{"words":["The","bank","is","across","from","the","park"],"translation":"El banco está enfrente del parque.","translations":{"es":"El banco está enfrente del parque."}},{"words":["Is","there","a","pharmacy","near","here"],"translation":"¿Hay una farmacia cerca de aquí?","translations":{"es":"¿Hay una farmacia cerca de aquí?"}},{"words":["It","is","just","around","the","corner"],"translation":"Está a la vuelta de la esquina.","translations":{"es":"Está a la vuelta de la esquina."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Dónde está el banco?","translations":{"es":"¿Dónde está el banco?"},"answer":"Where is the bank"},{"prompt":"Dé vuelta a la izquierda","translations":{"es":"Dé vuelta a la izquierda"},"answer":"Turn left"},{"prompt":"Siga derecho","translations":{"es":"Siga derecho"},"answer":"Go straight"},{"prompt":"¿Está lejos?","translations":{"es":"¿Está lejos?"},"answer":"Is it far"},{"prompt":"¿Hay un supermercado cerca de aquí?","translations":{"es":"¿Hay un supermercado cerca de aquí?"},"answer":"Is there a supermarket near here"},{"prompt":"Está a su derecha","translations":{"es":"Está a su derecha"},"answer":"It is on your right"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 21: Time and measurements
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-21', 'Time and measurements', '⏱️', 'La hora y las medidas', 21, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"hour","translation":"hora","translations":{"es":"hora"}},{"id":"2","word":"minute","translation":"minuto","translations":{"es":"minuto"}},{"id":"3","word":"second","translation":"segundo","translations":{"es":"segundo"}},{"id":"4","word":"half past","translation":"y media","translations":{"es":"y media"}},{"id":"5","word":"quarter past","translation":"y cuarto","translations":{"es":"y cuarto"}},{"id":"6","word":"quarter to","translation":"cuarto para","translations":{"es":"cuarto para"}},{"id":"7","word":"o''clock","translation":"en punto","translations":{"es":"en punto"}},{"id":"8","word":"noon","translation":"mediodía","translations":{"es":"mediodía"}},{"id":"9","word":"midnight","translation":"medianoche","translations":{"es":"medianoche"}},{"id":"10","word":"on time","translation":"a tiempo / puntual","translations":{"es":"a tiempo / puntual"}},{"id":"11","word":"foot","translation":"pie (medida)","translations":{"es":"pie (medida)"}},{"id":"12","word":"inch","translation":"pulgada","translations":{"es":"pulgada"}},{"id":"13","word":"pound","translation":"libra","translations":{"es":"libra"}},{"id":"14","word":"mile","translation":"milla","translations":{"es":"milla"}},{"id":"15","word":"tall","translation":"alto","translations":{"es":"alto"}},{"id":"16","word":"heavy","translation":"pesado","translations":{"es":"pesado"}},{"id":"17","word":"long","translation":"largo","translations":{"es":"largo"}}],"grammar":[{"structure":"What time is it? — It''s…","example":"It''s ten thirty. It''s a quarter to six.","en":"Telling the time","es":"Decir la hora"},{"structure":"at + time","example":"My class starts at nine.","en":"\"At\" with clock times","es":"«At» con la hora"},{"structure":"a.m. / p.m.","example":"The store opens at 8 a.m. and closes at 9 p.m.","en":"Morning and afternoon/night","es":"Mañana y tarde/noche"},{"structure":"How long…? — It takes…","example":"How long does it take? — It takes twenty minutes.","en":"Asking about duration","es":"Preguntar cuánto tiempo toma algo"},{"structure":"How tall / how heavy / how far","example":"How tall are you? — I''m five feet four.","en":"Asking about measurements","es":"Preguntar medidas"}],"tips":[{"en":"\"Quarter past\" = :15, \"half past\" = :30, \"quarter to\" = :45. Many people simply say the numbers: \"six forty-five\".","es":"«Quarter past» = :15, «half past» = :30, «quarter to» = :45. Mucha gente dice solo los números: «six forty-five»."},{"en":"The US uses the 12-hour clock with a.m. and p.m. 15:00 is \"3 p.m.\"","es":"En Estados Unidos se usa el reloj de 12 horas con a.m. y p.m. Las 15:00 son «3 p.m.»"},{"en":"Height is in feet and inches: 1 foot ≈ 30 cm, 1 inch ≈ 2.5 cm. Weight is in pounds.","es":"La estatura se mide en pies y pulgadas: 1 pie ≈ 30 cm, 1 pulgada ≈ 2.5 cm. El peso en libras."},{"en":"Temperature is in Fahrenheit: 70°F is about 21°C, 32°F is freezing.","es":"La temperatura es en Fahrenheit: 70°F son unos 21°C; 32°F es el punto de congelación."},{"en":"Americans are usually on time. \"Five minutes late\" is okay; more than that, send a message.","es":"En Estados Unidos la gente suele ser puntual. «Cinco minutos tarde» está bien; si es más, manda un mensaje."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What time is it?","translation":"¿Qué hora es?","translations":{"es":"¿Qué hora es?"}},{"phrase":"It''s ten o''clock.","translation":"Son las diez en punto.","translations":{"es":"Son las diez en punto."}},{"phrase":"It''s half past four.","translation":"Son las cuatro y media.","translations":{"es":"Son las cuatro y media."}},{"phrase":"It''s a quarter to six.","translation":"Es un cuarto para las seis.","translations":{"es":"Es un cuarto para las seis."}},{"phrase":"What time does the store open?","translation":"¿A qué hora abre la tienda?","translations":{"es":"¿A qué hora abre la tienda?"}},{"phrase":"At nine in the morning.","translation":"A las nueve de la mañana.","translations":{"es":"A las nueve de la mañana."}},{"phrase":"How long does it take?","translation":"¿Cuánto tiempo tarda?","translations":{"es":"¿Cuánto tiempo tarda?"}},{"phrase":"It takes about twenty minutes.","translation":"Tarda unos veinte minutos.","translations":{"es":"Tarda unos veinte minutos."}},{"phrase":"I''m sorry I''m late.","translation":"Perdón por llegar tarde.","translations":{"es":"Perdón por llegar tarde."}},{"phrase":"Right on time!","translation":"¡Justo a tiempo!","translations":{"es":"¡Justo a tiempo!"}},{"phrase":"How tall is he?","translation":"¿Cuánto mide él?","translations":{"es":"¿Cuánto mide él?"}},{"phrase":"It''s seventy degrees today.","translation":"Hoy hace setenta grados (Fahrenheit).","translations":{"es":"Hoy hace setenta grados (Fahrenheit)."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"It''s 4:30. How do you say it?","options":["It''s half to four.","It''s four and half.","It''s half past four.","It''s half four past."],"correct":2,"explanation":"4:30 = half past four (or \"four thirty\").","translations":{"es":{"question":"Son las 4:30. ¿Cómo se dice?","explanation":"4:30 = half past four (o «four thirty»)."}}},{"id":"2","question":"It''s 5:45. How do you say it?","options":["It''s a quarter to five.","It''s half past five.","It''s a quarter to six.","It''s a quarter past six."],"correct":2,"explanation":"5:45 = a quarter to six (or \"five forty-five\").","translations":{"es":{"question":"Son las 5:45. ¿Cómo se dice?","explanation":"5:45 = a quarter to six (o «five forty-five»)."}}},{"id":"3","question":"Complete: \"My class starts ___ nine.\"","options":["in","to","at","on"],"correct":2,"explanation":"We use \"at\" with clock times.","translations":{"es":{"question":"Completa: «My class starts ___ nine.»","explanation":"Con la hora se usa «at»."}}},{"id":"4","question":"3 p.m. is…","options":["13:00","15:00","midnight","3:00 in the morning"],"correct":1,"explanation":"p.m. is after noon: 3 p.m. = 15:00.","translations":{"es":{"question":"3 p.m. es…","explanation":"p.m. es después del mediodía: 3 p.m. = 15:00."}}},{"id":"5","question":"How do you ask about duration?","options":["How time does it take?","How long does it take?","What long is it?","How much does it take?"],"correct":1,"explanation":"\"How long…?\" asks about time.","translations":{"es":{"question":"¿Cómo preguntas cuánto tiempo tarda algo?","explanation":"«How long…?» pregunta por el tiempo."}}},{"id":"6","question":"12 a.m. is…","options":["midnight","morning","evening","noon"],"correct":0,"explanation":"12 a.m. = midnight, 12 p.m. = noon.","translations":{"es":{"question":"12 a.m. es…","explanation":"12 a.m. = medianoche, 12 p.m. = mediodía."}}},{"id":"7","question":"It''s 70°F. Is it hot or cold?","options":["Freezing","Nice and warm (about 21°C)","Extremely hot","Very cold"],"correct":1,"explanation":"70°F is about 21°C: pleasant.","translations":{"es":{"question":"Hace 70°F. ¿Hace calor o frío?","explanation":"70°F son unos 21°C: agradable."}}},{"id":"8","question":"You arrive exactly at 10:00 for a 10:00 meeting. You are…","options":["past","on time","early","late"],"correct":1,"explanation":"On time = puntual.","translations":{"es":{"question":"Llegas exactamente a las 10:00 a una reunión de las 10:00. Llegas…","explanation":"On time = puntual."}}}]}'::jsonb, 3),
  ('story', 'Right on Time', '{"text":"On Wednesday, the conversation group at the library starts at ten o''clock. Carmen doesn''t want to be late. \"How long does it take by bus?\" she asks Laura. \"It takes about forty minutes. Take the bus at a quarter past nine.\" At nine o''clock Carmen is ready. At a quarter past nine she is at the bus stop. The bus is late. Five minutes… ten minutes… At half past nine the bus finally comes. Carmen looks at her watch all the time. At five to ten she runs into the library. A man at the door smiles. \"Right on time!\" The group leader asks everybody, \"What time do you usually get up?\" \"I get up at six o''clock,\" says Carmen. \"But today… today I run!\" Everybody laughs.","translation":"El miércoles, el grupo de conversación de la biblioteca empieza a las diez en punto. Carmen no quiere llegar tarde. «¿Cuánto tarda en autobús?», le pregunta a Laura. «Unos cuarenta minutos. Toma el autobús a las nueve y cuarto.» A las nueve en punto Carmen ya está lista. A las nueve y cuarto está en la parada. El autobús viene tarde. Cinco minutos… diez minutos… A las nueve y media por fin llega el autobús. Carmen mira su reloj todo el tiempo. A las diez menos cinco entra corriendo a la biblioteca. Un hombre en la puerta sonríe. «¡Justo a tiempo!» La coordinadora del grupo les pregunta a todos: «¿A qué hora se levantan normalmente?» «Me levanto a las seis en punto», dice Carmen. «Pero hoy… ¡hoy corro!» Todos se ríen.","translations":{"es":"El miércoles, el grupo de conversación de la biblioteca empieza a las diez en punto. Carmen no quiere llegar tarde. «¿Cuánto tarda en autobús?», le pregunta a Laura. «Unos cuarenta minutos. Toma el autobús a las nueve y cuarto.» A las nueve en punto Carmen ya está lista. A las nueve y cuarto está en la parada. El autobús viene tarde. Cinco minutos… diez minutos… A las nueve y media por fin llega el autobús. Carmen mira su reloj todo el tiempo. A las diez menos cinco entra corriendo a la biblioteca. Un hombre en la puerta sonríe. «¡Justo a tiempo!» La coordinadora del grupo les pregunta a todos: «¿A qué hora se levantan normalmente?» «Me levanto a las seis en punto», dice Carmen. «Pero hoy… ¡hoy corro!» Todos se ríen."},"highlighted_words":["ten o''clock","late","How long does it take","forty minutes","a quarter past nine","half past nine","watch","Right on time","What time","six o''clock"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["What","time","is","it","now"],"translation":"¿Qué hora es ahora?","translations":{"es":"¿Qué hora es ahora?"}},{"words":["It","is","half","past","four"],"translation":"Son las cuatro y media.","translations":{"es":"Son las cuatro y media."}},{"words":["The","store","opens","at","nine"],"translation":"La tienda abre a las nueve.","translations":{"es":"La tienda abre a las nueve."}},{"words":["How","long","does","it","take","by","bus"],"translation":"¿Cuánto tarda en autobús?","translations":{"es":"¿Cuánto tarda en autobús?"}},{"words":["It","takes","about","twenty","minutes"],"translation":"Tarda unos veinte minutos.","translations":{"es":"Tarda unos veinte minutos."}},{"words":["I","am","sorry","I","am","late"],"translation":"Perdón por llegar tarde.","translations":{"es":"Perdón por llegar tarde."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Qué hora es?","translations":{"es":"¿Qué hora es?"},"answer":"What time is it"},{"prompt":"Son las diez en punto","translations":{"es":"Son las diez en punto"},"answer":"It is ten o''clock"},{"prompt":"Mi clase empieza a las nueve","translations":{"es":"Mi clase empieza a las nueve"},"answer":"My class starts at nine"},{"prompt":"¿Cuánto tiempo tarda?","translations":{"es":"¿Cuánto tiempo tarda?"},"answer":"How long does it take"},{"prompt":"Llego a tiempo","translations":{"es":"Llego a tiempo"},"answer":"I am on time"},{"prompt":"Es un cuarto para las seis","translations":{"es":"Es un cuarto para las seis"},"answer":"It is a quarter to six"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 22: Vacations
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-22', 'Vacations', '🏖️', 'Las vacaciones', 22, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"vacation","translation":"vacaciones","translations":{"es":"vacaciones"}},{"id":"2","word":"trip","translation":"viaje","translations":{"es":"viaje"}},{"id":"3","word":"hotel","translation":"hotel","translations":{"es":"hotel"}},{"id":"4","word":"suitcase","translation":"maleta","translations":{"es":"maleta"}},{"id":"5","word":"passport","translation":"pasaporte","translations":{"es":"pasaporte"}},{"id":"6","word":"sunscreen","translation":"protector solar","translations":{"es":"protector solar"}},{"id":"7","word":"sunglasses","translation":"lentes de sol","translations":{"es":"lentes de sol"}},{"id":"8","word":"swimsuit","translation":"traje de baño","translations":{"es":"traje de baño"}},{"id":"9","word":"souvenir","translation":"recuerdo","translations":{"es":"recuerdo"}},{"id":"10","word":"tourist","translation":"turista","translations":{"es":"turista"}},{"id":"11","word":"relax","translation":"relajarse","translations":{"es":"relajarse"}},{"id":"12","word":"swim","translation":"nadar","translations":{"es":"nadar"}},{"id":"13","word":"sunbathe","translation":"tomar el sol","translations":{"es":"tomar el sol"}},{"id":"14","word":"take pictures","translation":"tomar fotos","translations":{"es":"tomar fotos"}},{"id":"15","word":"stay","translation":"quedarse / hospedarse","translations":{"es":"quedarse / hospedarse"}},{"id":"16","word":"visit","translation":"visitar","translations":{"es":"visitar"}},{"id":"17","word":"wave","translation":"ola","translations":{"es":"ola"}}],"grammar":[{"structure":"am / is / are + verb-ing","example":"We are staying at a hotel. Leo is swimming.","en":"Present continuous: actions happening now","es":"Presente continuo: acciones que pasan ahora"},{"structure":"-ing spelling","example":"swim → swimming, make → making, lie → lying","en":"Spelling rules for -ing","es":"Reglas de ortografía para -ing"},{"structure":"I''m not / she isn''t + verb-ing","example":"I''m not working this week.","en":"Negative","es":"Negativo"},{"structure":"Are you…ing? / What are you doing?","example":"What are you doing? — I''m reading.","en":"Questions","es":"Preguntas"},{"structure":"present simple vs. present continuous","example":"I usually work, but this week I''m relaxing.","en":"Habits vs. right now","es":"Hábitos vs. ahora mismo"}],"tips":[{"en":"Use the present continuous for \"right now\" and \"these days\": \"I''m reading a good book\".","es":"Usa el presente continuo para «ahora mismo» y «estos días»: «I''m reading a good book» (estoy leyendo)."},{"en":"Some verbs don''t use -ing for states: say \"I like\", \"I know\", \"I want\" (not \"I''m liking\").","es":"Algunos verbos de estado no usan -ing: se dice «I like», «I know», «I want» (no «I''m liking»)."},{"en":"\"Vacation\" is American; British English says \"holiday\".","es":"«Vacation» es estadounidense; en inglés británico se dice «holiday»."},{"en":"Postcards and messages often use this tense: \"We''re having a great time!\"","es":"Las postales y los mensajes suelen usar este tiempo: «We''re having a great time!» (¡la estamos pasando genial!)."},{"en":"Don''t forget sunscreen: the California sun is strong even when it''s cool.","es":"No olvides el protector solar: el sol de California es fuerte aunque esté fresco."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"We''re on vacation!","translation":"¡Estamos de vacaciones!","translations":{"es":"¡Estamos de vacaciones!"}},{"phrase":"What are you doing?","translation":"¿Qué estás haciendo?","translations":{"es":"¿Qué estás haciendo?"}},{"phrase":"I''m relaxing on the beach.","translation":"Estoy descansando en la playa.","translations":{"es":"Estoy descansando en la playa."}},{"phrase":"We''re staying at a small hotel.","translation":"Nos estamos quedando en un hotel pequeño.","translations":{"es":"Nos estamos quedando en un hotel pequeño."}},{"phrase":"Leo is swimming in the ocean.","translation":"Leo está nadando en el mar.","translations":{"es":"Leo está nadando en el mar."}},{"phrase":"We''re having a great time.","translation":"La estamos pasando muy bien.","translations":{"es":"La estamos pasando muy bien."}},{"phrase":"Are you enjoying your trip?","translation":"¿Estás disfrutando tu viaje?","translations":{"es":"¿Estás disfrutando tu viaje?"}},{"phrase":"Don''t forget your sunscreen.","translation":"No olvides tu protector solar.","translations":{"es":"No olvides tu protector solar."}},{"phrase":"Can you take a picture of us?","translation":"¿Nos puede tomar una foto?","translations":{"es":"¿Nos puede tomar una foto?"}},{"phrase":"Wish you were here!","translation":"¡Ojalá estuvieras aquí!","translations":{"es":"¡Ojalá estuvieras aquí!"}},{"phrase":"I''m not working this week.","translation":"No estoy trabajando esta semana.","translations":{"es":"No estoy trabajando esta semana."}},{"phrase":"The waves are really big today.","translation":"Las olas están muy grandes hoy.","translations":{"es":"Las olas están muy grandes hoy."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Look! Leo ___ in the ocean.\"","options":["swims","are swimming","is swimming","swimming"],"correct":2,"explanation":"Right now → present continuous: is swimming.","translations":{"es":{"question":"Completa: «Look! Leo ___ in the ocean.»","explanation":"Ahora mismo → presente continuo: is swimming."}}},{"id":"2","question":"What is the -ing form of \"swim\"?","options":["swimming","swimeing","swiming","swimmming"],"correct":0,"explanation":"Short vowel + consonant: double it → swimming.","translations":{"es":{"question":"¿Cuál es la forma -ing de «swim»?","explanation":"Vocal corta + consonante: se duplica → swimming."}}},{"id":"3","question":"Complete: \"I usually work on Mondays, but this week I ___.\"","options":["am relaxing","relaxing","relax","relaxes"],"correct":0,"explanation":"\"This week\" is temporary → present continuous.","translations":{"es":{"question":"Completa: «I usually work on Mondays, but this week I ___.»","explanation":"«This week» es temporal → presente continuo."}}},{"id":"4","question":"Choose the correct question.","options":["What are you do?","What are you doing?","What you are doing?","What do you doing?"],"correct":1,"explanation":"Question: What + are + you + verb-ing?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Pregunta: What + are + you + verbo-ing?"}}},{"id":"5","question":"Which sentence is correct?","options":["I am like this hotel.","I like this hotel.","I''m liking this hotel.","I liking this hotel."],"correct":1,"explanation":"\"Like\" is a state verb: no -ing.","translations":{"es":{"question":"¿Qué oración es correcta?","explanation":"«Like» es un verbo de estado: sin -ing."}}},{"id":"6","question":"You protect your skin from the sun with…","options":["sunscreen","a suitcase","a passport","a souvenir"],"correct":0,"explanation":"Sunscreen = protector solar.","translations":{"es":{"question":"Proteges tu piel del sol con…","explanation":"Sunscreen = protector solar."}}},{"id":"7","question":"Complete: \"We ___ at a small hotel this week.\"","options":["is staying","are staying","staying","stays"],"correct":1,"explanation":"We → are + staying.","translations":{"es":{"question":"Completa: «We ___ at a small hotel this week.»","explanation":"We → are + staying."}}},{"id":"8","question":"Something you buy to remember a place is a…","options":["swimsuit","souvenir","tourist","wave"],"correct":1,"explanation":"A souvenir = un recuerdo.","translations":{"es":{"question":"Algo que compras para recordar un lugar es un…","explanation":"A souvenir = un recuerdo."}}}]}'::jsonb, 3),
  ('story', 'A Message from the Beach', '{"text":"It''s July, and Laura has a week of vacation. The family is staying at a small hotel in Santa Barbara. Carmen is sitting on the beach with her sunglasses and a book. She sends a message to Linda: \"Hi Linda! We''re having a great time. Right now I''m sitting on the beach. Leo is swimming with his father. The waves are really big today! Laura is sleeping under an umbrella — she is very tired from work. Tonight we are eating at a fish restaurant. I''m buying a souvenir for you. Wish you were here!\" Five minutes later, Linda answers: \"Enjoy, Carmen! Here it''s raining and I''m cleaning the house. Don''t forget your sunscreen!\" Carmen laughs and puts on more sunscreen.","translation":"Es julio y Laura tiene una semana de vacaciones. La familia se está quedando en un hotel pequeño en Santa Bárbara. Carmen está sentada en la playa con sus lentes de sol y un libro. Le manda un mensaje a Linda: «¡Hola, Linda! La estamos pasando muy bien. Ahora mismo estoy sentada en la playa. Leo está nadando con su papá. ¡Las olas están muy grandes hoy! Laura está durmiendo bajo una sombrilla: está muy cansada del trabajo. Esta noche vamos a cenar en un restaurante de mariscos. Te estoy comprando un recuerdo. ¡Ojalá estuvieras aquí!» Cinco minutos después, Linda contesta: «¡Disfruta, Carmen! Aquí está lloviendo y yo estoy limpiando la casa. ¡No olvides tu protector solar!» Carmen se ríe y se pone más protector solar.","translations":{"es":"Es julio y Laura tiene una semana de vacaciones. La familia se está quedando en un hotel pequeño en Santa Bárbara. Carmen está sentada en la playa con sus lentes de sol y un libro. Le manda un mensaje a Linda: «¡Hola, Linda! La estamos pasando muy bien. Ahora mismo estoy sentada en la playa. Leo está nadando con su papá. ¡Las olas están muy grandes hoy! Laura está durmiendo bajo una sombrilla: está muy cansada del trabajo. Esta noche vamos a cenar en un restaurante de mariscos. Te estoy comprando un recuerdo. ¡Ojalá estuvieras aquí!» Cinco minutos después, Linda contesta: «¡Disfruta, Carmen! Aquí está lloviendo y yo estoy limpiando la casa. ¡No olvides tu protector solar!» Carmen se ríe y se pone más protector solar."},"highlighted_words":["vacation","is staying","hotel","sunglasses","We''re having a great time","I''m sitting","Leo is swimming","waves","is sleeping","souvenir","Wish you were here","it''s raining","sunscreen"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["We","are","staying","at","a","small","hotel"],"translation":"Nos estamos quedando en un hotel pequeño.","translations":{"es":"Nos estamos quedando en un hotel pequeño."}},{"words":["What","are","you","doing","right","now"],"translation":"¿Qué estás haciendo ahora mismo?","translations":{"es":"¿Qué estás haciendo ahora mismo?"}},{"words":["Leo","is","swimming","with","his","father"],"translation":"Leo está nadando con su papá.","translations":{"es":"Leo está nadando con su papá."}},{"words":["We","are","having","a","great","time"],"translation":"La estamos pasando muy bien.","translations":{"es":"La estamos pasando muy bien."}},{"words":["I","am","not","working","this","week"],"translation":"No estoy trabajando esta semana.","translations":{"es":"No estoy trabajando esta semana."}},{"words":["Can","you","take","a","picture","of","us"],"translation":"¿Nos puede tomar una foto?","translations":{"es":"¿Nos puede tomar una foto?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Estamos de vacaciones","translations":{"es":"Estamos de vacaciones"},"answer":"We are on vacation"},{"prompt":"¿Qué estás haciendo?","translations":{"es":"¿Qué estás haciendo?"},"answer":"What are you doing"},{"prompt":"Estoy leyendo un libro","translations":{"es":"Estoy leyendo un libro"},"answer":"I am reading a book"},{"prompt":"Está lloviendo","translations":{"es":"Está lloviendo"},"answer":"It is raining"},{"prompt":"Leo está nadando","translations":{"es":"Leo está nadando"},"answer":"Leo is swimming"},{"prompt":"No olvides tu pasaporte","translations":{"es":"No olvides tu pasaporte"},"answer":"Do not forget your passport"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 23: Seasons and weather
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-23', 'Seasons and weather', '🌦️', 'Las estaciones y el clima', 23, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"weather","translation":"clima / tiempo","translations":{"es":"clima / tiempo"}},{"id":"2","word":"spring","translation":"primavera","translations":{"es":"primavera"}},{"id":"3","word":"summer","translation":"verano","translations":{"es":"verano"}},{"id":"4","word":"fall","translation":"otoño","translations":{"es":"otoño"}},{"id":"5","word":"winter","translation":"invierno","translations":{"es":"invierno"}},{"id":"6","word":"sunny","translation":"soleado","translations":{"es":"soleado"}},{"id":"7","word":"cloudy","translation":"nublado","translations":{"es":"nublado"}},{"id":"8","word":"rainy","translation":"lluvioso","translations":{"es":"lluvioso"}},{"id":"9","word":"windy","translation":"con viento","translations":{"es":"con viento"}},{"id":"10","word":"foggy","translation":"con neblina","translations":{"es":"con neblina"}},{"id":"11","word":"snow","translation":"nieve / nevar","translations":{"es":"nieve / nevar"}},{"id":"12","word":"rain","translation":"lluvia / llover","translations":{"es":"lluvia / llover"}},{"id":"13","word":"hot","translation":"caluroso / caliente","translations":{"es":"caluroso / caliente"}},{"id":"14","word":"warm","translation":"cálido / templado","translations":{"es":"cálido / templado"}},{"id":"15","word":"chilly","translation":"fresco / frío","translations":{"es":"fresco / frío"}},{"id":"16","word":"umbrella","translation":"paraguas / sombrilla","translations":{"es":"paraguas / sombrilla"}},{"id":"17","word":"forecast","translation":"pronóstico","translations":{"es":"pronóstico"}}],"grammar":[{"structure":"It''s + adjective","example":"It''s sunny. It''s cold today.","en":"Describing the weather with \"it\"","es":"Describir el clima con «it»"},{"structure":"It''s + verb-ing","example":"It''s raining. It''s snowing.","en":"Weather happening now","es":"Clima que está pasando ahora"},{"structure":"What''s the weather like?","example":"What''s the weather like in Guadalajara?","en":"Asking about the weather","es":"Preguntar cómo está el clima"},{"structure":"in + season","example":"It''s hot in summer.","en":"\"In\" with seasons","es":"«In» con las estaciones"},{"structure":"too / very","example":"It''s very hot. It''s too hot to walk.","en":"\"Very\" (a lot) vs. \"too\" (more than you want)","es":"«Very» (mucho) vs. «too» (demasiado)"}],"tips":[{"en":"English always needs a subject: \"It''s raining\" (not just \"Is raining\"). \"It\" is the weather.","es":"El inglés siempre necesita sujeto: «It''s raining» (no «Is raining»). «It» es el clima."},{"en":"\"Fall\" is the American word for autumn.","es":"«Fall» es la palabra estadounidense para otoño."},{"en":"Weather talk is perfect small talk with neighbors and in line at the store.","es":"Hablar del clima es la charla perfecta con vecinos y en la fila de la tienda."},{"en":"\"Chilly\" means a little cold; \"freezing\" means very, very cold.","es":"«Chilly» significa un poco frío; «freezing», muchísimo frío."},{"en":"San Diego weather is mild all year, but mornings near the ocean can be foggy in May and June.","es":"El clima de San Diego es templado todo el año, pero las mañanas cerca del mar pueden tener neblina en mayo y junio."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What''s the weather like today?","translation":"¿Cómo está el clima hoy?","translations":{"es":"¿Cómo está el clima hoy?"}},{"phrase":"It''s sunny and warm.","translation":"Está soleado y templado.","translations":{"es":"Está soleado y templado."}},{"phrase":"It''s raining. Take an umbrella.","translation":"Está lloviendo. Lleva paraguas.","translations":{"es":"Está lloviendo. Lleva paraguas."}},{"phrase":"It''s a little chilly this morning.","translation":"Está un poco fresco esta mañana.","translations":{"es":"Está un poco fresco esta mañana."}},{"phrase":"It''s too hot!","translation":"¡Hace demasiado calor!","translations":{"es":"¡Hace demasiado calor!"}},{"phrase":"What a beautiful day!","translation":"¡Qué día tan bonito!","translations":{"es":"¡Qué día tan bonito!"}},{"phrase":"What''s the forecast for tomorrow?","translation":"¿Cuál es el pronóstico para mañana?","translations":{"es":"¿Cuál es el pronóstico para mañana?"}},{"phrase":"My favorite season is spring.","translation":"Mi estación favorita es la primavera.","translations":{"es":"Mi estación favorita es la primavera."}},{"phrase":"It''s freezing!","translation":"¡Hace un frío tremendo!","translations":{"es":"¡Hace un frío tremendo!"}},{"phrase":"Is it cold outside?","translation":"¿Hace frío afuera?","translations":{"es":"¿Hace frío afuera?"}},{"phrase":"Bring a jacket.","translation":"Trae una chaqueta.","translations":{"es":"Trae una chaqueta."}},{"phrase":"The leaves change color in the fall.","translation":"Las hojas cambian de color en otoño.","translations":{"es":"Las hojas cambian de color en otoño."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence.","options":["Rains now.","It raining.","Is raining.","It''s raining."],"correct":3,"explanation":"Weather needs \"it\": It''s raining.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"El clima necesita «it»: It''s raining."}}},{"id":"2","question":"What is \"fall\" in American English?","options":["summer","spring","winter","autumn"],"correct":3,"explanation":"Fall = autumn = otoño.","translations":{"es":{"question":"¿Qué es «fall» en inglés estadounidense?","explanation":"Fall = autumn = otoño."}}},{"id":"3","question":"How do you ask about the weather?","options":["How the weather?","What weather is?","How is weather like?","What''s the weather like?"],"correct":3,"explanation":"The natural question is \"What''s the weather like?\"","translations":{"es":{"question":"¿Cómo preguntas por el clima?","explanation":"La pregunta natural es «What''s the weather like?»"}}},{"id":"4","question":"Complete: \"It''s very hot ___ summer.\"","options":["on","to","at","in"],"correct":3,"explanation":"Seasons use \"in\".","translations":{"es":{"question":"Completa: «It''s very hot ___ summer.»","explanation":"Las estaciones usan «in»."}}},{"id":"5","question":"You need this when it rains.","options":["sunscreen","a swimsuit","sunglasses","an umbrella"],"correct":3,"explanation":"An umbrella keeps you dry.","translations":{"es":{"question":"Lo necesitas cuando llueve.","explanation":"Un paraguas (umbrella) te mantiene seco."}}},{"id":"6","question":"\"It''s too hot to walk\" means…","options":["It''s cold.","It''s a little hot.","It''s nice for walking.","It''s so hot that walking is not a good idea."],"correct":3,"explanation":"\"Too\" = more than is good or possible.","translations":{"es":{"question":"«It''s too hot to walk» significa…","explanation":"«Too» = más de lo conveniente o posible."}}},{"id":"7","question":"There are many clouds. It''s…","options":["sunny","dry","snowy","cloudy"],"correct":3,"explanation":"Clouds → cloudy.","translations":{"es":{"question":"Hay muchas nubes. Está…","explanation":"Nubes (clouds) → cloudy."}}},{"id":"8","question":"\"Chilly\" means…","options":["very hot","rainy","windy","a little cold"],"correct":3,"explanation":"Chilly = un poco frío, fresco.","translations":{"es":{"question":"«Chilly» significa…","explanation":"Chilly = un poco frío, fresco."}}}]}'::jsonb, 3),
  ('story', 'Small Talk', '{"text":"In San Diego, everybody talks about the weather. In the morning, Carmen waits for the bus with an old man. \"It''s a little chilly this morning,\" he says. \"Yes, and it''s foggy,\" says Carmen. \"But the forecast says it''s sunny this afternoon.\" At the bakery, Grace says, \"What a beautiful day!\" In the evening, Carmen calls her sister Rosa in Guadalajara. \"What''s the weather like there?\" \"It''s raining a lot. It''s the rainy season. And in San Diego?\" \"Sunny and warm, like every day. Here every day is like spring.\" \"Lucky you!\" says Rosa. \"Do you miss the rain?\" Carmen thinks. \"I miss the smell of rain in Guadalajara. But I don''t miss my wet shoes!\"","translation":"En San Diego todo el mundo habla del clima. En la mañana, Carmen espera el autobús con un señor mayor. «Está un poco fresco esta mañana», dice él. «Sí, y hay neblina», dice Carmen. «Pero el pronóstico dice que en la tarde va a estar soleado.» En la panadería, Grace dice: «¡Qué día tan bonito!» En la noche, Carmen llama a su hermana Rosa en Guadalajara. «¿Cómo está el clima allá?» «Está lloviendo mucho. Es temporada de lluvias. ¿Y en San Diego?» «Soleado y templado, como todos los días. Aquí cada día es como primavera.» «¡Qué suerte!», dice Rosa. «¿Extrañas la lluvia?» Carmen piensa. «Extraño el olor de la lluvia en Guadalajara. ¡Pero no extraño los zapatos mojados!»","translations":{"es":"En San Diego todo el mundo habla del clima. En la mañana, Carmen espera el autobús con un señor mayor. «Está un poco fresco esta mañana», dice él. «Sí, y hay neblina», dice Carmen. «Pero el pronóstico dice que en la tarde va a estar soleado.» En la panadería, Grace dice: «¡Qué día tan bonito!» En la noche, Carmen llama a su hermana Rosa en Guadalajara. «¿Cómo está el clima allá?» «Está lloviendo mucho. Es temporada de lluvias. ¿Y en San Diego?» «Soleado y templado, como todos los días. Aquí cada día es como primavera.» «¡Qué suerte!», dice Rosa. «¿Extrañas la lluvia?» Carmen piensa. «Extraño el olor de la lluvia en Guadalajara. ¡Pero no extraño los zapatos mojados!»"},"highlighted_words":["weather","chilly","foggy","forecast","sunny","What a beautiful day","What''s the weather like","raining","rainy","warm","spring"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["What","is","the","weather","like","today"],"translation":"¿Cómo está el clima hoy?","translations":{"es":"¿Cómo está el clima hoy?"}},{"words":["It","is","sunny","and","warm"],"translation":"Está soleado y templado.","translations":{"es":"Está soleado y templado."}},{"words":["It","is","raining","a","lot"],"translation":"Está lloviendo mucho.","translations":{"es":"Está lloviendo mucho."}},{"words":["My","favorite","season","is","spring"],"translation":"Mi estación favorita es la primavera.","translations":{"es":"Mi estación favorita es la primavera."}},{"words":["Take","an","umbrella","with","you"],"translation":"Lleva un paraguas.","translations":{"es":"Lleva un paraguas."}},{"words":["It","is","too","cold","to","go","out"],"translation":"Hace demasiado frío para salir.","translations":{"es":"Hace demasiado frío para salir."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Está lloviendo","translations":{"es":"Está lloviendo"},"answer":"It is raining"},{"prompt":"Hace mucho calor","translations":{"es":"Hace mucho calor"},"answer":"It is very hot"},{"prompt":"¡Qué día tan bonito!","translations":{"es":"¡Qué día tan bonito!"},"answer":"What a beautiful day"},{"prompt":"¿Hace frío afuera?","translations":{"es":"¿Hace frío afuera?"},"answer":"Is it cold outside"},{"prompt":"Mi estación favorita es el verano","translations":{"es":"Mi estación favorita es el verano"},"answer":"My favorite season is summer"},{"prompt":"Trae una chaqueta","translations":{"es":"Trae una chaqueta"},"answer":"Bring a jacket"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 24: Art and museums
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-24', 'Art and museums', '🏛️', 'El arte y los museos', 24, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"museum","translation":"museo","translations":{"es":"museo"}},{"id":"2","word":"art","translation":"arte","translations":{"es":"arte"}},{"id":"3","word":"painting","translation":"pintura / cuadro","translations":{"es":"pintura / cuadro"}},{"id":"4","word":"painter","translation":"pintor / pintora","translations":{"es":"pintor / pintora"}},{"id":"5","word":"artist","translation":"artista","translations":{"es":"artista"}},{"id":"6","word":"sculpture","translation":"escultura","translations":{"es":"escultura"}},{"id":"7","word":"exhibition","translation":"exposición","translations":{"es":"exposición"}},{"id":"8","word":"gallery","translation":"galería","translations":{"es":"galería"}},{"id":"9","word":"ticket","translation":"boleto / entrada","translations":{"es":"boleto / entrada"}},{"id":"10","word":"guide","translation":"guía","translations":{"es":"guía"}},{"id":"11","word":"gift shop","translation":"tienda de recuerdos","translations":{"es":"tienda de recuerdos"}},{"id":"12","word":"famous","translation":"famoso","translations":{"es":"famoso"}},{"id":"13","word":"modern","translation":"moderno","translations":{"es":"moderno"}},{"id":"14","word":"ancient","translation":"antiguo","translations":{"es":"antiguo"}},{"id":"15","word":"colorful","translation":"colorido","translations":{"es":"colorido"}},{"id":"16","word":"free admission","translation":"entrada gratis","translations":{"es":"entrada gratis"}},{"id":"17","word":"was / were","translation":"era, estaba, fue, estuvo","translations":{"es":"era, estaba, fue, estuvo"}}],"grammar":[{"structure":"was / were","example":"The museum was beautiful. The paintings were old.","en":"Past of \"to be\"","es":"Pasado de «to be»"},{"structure":"I / he / she / it + was","example":"Frida Kahlo was a Mexican painter.","en":"\"Was\" with I, he, she, it","es":"«Was» con I, he, she, it"},{"structure":"you / we / they + were","example":"We were at the museum all day.","en":"\"Were\" with you, we, they","es":"«Were» con you, we, they"},{"structure":"wasn''t / weren''t","example":"It wasn''t expensive.","en":"Negative past of \"to be\"","es":"Negativo del pasado de «to be»"},{"structure":"Was it…? / Were you…?","example":"Was it interesting? — Yes, it was.","en":"Questions in the past with \"to be\"","es":"Preguntas en pasado con «to be»"}],"tips":[{"en":"\"Was\" and \"were\" mean both \"era/estaba\" and \"fue/estuvo\": English has one past for \"to be\".","es":"«Was» y «were» significan «era/estaba» y también «fue/estuvo»: el inglés tiene un solo pasado para «to be»."},{"en":"Many museums in the US are free on certain days. Look for \"free admission\" days.","es":"Muchos museos en Estados Unidos son gratis ciertos días. Busca los días de «free admission»."},{"en":"\"Painting\" is the picture; \"painter\" is the person who paints.","es":"«Painting» es el cuadro; «painter» es la persona que pinta."},{"en":"In a museum, \"Please don''t touch\" signs are serious. Photos are often allowed without flash.","es":"En un museo, los letreros «Please don''t touch» son serios. Las fotos suelen estar permitidas sin flash."},{"en":"\"Gift shop\" is the museum store, usually near the exit.","es":"La «gift shop» es la tienda del museo, normalmente cerca de la salida."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Two tickets, please.","translation":"Dos boletos, por favor.","translations":{"es":"Dos boletos, por favor."}},{"phrase":"Is there a guided tour?","translation":"¿Hay visita guiada?","translations":{"es":"¿Hay visita guiada?"}},{"phrase":"Who is the artist?","translation":"¿Quién es el artista?","translations":{"es":"¿Quién es el artista?"}},{"phrase":"It was painted in 1940.","translation":"Fue pintado en 1940.","translations":{"es":"Fue pintado en 1940."}},{"phrase":"Please don''t touch.","translation":"Por favor, no tocar.","translations":{"es":"Por favor, no tocar."}},{"phrase":"Can I take pictures?","translation":"¿Puedo tomar fotos?","translations":{"es":"¿Puedo tomar fotos?"}},{"phrase":"No flash, please.","translation":"Sin flash, por favor.","translations":{"es":"Sin flash, por favor."}},{"phrase":"The exhibition was amazing.","translation":"La exposición estuvo increíble.","translations":{"es":"La exposición estuvo increíble."}},{"phrase":"Where were you yesterday?","translation":"¿Dónde estuviste ayer?","translations":{"es":"¿Dónde estuviste ayer?"}},{"phrase":"I was at the museum.","translation":"Estuve en el museo.","translations":{"es":"Estuve en el museo."}},{"phrase":"It wasn''t crowded.","translation":"No había mucha gente.","translations":{"es":"No había mucha gente."}},{"phrase":"Where is the gift shop?","translation":"¿Dónde está la tienda de recuerdos?","translations":{"es":"¿Dónde está la tienda de recuerdos?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"The museum ___ beautiful.\"","options":["be","was","weres","were"],"correct":1,"explanation":"It (the museum) → was.","translations":{"es":{"question":"Completa: «The museum ___ beautiful.»","explanation":"It (el museo) → was."}}},{"id":"2","question":"Complete: \"We ___ at the gallery yesterday.\"","options":["were","is","are","was"],"correct":0,"explanation":"We → were.","translations":{"es":{"question":"Completa: «We ___ at the gallery yesterday.»","explanation":"We → were."}}},{"id":"3","question":"Choose the correct negative.","options":["It wasn''t expensive.","It didn''t was expensive.","It no was expensive.","It weren''t expensive."],"correct":0,"explanation":"It → was not → wasn''t.","translations":{"es":{"question":"Elige la negación correcta.","explanation":"It → was not → wasn''t."}}},{"id":"4","question":"Short answer: \"Was it interesting?\" (yes)","options":["Yes, was it.","Yes, it was.","Yes, it is was.","Yes, it did."],"correct":1,"explanation":"Short answer: Yes, it was.","translations":{"es":{"question":"Respuesta corta: «Was it interesting?» (sí)","explanation":"Respuesta corta: Yes, it was."}}},{"id":"5","question":"The person who paints is a…","options":["gallery","painter","paint","painting"],"correct":1,"explanation":"Painter = la persona; painting = el cuadro.","translations":{"es":{"question":"La persona que pinta es un/a…","explanation":"Painter = la persona; painting = el cuadro."}}},{"id":"6","question":"Complete: \"Frida Kahlo ___ a famous Mexican painter.\"","options":["is been","are","was","were"],"correct":2,"explanation":"She → was (she lived in the past).","translations":{"es":{"question":"Completa: «Frida Kahlo ___ a famous Mexican painter.»","explanation":"She → was (vivió en el pasado)."}}},{"id":"7","question":"Where do you buy souvenirs in a museum?","options":["at the guide","at the gallery wall","at the gift shop","at the exhibition"],"correct":2,"explanation":"The gift shop sells souvenirs.","translations":{"es":{"question":"¿Dónde compras recuerdos en un museo?","explanation":"La gift shop vende recuerdos."}}},{"id":"8","question":"Choose the correct question.","options":["Where did you was yesterday?","Where you were yesterday?","Where were you yesterday?","Where was you yesterday?"],"correct":2,"explanation":"You → were. Question: Where were you…?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"You → were. Pregunta: Where were you…?"}}}]}'::jsonb, 3),
  ('story', 'Frida in San Diego', '{"text":"Last Saturday was a special day. There was an exhibition of Frida Kahlo''s paintings at a museum in Balboa Park. Carmen and Ana were there at ten in the morning. The tickets weren''t expensive, and there was a free guided tour. The guide was a young woman from Monterrey. \"Frida was a Mexican painter,\" she said. \"Her paintings were very colorful and very personal.\" Carmen was very emotional. \"When I was a girl, my mother had a book about Frida,\" she told Ana. The museum was crowded, but it wasn''t noisy. At the end, they were in the gift shop for half an hour. Carmen bought a postcard for her sister. On Monday, Mr. Park asked, \"Where were you on Saturday?\" \"I was with Frida!\" said Carmen.","translation":"El sábado pasado fue un día especial. Había una exposición de pinturas de Frida Kahlo en un museo del Parque Balboa. Carmen y Ana estuvieron ahí a las diez de la mañana. Los boletos no eran caros y había una visita guiada gratis. La guía era una joven de Monterrey. «Frida fue una pintora mexicana», dijo. «Sus pinturas eran muy coloridas y muy personales.» Carmen estaba muy emocionada. «Cuando yo era niña, mi madre tenía un libro sobre Frida», le contó a Ana. El museo estaba lleno, pero no había ruido. Al final, estuvieron media hora en la tienda de recuerdos. Carmen compró una postal para su hermana. El lunes, el señor Park preguntó: «¿Dónde estuvieron el sábado?» «¡Estuve con Frida!», dijo Carmen.","translations":{"es":"El sábado pasado fue un día especial. Había una exposición de pinturas de Frida Kahlo en un museo del Parque Balboa. Carmen y Ana estuvieron ahí a las diez de la mañana. Los boletos no eran caros y había una visita guiada gratis. La guía era una joven de Monterrey. «Frida fue una pintora mexicana», dijo. «Sus pinturas eran muy coloridas y muy personales.» Carmen estaba muy emocionada. «Cuando yo era niña, mi madre tenía un libro sobre Frida», le contó a Ana. El museo estaba lleno, pero no había ruido. Al final, estuvieron media hora en la tienda de recuerdos. Carmen compró una postal para su hermana. El lunes, el señor Park preguntó: «¿Dónde estuvieron el sábado?» «¡Estuve con Frida!», dijo Carmen."},"highlighted_words":["was a special day","exhibition","paintings","museum","were there","tickets weren''t expensive","guided tour","guide","painter","colorful","wasn''t noisy","gift shop","Where were you","I was"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["The","museum","was","very","beautiful"],"translation":"El museo era muy bonito.","translations":{"es":"El museo era muy bonito."}},{"words":["We","were","at","the","gallery","yesterday"],"translation":"Ayer estuvimos en la galería.","translations":{"es":"Ayer estuvimos en la galería."}},{"words":["The","tickets","were","not","expensive"],"translation":"Los boletos no eran caros.","translations":{"es":"Los boletos no eran caros."}},{"words":["Who","is","the","artist","of","this","painting"],"translation":"¿Quién es el artista de este cuadro?","translations":{"es":"¿Quién es el artista de este cuadro?"}},{"words":["Where","were","you","on","Saturday"],"translation":"¿Dónde estuviste el sábado?","translations":{"es":"¿Dónde estuviste el sábado?"}},{"words":["Is","there","a","guided","tour","today"],"translation":"¿Hay visita guiada hoy?","translations":{"es":"¿Hay visita guiada hoy?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Estuve en el museo","translations":{"es":"Estuve en el museo"},"answer":"I was at the museum"},{"prompt":"Fue hermoso","translations":{"es":"Fue hermoso"},"answer":"It was beautiful"},{"prompt":"¿Dónde estuviste ayer?","translations":{"es":"¿Dónde estuviste ayer?"},"answer":"Where were you yesterday"},{"prompt":"No había mucha gente","translations":{"es":"No había mucha gente"},"answer":"It was not crowded"},{"prompt":"Dos boletos, por favor","translations":{"es":"Dos boletos, por favor"},"answer":"Two tickets, please"},{"prompt":"¿Puedo tomar fotos?","translations":{"es":"¿Puedo tomar fotos?"},"answer":"Can I take pictures"}]}'::jsonb, 6)
) as v(type, title, content, ord);

