insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"bus","translation":"autobús / camión","translations":{"es":"autobús / camión"}},{"id":"2","word":"bus stop","translation":"parada de autobús","translations":{"es":"parada de autobús"}},{"id":"3","word":"train","translation":"tren","translations":{"es":"tren"}},{"id":"4","word":"station","translation":"estación","translations":{"es":"estación"}},{"id":"5","word":"trolley","translation":"tranvía","translations":{"es":"tranvía"}},{"id":"6","word":"taxi","translation":"taxi","translations":{"es":"taxi"}},{"id":"7","word":"car","translation":"auto / carro","translations":{"es":"auto / carro"}},{"id":"8","word":"bike","translation":"bicicleta","translations":{"es":"bicicleta"}},{"id":"9","word":"plane","translation":"avión","translations":{"es":"avión"}},{"id":"10","word":"ticket","translation":"boleto","translations":{"es":"boleto"}},{"id":"11","word":"fare","translation":"tarifa / pasaje","translations":{"es":"tarifa / pasaje"}},{"id":"12","word":"driver","translation":"conductor","translations":{"es":"conductor"}},{"id":"13","word":"traffic","translation":"tráfico","translations":{"es":"tráfico"}},{"id":"14","word":"get on","translation":"subirse (a un autobús, tren)","translations":{"es":"subirse (a un autobús, tren)"}},{"id":"15","word":"get off","translation":"bajarse (de un autobús, tren)","translations":{"es":"bajarse (de un autobús, tren)"}},{"id":"16","word":"on foot","translation":"a pie","translations":{"es":"a pie"}},{"id":"17","word":"transfer","translation":"transbordo","translations":{"es":"transbordo"}}],"grammar":[{"structure":"verb + -ed","example":"I walked to the station. We waited for the bus.","en":"Past simple of regular verbs","es":"Pasado simple de los verbos regulares"},{"structure":"-ed spelling","example":"stop → stopped, try → tried, arrive → arrived","en":"Spelling rules for -ed","es":"Reglas de ortografía para -ed"},{"structure":"Three sounds of -ed","example":"walked /t/, played /d/, waited /ɪd/","en":"Pronouncing -ed","es":"Pronunciar la terminación -ed"},{"structure":"by + transport","example":"I go to work by bus. She travels by train.","en":"\"By\" with means of transport","es":"«By» con medios de transporte"},{"structure":"on foot / get on / get off","example":"Get off at the third stop.","en":"Useful transport expressions","es":"Expresiones útiles de transporte"}],"tips":[{"en":"The past simple is the same for all persons: I walked, she walked, they walked.","es":"El pasado simple es igual para todas las personas: I walked, she walked, they walked."},{"en":"Don''t say an extra syllable: \"walked\" is one syllable (wokt), not \"walk-ed\". Only after t or d do you add a syllable: wait-ed, need-ed.","es":"No agregues una sílaba extra: «walked» es una sílaba (uókt), no «walk-ed». Solo después de t o d se agrega sílaba: wait-ed, need-ed."},{"en":"\"Get on\" and \"get off\" are for buses, trains and planes; \"get in\" and \"get out of\" are for cars and taxis.","es":"«Get on» y «get off» son para autobuses, trenes y aviones; «get in» y «get out of» para autos y taxis."},{"en":"Many US cities have a \"transit app\" with real-time bus times. It''s worth installing.","es":"Muchas ciudades de Estados Unidos tienen una app de transporte con los horarios en tiempo real. Vale la pena instalarla."},{"en":"Senior discounts are common on public transport: ask \"Is there a senior fare?\"","es":"En el transporte público son comunes los descuentos para adultos mayores: pregunta «Is there a senior fare?»"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"How do you get to work?","translation":"¿Cómo te vas al trabajo?","translations":{"es":"¿Cómo te vas al trabajo?"}},{"phrase":"I usually go by bus.","translation":"Normalmente me voy en autobús.","translations":{"es":"Normalmente me voy en autobús."}},{"phrase":"Does this bus go downtown?","translation":"¿Este autobús va al centro?","translations":{"es":"¿Este autobús va al centro?"}},{"phrase":"Where do I get off?","translation":"¿Dónde me bajo?","translations":{"es":"¿Dónde me bajo?"}},{"phrase":"Get off at the third stop.","translation":"Bájese en la tercera parada.","translations":{"es":"Bájese en la tercera parada."}},{"phrase":"One ticket to Old Town, please.","translation":"Un boleto a Old Town, por favor.","translations":{"es":"Un boleto a Old Town, por favor."}},{"phrase":"Is there a senior fare?","translation":"¿Hay tarifa para adultos mayores?","translations":{"es":"¿Hay tarifa para adultos mayores?"}},{"phrase":"We waited for twenty minutes.","translation":"Esperamos veinte minutos.","translations":{"es":"Esperamos veinte minutos."}},{"phrase":"The train arrived late.","translation":"El tren llegó tarde.","translations":{"es":"El tren llegó tarde."}},{"phrase":"There was a lot of traffic.","translation":"Había mucho tráfico.","translations":{"es":"Había mucho tráfico."}},{"phrase":"I walked home.","translation":"Me fui caminando a casa.","translations":{"es":"Me fui caminando a casa."}},{"phrase":"Can you call a taxi for me?","translation":"¿Me puede llamar un taxi?","translations":{"es":"¿Me puede llamar un taxi?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Yesterday I ___ to the station.\"","options":["walk","walked","walking","walks"],"correct":1,"explanation":"Yesterday → past simple: walked.","translations":{"es":{"question":"Completa: «Yesterday I ___ to the station.»","explanation":"Yesterday → pasado simple: walked."}}},{"id":"2","question":"What is the past of \"stop\"?","options":["stopped","stoped","stopt","stopping"],"correct":0,"explanation":"Short vowel + consonant: double it → stopped.","translations":{"es":{"question":"¿Cuál es el pasado de «stop»?","explanation":"Vocal corta + consonante: se duplica → stopped."}}},{"id":"3","question":"What is the past of \"try\"?","options":["tried","tryed","tryied","tride"],"correct":0,"explanation":"Consonant + y → -ied: tried.","translations":{"es":{"question":"¿Cuál es el pasado de «try»?","explanation":"Consonante + y → -ied: tried."}}},{"id":"4","question":"In which word does -ed sound like an extra syllable /ɪd/?","options":["walked","played","waited","called"],"correct":2,"explanation":"After t or d, -ed is a new syllable: wait-ed.","translations":{"es":{"question":"¿En qué palabra -ed suena como sílaba extra /ɪd/?","explanation":"Después de t o d, -ed es una sílaba nueva: wait-ed."}}},{"id":"5","question":"Complete: \"She goes to work ___ train.\"","options":["in the","with","by","on a"],"correct":2,"explanation":"Transport: by bus, by train, by car.","translations":{"es":{"question":"Completa: «She goes to work ___ train.»","explanation":"Transporte: by bus, by train, by car."}}},{"id":"6","question":"You are on the bus and it''s your stop. You…","options":["get in","get on","get off","get up"],"correct":2,"explanation":"Leave a bus or train → get off.","translations":{"es":{"question":"Vas en el autobús y es tu parada. Tú…","explanation":"Bajarse de un autobús o tren → get off."}}},{"id":"7","question":"How do you say \"a pie\"?","options":["by foot","in foot","on foot","with feet"],"correct":2,"explanation":"The expression is \"on foot\".","translations":{"es":{"question":"¿Cómo se dice «a pie»?","explanation":"La expresión es «on foot»."}}},{"id":"8","question":"Complete: \"We ___ for the bus for twenty minutes.\"","options":["wait","waited","waitted","waits"],"correct":1,"explanation":"Past simple: waited.","translations":{"es":{"question":"Completa: «We ___ for the bus for twenty minutes.»","explanation":"Pasado simple: waited."}}}]}'::jsonb, 3),
  ('story', 'The Trolley to Old Town', '{"text":"Yesterday Carmen visited Old Town, the historic part of San Diego. She traveled by trolley for the first time. At the station, she asked the driver, \"Does this trolley go to Old Town?\" \"Yes, it does. Get off at the fourth stop.\" She showed her senior pass and paid a low fare. On the trolley, she watched the city through the window and counted the stops: one, two, three, four. She got off and walked to the old plaza. There was music, there were colorful flowers and the restaurants smelled like home. Carmen talked to a man who sold handmade toys. She stayed there for three hours. In the evening she called Laura. \"I traveled alone today, by trolley! And I didn''t get lost!\"","translation":"Ayer Carmen visitó Old Town, la parte histórica de San Diego. Viajó en tranvía por primera vez. En la estación le preguntó al conductor: «¿Este tranvía va a Old Town?» «Sí. Bájese en la cuarta parada.» Mostró su pase de adulto mayor y pagó una tarifa baja. En el tranvía miró la ciudad por la ventana y contó las paradas: una, dos, tres, cuatro. Se bajó y caminó hasta la plaza antigua. Había música, había flores de colores y los restaurantes olían a casa. Carmen platicó con un señor que vendía juguetes hechos a mano. Se quedó ahí tres horas. En la noche llamó a Laura. «¡Hoy viajé sola, en tranvía! ¡Y no me perdí!»","translations":{"es":"Ayer Carmen visitó Old Town, la parte histórica de San Diego. Viajó en tranvía por primera vez. En la estación le preguntó al conductor: «¿Este tranvía va a Old Town?» «Sí. Bájese en la cuarta parada.» Mostró su pase de adulto mayor y pagó una tarifa baja. En el tranvía miró la ciudad por la ventana y contó las paradas: una, dos, tres, cuatro. Se bajó y caminó hasta la plaza antigua. Había música, había flores de colores y los restaurantes olían a casa. Carmen platicó con un señor que vendía juguetes hechos a mano. Se quedó ahí tres horas. En la noche llamó a Laura. «¡Hoy viajé sola, en tranvía! ¡Y no me perdí!»"},"highlighted_words":["visited","traveled by trolley","station","asked the driver","Get off","fare","watched","counted the stops","walked","talked","stayed","called"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","usually","go","to","work","by","bus"],"translation":"Normalmente me voy al trabajo en autobús.","translations":{"es":"Normalmente me voy al trabajo en autobús."}},{"words":["We","waited","for","the","train","for","an","hour"],"translation":"Esperamos el tren una hora.","translations":{"es":"Esperamos el tren una hora."}},{"words":["Get","off","at","the","third","stop"],"translation":"Bájese en la tercera parada.","translations":{"es":"Bájese en la tercera parada."}},{"words":["Does","this","bus","go","downtown"],"translation":"¿Este autobús va al centro?","translations":{"es":"¿Este autobús va al centro?"}},{"words":["She","traveled","by","train","to","Los","Angeles"],"translation":"Viajó en tren a Los Ángeles.","translations":{"es":"Viajó en tren a Los Ángeles."}},{"words":["There","was","a","lot","of","traffic"],"translation":"Había mucho tráfico.","translations":{"es":"Había mucho tráfico."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Me fui caminando a casa","translations":{"es":"Me fui caminando a casa"},"answer":"I walked home"},{"prompt":"El autobús llegó tarde","translations":{"es":"El autobús llegó tarde"},"answer":"The bus arrived late"},{"prompt":"¿Dónde me bajo?","translations":{"es":"¿Dónde me bajo?"},"answer":"Where do I get off"},{"prompt":"Viajamos en tren","translations":{"es":"Viajamos en tren"},"answer":"We traveled by train"},{"prompt":"Ella visitó a su hermana","translations":{"es":"Ella visitó a su hermana"},"answer":"She visited her sister"},{"prompt":"Esperé veinte minutos","translations":{"es":"Esperé veinte minutos"},"answer":"I waited for twenty minutes"}]}'::jsonb, 6)
) as v(type, title, content, ord);

