insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"music","translation":"música","translations":{"es":"música"}},{"id":"2","word":"song","translation":"canción","translations":{"es":"canción"}},{"id":"3","word":"singer","translation":"cantante","translations":{"es":"cantante"}},{"id":"4","word":"band","translation":"banda / grupo","translations":{"es":"banda / grupo"}},{"id":"5","word":"concert","translation":"concierto","translations":{"es":"concierto"}},{"id":"6","word":"guitar","translation":"guitarra","translations":{"es":"guitarra"}},{"id":"7","word":"piano","translation":"piano","translations":{"es":"piano"}},{"id":"8","word":"violin","translation":"violín","translations":{"es":"violín"}},{"id":"9","word":"trumpet","translation":"trompeta","translations":{"es":"trompeta"}},{"id":"10","word":"drums","translation":"batería / tambores","translations":{"es":"batería / tambores"}},{"id":"11","word":"dance","translation":"bailar / baile","translations":{"es":"bailar / baile"}},{"id":"12","word":"sing","translation":"cantar","translations":{"es":"cantar"}},{"id":"13","word":"loud","translation":"fuerte (volumen)","translations":{"es":"fuerte (volumen)"}},{"id":"14","word":"went","translation":"fue / fui (pasado de go)","translations":{"es":"fue / fui (pasado de go)"}},{"id":"15","word":"sang","translation":"cantó (pasado de sing)","translations":{"es":"cantó (pasado de sing)"}},{"id":"16","word":"heard","translation":"oyó (pasado de hear)","translations":{"es":"oyó (pasado de hear)"}},{"id":"17","word":"ago","translation":"hace (tiempo)","translations":{"es":"hace (tiempo)"}}],"grammar":[{"structure":"Irregular past verbs","example":"go → went, sing → sang, buy → bought","en":"Past simple of irregular verbs","es":"Pasado simple de los verbos irregulares"},{"structure":"Common irregulars","example":"have → had, see → saw, hear → heard, make → made","en":"The most frequent irregular verbs","es":"Los verbos irregulares más frecuentes"},{"structure":"play + the + instrument","example":"She plays the guitar.","en":"\"The\" with instruments","es":"«The» con los instrumentos"},{"structure":"ago","example":"I learned the guitar many years ago.","en":"\"Ago\" = hace (tiempo)","es":"«Ago» = hace (tiempo)"},{"structure":"last night / last week / last year","example":"We went to a concert last night.","en":"Past time expressions","es":"Expresiones de tiempo pasado"}],"tips":[{"en":"Irregular verbs must be memorized, but the most common ones (went, had, saw, made, said, got) appear everywhere — you''ll learn them fast.","es":"Los verbos irregulares hay que memorizarlos, pero los más comunes (went, had, saw, made, said, got) aparecen en todas partes: los aprenderás rápido."},{"en":"\"Ago\" goes after the time: \"two years ago\" (hace dos años).","es":"«Ago» va después del tiempo: «two years ago» (hace dos años)."},{"en":"With instruments use \"the\": play the piano, play the violin. With sports, no \"the\": play soccer.","es":"Con instrumentos se usa «the»: play the piano, play the violin. Con deportes, sin «the»: play soccer."},{"en":"\"Last night\" is \"anoche\"; \"last week\" is \"la semana pasada\".","es":"«Last night» es «anoche»; «last week» es «la semana pasada»."},{"en":"Mariachi music is very popular in the Southwest of the US — especially in San Diego and Los Angeles.","es":"La música de mariachi es muy popular en el suroeste de Estados Unidos, sobre todo en San Diego y Los Ángeles."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What kind of music do you like?","translation":"¿Qué tipo de música te gusta?","translations":{"es":"¿Qué tipo de música te gusta?"}},{"phrase":"I love mariachi music.","translation":"Me encanta la música de mariachi.","translations":{"es":"Me encanta la música de mariachi."}},{"phrase":"Do you play an instrument?","translation":"¿Tocas algún instrumento?","translations":{"es":"¿Tocas algún instrumento?"}},{"phrase":"I played the guitar many years ago.","translation":"Tocaba la guitarra hace muchos años.","translations":{"es":"Tocaba la guitarra hace muchos años."}},{"phrase":"We went to a concert last night.","translation":"Anoche fuimos a un concierto.","translations":{"es":"Anoche fuimos a un concierto."}},{"phrase":"The band was amazing.","translation":"La banda estuvo increíble.","translations":{"es":"La banda estuvo increíble."}},{"phrase":"Everybody sang and danced.","translation":"Todos cantaron y bailaron.","translations":{"es":"Todos cantaron y bailaron."}},{"phrase":"Turn up the music!","translation":"¡Sube la música!","translations":{"es":"¡Sube la música!"}},{"phrase":"It''s too loud.","translation":"Está demasiado fuerte.","translations":{"es":"Está demasiado fuerte."}},{"phrase":"I heard this song on the radio.","translation":"Oí esta canción en la radio.","translations":{"es":"Oí esta canción en la radio."}},{"phrase":"Who sings this song?","translation":"¿Quién canta esta canción?","translations":{"es":"¿Quién canta esta canción?"}},{"phrase":"Let''s dance!","translation":"¡Bailemos!","translations":{"es":"¡Bailemos!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is the past of \"go\"?","options":["goed","go","gone","went"],"correct":3,"explanation":"Go → went (irregular).","translations":{"es":{"question":"¿Cuál es el pasado de «go»?","explanation":"Go → went (irregular)."}}},{"id":"2","question":"Complete: \"Last night we ___ a great song.\"","options":["hear","heared","hears","heard"],"correct":3,"explanation":"Hear → heard (irregular).","translations":{"es":{"question":"Completa: «Last night we ___ a great song.»","explanation":"Hear → heard (irregular)."}}},{"id":"3","question":"Choose the correct sentence.","options":["She plays a the piano.","She plays piano the.","She play piano.","She plays the piano."],"correct":3,"explanation":"Instruments: play the piano.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"Instrumentos: play the piano."}}},{"id":"4","question":"How do you say \"hace dos años\"?","options":["ago two years","makes two years","before two years","two years ago"],"correct":3,"explanation":"\"Ago\" goes after the time.","translations":{"es":{"question":"¿Cómo se dice «hace dos años»?","explanation":"«Ago» va después del tiempo."}}},{"id":"5","question":"What is the past of \"sing\"?","options":["singed","sung","sanged","sang"],"correct":3,"explanation":"Sing → sang.","translations":{"es":{"question":"¿Cuál es el pasado de «sing»?","explanation":"Sing → sang."}}},{"id":"6","question":"What is the past of \"have\"?","options":["hadded","has","haved","had"],"correct":3,"explanation":"Have → had.","translations":{"es":{"question":"¿Cuál es el pasado de «have»?","explanation":"Have → had."}}},{"id":"7","question":"\"Last night\" means…","options":["mañana en la noche","la última noche del año","esta noche","anoche"],"correct":3,"explanation":"Last night = anoche.","translations":{"es":{"question":"«Last night» significa…","explanation":"Last night = anoche."}}},{"id":"8","question":"The music is very strong for your ears. It''s…","options":["too slow","too cheap","too quiet","too loud"],"correct":3,"explanation":"Loud = fuerte (volumen).","translations":{"es":{"question":"La música está muy fuerte para tus oídos. Está…","explanation":"Loud = fuerte (volumen)."}}}]}'::jsonb, 3),
  ('story', 'Mariachi in the Park', '{"text":"Last Sunday there was a free mariachi concert in the park. Carmen went with Linda and Leo. When they arrived, the band was already on stage: guitars, violins and two trumpets. The music was loud and happy. Carmen sang every song. Linda didn''t know the words, but she clapped and smiled. Then the band played \"Cielito Lindo\", and everybody sang together — Mexicans, Americans, children and grandparents. Leo looked at his grandmother. \"Grandma, you know all the songs!\" \"Of course. Many years ago, I played the guitar,\" said Carmen. \"Really? Can you teach me?\" On the way home, Linda said, \"I had a wonderful time. I want to learn one song in Spanish.\" Carmen laughed. \"Ay, ay, ay, ay… that''s the first lesson!\"","translation":"El domingo pasado hubo un concierto gratis de mariachi en el parque. Carmen fue con Linda y Leo. Cuando llegaron, la banda ya estaba en el escenario: guitarras, violines y dos trompetas. La música era fuerte y alegre. Carmen cantó todas las canciones. Linda no sabía la letra, pero aplaudía y sonreía. Luego la banda tocó «Cielito Lindo» y todos cantaron juntos: mexicanos, estadounidenses, niños y abuelos. Leo miró a su abuela. «¡Abuela, te sabes todas las canciones!» «Claro. Hace muchos años tocaba la guitarra», dijo Carmen. «¿En serio? ¿Me enseñas?» De regreso a casa, Linda dijo: «La pasé de maravilla. Quiero aprender una canción en español.» Carmen se rió. «Ay, ay, ay, ay… ¡esa es la primera lección!»","translations":{"es":"El domingo pasado hubo un concierto gratis de mariachi en el parque. Carmen fue con Linda y Leo. Cuando llegaron, la banda ya estaba en el escenario: guitarras, violines y dos trompetas. La música era fuerte y alegre. Carmen cantó todas las canciones. Linda no sabía la letra, pero aplaudía y sonreía. Luego la banda tocó «Cielito Lindo» y todos cantaron juntos: mexicanos, estadounidenses, niños y abuelos. Leo miró a su abuela. «¡Abuela, te sabes todas las canciones!» «Claro. Hace muchos años tocaba la guitarra», dijo Carmen. «¿En serio? ¿Me enseñas?» De regreso a casa, Linda dijo: «La pasé de maravilla. Quiero aprender una canción en español.» Carmen se rió. «Ay, ay, ay, ay… ¡esa es la primera lección!»"},"highlighted_words":["concert","went","band","guitars","violins","trumpets","loud","sang","played","Many years ago","I played the guitar","had a wonderful time"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["We","went","to","a","concert","last","night"],"translation":"Anoche fuimos a un concierto.","translations":{"es":"Anoche fuimos a un concierto."}},{"words":["She","plays","the","violin","very","well"],"translation":"Ella toca muy bien el violín.","translations":{"es":"Ella toca muy bien el violín."}},{"words":["I","played","the","guitar","many","years","ago"],"translation":"Tocaba la guitarra hace muchos años.","translations":{"es":"Tocaba la guitarra hace muchos años."}},{"words":["What","kind","of","music","do","you","like"],"translation":"¿Qué tipo de música te gusta?","translations":{"es":"¿Qué tipo de música te gusta?"}},{"words":["Everybody","sang","and","danced"],"translation":"Todos cantaron y bailaron.","translations":{"es":"Todos cantaron y bailaron."}},{"words":["I","heard","this","song","on","the","radio"],"translation":"Oí esta canción en la radio.","translations":{"es":"Oí esta canción en la radio."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Fui a un concierto","translations":{"es":"Fui a un concierto"},"answer":"I went to a concert"},{"prompt":"Ella cantó una canción","translations":{"es":"Ella cantó una canción"},"answer":"She sang a song"},{"prompt":"¿Tocas algún instrumento?","translations":{"es":"¿Tocas algún instrumento?"},"answer":"Do you play an instrument"},{"prompt":"La música está demasiado fuerte","translations":{"es":"La música está demasiado fuerte"},"answer":"The music is too loud"},{"prompt":"La pasamos muy bien","translations":{"es":"La pasamos muy bien"},"answer":"We had a great time"},{"prompt":"Me encanta esta canción","translations":{"es":"Me encanta esta canción"},"answer":"I love this song"}]}'::jsonb, 6)
) as v(type, title, content, ord);

