insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"flower","translation":"flor","translations":{"es":"flor"}},{"id":"2","word":"rose","translation":"rosa","translations":{"es":"rosa"}},{"id":"3","word":"sunflower","translation":"girasol","translations":{"es":"girasol"}},{"id":"4","word":"plant","translation":"planta / plantar","translations":{"es":"planta / plantar"}},{"id":"5","word":"tree","translation":"árbol","translations":{"es":"árbol"}},{"id":"6","word":"grass","translation":"pasto","translations":{"es":"pasto"}},{"id":"7","word":"leaf","translation":"hoja","translations":{"es":"hoja"}},{"id":"8","word":"seeds","translation":"semillas","translations":{"es":"semillas"}},{"id":"9","word":"soil","translation":"tierra (para plantas)","translations":{"es":"tierra (para plantas)"}},{"id":"10","word":"pot","translation":"maceta","translations":{"es":"maceta"}},{"id":"11","word":"water","translation":"regar / agua","translations":{"es":"regar / agua"}},{"id":"12","word":"grow","translation":"crecer / cultivar","translations":{"es":"crecer / cultivar"}},{"id":"13","word":"weeds","translation":"malas hierbas","translations":{"es":"malas hierbas"}},{"id":"14","word":"hose","translation":"manguera","translations":{"es":"manguera"}},{"id":"15","word":"gardener","translation":"jardinero","translations":{"es":"jardinero"}},{"id":"16","word":"bloom","translation":"florecer","translations":{"es":"florecer"}},{"id":"17","word":"herbs","translation":"hierbas (de cocina)","translations":{"es":"hierbas (de cocina)"}}],"grammar":[{"structure":"didn''t + verb","example":"I didn''t water the plants yesterday.","en":"Negative past simple","es":"Pasado simple negativo"},{"structure":"Did you…? — Yes, I did. / No, I didn''t.","example":"Did you plant the roses? — Yes, I did.","en":"Past simple questions","es":"Preguntas en pasado simple"},{"structure":"did + base verb (no -ed)","example":"Did she buy seeds? (not \"Did she bought\")","en":"After \"did\", the verb goes back to its base form","es":"Después de «did», el verbo vuelve a su forma base"},{"structure":"What did you do…?","example":"What did you do on the weekend?","en":"Wh- questions in the past","es":"Preguntas con wh- en pasado"},{"structure":"need to + verb","example":"The plants need to get more sun.","en":"Talking about needs","es":"Hablar de necesidades"}],"tips":[{"en":"The past is only in \"did\": \"Did you water…?\", never \"Did you watered…?\".","es":"El pasado va solo en «did»: «Did you water…?», nunca «Did you watered…?»."},{"en":"\"What did you do on the weekend?\" is a classic Monday question at work or class.","es":"«What did you do on the weekend?» es la pregunta clásica del lunes en el trabajo o en clase."},{"en":"\"Water\" is also a verb: \"water the plants\" = regar las plantas.","es":"«Water» también es verbo: «water the plants» = regar las plantas."},{"en":"Many US cities have \"community gardens\" where neighbors grow vegetables together.","es":"Muchas ciudades de Estados Unidos tienen «community gardens» donde los vecinos cultivan verduras juntos."},{"en":"\"Weeds\" are the plants you don''t want in your garden.","es":"«Weeds» son las malas hierbas que no quieres en tu jardín."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What did you do on the weekend?","translation":"¿Qué hiciste el fin de semana?","translations":{"es":"¿Qué hiciste el fin de semana?"}},{"phrase":"I planted some flowers.","translation":"Planté unas flores.","translations":{"es":"Planté unas flores."}},{"phrase":"Did you water the plants?","translation":"¿Regaste las plantas?","translations":{"es":"¿Regaste las plantas?"}},{"phrase":"No, I didn''t. I forgot.","translation":"No. Se me olvidó.","translations":{"es":"No. Se me olvidó."}},{"phrase":"The roses are blooming.","translation":"Las rosas están floreciendo.","translations":{"es":"Las rosas están floreciendo."}},{"phrase":"This plant needs more sun.","translation":"Esta planta necesita más sol.","translations":{"es":"Esta planta necesita más sol."}},{"phrase":"Don''t step on the grass.","translation":"No pises el pasto.","translations":{"es":"No pises el pasto."}},{"phrase":"I grow my own herbs.","translation":"Cultivo mis propias hierbas.","translations":{"es":"Cultivo mis propias hierbas."}},{"phrase":"What a beautiful garden!","translation":"¡Qué jardín tan bonito!","translations":{"es":"¡Qué jardín tan bonito!"}},{"phrase":"Did it rain last night?","translation":"¿Llovió anoche?","translations":{"es":"¿Llovió anoche?"}},{"phrase":"I didn''t have time.","translation":"No tuve tiempo.","translations":{"es":"No tuve tiempo."}},{"phrase":"Can I have some seeds?","translation":"¿Me das unas semillas?","translations":{"es":"¿Me das unas semillas?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct question.","options":["Did you watered the plants?","Do you watered the plants?","Did you water the plants?","You watered the plants did?"],"correct":2,"explanation":"Did + base verb: Did you water…?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Did + verbo base: Did you water…?"}}},{"id":"2","question":"Choose the correct negative.","options":["I didn''t planted the roses.","I not plant the roses.","I didn''t plant the roses.","I no planted the roses."],"correct":2,"explanation":"didn''t + base verb.","translations":{"es":{"question":"Elige la negación correcta.","explanation":"didn''t + verbo base."}}},{"id":"3","question":"Short answer: \"Did you buy seeds?\" (no)","options":["No, I didn''t buy.","No, I don''t.","No, I didn''t.","No, I wasn''t."],"correct":2,"explanation":"Short answer: No, I didn''t.","translations":{"es":{"question":"Respuesta corta: «Did you buy seeds?» (no)","explanation":"Respuesta corta: No, I didn''t."}}},{"id":"4","question":"Complete: \"What ___ you do yesterday?\"","options":["was","did","do","were"],"correct":1,"explanation":"Past questions use \"did\".","translations":{"es":{"question":"Completa: «What ___ you do yesterday?»","explanation":"Las preguntas en pasado usan «did»."}}},{"id":"5","question":"You put soil and a plant in a…","options":["rose","pot","hose","leaf"],"correct":1,"explanation":"A pot = una maceta.","translations":{"es":{"question":"Pones tierra y una planta en una…","explanation":"A pot = una maceta."}}},{"id":"6","question":"\"Water the plants\" means…","options":["regar las plantas","lavar las plantas con jabón","plantar agua","beber agua"],"correct":0,"explanation":"\"Water\" as a verb = regar.","translations":{"es":{"question":"«Water the plants» significa…","explanation":"«Water» como verbo = regar."}}},{"id":"7","question":"Plants you don''t want in your garden are…","options":["seeds","weeds","herbs","roses"],"correct":1,"explanation":"Weeds = malas hierbas.","translations":{"es":{"question":"Las plantas que no quieres en tu jardín son…","explanation":"Weeds = malas hierbas."}}},{"id":"8","question":"Complete: \"She ___ go to the garden yesterday.\"","options":["doesn''t","didn''t","wasn''t","don''t"],"correct":1,"explanation":"Past negative: didn''t + go.","translations":{"es":{"question":"Completa: «She ___ go to the garden yesterday.»","explanation":"Negativo en pasado: didn''t + go."}}}]}'::jsonb, 3),
  ('story', 'The Community Garden', '{"text":"On Monday, Mr. Park asked the class, \"What did you do on the weekend?\" Kenji said, \"I didn''t do much. I watched TV.\" Then it was Carmen''s turn. \"On Saturday I went to the community garden with Linda. We planted tomatoes, chiles and herbs.\" \"Did you grow chiles in Mexico too?\" asked Mr. Park. \"Yes, I did. My mother had a big garden with roses and sunflowers.\" \"And did you water the plants on Sunday?\" asked Ana. Carmen laughed. \"No, I didn''t. It rained!\" After class, Kenji asked, \"Can I visit the garden? In Japan my grandfather grew vegetables.\" \"Of course,\" said Carmen. \"Come on Saturday. But bring a hose — and patience. The weeds grow faster than the tomatoes!\"","translation":"El lunes, el señor Park le preguntó a la clase: «¿Qué hicieron el fin de semana?» Kenji dijo: «No hice mucho. Vi la tele.» Luego le tocó a Carmen. «El sábado fui al huerto comunitario con Linda. Plantamos jitomates, chiles y hierbas.» «¿También cultivaba chiles en México?», preguntó el señor Park. «Sí. Mi mamá tenía un jardín grande con rosas y girasoles.» «¿Y regaron las plantas el domingo?», preguntó Ana. Carmen se rió. «No. ¡Llovió!» Después de clase, Kenji preguntó: «¿Puedo visitar el huerto? En Japón mi abuelo cultivaba verduras.» «Claro», dijo Carmen. «Ven el sábado. Pero trae una manguera… y paciencia. ¡La mala hierba crece más rápido que los jitomates!»","translations":{"es":"El lunes, el señor Park le preguntó a la clase: «¿Qué hicieron el fin de semana?» Kenji dijo: «No hice mucho. Vi la tele.» Luego le tocó a Carmen. «El sábado fui al huerto comunitario con Linda. Plantamos jitomates, chiles y hierbas.» «¿También cultivaba chiles en México?», preguntó el señor Park. «Sí. Mi mamá tenía un jardín grande con rosas y girasoles.» «¿Y regaron las plantas el domingo?», preguntó Ana. Carmen se rió. «No. ¡Llovió!» Después de clase, Kenji preguntó: «¿Puedo visitar el huerto? En Japón mi abuelo cultivaba verduras.» «Claro», dijo Carmen. «Ven el sábado. Pero trae una manguera… y paciencia. ¡La mala hierba crece más rápido que los jitomates!»"},"highlighted_words":["What did you do on the weekend","I didn''t do much","community garden","planted","herbs","Did you grow","Yes, I did","roses","sunflowers","did you water the plants","No, I didn''t","hose","weeds"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["What","did","you","do","on","the","weekend"],"translation":"¿Qué hiciste el fin de semana?","translations":{"es":"¿Qué hiciste el fin de semana?"}},{"words":["I","did","not","water","the","plants"],"translation":"No regué las plantas.","translations":{"es":"No regué las plantas."}},{"words":["Did","you","plant","the","roses"],"translation":"¿Plantaste las rosas?","translations":{"es":"¿Plantaste las rosas?"}},{"words":["This","plant","needs","more","sun"],"translation":"Esta planta necesita más sol.","translations":{"es":"Esta planta necesita más sol."}},{"words":["My","mother","had","a","big","garden"],"translation":"Mi madre tenía un jardín grande.","translations":{"es":"Mi madre tenía un jardín grande."}},{"words":["The","weeds","grow","very","fast"],"translation":"Las malas hierbas crecen muy rápido.","translations":{"es":"Las malas hierbas crecen muy rápido."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Planté unas flores","translations":{"es":"Planté unas flores"},"answer":"I planted some flowers"},{"prompt":"¿Regaste las plantas?","translations":{"es":"¿Regaste las plantas?"},"answer":"Did you water the plants"},{"prompt":"No tuve tiempo","translations":{"es":"No tuve tiempo"},"answer":"I did not have time"},{"prompt":"¿Qué hiciste ayer?","translations":{"es":"¿Qué hiciste ayer?"},"answer":"What did you do yesterday"},{"prompt":"Las rosas están hermosas","translations":{"es":"Las rosas están hermosas"},"answer":"The roses are beautiful"},{"prompt":"No llovió","translations":{"es":"No llovió"},"answer":"It did not rain"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 28: Appointments and visits
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-28', 'Appointments and visits', '📅', 'Citas y visitas', 28, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"appointment","translation":"cita (médico, trámite)","translations":{"es":"cita (médico, trámite)"}},{"id":"2","word":"schedule","translation":"horario / agenda","translations":{"es":"horario / agenda"}},{"id":"3","word":"reschedule","translation":"cambiar la cita","translations":{"es":"cambiar la cita"}},{"id":"4","word":"cancel","translation":"cancelar","translations":{"es":"cancelar"}},{"id":"5","word":"available","translation":"disponible","translations":{"es":"disponible"}},{"id":"6","word":"busy","translation":"ocupado","translations":{"es":"ocupado"}},{"id":"7","word":"free","translation":"libre / gratis","translations":{"es":"libre / gratis"}},{"id":"8","word":"visit","translation":"visita / visitar","translations":{"es":"visita / visitar"}},{"id":"9","word":"guest","translation":"invitado","translations":{"es":"invitado"}},{"id":"10","word":"invite","translation":"invitar","translations":{"es":"invitar"}},{"id":"11","word":"reminder","translation":"recordatorio","translations":{"es":"recordatorio"}},{"id":"12","word":"tomorrow morning","translation":"mañana en la mañana","translations":{"es":"mañana en la mañana"}},{"id":"13","word":"next week","translation":"la próxima semana","translations":{"es":"la próxima semana"}},{"id":"14","word":"plan","translation":"plan / planear","translations":{"es":"plan / planear"}},{"id":"15","word":"drop by","translation":"pasar de visita","translations":{"es":"pasar de visita"}},{"id":"16","word":"receptionist","translation":"recepcionista","translations":{"es":"recepcionista"}},{"id":"17","word":"confirm","translation":"confirmar","translations":{"es":"confirmar"}}],"grammar":[{"structure":"be going to + verb","example":"I''m going to visit Linda tomorrow.","en":"Future plans with \"going to\"","es":"Planes futuros con «going to»"},{"structure":"I''m not going to…","example":"We''re not going to stay long.","en":"Negative","es":"Negativo"},{"structure":"Are you going to…?","example":"Are you going to come to the party?","en":"Questions about plans","es":"Preguntar por planes"},{"structure":"make an appointment / reschedule / cancel","example":"I need to reschedule my appointment.","en":"Managing appointments","es":"Gestionar citas"},{"structure":"Are you free on…? / How about…?","example":"Are you free on Thursday? How about three o''clock?","en":"Arranging a time","es":"Acordar una hora"}],"tips":[{"en":"In fast speech \"going to\" sounds like \"gonna\": \"I''m gonna call you.\" Understand it, but write \"going to\".","es":"Al hablar rápido, «going to» suena como «gonna»: «I''m gonna call you.» Entiéndelo, pero escribe «going to»."},{"en":"Doctors, hairdressers and banks usually need an appointment. Call ahead or book online.","es":"Los médicos, las estéticas y los bancos normalmente piden cita. Llama antes o haz la reservación en línea."},{"en":"If you can''t go, call to cancel: some offices charge a fee for missed appointments.","es":"Si no puedes ir, llama para cancelar: algunos consultorios cobran por las citas perdidas."},{"en":"When visiting someone''s home in the US, it''s polite to say what time you''re coming and not arrive too early.","es":"Al visitar una casa en Estados Unidos, es de buena educación avisar a qué hora llegas y no llegar demasiado temprano."},{"en":"\"Drop by\" means a short, informal visit: \"Drop by anytime!\"","es":"«Drop by» significa pasar de visita un rato, informalmente: «Drop by anytime!» (¡pasa cuando quieras!)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to make an appointment.","translation":"Quisiera hacer una cita.","translations":{"es":"Quisiera hacer una cita."}},{"phrase":"Are you available on Thursday?","translation":"¿Tiene disponibilidad el jueves?","translations":{"es":"¿Tiene disponibilidad el jueves?"}},{"phrase":"How about ten thirty?","translation":"¿Qué tal a las diez y media?","translations":{"es":"¿Qué tal a las diez y media?"}},{"phrase":"That works for me.","translation":"Me queda bien.","translations":{"es":"Me queda bien."}},{"phrase":"I need to reschedule.","translation":"Necesito cambiar la cita.","translations":{"es":"Necesito cambiar la cita."}},{"phrase":"I''m going to be a little late.","translation":"Voy a llegar un poco tarde.","translations":{"es":"Voy a llegar un poco tarde."}},{"phrase":"What are you going to do tomorrow?","translation":"¿Qué vas a hacer mañana?","translations":{"es":"¿Qué vas a hacer mañana?"}},{"phrase":"I''m going to visit my friend.","translation":"Voy a visitar a mi amiga.","translations":{"es":"Voy a visitar a mi amiga."}},{"phrase":"Can I drop by this afternoon?","translation":"¿Puedo pasar esta tarde?","translations":{"es":"¿Puedo pasar esta tarde?"}},{"phrase":"See you at three!","translation":"¡Nos vemos a las tres!","translations":{"es":"¡Nos vemos a las tres!"}},{"phrase":"Thank you for coming.","translation":"Gracias por venir.","translations":{"es":"Gracias por venir."}},{"phrase":"Please confirm your appointment.","translation":"Por favor, confirme su cita.","translations":{"es":"Por favor, confirme su cita."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Tomorrow I ___ visit my sister.\"","options":["going to","go to","am going to","am go"],"correct":2,"explanation":"Plans: am/is/are + going to + verb.","translations":{"es":{"question":"Completa: «Tomorrow I ___ visit my sister.»","explanation":"Planes: am/is/are + going to + verbo."}}},{"id":"2","question":"Choose the correct question.","options":["Do you going to come?","Are you going to come?","You going to come?","Are you go to come?"],"correct":1,"explanation":"Are + you + going to + verb?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Are + you + going to + verbo?"}}},{"id":"3","question":"You can''t go to your appointment on Monday, but you can on Wednesday. You want to…","options":["reschedule","confirm","cancel forever","drop by"],"correct":0,"explanation":"Reschedule = change the date or time.","translations":{"es":{"question":"No puedes ir a tu cita el lunes, pero sí el miércoles. Quieres…","explanation":"Reschedule = cambiar la fecha u hora."}}},{"id":"4","question":"The receptionist suggests 3 p.m. and it''s fine for you. You say:","options":["I''m going to cancel.","That works for me.","That''s busy.","Drop by."],"correct":1,"explanation":"\"That works for me\" = me queda bien.","translations":{"es":{"question":"La recepcionista propone las 3 p.m. y te parece bien. Dices:","explanation":"«That works for me» = me queda bien."}}},{"id":"5","question":"Complete: \"She ___ going to come tonight. She''s sick.\"","options":["don''t","isn''t","doesn''t","aren''t"],"correct":1,"explanation":"She → is not → isn''t going to.","translations":{"es":{"question":"Completa: «She ___ going to come tonight. She''s sick.»","explanation":"She → is not → isn''t going to."}}},{"id":"6","question":"\"Gonna\" is the spoken form of…","options":["going to","got to","want to","go now"],"correct":0,"explanation":"gonna = going to (informal speech).","translations":{"es":{"question":"«Gonna» es la forma hablada de…","explanation":"gonna = going to (habla informal)."}}},{"id":"7","question":"How do you ask for a medical appointment politely?","options":["Give me appointment.","I''d like to make an appointment, please.","I want doctor now.","Appointment, yes?"],"correct":1,"explanation":"\"I''d like to make an appointment\" is polite and clear.","translations":{"es":{"question":"¿Cómo pides una cita médica amablemente?","explanation":"«I''d like to make an appointment» es amable y claro."}}},{"id":"8","question":"\"Drop by anytime\" means…","options":["Don''t visit me.","Visit me whenever you want.","Call before you come.","Leave something at my door."],"correct":1,"explanation":"It''s a friendly invitation to visit.","translations":{"es":{"question":"«Drop by anytime» significa…","explanation":"Es una invitación amistosa a visitar."}}}]}'::jsonb, 3),
  ('story', 'A Busy Week', '{"text":"Carmen''s week is going to be very busy. On Monday she''s going to have English class. On Tuesday she has an appointment with the dentist at nine. On Wednesday she''s going to make tamales for the bakery. Then Linda calls. \"Carmen, my brother is going to visit from Texas. Are you free on Thursday? I''m going to have a small dinner.\" Carmen looks at her calendar. \"Thursday… yes, I''m free. What time?\" \"How about six thirty?\" \"That works for me!\" But on Monday, the dentist''s office calls. \"Mrs. Ruiz, the doctor is not going to be here on Tuesday. Can you reschedule?\" \"Of course. Is Friday available?\" \"Yes, Friday at ten.\" Carmen writes everything down. \"Busy week,\" she says, \"but a happy one.\"","translation":"La semana de Carmen va a estar muy ocupada. El lunes va a tener clase de inglés. El martes tiene cita con el dentista a las nueve. El miércoles va a hacer tamales para la panadería. Entonces llama Linda. «Carmen, mi hermano va a venir de visita desde Texas. ¿Estás libre el jueves? Voy a hacer una cena pequeña.» Carmen mira su calendario. «El jueves… sí, estoy libre. ¿A qué hora?» «¿Qué tal a las seis y media?» «¡Me queda bien!» Pero el lunes llaman del consultorio del dentista. «Señora Ruiz, el doctor no va a estar el martes. ¿Puede cambiar la cita?» «Claro. ¿Tiene disponible el viernes?» «Sí, el viernes a las diez.» Carmen lo anota todo. «Semana ocupada», dice, «pero feliz.»","translations":{"es":"La semana de Carmen va a estar muy ocupada. El lunes va a tener clase de inglés. El martes tiene cita con el dentista a las nueve. El miércoles va a hacer tamales para la panadería. Entonces llama Linda. «Carmen, mi hermano va a venir de visita desde Texas. ¿Estás libre el jueves? Voy a hacer una cena pequeña.» Carmen mira su calendario. «El jueves… sí, estoy libre. ¿A qué hora?» «¿Qué tal a las seis y media?» «¡Me queda bien!» Pero el lunes llaman del consultorio del dentista. «Señora Ruiz, el doctor no va a estar el martes. ¿Puede cambiar la cita?» «Claro. ¿Tiene disponible el viernes?» «Sí, el viernes a las diez.» Carmen lo anota todo. «Semana ocupada», dice, «pero feliz.»"},"highlighted_words":["busy","she''s going to have","appointment","is going to visit","Are you free on Thursday","How about six thirty","That works for me","is not going to be here","reschedule","available"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","am","going","to","visit","my","friend"],"translation":"Voy a visitar a mi amiga.","translations":{"es":"Voy a visitar a mi amiga."}},{"words":["Are","you","free","on","Thursday"],"translation":"¿Estás libre el jueves?","translations":{"es":"¿Estás libre el jueves?"}},{"words":["I","would","like","to","make","an","appointment"],"translation":"Quisiera hacer una cita.","translations":{"es":"Quisiera hacer una cita."}},{"words":["We","are","not","going","to","stay","long"],"translation":"No nos vamos a quedar mucho tiempo.","translations":{"es":"No nos vamos a quedar mucho tiempo."}},{"words":["How","about","ten","thirty"],"translation":"¿Qué tal a las diez y media?","translations":{"es":"¿Qué tal a las diez y media?"}},{"words":["I","need","to","reschedule","my","appointment"],"translation":"Necesito cambiar mi cita.","translations":{"es":"Necesito cambiar mi cita."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Te voy a llamar","translations":{"es":"Te voy a llamar"},"answer":"I am going to call you"},{"prompt":"¿Qué vas a hacer?","translations":{"es":"¿Qué vas a hacer?"},"answer":"What are you going to do"},{"prompt":"Necesito cancelar mi cita","translations":{"es":"Necesito cancelar mi cita"},"answer":"I need to cancel my appointment"},{"prompt":"Me queda bien","translations":{"es":"Me queda bien"},"answer":"That works for me"},{"prompt":"Gracias por venir","translations":{"es":"Gracias por venir"},"answer":"Thank you for coming"},{"prompt":"Ella va a llegar tarde","translations":{"es":"Ella va a llegar tarde"},"answer":"She is going to be late"}]}'::jsonb, 6)
) as v(type, title, content, ord);

