insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"movie","translation":"película","translations":{"es":"película"}},{"id":"2","word":"the movies","translation":"el cine","translations":{"es":"el cine"}},{"id":"3","word":"theater","translation":"teatro","translations":{"es":"teatro"}},{"id":"4","word":"play","translation":"obra de teatro","translations":{"es":"obra de teatro"}},{"id":"5","word":"actor","translation":"actor","translations":{"es":"actor"}},{"id":"6","word":"actress","translation":"actriz","translations":{"es":"actriz"}},{"id":"7","word":"stage","translation":"escenario","translations":{"es":"escenario"}},{"id":"8","word":"seat","translation":"asiento","translations":{"es":"asiento"}},{"id":"9","word":"screen","translation":"pantalla","translations":{"es":"pantalla"}},{"id":"10","word":"subtitles","translation":"subtítulos","translations":{"es":"subtítulos"}},{"id":"11","word":"comedy","translation":"comedia","translations":{"es":"comedia"}},{"id":"12","word":"drama","translation":"drama","translations":{"es":"drama"}},{"id":"13","word":"popcorn","translation":"palomitas","translations":{"es":"palomitas"}},{"id":"14","word":"show","translation":"función / espectáculo","translations":{"es":"función / espectáculo"}},{"id":"15","word":"the best","translation":"el mejor","translations":{"es":"el mejor"}},{"id":"16","word":"the worst","translation":"el peor","translations":{"es":"el peor"}},{"id":"17","word":"funniest","translation":"el más gracioso","translations":{"es":"el más gracioso"}}],"grammar":[{"structure":"the + adjective-est","example":"It''s the longest movie of the year.","en":"Superlatives with short adjectives","es":"Superlativos con adjetivos cortos"},{"structure":"the most + long adjective","example":"She is the most famous actress in Mexico.","en":"Superlatives with long adjectives","es":"Superlativos con adjetivos largos"},{"structure":"the best / the worst","example":"That was the best show I''ve ever seen.","en":"Irregular superlatives","es":"Superlativos irregulares"},{"structure":"superlative + in / of","example":"the biggest theater in the city","en":"\"In\" with places, \"of\" with groups or time","es":"«In» con lugares, «of» con grupos o tiempo"},{"structure":"What''s playing…?","example":"What''s playing at the movies tonight?","en":"Asking what''s on","es":"Preguntar qué hay en cartelera"}],"tips":[{"en":"Superlatives always need \"the\": the best, the most beautiful.","es":"Los superlativos siempre llevan «the»: the best, the most beautiful."},{"en":"In American English you \"go to the movies\" (ir al cine). \"Movie theater\" is the building.","es":"En inglés estadounidense se dice «go to the movies» (ir al cine). «Movie theater» es el edificio."},{"en":"Many movies have Spanish subtitles or audio: ask \"Is there a Spanish version?\"","es":"Muchas películas tienen subtítulos o audio en español: pregunta «Is there a Spanish version?»"},{"en":"\"Matinee\" is an afternoon show; tickets are often cheaper.","es":"«Matinee» es una función de la tarde; los boletos suelen ser más baratos."},{"en":"Watching movies in English with English subtitles is great practice for your ear.","es":"Ver películas en inglés con subtítulos en inglés es una excelente práctica para el oído."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What''s playing tonight?","translation":"¿Qué hay en cartelera esta noche?","translations":{"es":"¿Qué hay en cartelera esta noche?"}},{"phrase":"Two tickets for the seven o''clock show.","translation":"Dos boletos para la función de las siete.","translations":{"es":"Dos boletos para la función de las siete."}},{"phrase":"Where are our seats?","translation":"¿Dónde están nuestros asientos?","translations":{"es":"¿Dónde están nuestros asientos?"}},{"phrase":"Does it have subtitles?","translation":"¿Tiene subtítulos?","translations":{"es":"¿Tiene subtítulos?"}},{"phrase":"Let''s get some popcorn.","translation":"Vamos por palomitas.","translations":{"es":"Vamos por palomitas."}},{"phrase":"Please turn off your phone.","translation":"Por favor, apague su teléfono.","translations":{"es":"Por favor, apague su teléfono."}},{"phrase":"It was the funniest movie of the year!","translation":"¡Fue la película más graciosa del año!","translations":{"es":"¡Fue la película más graciosa del año!"}},{"phrase":"She''s the best actress.","translation":"Es la mejor actriz.","translations":{"es":"Es la mejor actriz."}},{"phrase":"What did you think of the movie?","translation":"¿Qué te pareció la película?","translations":{"es":"¿Qué te pareció la película?"}},{"phrase":"I loved it!","translation":"¡Me encantó!","translations":{"es":"¡Me encantó!"}},{"phrase":"It was a little boring.","translation":"Estuvo un poco aburrida.","translations":{"es":"Estuvo un poco aburrida."}},{"phrase":"No spoilers, please!","translation":"¡No me cuentes el final, por favor!","translations":{"es":"¡No me cuentes el final, por favor!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"It''s the ___ movie of the year.\"","options":["most funny","funniest","funnier","funnyest"],"correct":1,"explanation":"Funny → the funniest (-y → -iest).","translations":{"es":{"question":"Completa: «It''s the ___ movie of the year.»","explanation":"Funny → the funniest (-y → -iest)."}}},{"id":"2","question":"Complete: \"She is ___ actress in the world.\"","options":["most famous","the most famous","the more famous","the famousest"],"correct":1,"explanation":"Long adjective: the most famous.","translations":{"es":{"question":"Completa: «She is ___ actress in the world.»","explanation":"Adjetivo largo: the most famous."}}},{"id":"3","question":"What is the superlative of \"good\"?","options":["the best","the better","the most good","the goodest"],"correct":0,"explanation":"Good → better → the best.","translations":{"es":{"question":"¿Cuál es el superlativo de «good»?","explanation":"Good → better → the best."}}},{"id":"4","question":"Complete: \"It''s the biggest theater ___ San Diego.\"","options":["on","in","at","of"],"correct":1,"explanation":"With places we use \"in\".","translations":{"es":{"question":"Completa: «It''s the biggest theater ___ San Diego.»","explanation":"Con lugares se usa «in»."}}},{"id":"5","question":"How do you say \"ir al cine\" in American English?","options":["go to movie","go to the movies","go to the film","go to the cinema house"],"correct":1,"explanation":"Americans say \"go to the movies\".","translations":{"es":{"question":"¿Cómo se dice «ir al cine» en inglés estadounidense?","explanation":"En Estados Unidos se dice «go to the movies»."}}},{"id":"6","question":"Words at the bottom of the screen that translate the dialogue are…","options":["subtitles","stages","seats","tickets"],"correct":0,"explanation":"Subtitles = subtítulos.","translations":{"es":{"question":"Las palabras abajo en la pantalla que traducen los diálogos son…","explanation":"Subtitles = subtítulos."}}},{"id":"7","question":"Your friend wants to tell you the end of the movie. You say:","options":["Where are our seats?","No spoilers, please!","I loved it!","Let''s get popcorn!"],"correct":1,"explanation":"A spoiler reveals the end.","translations":{"es":{"question":"Tu amigo quiere contarte el final de la película. Dices:","explanation":"Un «spoiler» revela el final."}}},{"id":"8","question":"What is the superlative of \"bad\"?","options":["the most bad","the worse","the worst","the baddest"],"correct":2,"explanation":"Bad → worse → the worst.","translations":{"es":{"question":"¿Cuál es el superlativo de «bad»?","explanation":"Bad → worse → the worst."}}}]}'::jsonb, 3),
  ('story', 'Movie Night', '{"text":"On Friday night, Ana invites Carmen to the movies. \"What''s playing?\" asks Carmen. \"A new comedy. People say it''s the funniest movie of the year.\" At the theater, Ana buys two tickets for the seven o''clock show. Carmen buys the biggest popcorn on the menu. \"Does it have subtitles?\" she asks. \"Only in English,\" says Ana. \"But that''s good practice!\" The movie is about a grandmother who travels to New York alone. The actress is wonderful. Carmen understands most of the jokes and laughs a lot. At the end, everybody claps. \"What did you think?\" asks Ana. \"It was the best movie I''ve ever seen in English! And the grandmother… she is a little like me.\" Ana laughs. \"Maybe one day you''re going to travel to New York too.\"","translation":"El viernes en la noche, Ana invita a Carmen al cine. «¿Qué hay en cartelera?», pregunta Carmen. «Una comedia nueva. La gente dice que es la película más graciosa del año.» En el cine, Ana compra dos boletos para la función de las siete. Carmen compra las palomitas más grandes del menú. «¿Tiene subtítulos?», pregunta. «Solo en inglés», dice Ana. «¡Pero es buena práctica!» La película trata de una abuela que viaja sola a Nueva York. La actriz es maravillosa. Carmen entiende la mayoría de los chistes y se ríe mucho. Al final, todos aplauden. «¿Qué te pareció?», pregunta Ana. «¡Es la mejor película que he visto en inglés! Y la abuela… se parece un poco a mí.» Ana se ríe. «Quizás un día tú también vas a viajar a Nueva York.»","translations":{"es":"El viernes en la noche, Ana invita a Carmen al cine. «¿Qué hay en cartelera?», pregunta Carmen. «Una comedia nueva. La gente dice que es la película más graciosa del año.» En el cine, Ana compra dos boletos para la función de las siete. Carmen compra las palomitas más grandes del menú. «¿Tiene subtítulos?», pregunta. «Solo en inglés», dice Ana. «¡Pero es buena práctica!» La película trata de una abuela que viaja sola a Nueva York. La actriz es maravillosa. Carmen entiende la mayoría de los chistes y se ríe mucho. Al final, todos aplauden. «¿Qué te pareció?», pregunta Ana. «¡Es la mejor película que he visto en inglés! Y la abuela… se parece un poco a mí.» Ana se ríe. «Quizás un día tú también vas a viajar a Nueva York.»"},"highlighted_words":["the movies","What''s playing","comedy","the funniest movie of the year","theater","tickets","show","the biggest popcorn","subtitles","actress","What did you think","the best movie"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["It","was","the","funniest","movie","of","the","year"],"translation":"Fue la película más graciosa del año.","translations":{"es":"Fue la película más graciosa del año."}},{"words":["She","is","the","best","actress","in","Mexico"],"translation":"Es la mejor actriz de México.","translations":{"es":"Es la mejor actriz de México."}},{"words":["What","is","playing","at","the","movies","tonight"],"translation":"¿Qué hay en el cine esta noche?","translations":{"es":"¿Qué hay en el cine esta noche?"}},{"words":["Does","the","movie","have","subtitles"],"translation":"¿La película tiene subtítulos?","translations":{"es":"¿La película tiene subtítulos?"}},{"words":["Two","tickets","for","the","seven","o''clock","show"],"translation":"Dos boletos para la función de las siete.","translations":{"es":"Dos boletos para la función de las siete."}},{"words":["This","is","the","biggest","theater","in","the","city"],"translation":"Este es el teatro más grande de la ciudad.","translations":{"es":"Este es el teatro más grande de la ciudad."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Vamos al cine","translations":{"es":"Vamos al cine"},"answer":"Let''s go to the movies"},{"prompt":"Fue la mejor película","translations":{"es":"Fue la mejor película"},"answer":"It was the best movie"},{"prompt":"Me encantó","translations":{"es":"Me encantó"},"answer":"I loved it"},{"prompt":"¿Dónde están nuestros asientos?","translations":{"es":"¿Dónde están nuestros asientos?"},"answer":"Where are our seats"},{"prompt":"¿Tiene subtítulos?","translations":{"es":"¿Tiene subtítulos?"},"answer":"Does it have subtitles"},{"prompt":"Estuvo un poco aburrida","translations":{"es":"Estuvo un poco aburrida"},"answer":"It was a little boring"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 30: On the phone
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-30', 'On the phone', '📞', 'Al teléfono', 30, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"phone","translation":"teléfono","translations":{"es":"teléfono"}},{"id":"2","word":"cell phone","translation":"celular","translations":{"es":"celular"}},{"id":"3","word":"call","translation":"llamar / llamada","translations":{"es":"llamar / llamada"}},{"id":"4","word":"call back","translation":"devolver la llamada","translations":{"es":"devolver la llamada"}},{"id":"5","word":"hang up","translation":"colgar","translations":{"es":"colgar"}},{"id":"6","word":"hold on","translation":"esperar (en la línea)","translations":{"es":"esperar (en la línea)"}},{"id":"7","word":"message","translation":"mensaje / recado","translations":{"es":"mensaje / recado"}},{"id":"8","word":"voicemail","translation":"buzón de voz","translations":{"es":"buzón de voz"}},{"id":"9","word":"text","translation":"mensaje de texto / mandar mensaje","translations":{"es":"mensaje de texto / mandar mensaje"}},{"id":"10","word":"wrong number","translation":"número equivocado","translations":{"es":"número equivocado"}},{"id":"11","word":"speak up","translation":"hablar más fuerte","translations":{"es":"hablar más fuerte"}},{"id":"12","word":"battery","translation":"batería / pila","translations":{"es":"batería / pila"}},{"id":"13","word":"charger","translation":"cargador","translations":{"es":"cargador"}},{"id":"14","word":"signal","translation":"señal","translations":{"es":"señal"}},{"id":"15","word":"video call","translation":"videollamada","translations":{"es":"videollamada"}},{"id":"16","word":"answer","translation":"contestar","translations":{"es":"contestar"}},{"id":"17","word":"busy line","translation":"línea ocupada","translations":{"es":"línea ocupada"}}],"grammar":[{"structure":"I''ll + verb (offers)","example":"I''ll call you back. I''ll get it!","en":"\"Will\" for offers and quick decisions","es":"«Will» para ofrecimientos y decisiones rápidas"},{"structure":"I''ll + verb (promises)","example":"I''ll be there at five, I promise.","en":"\"Will\" for promises","es":"«Will» para promesas"},{"structure":"Could you…? / Can I…?","example":"Could you speak up, please? Can I leave a message?","en":"Polite requests on the phone","es":"Pedidos amables por teléfono"},{"structure":"This is… (not \"I am\")","example":"Hello, this is Carmen.","en":"Saying who you are on the phone","es":"Decir quién eres por teléfono"},{"structure":"Phrasal verbs: call back, hang up, hold on","example":"Hold on a minute, please.","en":"Common phone phrasal verbs","es":"Verbos frasales comunes del teléfono"}],"tips":[{"en":"On the phone say \"This is Carmen\", not \"I am Carmen\".","es":"Por teléfono se dice «This is Carmen», no «I am Carmen»."},{"en":"If you don''t understand a name, ask the person to spell it, or ask \"Can you text it to me?\".","es":"Si no entiendes un nombre, pide que lo deletreen o pregunta «Can you text it to me?» (¿me lo mandas por mensaje?)."},{"en":"\"Text\" is also a verb: \"I''ll text you\" = Te mando un mensaje.","es":"«Text» también es verbo: «I''ll text you» = Te mando un mensaje."},{"en":"Automated phone menus say \"Press 1 for English, press 2 for Spanish\" — many services have Spanish options.","es":"Los menús automáticos dicen «Press 1 for English, press 2 for Spanish»: muchos servicios tienen opción en español."},{"en":"Be careful with calls asking for money or personal data. Hang up and call the official number.","es":"Cuidado con las llamadas que piden dinero o datos personales. Cuelga y llama al número oficial."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Hello, this is Carmen.","translation":"Hola, habla Carmen.","translations":{"es":"Hola, habla Carmen."}},{"phrase":"Can I speak to Grace, please?","translation":"¿Puedo hablar con Grace, por favor?","translations":{"es":"¿Puedo hablar con Grace, por favor?"}},{"phrase":"Hold on a minute, please.","translation":"Espere un momento, por favor.","translations":{"es":"Espere un momento, por favor."}},{"phrase":"She''s not here right now.","translation":"No está en este momento.","translations":{"es":"No está en este momento."}},{"phrase":"Can I leave a message?","translation":"¿Le puedo dejar un recado?","translations":{"es":"¿Le puedo dejar un recado?"}},{"phrase":"I''ll call you back later.","translation":"Te devuelvo la llamada más tarde.","translations":{"es":"Te devuelvo la llamada más tarde."}},{"phrase":"Could you speak up, please?","translation":"¿Podría hablar más fuerte, por favor?","translations":{"es":"¿Podría hablar más fuerte, por favor?"}},{"phrase":"Sorry, you have the wrong number.","translation":"Perdón, se equivocó de número.","translations":{"es":"Perdón, se equivocó de número."}},{"phrase":"My battery is dying.","translation":"Se me está acabando la batería.","translations":{"es":"Se me está acabando la batería."}},{"phrase":"I''ll text you the address.","translation":"Te mando la dirección por mensaje.","translations":{"es":"Te mando la dirección por mensaje."}},{"phrase":"Thanks for calling.","translation":"Gracias por llamar.","translations":{"es":"Gracias por llamar."}},{"phrase":"Talk to you soon!","translation":"¡Hablamos pronto!","translations":{"es":"¡Hablamos pronto!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say who you are on the phone?","options":["Hello, Carmen is me.","Hello, here is Carmen speak.","Hello, this is Carmen.","Hello, I am Carmen here."],"correct":2,"explanation":"On the phone: \"This is…\"","translations":{"es":{"question":"¿Cómo dices quién eres por teléfono?","explanation":"Por teléfono: «This is…»"}}},{"id":"2","question":"The phone rings. You offer to answer. You say:","options":["I got it yesterday.","I going to get.","I''ll get it!","I get it tomorrow."],"correct":2,"explanation":"Quick decision or offer → I''ll + verb.","translations":{"es":{"question":"Suena el teléfono. Te ofreces a contestar. Dices:","explanation":"Decisión rápida u ofrecimiento → I''ll + verbo."}}},{"id":"3","question":"You can''t hear well. You say:","options":["Could you hold on me?","Speak down, please.","Could you speak up, please?","Could you hang up, please?"],"correct":2,"explanation":"\"Speak up\" = speak louder.","translations":{"es":{"question":"No oyes bien. Dices:","explanation":"«Speak up» = hablar más fuerte."}}},{"id":"4","question":"\"Hang up\" means…","options":["call again","end the call","answer the phone","wait on the line"],"correct":1,"explanation":"Hang up = colgar.","translations":{"es":{"question":"«Hang up» significa…","explanation":"Hang up = colgar."}}},{"id":"5","question":"The person you want is not there. You ask:","options":["Can you hold on a message?","Can I leave a message?","Can I speak up?","Can I hang up a message?"],"correct":1,"explanation":"\"Leave a message\" = dejar un recado.","translations":{"es":{"question":"La persona que buscas no está. Preguntas:","explanation":"«Leave a message» = dejar un recado."}}},{"id":"6","question":"Complete: \"I''m busy now. I ___ you back in an hour.\"","options":["''ll call","calling","called","call"],"correct":0,"explanation":"Promise/offer → I''ll call you back.","translations":{"es":{"question":"Completa: «I''m busy now. I ___ you back in an hour.»","explanation":"Promesa/ofrecimiento → I''ll call you back."}}},{"id":"7","question":"Someone calls you, but they want another person. You say:","options":["Sorry, you have the wrong number.","Hold on, I''ll text you.","Thanks for calling, bye.","Sorry, my battery is dying."],"correct":0,"explanation":"Wrong number = número equivocado.","translations":{"es":{"question":"Alguien te llama, pero busca a otra persona. Dices:","explanation":"Wrong number = número equivocado."}}},{"id":"8","question":"A stranger calls and asks for your bank password. You should…","options":["leave a message with it","hang up and call the bank''s official number","text it to them","give it quickly"],"correct":1,"explanation":"Never share passwords by phone. Hang up.","translations":{"es":{"question":"Un desconocido llama y te pide la contraseña del banco. Debes…","explanation":"Nunca compartas contraseñas por teléfono. Cuelga."}}}]}'::jsonb, 3),
  ('story', 'The Important Call', '{"text":"Carmen''s phone rings. It''s a number she doesn''t know. \"Hello?\" \"Hello, this is Grace from the bakery. Can I speak to Carmen?\" \"This is Carmen! Hi, Grace!\" \"Carmen, I have a question. Could you work here on Saturdays? Just in the mornings.\" Carmen''s heart beats fast. \"Sorry, could you speak up, please? The signal is bad.\" Grace repeats the question louder. \"Yes! I''d love to!\" says Carmen. \"Great. I''ll send you a message with the details.\" \"Thank you so much. I''ll be there at seven on Saturday, I promise.\" After she hangs up, Carmen calls Laura. The line is busy, so she leaves a voicemail: \"Laura, call me back! I have big news!\" Two minutes later her phone rings again. \"Mom, what happened?\" \"I have a job!\"","translation":"Suena el teléfono de Carmen. Es un número que no conoce. «¿Bueno?» «Hola, habla Grace, de la panadería. ¿Puedo hablar con Carmen?» «¡Habla Carmen! ¡Hola, Grace!» «Carmen, tengo una pregunta. ¿Podrías trabajar aquí los sábados? Solo en las mañanas.» El corazón de Carmen late rápido. «Perdón, ¿podrías hablar más fuerte, por favor? La señal está mala.» Grace repite la pregunta más fuerte. «¡Sí! ¡Me encantaría!», dice Carmen. «Perfecto. Te mando un mensaje con los detalles.» «Muchísimas gracias. El sábado estoy ahí a las siete, te lo prometo.» Después de colgar, Carmen llama a Laura. La línea está ocupada, así que le deja un mensaje de voz: «¡Laura, regrésame la llamada! ¡Tengo una gran noticia!» Dos minutos después vuelve a sonar su teléfono. «Mamá, ¿qué pasó?» «¡Tengo trabajo!»","translations":{"es":"Suena el teléfono de Carmen. Es un número que no conoce. «¿Bueno?» «Hola, habla Grace, de la panadería. ¿Puedo hablar con Carmen?» «¡Habla Carmen! ¡Hola, Grace!» «Carmen, tengo una pregunta. ¿Podrías trabajar aquí los sábados? Solo en las mañanas.» El corazón de Carmen late rápido. «Perdón, ¿podrías hablar más fuerte, por favor? La señal está mala.» Grace repite la pregunta más fuerte. «¡Sí! ¡Me encantaría!», dice Carmen. «Perfecto. Te mando un mensaje con los detalles.» «Muchísimas gracias. El sábado estoy ahí a las siete, te lo prometo.» Después de colgar, Carmen llama a Laura. La línea está ocupada, así que le deja un mensaje de voz: «¡Laura, regrésame la llamada! ¡Tengo una gran noticia!» Dos minutos después vuelve a sonar su teléfono. «Mamá, ¿qué pasó?» «¡Tengo trabajo!»"},"highlighted_words":["phone rings","this is Grace","Can I speak to Carmen","This is Carmen","Could you work","could you speak up, please","signal","I''ll send you a message","I''ll be there","hangs up","busy","voicemail","call me back"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Hello","this","is","Carmen"],"translation":"Hola, habla Carmen.","translations":{"es":"Hola, habla Carmen."}},{"words":["Can","I","speak","to","Grace","please"],"translation":"¿Puedo hablar con Grace, por favor?","translations":{"es":"¿Puedo hablar con Grace, por favor?"}},{"words":["I","will","call","you","back","later"],"translation":"Te devuelvo la llamada más tarde.","translations":{"es":"Te devuelvo la llamada más tarde."}},{"words":["Could","you","speak","up","please"],"translation":"¿Podría hablar más fuerte, por favor?","translations":{"es":"¿Podría hablar más fuerte, por favor?"}},{"words":["Can","I","leave","a","message"],"translation":"¿Le puedo dejar un recado?","translations":{"es":"¿Le puedo dejar un recado?"}},{"words":["Hold","on","a","minute","please"],"translation":"Espere un momento, por favor.","translations":{"es":"Espere un momento, por favor."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Habla Carmen","translations":{"es":"Habla Carmen"},"answer":"This is Carmen"},{"prompt":"Te devuelvo la llamada","translations":{"es":"Te devuelvo la llamada"},"answer":"I will call you back"},{"prompt":"¿Puedo dejar un recado?","translations":{"es":"¿Puedo dejar un recado?"},"answer":"Can I leave a message"},{"prompt":"Se equivocó de número","translations":{"es":"Se equivocó de número"},"answer":"You have the wrong number"},{"prompt":"Gracias por llamar","translations":{"es":"Gracias por llamar"},"answer":"Thanks for calling"},{"prompt":"Te mando un mensaje","translations":{"es":"Te mando un mensaje"},"answer":"I will text you"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 31: At the travel agency
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-31', 'At the travel agency', '🧳', 'En la agencia de viajes', 31, true)
  returning id
