insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"travel agency","translation":"agencia de viajes","translations":{"es":"agencia de viajes"}},{"id":"2","word":"travel agent","translation":"agente de viajes","translations":{"es":"agente de viajes"}},{"id":"3","word":"flight","translation":"vuelo","translations":{"es":"vuelo"}},{"id":"4","word":"round-trip","translation":"ida y vuelta","translations":{"es":"ida y vuelta"}},{"id":"5","word":"one-way","translation":"solo ida","translations":{"es":"solo ida"}},{"id":"6","word":"direct flight","translation":"vuelo directo","translations":{"es":"vuelo directo"}},{"id":"7","word":"layover","translation":"escala","translations":{"es":"escala"}},{"id":"8","word":"departure","translation":"salida","translations":{"es":"salida"}},{"id":"9","word":"arrival","translation":"llegada","translations":{"es":"llegada"}},{"id":"10","word":"reservation","translation":"reservación","translations":{"es":"reservación"}},{"id":"11","word":"price","translation":"precio","translations":{"es":"precio"}},{"id":"12","word":"travel insurance","translation":"seguro de viaje","translations":{"es":"seguro de viaje"}},{"id":"13","word":"window seat","translation":"asiento de ventana","translations":{"es":"asiento de ventana"}},{"id":"14","word":"aisle seat","translation":"asiento de pasillo","translations":{"es":"asiento de pasillo"}},{"id":"15","word":"book","translation":"reservar","translations":{"es":"reservar"}},{"id":"16","word":"destination","translation":"destino","translations":{"es":"destino"}},{"id":"17","word":"ID","translation":"identificación","translations":{"es":"identificación"}}],"grammar":[{"structure":"would like to + verb","example":"I''d like to go to New York in October.","en":"Polite wishes","es":"Deseos expresados con amabilidad"},{"structure":"want to + verb","example":"I want to visit my cousin.","en":"Saying what you want to do","es":"Decir lo que quieres hacer"},{"structure":"Would you like…?","example":"Would you like a window seat?","en":"Polite offers and questions","es":"Ofrecer y preguntar con amabilidad"},{"structure":"round-trip / one-way","example":"A round-trip ticket, please.","en":"Types of tickets","es":"Tipos de boletos"},{"structure":"from … to …","example":"from October 5th to October 19th","en":"Dates and places","es":"Fechas y lugares"}],"tips":[{"en":"\"I''d like to…\" is the most useful phrase for traveling: polite and clear.","es":"«I''d like to…» es la frase más útil para viajar: amable y clara."},{"en":"\"Would you like…?\" is an offer. Answer \"Yes, please\" or \"No, thank you\".","es":"«Would you like…?» es un ofrecimiento. Responde «Yes, please» o «No, thank you»."},{"en":"\"Round-trip\" = ida y vuelta; \"one-way\" = solo ida.","es":"«Round-trip» = ida y vuelta; «one-way» = solo ida."},{"en":"Domestic flights inside the US need a valid ID (like a REAL ID or passport), not a visa.","es":"Los vuelos nacionales dentro de Estados Unidos piden una identificación válida (como REAL ID o pasaporte), no visa."},{"en":"\"Layover\" is a stop between two flights.","es":"«Layover» es una escala entre dos vuelos."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to book a flight to New York.","translation":"Quisiera reservar un vuelo a Nueva York.","translations":{"es":"Quisiera reservar un vuelo a Nueva York."}},{"phrase":"When would you like to travel?","translation":"¿Cuándo le gustaría viajar?","translations":{"es":"¿Cuándo le gustaría viajar?"}},{"phrase":"From October 5th to the 19th.","translation":"Del 5 al 19 de octubre.","translations":{"es":"Del 5 al 19 de octubre."}},{"phrase":"Round-trip, please.","translation":"Ida y vuelta, por favor.","translations":{"es":"Ida y vuelta, por favor."}},{"phrase":"Is it a direct flight?","translation":"¿Es un vuelo directo?","translations":{"es":"¿Es un vuelo directo?"}},{"phrase":"There''s a layover in Chicago.","translation":"Hay una escala en Chicago.","translations":{"es":"Hay una escala en Chicago."}},{"phrase":"Would you like a window seat or an aisle seat?","translation":"¿Quiere asiento de ventana o de pasillo?","translations":{"es":"¿Quiere asiento de ventana o de pasillo?"}},{"phrase":"A window seat, please.","translation":"Ventana, por favor.","translations":{"es":"Ventana, por favor."}},{"phrase":"How much is the ticket?","translation":"¿Cuánto cuesta el boleto?","translations":{"es":"¿Cuánto cuesta el boleto?"}},{"phrase":"Does the price include luggage?","translation":"¿El precio incluye equipaje?","translations":{"es":"¿El precio incluye equipaje?"}},{"phrase":"I want to visit my cousin.","translation":"Quiero visitar a mi prima.","translations":{"es":"Quiero visitar a mi prima."}},{"phrase":"Here is your reservation.","translation":"Aquí está su reservación.","translations":{"es":"Aquí está su reservación."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which is the most polite?","options":["I want a flight now.","Give me a flight.","I''d like to book a flight.","Flight!"],"correct":2,"explanation":"\"I''d like to…\" is polite.","translations":{"es":{"question":"¿Cuál es la más amable?","explanation":"«I''d like to…» es amable."}}},{"id":"2","question":"\"Round-trip\" means…","options":["vuelo directo","ida y vuelta","solo ida","escala"],"correct":1,"explanation":"Round-trip = there and back.","translations":{"es":{"question":"«Round-trip» significa…","explanation":"Round-trip = ida y vuelta."}}},{"id":"3","question":"The agent asks \"Would you like travel insurance?\" You want it. You say:","options":["Yes, please.","Yes, I like.","Yes, I would like.","Yes, you would."],"correct":0,"explanation":"Accept an offer: Yes, please.","translations":{"es":{"question":"El agente pregunta «Would you like travel insurance?». Lo quieres. Dices:","explanation":"Para aceptar un ofrecimiento: Yes, please."}}},{"id":"4","question":"Complete: \"I''d like ___ to New York.\"","options":["going","to go","go","goes"],"correct":1,"explanation":"would like + to + verb.","translations":{"es":{"question":"Completa: «I''d like ___ to New York.»","explanation":"would like + to + verbo."}}},{"id":"5","question":"A stop between two flights is a…","options":["arrival","layover","departure","reservation"],"correct":1,"explanation":"Layover = escala.","translations":{"es":{"question":"Una parada entre dos vuelos es una…","explanation":"Layover = escala."}}},{"id":"6","question":"You want to look out during the flight. You ask for…","options":["a window seat","an aisle seat","a layover","a one-way ticket"],"correct":0,"explanation":"Window seat = asiento de ventana.","translations":{"es":{"question":"Quieres mirar afuera durante el vuelo. Pides…","explanation":"Window seat = asiento de ventana."}}},{"id":"7","question":"Complete: \"___ you like a direct flight?\"","options":["Would","Do would","Will","Are"],"correct":0,"explanation":"Polite offer: Would you like…?","translations":{"es":{"question":"Completa: «___ you like a direct flight?»","explanation":"Ofrecimiento amable: Would you like…?"}}},{"id":"8","question":"For a flight inside the US, you need…","options":["a visa","a valid ID","a work permit","nothing"],"correct":1,"explanation":"Domestic flights require a valid ID.","translations":{"es":{"question":"Para un vuelo dentro de Estados Unidos necesitas…","explanation":"Los vuelos nacionales piden identificación válida."}}}]}'::jsonb, 3),
  ('story', 'A Dream Trip', '{"text":"Carmen''s cousin Elena lives in New York. They haven''t seen each other in twenty years. This year, Carmen wants to visit her. She goes to a travel agency with Laura. \"Good morning. I''d like to book a flight to New York,\" says Carmen. \"Of course. When would you like to travel?\" asks the travel agent. \"From October fifth to the nineteenth.\" \"Round-trip?\" \"Yes, round-trip, please. Is there a direct flight?\" \"There''s a direct flight at eight in the morning, or a cheaper one with a layover in Chicago.\" \"The direct flight, please. I don''t want to get lost in Chicago!\" The agent laughs. \"Would you like a window seat or an aisle seat?\" \"A window seat. I want to see everything.\" When they leave, Carmen holds the reservation like a treasure.","translation":"La prima de Carmen, Elena, vive en Nueva York. No se ven desde hace veinte años. Este año, Carmen quiere visitarla. Va a una agencia de viajes con Laura. «Buenos días. Quisiera reservar un vuelo a Nueva York», dice Carmen. «Claro. ¿Cuándo le gustaría viajar?», pregunta el agente de viajes. «Del cinco al diecinueve de octubre.» «¿Ida y vuelta?» «Sí, ida y vuelta, por favor. ¿Hay vuelo directo?» «Hay un vuelo directo a las ocho de la mañana, o uno más barato con escala en Chicago.» «El directo, por favor. ¡No me quiero perder en Chicago!» El agente se ríe. «¿Quiere asiento de ventana o de pasillo?» «De ventana. Quiero verlo todo.» Al salir, Carmen sostiene la reservación como un tesoro.","translations":{"es":"La prima de Carmen, Elena, vive en Nueva York. No se ven desde hace veinte años. Este año, Carmen quiere visitarla. Va a una agencia de viajes con Laura. «Buenos días. Quisiera reservar un vuelo a Nueva York», dice Carmen. «Claro. ¿Cuándo le gustaría viajar?», pregunta el agente de viajes. «Del cinco al diecinueve de octubre.» «¿Ida y vuelta?» «Sí, ida y vuelta, por favor. ¿Hay vuelo directo?» «Hay un vuelo directo a las ocho de la mañana, o uno más barato con escala en Chicago.» «El directo, por favor. ¡No me quiero perder en Chicago!» El agente se ríe. «¿Quiere asiento de ventana o de pasillo?» «De ventana. Quiero verlo todo.» Al salir, Carmen sostiene la reservación como un tesoro."},"highlighted_words":["wants to visit","travel agency","I''d like to book a flight","When would you like to travel","travel agent","Round-trip","direct flight","layover","Would you like a window seat","aisle seat","reservation"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","to","book","a","flight"],"translation":"Quisiera reservar un vuelo.","translations":{"es":"Quisiera reservar un vuelo."}},{"words":["When","would","you","like","to","travel"],"translation":"¿Cuándo le gustaría viajar?","translations":{"es":"¿Cuándo le gustaría viajar?"}},{"words":["Is","it","a","direct","flight"],"translation":"¿Es un vuelo directo?","translations":{"es":"¿Es un vuelo directo?"}},{"words":["I","want","to","visit","my","cousin","in","New","York"],"translation":"Quiero visitar a mi prima en Nueva York.","translations":{"es":"Quiero visitar a mi prima en Nueva York."}},{"words":["Would","you","like","a","window","seat"],"translation":"¿Quiere asiento de ventana?","translations":{"es":"¿Quiere asiento de ventana?"}},{"words":["There","is","a","layover","in","Chicago"],"translation":"Hay una escala en Chicago.","translations":{"es":"Hay una escala en Chicago."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Me gustaría viajar en octubre","translations":{"es":"Me gustaría viajar en octubre"},"answer":"I would like to travel in October"},{"prompt":"Un boleto de ida y vuelta, por favor","translations":{"es":"Un boleto de ida y vuelta, por favor"},"answer":"A round-trip ticket, please"},{"prompt":"¿Es un vuelo directo?","translations":{"es":"¿Es un vuelo directo?"},"answer":"Is it a direct flight"},{"prompt":"¿Cuánto cuesta el boleto?","translations":{"es":"¿Cuánto cuesta el boleto?"},"answer":"How much is the ticket"},{"prompt":"Quiero asiento de ventana","translations":{"es":"Quiero asiento de ventana"},"answer":"I want a window seat"},{"prompt":"¿Le gustaría un café?","translations":{"es":"¿Le gustaría un café?"},"answer":"Would you like some coffee"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 32: At the airport
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-32', 'At the airport', '🛫', 'En el aeropuerto', 32, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"airport","translation":"aeropuerto","translations":{"es":"aeropuerto"}},{"id":"2","word":"check-in","translation":"documentación / registro","translations":{"es":"documentación / registro"}},{"id":"3","word":"boarding pass","translation":"pase de abordar","translations":{"es":"pase de abordar"}},{"id":"4","word":"luggage","translation":"equipaje","translations":{"es":"equipaje"}},{"id":"5","word":"carry-on","translation":"equipaje de mano","translations":{"es":"equipaje de mano"}},{"id":"6","word":"check a bag","translation":"documentar una maleta","translations":{"es":"documentar una maleta"}},{"id":"7","word":"security","translation":"control de seguridad","translations":{"es":"control de seguridad"}},{"id":"8","word":"gate","translation":"puerta / sala de abordar","translations":{"es":"puerta / sala de abordar"}},{"id":"9","word":"terminal","translation":"terminal","translations":{"es":"terminal"}},{"id":"10","word":"boarding","translation":"abordaje","translations":{"es":"abordaje"}},{"id":"11","word":"delayed","translation":"retrasado","translations":{"es":"retrasado"}},{"id":"12","word":"on time","translation":"a tiempo","translations":{"es":"a tiempo"}},{"id":"13","word":"canceled","translation":"cancelado","translations":{"es":"cancelado"}},{"id":"14","word":"screen","translation":"pantalla","translations":{"es":"pantalla"}},{"id":"15","word":"liquids","translation":"líquidos","translations":{"es":"líquidos"}},{"id":"16","word":"take off","translation":"quitarse (ropa) / despegar","translations":{"es":"quitarse (ropa) / despegar"}},{"id":"17","word":"baggage claim","translation":"reclamo de equipaje","translations":{"es":"reclamo de equipaje"}}],"grammar":[{"structure":"have to + verb","example":"You have to take off your shoes.","en":"Obligation with \"have to\"","es":"Obligación con «have to» (tener que)"},{"structure":"has to (he / she)","example":"She has to show her ID.","en":"\"Has to\" with he/she/it","es":"«Has to» con he/she/it"},{"structure":"don''t have to","example":"You don''t have to print your boarding pass.","en":"No obligation (it''s not necessary)","es":"Sin obligación (no es necesario)"},{"structure":"Do I have to…?","example":"Do I have to check this bag?","en":"Asking about rules","es":"Preguntar por reglas"},{"structure":"had to (past)","example":"We had to run to the gate.","en":"Past obligation","es":"Obligación en pasado"}],"tips":[{"en":"\"Don''t have to\" means \"no hace falta\", not \"no debes\". You don''t have to come = no es necesario que vengas.","es":"«Don''t have to» significa «no hace falta», no «no debes». You don''t have to come = no es necesario que vengas."},{"en":"Arrive at the airport 2 hours before a domestic flight and 3 hours before an international one.","es":"Llega al aeropuerto 2 horas antes de un vuelo nacional y 3 horas antes de uno internacional."},{"en":"At security, liquids must be in small containers (3.4 oz / 100 ml) in a clear bag.","es":"En el control de seguridad, los líquidos deben ir en envases pequeños (3.4 oz / 100 ml) en una bolsa transparente."},{"en":"\"Gate\" is where you board; check the screens because gates can change.","es":"La «gate» es la sala donde abordas; revisa las pantallas porque pueden cambiar."},{"en":"Ask for help: airports have \"wheelchair assistance\" and staff who speak Spanish.","es":"Pide ayuda: los aeropuertos tienen «wheelchair assistance» (asistencia con silla de ruedas) y personal que habla español."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Where is the check-in counter?","translation":"¿Dónde está el mostrador de documentación?","translations":{"es":"¿Dónde está el mostrador de documentación?"}},{"phrase":"Can I see your ID, please?","translation":"¿Me permite su identificación?","translations":{"es":"¿Me permite su identificación?"}},{"phrase":"Do I have to check this bag?","translation":"¿Tengo que documentar esta maleta?","translations":{"es":"¿Tengo que documentar esta maleta?"}},{"phrase":"You don''t have to. It''s a carry-on.","translation":"No hace falta. Es equipaje de mano.","translations":{"es":"No hace falta. Es equipaje de mano."}},{"phrase":"You have to take off your shoes.","translation":"Tiene que quitarse los zapatos.","translations":{"es":"Tiene que quitarse los zapatos."}},{"phrase":"Put your liquids in this bag.","translation":"Ponga sus líquidos en esta bolsa.","translations":{"es":"Ponga sus líquidos en esta bolsa."}},{"phrase":"Which gate is it?","translation":"¿Qué puerta es?","translations":{"es":"¿Qué puerta es?"}},{"phrase":"The flight is delayed.","translation":"El vuelo está retrasado.","translations":{"es":"El vuelo está retrasado."}},{"phrase":"Boarding starts at seven thirty.","translation":"El abordaje empieza a las siete y media.","translations":{"es":"El abordaje empieza a las siete y media."}},{"phrase":"We had to run!","translation":"¡Tuvimos que correr!","translations":{"es":"¡Tuvimos que correr!"}},{"phrase":"Where is baggage claim?","translation":"¿Dónde está el reclamo de equipaje?","translations":{"es":"¿Dónde está el reclamo de equipaje?"}},{"phrase":"Have a good flight!","translation":"¡Buen vuelo!","translations":{"es":"¡Buen vuelo!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"You ___ show your ID.\" (it''s a rule)","options":["having to","have","has to","have to"],"correct":3,"explanation":"Obligation: you have to.","translations":{"es":{"question":"Completa: «You ___ show your ID.» (es una regla)","explanation":"Obligación: you have to."}}},{"id":"2","question":"Complete: \"She ___ take off her jacket.\"","options":["haves to","must to","have to","has to"],"correct":3,"explanation":"She → has to.","translations":{"es":{"question":"Completa: «She ___ take off her jacket.»","explanation":"She → has to."}}},{"id":"3","question":"\"You don''t have to print the boarding pass\" means…","options":["You can''t fly.","You must print it.","It''s prohibited to print it.","It''s not necessary to print it."],"correct":3,"explanation":"Don''t have to = not necessary.","translations":{"es":{"question":"«You don''t have to print the boarding pass» significa…","explanation":"Don''t have to = no es necesario."}}},{"id":"4","question":"Choose the correct question.","options":["Have I to check this bag?","I have to check this bag do?","Do I has to check this bag?","Do I have to check this bag?"],"correct":3,"explanation":"Questions: Do + I + have to…?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Preguntas: Do + I + have to…?"}}},{"id":"5","question":"Your flight leaves later than planned. It''s…","options":["on time","canceled","boarding","delayed"],"correct":3,"explanation":"Delayed = retrasado.","translations":{"es":{"question":"Tu vuelo sale más tarde de lo planeado. Está…","explanation":"Delayed = retrasado."}}},{"id":"6","question":"Where do you pick up your suitcase after the flight?","options":["at check-in","at security","at the gate","at baggage claim"],"correct":3,"explanation":"Baggage claim = reclamo de equipaje.","translations":{"es":{"question":"¿Dónde recoges tu maleta después del vuelo?","explanation":"Baggage claim = reclamo de equipaje."}}},{"id":"7","question":"Complete: \"Yesterday we ___ run to the gate.\"","options":["must","have to","has to","had to"],"correct":3,"explanation":"Past obligation: had to.","translations":{"es":{"question":"Completa: «Yesterday we ___ run to the gate.»","explanation":"Obligación en pasado: had to."}}},{"id":"8","question":"A small bag you take on the plane is a…","options":["boarding pass","baggage claim","gate","carry-on"],"correct":3,"explanation":"Carry-on = equipaje de mano.","translations":{"es":{"question":"Una bolsa pequeña que llevas en el avión es…","explanation":"Carry-on = equipaje de mano."}}}]}'::jsonb, 3),
  ('story', 'Running to Gate 12', '{"text":"On October fifth, Laura takes Carmen to the airport at six in the morning. At the check-in counter, the agent says, \"Can I see your ID, please?\" Carmen gives her passport. \"Do I have to check this bag?\" \"No, you don''t have to. It''s a carry-on. Your gate is number twelve.\" At security, there is a long line. \"You have to take off your shoes and your jacket,\" says the officer. \"And put your liquids in this bag.\" Carmen has a big bottle of hot sauce for Elena. \"Sorry, ma''am. You can''t take this.\" Carmen is sad, but she smiles. Then she looks at the screen: \"Gate 12 — BOARDING.\" She has to run! She arrives just in time. \"Have a good flight!\" says the agent. Carmen sits by the window. \"No hot sauce,\" she thinks, \"but I''m on the plane!\"","translation":"El cinco de octubre, Laura lleva a Carmen al aeropuerto a las seis de la mañana. En el mostrador de documentación, la agente dice: «¿Me permite su identificación?» Carmen le da su pasaporte. «¿Tengo que documentar esta maleta?» «No hace falta. Es equipaje de mano. Su puerta es la número doce.» En el control de seguridad hay una fila larga. «Tiene que quitarse los zapatos y la chaqueta», dice el oficial. «Y ponga sus líquidos en esta bolsa.» Carmen lleva una botella grande de salsa picante para Elena. «Lo siento, señora. No puede llevar esto.» Carmen se pone triste, pero sonríe. Luego mira la pantalla: «Puerta 12 — ABORDANDO.» ¡Tiene que correr! Llega justo a tiempo. «¡Buen vuelo!», dice la agente. Carmen se sienta junto a la ventana. «Sin salsa picante», piensa, «¡pero ya estoy en el avión!»","translations":{"es":"El cinco de octubre, Laura lleva a Carmen al aeropuerto a las seis de la mañana. En el mostrador de documentación, la agente dice: «¿Me permite su identificación?» Carmen le da su pasaporte. «¿Tengo que documentar esta maleta?» «No hace falta. Es equipaje de mano. Su puerta es la número doce.» En el control de seguridad hay una fila larga. «Tiene que quitarse los zapatos y la chaqueta», dice el oficial. «Y ponga sus líquidos en esta bolsa.» Carmen lleva una botella grande de salsa picante para Elena. «Lo siento, señora. No puede llevar esto.» Carmen se pone triste, pero sonríe. Luego mira la pantalla: «Puerta 12 — ABORDANDO.» ¡Tiene que correr! Llega justo a tiempo. «¡Buen vuelo!», dice la agente. Carmen se sienta junto a la ventana. «Sin salsa picante», piensa, «¡pero ya estoy en el avión!»"},"highlighted_words":["airport","check-in counter","Can I see your ID, please","Do I have to check this bag","you don''t have to","carry-on","gate","security","You have to take off your shoes","liquids","screen","She has to run","Have a good flight"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Do","I","have","to","check","this","bag"],"translation":"¿Tengo que documentar esta maleta?","translations":{"es":"¿Tengo que documentar esta maleta?"}},{"words":["You","have","to","take","off","your","shoes"],"translation":"Tiene que quitarse los zapatos.","translations":{"es":"Tiene que quitarse los zapatos."}},{"words":["You","do","not","have","to","print","it"],"translation":"No hace falta imprimirlo.","translations":{"es":"No hace falta imprimirlo."}},{"words":["Our","flight","is","delayed"],"translation":"Nuestro vuelo está retrasado.","translations":{"es":"Nuestro vuelo está retrasado."}},{"words":["We","had","to","run","to","the","gate"],"translation":"Tuvimos que correr a la puerta.","translations":{"es":"Tuvimos que correr a la puerta."}},{"words":["Where","is","baggage","claim"],"translation":"¿Dónde está el reclamo de equipaje?","translations":{"es":"¿Dónde está el reclamo de equipaje?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Tengo que mostrar mi identificación","translations":{"es":"Tengo que mostrar mi identificación"},"answer":"I have to show my ID"},{"prompt":"¿Qué puerta es?","translations":{"es":"¿Qué puerta es?"},"answer":"Which gate is it"},{"prompt":"El vuelo está retrasado","translations":{"es":"El vuelo está retrasado"},"answer":"The flight is delayed"},{"prompt":"No hace falta pagar","translations":{"es":"No hace falta pagar"},"answer":"You do not have to pay"},{"prompt":"Ella tiene que correr","translations":{"es":"Ella tiene que correr"},"answer":"She has to run"},{"prompt":"Buen vuelo","translations":{"es":"Buen vuelo"},"answer":"Have a good flight"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 33: On the plane
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-33', 'On the plane', '✈️', 'En el avión', 33, true)
