insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"plane","translation":"avión","translations":{"es":"avión"}},{"id":"2","word":"flight attendant","translation":"sobrecargo / azafata","translations":{"es":"sobrecargo / azafata"}},{"id":"3","word":"pilot","translation":"piloto","translations":{"es":"piloto"}},{"id":"4","word":"passenger","translation":"pasajero","translations":{"es":"pasajero"}},{"id":"5","word":"seatbelt","translation":"cinturón de seguridad","translations":{"es":"cinturón de seguridad"}},{"id":"6","word":"fasten","translation":"abrochar","translations":{"es":"abrochar"}},{"id":"7","word":"takeoff","translation":"despegue","translations":{"es":"despegue"}},{"id":"8","word":"landing","translation":"aterrizaje","translations":{"es":"aterrizaje"}},{"id":"9","word":"turbulence","translation":"turbulencia","translations":{"es":"turbulencia"}},{"id":"10","word":"blanket","translation":"cobija / manta","translations":{"es":"cobija / manta"}},{"id":"11","word":"pillow","translation":"almohada","translations":{"es":"almohada"}},{"id":"12","word":"overhead bin","translation":"compartimento superior","translations":{"es":"compartimento superior"}},{"id":"13","word":"aisle","translation":"pasillo","translations":{"es":"pasillo"}},{"id":"14","word":"snack","translation":"botana / bocadillo","translations":{"es":"botana / bocadillo"}},{"id":"15","word":"should","translation":"debería (consejo)","translations":{"es":"debería (consejo)"}},{"id":"16","word":"jet lag","translation":"desfase horario","translations":{"es":"desfase horario"}},{"id":"17","word":"window shade","translation":"persiana de la ventanilla","translations":{"es":"persiana de la ventanilla"}}],"grammar":[{"structure":"should + verb","example":"You should drink water on long flights.","en":"Advice with \"should\"","es":"Consejos con «should» (deberías)"},{"structure":"shouldn''t + verb","example":"You shouldn''t stand up during takeoff.","en":"Negative advice","es":"Consejo negativo"},{"structure":"Should I…?","example":"Should I fasten my seatbelt now?","en":"Asking for advice","es":"Pedir consejo"},{"structure":"Would you like…? — I''d like…","example":"Would you like something to drink? — I''d like some water.","en":"Offers on the plane","es":"Ofrecimientos en el avión"},{"structure":"Excuse me, could I…?","example":"Excuse me, could I get past?","en":"Polite requests to other passengers","es":"Pedidos amables a otros pasajeros"}],"tips":[{"en":"\"Should\" is softer than \"have to\": it''s advice, not a rule.","es":"«Should» es más suave que «have to»: es un consejo, no una regla."},{"en":"\"Flight attendant\" is the modern word (not \"stewardess\").","es":"«Flight attendant» es la palabra actual para el sobrecargo (no «stewardess»)."},{"en":"If you need to go to the bathroom from a window seat, say \"Excuse me, could I get past?\"","es":"Si necesitas ir al baño desde la ventana, di «Excuse me, could I get past?» (¿me permite pasar?)."},{"en":"On domestic US flights, drinks and small snacks are usually free; meals often cost extra.","es":"En los vuelos nacionales de Estados Unidos, las bebidas y botanas pequeñas suelen ser gratis; las comidas suelen costar aparte."},{"en":"\"Turbulence\" is normal. Keep your seatbelt fastened when you''re seated.","es":"La turbulencia es normal. Mantén el cinturón abrochado cuando estés sentado."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Please fasten your seatbelt.","translation":"Por favor, abróchese el cinturón.","translations":{"es":"Por favor, abróchese el cinturón."}},{"phrase":"Would you like something to drink?","translation":"¿Le gustaría algo de tomar?","translations":{"es":"¿Le gustaría algo de tomar?"}},{"phrase":"Some water, please.","translation":"Agua, por favor.","translations":{"es":"Agua, por favor."}},{"phrase":"Excuse me, could I get past?","translation":"Disculpe, ¿me permite pasar?","translations":{"es":"Disculpe, ¿me permite pasar?"}},{"phrase":"Could I have a blanket?","translation":"¿Me podría dar una cobija?","translations":{"es":"¿Me podría dar una cobija?"}},{"phrase":"Is this seat taken?","translation":"¿Está ocupado este asiento?","translations":{"es":"¿Está ocupado este asiento?"}},{"phrase":"You should drink a lot of water.","translation":"Deberías tomar mucha agua.","translations":{"es":"Deberías tomar mucha agua."}},{"phrase":"You shouldn''t worry.","translation":"No deberías preocuparte.","translations":{"es":"No deberías preocuparte."}},{"phrase":"Should I turn off my phone?","translation":"¿Debo apagar mi teléfono?","translations":{"es":"¿Debo apagar mi teléfono?"}},{"phrase":"We are starting our descent.","translation":"Estamos iniciando el descenso.","translations":{"es":"Estamos iniciando el descenso."}},{"phrase":"Welcome to New York!","translation":"¡Bienvenidos a Nueva York!","translations":{"es":"¡Bienvenidos a Nueva York!"}},{"phrase":"That was a smooth flight.","translation":"Fue un vuelo tranquilo.","translations":{"es":"Fue un vuelo tranquilo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"You ___ drink water on a long flight.\" (advice)","options":["have","should","should to","shoulds"],"correct":1,"explanation":"Advice: should + verb (no \"to\").","translations":{"es":{"question":"Completa: «You ___ drink water on a long flight.» (consejo)","explanation":"Consejo: should + verbo (sin «to»)."}}},{"id":"2","question":"Choose the negative advice.","options":["You don''t should stand up now.","You shouldn''t stand up now.","You no should stand up now.","You should not to stand up now."],"correct":1,"explanation":"Negative: shouldn''t + verb.","translations":{"es":{"question":"Elige el consejo negativo.","explanation":"Negativo: shouldn''t + verbo."}}},{"id":"3","question":"You are in the window seat and want to go to the bathroom. You say:","options":["Excuse me, could I get past?","Move!","Could you fasten?","Bathroom, you."],"correct":0,"explanation":"\"Could I get past?\" is the polite way.","translations":{"es":{"question":"Estás en la ventana y quieres ir al baño. Dices:","explanation":"«Could I get past?» es la forma amable."}}},{"id":"4","question":"The person who serves drinks on the plane is the…","options":["pilot","flight attendant","agent","passenger"],"correct":1,"explanation":"Flight attendant = sobrecargo.","translations":{"es":{"question":"La persona que sirve bebidas en el avión es…","explanation":"Flight attendant = sobrecargo."}}},{"id":"5","question":"\"Fasten your seatbelt\" means…","options":["quítese el cinturón","abróchese el cinturón","apague el teléfono","busque su asiento"],"correct":1,"explanation":"Fasten = abrochar.","translations":{"es":{"question":"«Fasten your seatbelt» significa…","explanation":"Fasten = abrochar."}}},{"id":"6","question":"Choose the question asking for advice.","options":["Should I to turn off my phone?","Do I should turn off my phone?","Should I turn off my phone?","I should turn off my phone?"],"correct":2,"explanation":"Should + I + verb?","translations":{"es":{"question":"Elige la pregunta que pide consejo.","explanation":"Should + I + verbo?"}}},{"id":"7","question":"The moment the plane arrives on the ground is the…","options":["turbulence","takeoff","landing","boarding"],"correct":2,"explanation":"Landing = aterrizaje. Takeoff = despegue.","translations":{"es":{"question":"El momento en que el avión llega a tierra es el…","explanation":"Landing = aterrizaje. Takeoff = despegue."}}},{"id":"8","question":"\"Should\" expresses…","options":["a strict rule","ability","advice","the past"],"correct":2,"explanation":"Should = advice (deberías).","translations":{"es":{"question":"«Should» expresa…","explanation":"Should = consejo (deberías)."}}}]}'::jsonb, 3),
  ('story', 'A New Friend at 30,000 Feet', '{"text":"The plane takes off at eight. Carmen looks out of the window: San Diego becomes small and blue. Next to her sits a young man with headphones. He looks nervous. \"Is this your first flight?\" asks Carmen. \"Yes, I''m going to a job interview in New York,\" he says. \"I''m very nervous.\" \"You shouldn''t worry,\" says Carmen. \"You should sleep a little and drink some water.\" A flight attendant comes with a cart. \"Would you like something to drink?\" \"Some water, please. And could I have a blanket?\" During the flight there is a little turbulence. The young man holds his seat. \"Should I be scared?\" \"No, it''s normal. Just keep your seatbelt fastened.\" Five hours later, the pilot says, \"Welcome to New York!\" The young man smiles. \"Thank you for your advice. You should be a teacher.\" \"I was one for thirty years!\"","translation":"El avión despega a las ocho. Carmen mira por la ventana: San Diego se vuelve pequeño y azul. A su lado se sienta un joven con audífonos. Se ve nervioso. «¿Es tu primer vuelo?», pregunta Carmen. «Sí, voy a una entrevista de trabajo en Nueva York», dice él. «Estoy muy nervioso.» «No deberías preocuparte», dice Carmen. «Deberías dormir un poco y tomar agua.» Una sobrecargo pasa con un carrito. «¿Les gustaría algo de tomar?» «Agua, por favor. ¿Y me podría dar una cobija?» Durante el vuelo hay un poco de turbulencia. El joven se agarra del asiento. «¿Debería tener miedo?» «No, es normal. Solo mantén el cinturón abrochado.» Cinco horas después, el piloto dice: «¡Bienvenidos a Nueva York!» El joven sonríe. «Gracias por sus consejos. Usted debería ser maestra.» «¡Lo fui durante treinta años!»","translations":{"es":"El avión despega a las ocho. Carmen mira por la ventana: San Diego se vuelve pequeño y azul. A su lado se sienta un joven con audífonos. Se ve nervioso. «¿Es tu primer vuelo?», pregunta Carmen. «Sí, voy a una entrevista de trabajo en Nueva York», dice él. «Estoy muy nervioso.» «No deberías preocuparte», dice Carmen. «Deberías dormir un poco y tomar agua.» Una sobrecargo pasa con un carrito. «¿Les gustaría algo de tomar?» «Agua, por favor. ¿Y me podría dar una cobija?» Durante el vuelo hay un poco de turbulencia. El joven se agarra del asiento. «¿Debería tener miedo?» «No, es normal. Solo mantén el cinturón abrochado.» Cinco horas después, el piloto dice: «¡Bienvenidos a Nueva York!» El joven sonríe. «Gracias por sus consejos. Usted debería ser maestra.» «¡Lo fui durante treinta años!»"},"highlighted_words":["takes off","You shouldn''t worry","You should sleep","flight attendant","Would you like something to drink","could I have a blanket","turbulence","Should I be scared","seatbelt fastened","pilot","Welcome to New York"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["You","should","drink","a","lot","of","water"],"translation":"Deberías tomar mucha agua.","translations":{"es":"Deberías tomar mucha agua."}},{"words":["You","should","not","stand","up","now"],"translation":"No deberías levantarte ahora.","translations":{"es":"No deberías levantarte ahora."}},{"words":["Please","fasten","your","seatbelt"],"translation":"Por favor, abróchese el cinturón.","translations":{"es":"Por favor, abróchese el cinturón."}},{"words":["Could","I","have","a","blanket","please"],"translation":"¿Me podría dar una cobija, por favor?","translations":{"es":"¿Me podría dar una cobija, por favor?"}},{"words":["Should","I","turn","off","my","phone"],"translation":"¿Debo apagar mi teléfono?","translations":{"es":"¿Debo apagar mi teléfono?"}},{"words":["Would","you","like","something","to","drink"],"translation":"¿Le gustaría algo de tomar?","translations":{"es":"¿Le gustaría algo de tomar?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Deberías descansar","translations":{"es":"Deberías descansar"},"answer":"You should rest"},{"prompt":"No deberías preocuparte","translations":{"es":"No deberías preocuparte"},"answer":"You should not worry"},{"prompt":"Abróchese el cinturón","translations":{"es":"Abróchese el cinturón"},"answer":"Fasten your seatbelt"},{"prompt":"Agua, por favor","translations":{"es":"Agua, por favor"},"answer":"Some water, please"},{"prompt":"¿Está ocupado este asiento?","translations":{"es":"¿Está ocupado este asiento?"},"answer":"Is this seat taken"},{"prompt":"¿Debería llamarla?","translations":{"es":"¿Debería llamarla?"},"answer":"Should I call her"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 34: Immigration and customs
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-34', 'Immigration and customs', '🛂', 'Migración y aduana', 34, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"immigration","translation":"migración","translations":{"es":"migración"}},{"id":"2","word":"customs","translation":"aduana","translations":{"es":"aduana"}},{"id":"3","word":"officer","translation":"oficial","translations":{"es":"oficial"}},{"id":"4","word":"passport","translation":"pasaporte","translations":{"es":"pasaporte"}},{"id":"5","word":"visa","translation":"visa","translations":{"es":"visa"}},{"id":"6","word":"purpose","translation":"propósito / motivo","translations":{"es":"propósito / motivo"}},{"id":"7","word":"declare","translation":"declarar","translations":{"es":"declarar"}},{"id":"8","word":"line","translation":"fila","translations":{"es":"fila"}},{"id":"9","word":"form","translation":"formulario","translations":{"es":"formulario"}},{"id":"10","word":"stamp","translation":"sello","translations":{"es":"sello"}},{"id":"11","word":"citizen","translation":"ciudadano","translations":{"es":"ciudadano"}},{"id":"12","word":"resident","translation":"residente","translations":{"es":"residente"}},{"id":"13","word":"border","translation":"frontera","translations":{"es":"frontera"}},{"id":"14","word":"been","translation":"estado / ido (participio de be / go)","translations":{"es":"estado / ido (participio de be / go)"}},{"id":"15","word":"ever","translation":"alguna vez","translations":{"es":"alguna vez"}},{"id":"16","word":"never","translation":"nunca","translations":{"es":"nunca"}},{"id":"17","word":"fine","translation":"multa","translations":{"es":"multa"}}],"grammar":[{"structure":"have / has + past participle","example":"I have visited Texas. She has lived here for a year.","en":"Present perfect: experiences and situations up to now","es":"Presente perfecto: experiencias y situaciones hasta ahora"},{"structure":"Have you ever…?","example":"Have you ever been to the United States?","en":"Asking about life experiences","es":"Preguntar por experiencias de vida"},{"structure":"I''ve never…","example":"I''ve never been to New York.","en":"Saying you haven''t had an experience","es":"Decir que nunca has vivido algo"},{"structure":"been / seen / had / done","example":"go → been, see → seen, have → had, do → done","en":"Common past participles","es":"Participios pasados comunes"},{"structure":"Do you have anything to declare?","example":"No, I have nothing to declare.","en":"Customs questions","es":"Preguntas de aduana"}],"tips":[{"en":"Answer immigration officers briefly and clearly: purpose of visit, how long, where you will stay.","es":"Responde a los oficiales de migración de forma breve y clara: motivo del viaje, cuánto tiempo y dónde te quedarás."},{"en":"\"Have you ever been to…?\" uses \"been\" (from \"go\"), not \"gone\".","es":"«Have you ever been to…?» usa «been» (de «go»), no «gone»."},{"en":"At customs, declare food like fruit, meat or seeds. Undeclared food can mean a fine.","es":"En la aduana declara alimentos como fruta, carne o semillas. No declararlos puede significar una multa."},{"en":"Keep your documents together in one folder: passport, visa, address where you''ll stay, return ticket.","es":"Guarda tus documentos juntos en una carpeta: pasaporte, visa, dirección donde te quedarás y boleto de regreso."},{"en":"If you don''t understand, say: \"Sorry, could you repeat the question?\" — it''s always okay to ask.","es":"Si no entiendes, di: «Sorry, could you repeat the question?»: siempre está bien preguntar."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What''s the purpose of your visit?","translation":"¿Cuál es el motivo de su visita?","translations":{"es":"¿Cuál es el motivo de su visita?"}},{"phrase":"I''m visiting my family.","translation":"Vengo a visitar a mi familia.","translations":{"es":"Vengo a visitar a mi familia."}},{"phrase":"How long are you staying?","translation":"¿Cuánto tiempo se va a quedar?","translations":{"es":"¿Cuánto tiempo se va a quedar?"}},{"phrase":"Three months.","translation":"Tres meses.","translations":{"es":"Tres meses."}},{"phrase":"Where are you staying?","translation":"¿Dónde se va a quedar?","translations":{"es":"¿Dónde se va a quedar?"}},{"phrase":"With my daughter, in San Diego.","translation":"Con mi hija, en San Diego.","translations":{"es":"Con mi hija, en San Diego."}},{"phrase":"Have you ever been to the United States?","translation":"¿Ha estado alguna vez en Estados Unidos?","translations":{"es":"¿Ha estado alguna vez en Estados Unidos?"}},{"phrase":"Yes, I have. Twice.","translation":"Sí. Dos veces.","translations":{"es":"Sí. Dos veces."}},{"phrase":"I''ve never been here before.","translation":"Nunca había estado aquí.","translations":{"es":"Nunca había estado aquí."}},{"phrase":"Do you have anything to declare?","translation":"¿Tiene algo que declarar?","translations":{"es":"¿Tiene algo que declarar?"}},{"phrase":"I have some dried chiles.","translation":"Traigo unos chiles secos.","translations":{"es":"Traigo unos chiles secos."}},{"phrase":"Welcome to the United States.","translation":"Bienvenida a Estados Unidos.","translations":{"es":"Bienvenida a Estados Unidos."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Have you ever ___ to New York?\"","options":["gone","been","went","be"],"correct":1,"explanation":"Experiences of visiting a place use \"been\".","translations":{"es":{"question":"Completa: «Have you ever ___ to New York?»","explanation":"Las experiencias de visitar un lugar usan «been»."}}},{"id":"2","question":"Short answer: \"Have you ever been to Canada?\" (no)","options":["No, I didn''t.","No, I haven''t.","No, I don''t.","No, I haven''t been gone."],"correct":1,"explanation":"Short answer: No, I haven''t.","translations":{"es":{"question":"Respuesta corta: «Have you ever been to Canada?» (no)","explanation":"Respuesta corta: No, I haven''t."}}},{"id":"3","question":"The officer asks \"What''s the purpose of your visit?\". A good answer is:","options":["I''m visiting my family.","Three months.","With my daughter.","Yes, I have."],"correct":0,"explanation":"\"Purpose\" asks WHY you are traveling.","translations":{"es":{"question":"El oficial pregunta «What''s the purpose of your visit?». Una buena respuesta es:","explanation":"«Purpose» pregunta POR QUÉ viajas."}}},{"id":"4","question":"Complete: \"She ___ lived in San Diego for one year.\"","options":["is","have","has","did"],"correct":2,"explanation":"She → has + past participle.","translations":{"es":{"question":"Completa: «She ___ lived in San Diego for one year.»","explanation":"She → has + participio."}}},{"id":"5","question":"What is the past participle of \"see\"?","options":["saw","seed","seen","sawn"],"correct":2,"explanation":"see → saw → seen.","translations":{"es":{"question":"¿Cuál es el participio de «see»?","explanation":"see → saw → seen."}}},{"id":"6","question":"At customs, you bring mangoes from Mexico. You should…","options":["eat them in line","hide them","declare them","say nothing"],"correct":2,"explanation":"Food must be declared. Not declaring it can mean a fine.","translations":{"es":{"question":"En la aduana, traes mangos de México. Deberías…","explanation":"Los alimentos se deben declarar. No hacerlo puede costar una multa."}}},{"id":"7","question":"Choose the correct sentence.","options":["I never have be here.","I''ve ever been here before.","I''ve never been here before.","I haven''t never been here."],"correct":2,"explanation":"I''ve never + past participle.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"I''ve never + participio."}}},{"id":"8","question":"\"How long are you staying?\" asks about…","options":["the reason for your trip","the length of your visit","your address","your luggage"],"correct":1,"explanation":"How long = cuánto tiempo.","translations":{"es":{"question":"«How long are you staying?» pregunta por…","explanation":"How long = cuánto tiempo."}}}]}'::jsonb, 3),
  ('story', 'The First Day', '{"text":"Now Carmen is in New York, at her cousin''s apartment. Elena asks, \"Was it difficult to come to the United States the first time?\" Carmen remembers that day at the airport in Los Angeles, many months ago. The line at immigration was very long. When it was her turn, the officer looked at her passport. \"What''s the purpose of your visit?\" \"I''m visiting my daughter.\" \"Have you ever been to the United States?\" \"No, I''ve never been here before.\" \"How long are you staying?\" \"Three months.\" Then, at customs: \"Do you have anything to declare?\" \"Yes… I have some dried chiles and chocolate for my grandson.\" The officer smiled. \"That''s fine. Welcome to the United States.\" Carmen laughs now. \"My hands were cold, Elena! But I have learned so much since that day.\"","translation":"Ahora Carmen está en Nueva York, en el departamento de su prima. Elena le pregunta: «¿Fue difícil venir a Estados Unidos la primera vez?» Carmen recuerda aquel día en el aeropuerto de Los Ángeles, hace muchos meses. La fila de migración era muy larga. Cuando le tocó, el oficial miró su pasaporte. «¿Cuál es el motivo de su visita?» «Vengo a visitar a mi hija.» «¿Ha estado alguna vez en Estados Unidos?» «No, nunca había estado aquí.» «¿Cuánto tiempo se va a quedar?» «Tres meses.» Luego, en la aduana: «¿Tiene algo que declarar?» «Sí… traigo unos chiles secos y chocolate para mi nieto.» El oficial sonrió. «Está bien. Bienvenida a Estados Unidos.» Ahora Carmen se ríe. «¡Tenía las manos frías, Elena! Pero he aprendido muchísimo desde ese día.»","translations":{"es":"Ahora Carmen está en Nueva York, en el departamento de su prima. Elena le pregunta: «¿Fue difícil venir a Estados Unidos la primera vez?» Carmen recuerda aquel día en el aeropuerto de Los Ángeles, hace muchos meses. La fila de migración era muy larga. Cuando le tocó, el oficial miró su pasaporte. «¿Cuál es el motivo de su visita?» «Vengo a visitar a mi hija.» «¿Ha estado alguna vez en Estados Unidos?» «No, nunca había estado aquí.» «¿Cuánto tiempo se va a quedar?» «Tres meses.» Luego, en la aduana: «¿Tiene algo que declarar?» «Sí… traigo unos chiles secos y chocolate para mi nieto.» El oficial sonrió. «Está bien. Bienvenida a Estados Unidos.» Ahora Carmen se ríe. «¡Tenía las manos frías, Elena! Pero he aprendido muchísimo desde ese día.»"},"highlighted_words":["immigration","officer","passport","What''s the purpose of your visit","Have you ever been to the United States","I''ve never been here before","How long are you staying","customs","Do you have anything to declare","Welcome to the United States","I have learned"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Have","you","ever","been","to","Mexico"],"translation":"¿Has estado alguna vez en México?","translations":{"es":"¿Has estado alguna vez en México?"}},{"words":["I","have","never","been","here","before"],"translation":"Nunca había estado aquí.","translations":{"es":"Nunca había estado aquí."}},{"words":["What","is","the","purpose","of","your","visit"],"translation":"¿Cuál es el motivo de su visita?","translations":{"es":"¿Cuál es el motivo de su visita?"}},{"words":["I","am","visiting","my","daughter"],"translation":"Vengo a visitar a mi hija.","translations":{"es":"Vengo a visitar a mi hija."}},{"words":["Do","you","have","anything","to","declare"],"translation":"¿Tiene algo que declarar?","translations":{"es":"¿Tiene algo que declarar?"}},{"words":["She","has","lived","here","for","a","year"],"translation":"Ella ha vivido aquí un año.","translations":{"es":"Ella ha vivido aquí un año."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Vengo a visitar a mi familia","translations":{"es":"Vengo a visitar a mi familia"},"answer":"I am visiting my family"},{"prompt":"¿Has estado alguna vez en Texas?","translations":{"es":"¿Has estado alguna vez en Texas?"},"answer":"Have you ever been to Texas"},{"prompt":"Nunca he visto la nieve","translations":{"es":"Nunca he visto la nieve"},"answer":"I have never seen snow"},{"prompt":"No tengo nada que declarar","translations":{"es":"No tengo nada que declarar"},"answer":"I have nothing to declare"},{"prompt":"¿Dónde se va a quedar?","translations":{"es":"¿Dónde se va a quedar?"},"answer":"Where are you staying"},{"prompt":"Ella ha aprendido mucho","translations":{"es":"Ella ha aprendido mucho"},"answer":"She has learned a lot"}]}'::jsonb, 6)
) as v(type, title, content, ord);

