insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"front desk","translation":"recepción","translations":{"es":"recepción"}},{"id":"2","word":"check in","translation":"registrarse (entrada)","translations":{"es":"registrarse (entrada)"}},{"id":"3","word":"check out","translation":"salir del hotel (salida)","translations":{"es":"salir del hotel (salida)"}},{"id":"4","word":"room key","translation":"llave del cuarto","translations":{"es":"llave del cuarto"}},{"id":"5","word":"single room","translation":"habitación sencilla","translations":{"es":"habitación sencilla"}},{"id":"6","word":"double room","translation":"habitación doble","translations":{"es":"habitación doble"}},{"id":"7","word":"towel","translation":"toalla","translations":{"es":"toalla"}},{"id":"8","word":"air conditioning","translation":"aire acondicionado","translations":{"es":"aire acondicionado"}},{"id":"9","word":"heater","translation":"calefacción","translations":{"es":"calefacción"}},{"id":"10","word":"elevator","translation":"elevador","translations":{"es":"elevador"}},{"id":"11","word":"floor","translation":"piso","translations":{"es":"piso"}},{"id":"12","word":"housekeeping","translation":"servicio de limpieza","translations":{"es":"servicio de limpieza"}},{"id":"13","word":"tip","translation":"propina","translations":{"es":"propina"}},{"id":"14","word":"view","translation":"vista","translations":{"es":"vista"}},{"id":"15","word":"noisy","translation":"ruidoso","translations":{"es":"ruidoso"}},{"id":"16","word":"quiet","translation":"tranquilo / silencioso","translations":{"es":"tranquilo / silencioso"}},{"id":"17","word":"Wi-Fi password","translation":"contraseña del wifi","translations":{"es":"contraseña del wifi"}}],"grammar":[{"structure":"Could you + verb, please?","example":"Could you call a taxi for me, please?","en":"Polite requests","es":"Pedidos amables"},{"structure":"Would you mind + verb-ing?","example":"Would you mind changing my room?","en":"Very polite requests","es":"Pedidos muy amables"},{"structure":"I have a reservation under…","example":"I have a reservation under Ruiz.","en":"Checking in","es":"Registrarse en el hotel"},{"structure":"There''s a problem with…","example":"There''s a problem with the air conditioning.","en":"Reporting a problem","es":"Reportar un problema"},{"structure":"What time is…?","example":"What time is checkout?","en":"Asking about hotel times","es":"Preguntar horarios del hotel"}],"tips":[{"en":"\"Would you mind…?\" is very polite. If the answer is \"No, not at all\", it means YES, they will do it.","es":"«Would you mind…?» es muy amable. Si la respuesta es «No, not at all», significa que SÍ lo harán."},{"en":"In US hotels, checkout is usually at 11 a.m. and check-in at 3 or 4 p.m.","es":"En los hoteles de Estados Unidos, la salida suele ser a las 11 a.m. y la entrada a las 3 o 4 p.m."},{"en":"It''s common to leave a small tip for housekeeping: a few dollars per night.","es":"Es común dejar una propina pequeña para la limpieza: unos dólares por noche."},{"en":"\"Front desk\" is the reception. Call it from your room phone for anything you need.","es":"La «front desk» es la recepción. Llámala desde el teléfono del cuarto para lo que necesites."},{"en":"Ask for the Wi-Fi password at check-in: \"What''s the Wi-Fi password?\"","es":"Pide la contraseña del wifi al registrarte: «What''s the Wi-Fi password?»"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I have a reservation under Ruiz.","translation":"Tengo una reservación a nombre de Ruiz.","translations":{"es":"Tengo una reservación a nombre de Ruiz."}},{"phrase":"For how many nights?","translation":"¿Por cuántas noches?","translations":{"es":"¿Por cuántas noches?"}},{"phrase":"Here''s your room key.","translation":"Aquí está la llave de su cuarto.","translations":{"es":"Aquí está la llave de su cuarto."}},{"phrase":"Your room is on the fifth floor.","translation":"Su cuarto está en el quinto piso.","translations":{"es":"Su cuarto está en el quinto piso."}},{"phrase":"What time is checkout?","translation":"¿A qué hora es la salida?","translations":{"es":"¿A qué hora es la salida?"}},{"phrase":"What''s the Wi-Fi password?","translation":"¿Cuál es la contraseña del wifi?","translations":{"es":"¿Cuál es la contraseña del wifi?"}},{"phrase":"Could I have some extra towels?","translation":"¿Me podría dar toallas extra?","translations":{"es":"¿Me podría dar toallas extra?"}},{"phrase":"There''s a problem with the heater.","translation":"Hay un problema con la calefacción.","translations":{"es":"Hay un problema con la calefacción."}},{"phrase":"Would you mind changing my room?","translation":"¿Le importaría cambiarme de cuarto?","translations":{"es":"¿Le importaría cambiarme de cuarto?"}},{"phrase":"No, not at all.","translation":"No, para nada (con gusto).","translations":{"es":"No, para nada (con gusto)."}},{"phrase":"Could you call a taxi for me?","translation":"¿Me podría llamar un taxi?","translations":{"es":"¿Me podría llamar un taxi?"}},{"phrase":"Is breakfast included?","translation":"¿El desayuno está incluido?","translations":{"es":"¿El desayuno está incluido?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"You arrive at the hotel. You say:","options":["My name reservation is.","I have a reservation under Ruiz.","Ruiz reservation me.","I have a reservation of Ruiz name."],"correct":1,"explanation":"\"A reservation under [name]\" is the standard phrase.","translations":{"es":{"question":"Llegas al hotel. Dices:","explanation":"«A reservation under [nombre]» es la frase estándar."}}},{"id":"2","question":"Complete: \"Would you mind ___ the window?\"","options":["opened","to open","opening","open"],"correct":2,"explanation":"Would you mind + verb-ing.","translations":{"es":{"question":"Completa: «Would you mind ___ the window?»","explanation":"Would you mind + verbo-ing."}}},{"id":"3","question":"You ask \"Would you mind helping me?\" The answer \"No, not at all\" means…","options":["I don''t know.","Later.","Yes, I''ll help you.","No, I won''t help you."],"correct":2,"explanation":"\"Not at all\" = it''s no problem for me. They will help.","translations":{"es":{"question":"Preguntas «Would you mind helping me?». La respuesta «No, not at all» significa…","explanation":"«Not at all» = no me molesta. Sí te ayudarán."}}},{"id":"4","question":"Where do you ask for help in a hotel?","options":["at housekeeping''s cart","in the view","at the front desk","in the elevator"],"correct":2,"explanation":"The front desk is the reception.","translations":{"es":{"question":"¿Dónde pides ayuda en un hotel?","explanation":"La front desk es la recepción."}}},{"id":"5","question":"Your room is cold and the heater doesn''t work. You say:","options":["Could I check out the heater?","I''d like a heater view.","There''s a problem with the heater.","The heater is very good."],"correct":2,"explanation":"\"There''s a problem with…\" reports a problem.","translations":{"es":{"question":"Tu cuarto está frío y la calefacción no funciona. Dices:","explanation":"«There''s a problem with…» reporta un problema."}}},{"id":"6","question":"\"Checkout\" is…","options":["when you leave the hotel","the hotel restaurant","the room key","when you arrive"],"correct":0,"explanation":"Check out = leave the hotel and pay.","translations":{"es":{"question":"«Checkout» es…","explanation":"Check out = salir del hotel y pagar."}}},{"id":"7","question":"Choose the polite request.","options":["Could you call a taxi for me, please?","You call me taxi.","Taxi now, please you.","Call taxi."],"correct":0,"explanation":"Could you…, please? is polite.","translations":{"es":{"question":"Elige el pedido amable.","explanation":"Could you…, please? es amable."}}},{"id":"8","question":"A room for one person is a…","options":["front desk","single room","suite floor","double room"],"correct":1,"explanation":"Single = one person.","translations":{"es":{"question":"Un cuarto para una persona es…","explanation":"Single = una persona."}}}]}'::jsonb, 3),
  ('story', 'Room 512', '{"text":"Elena''s apartment is very small, so Carmen stays at a hotel near her for the first two nights. At the front desk, she says, \"Good evening. I have a reservation under Ruiz.\" \"Welcome, Mrs. Ruiz. Two nights in a single room. Here''s your room key. You''re on the fifth floor, room 512.\" \"Thank you. What time is checkout?\" \"Eleven a.m. And the Wi-Fi password is on the card.\" The room is nice, with a view of the street. But it''s very noisy, and the heater doesn''t work. Carmen calls the front desk. \"Hello, this is room 512. There''s a problem with the heater. And the room is very noisy. Would you mind changing my room?\" \"No, not at all. We have a quiet room on the ninth floor.\" Ten minutes later, Carmen is in a warm, quiet room. \"New York is big,\" she writes to Laura, \"but people are kind.\"","translation":"El departamento de Elena es muy pequeño, así que Carmen se queda las primeras dos noches en un hotel cerca de ella. En la recepción dice: «Buenas noches. Tengo una reservación a nombre de Ruiz.» «Bienvenida, señora Ruiz. Dos noches en habitación sencilla. Aquí está la llave de su cuarto. Está en el quinto piso, cuarto 512.» «Gracias. ¿A qué hora es la salida?» «A las once de la mañana. Y la contraseña del wifi está en la tarjeta.» El cuarto es bonito, con vista a la calle. Pero es muy ruidoso y la calefacción no funciona. Carmen llama a la recepción. «Hola, habla del cuarto 512. Hay un problema con la calefacción. Y el cuarto es muy ruidoso. ¿Le importaría cambiarme de cuarto?» «No, para nada. Tenemos un cuarto tranquilo en el noveno piso.» Diez minutos después, Carmen está en un cuarto cálido y tranquilo. «Nueva York es grande», le escribe a Laura, «pero la gente es amable.»","translations":{"es":"El departamento de Elena es muy pequeño, así que Carmen se queda las primeras dos noches en un hotel cerca de ella. En la recepción dice: «Buenas noches. Tengo una reservación a nombre de Ruiz.» «Bienvenida, señora Ruiz. Dos noches en habitación sencilla. Aquí está la llave de su cuarto. Está en el quinto piso, cuarto 512.» «Gracias. ¿A qué hora es la salida?» «A las once de la mañana. Y la contraseña del wifi está en la tarjeta.» El cuarto es bonito, con vista a la calle. Pero es muy ruidoso y la calefacción no funciona. Carmen llama a la recepción. «Hola, habla del cuarto 512. Hay un problema con la calefacción. Y el cuarto es muy ruidoso. ¿Le importaría cambiarme de cuarto?» «No, para nada. Tenemos un cuarto tranquilo en el noveno piso.» Diez minutos después, Carmen está en un cuarto cálido y tranquilo. «Nueva York es grande», le escribe a Laura, «pero la gente es amable.»"},"highlighted_words":["hotel","front desk","I have a reservation under Ruiz","single room","room key","fifth floor","What time is checkout","Wi-Fi password","view","noisy","heater","There''s a problem with the heater","Would you mind changing my room","No, not at all","quiet"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","have","a","reservation","under","Ruiz"],"translation":"Tengo una reservación a nombre de Ruiz.","translations":{"es":"Tengo una reservación a nombre de Ruiz."}},{"words":["What","time","is","checkout"],"translation":"¿A qué hora es la salida?","translations":{"es":"¿A qué hora es la salida?"}},{"words":["Could","I","have","some","extra","towels"],"translation":"¿Me podría dar toallas extra?","translations":{"es":"¿Me podría dar toallas extra?"}},{"words":["There","is","a","problem","with","the","heater"],"translation":"Hay un problema con la calefacción.","translations":{"es":"Hay un problema con la calefacción."}},{"words":["Would","you","mind","changing","my","room"],"translation":"¿Le importaría cambiarme de cuarto?","translations":{"es":"¿Le importaría cambiarme de cuarto?"}},{"words":["Is","breakfast","included","in","the","price"],"translation":"¿El desayuno está incluido en el precio?","translations":{"es":"¿El desayuno está incluido en el precio?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Tengo una reservación","translations":{"es":"Tengo una reservación"},"answer":"I have a reservation"},{"prompt":"¿A qué hora es la salida?","translations":{"es":"¿A qué hora es la salida?"},"answer":"What time is checkout"},{"prompt":"¿Me podría llamar un taxi?","translations":{"es":"¿Me podría llamar un taxi?"},"answer":"Could you call a taxi for me"},{"prompt":"El cuarto es muy ruidoso","translations":{"es":"El cuarto es muy ruidoso"},"answer":"The room is very noisy"},{"prompt":"¿El desayuno está incluido?","translations":{"es":"¿El desayuno está incluido?"},"answer":"Is breakfast included"},{"prompt":"¿Me podría dar unas toallas?","translations":{"es":"¿Me podría dar unas toallas?"},"answer":"Could I have some towels"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 36: Going for a walk
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-36', 'Going for a walk', '🚶', 'Salir a pasear', 36, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"walk","translation":"paseo / caminar","translations":{"es":"paseo / caminar"}},{"id":"2","word":"stroll","translation":"paseo tranquilo","translations":{"es":"paseo tranquilo"}},{"id":"3","word":"path","translation":"sendero / camino","translations":{"es":"sendero / camino"}},{"id":"4","word":"bench","translation":"banca","translations":{"es":"banca"}},{"id":"5","word":"lake","translation":"lago","translations":{"es":"lago"}},{"id":"6","word":"bridge","translation":"puente","translations":{"es":"puente"}},{"id":"7","word":"squirrel","translation":"ardilla","translations":{"es":"ardilla"}},{"id":"8","word":"fountain","translation":"fuente","translations":{"es":"fuente"}},{"id":"9","word":"statue","translation":"estatua","translations":{"es":"estatua"}},{"id":"10","word":"neighborhood","translation":"barrio / vecindario","translations":{"es":"barrio / vecindario"}},{"id":"11","word":"me","translation":"me / mí","translations":{"es":"me / mí"}},{"id":"12","word":"him","translation":"lo / le / él","translations":{"es":"lo / le / él"}},{"id":"13","word":"her","translation":"la / le / ella","translations":{"es":"la / le / ella"}},{"id":"14","word":"us","translation":"nos / nosotros","translations":{"es":"nos / nosotros"}},{"id":"15","word":"them","translation":"los / las / les / ellos","translations":{"es":"los / las / les / ellos"}},{"id":"16","word":"let''s","translation":"vamos a… (sugerencia)","translations":{"es":"vamos a… (sugerencia)"}},{"id":"17","word":"tired","translation":"cansado","translations":{"es":"cansado"}}],"grammar":[{"structure":"me, you, him, her, it, us, them","example":"Elena showed us the park. I love them.","en":"Object pronouns","es":"Pronombres de objeto"},{"structure":"Let''s + verb","example":"Let''s go for a walk.","en":"Suggestions with \"Let''s\"","es":"Sugerencias con «Let''s» (vamos a…)"},{"structure":"Let''s not + verb","example":"Let''s not take the subway.","en":"Negative suggestions","es":"Sugerencias negativas"},{"structure":"verb + object pronoun","example":"Call me. Help them. Look at it!","en":"Pronouns go after the verb","es":"Los pronombres van después del verbo"},{"structure":"go for a walk / take a walk","example":"We took a walk by the river.","en":"Expressions for walking","es":"Expresiones para pasear"}],"tips":[{"en":"In Spanish the object pronoun goes before the verb (te llamo). In English it goes after: I''ll call you.","es":"En español el pronombre va antes del verbo (te llamo). En inglés va después: I''ll call you."},{"en":"\"Let''s\" = let us. It''s the friendliest way to suggest doing something together.","es":"«Let''s» = let us. Es la forma más amistosa de proponer hacer algo juntos."},{"en":"\"Them\" is for people and things in the plural: \"These flowers? I love them.\"","es":"«Them» sirve para personas y cosas en plural: «These flowers? I love them.»"},{"en":"City parks often have free walking tours on weekends — a great way to practice listening.","es":"Los parques de las ciudades suelen tener recorridos gratis a pie los fines de semana: una gran forma de practicar el oído."},{"en":"\"Stroll\" means a slow, relaxed walk.","es":"«Stroll» significa un paseo lento y relajado."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Let''s go for a walk.","translation":"Vamos a dar un paseo.","translations":{"es":"Vamos a dar un paseo."}},{"phrase":"Let''s sit on that bench.","translation":"Sentémonos en esa banca.","translations":{"es":"Sentémonos en esa banca."}},{"phrase":"Look at them!","translation":"¡Míralos!","translations":{"es":"¡Míralos!"}},{"phrase":"Can you take a picture of us?","translation":"¿Nos puede tomar una foto?","translations":{"es":"¿Nos puede tomar una foto?"}},{"phrase":"Wait for me!","translation":"¡Espérame!","translations":{"es":"¡Espérame!"}},{"phrase":"I''ll show you the lake.","translation":"Te voy a enseñar el lago.","translations":{"es":"Te voy a enseñar el lago."}},{"phrase":"Do you know him?","translation":"¿Lo conoces?","translations":{"es":"¿Lo conoces?"}},{"phrase":"I''m a little tired.","translation":"Estoy un poco cansada.","translations":{"es":"Estoy un poco cansada."}},{"phrase":"Let''s not walk too far.","translation":"No caminemos demasiado lejos.","translations":{"es":"No caminemos demasiado lejos."}},{"phrase":"This neighborhood is lovely.","translation":"Este barrio es precioso.","translations":{"es":"Este barrio es precioso."}},{"phrase":"Follow me.","translation":"Sígueme.","translations":{"es":"Sígueme."}},{"phrase":"Let''s go back.","translation":"Regresemos.","translations":{"es":"Regresemos."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Elena called ___ yesterday.\" (Carmen speaking about herself)","options":["I","mine","me","my"],"correct":2,"explanation":"After a verb we use the object pronoun: me.","translations":{"es":{"question":"Completa: «Elena called ___ yesterday.» (Carmen habla de sí misma)","explanation":"Después del verbo se usa el pronombre de objeto: me."}}},{"id":"2","question":"Complete: \"These shoes? I love ___.\"","options":["they","it","them","their"],"correct":2,"explanation":"Plural object → them.","translations":{"es":{"question":"Completa: «These shoes? I love ___.»","explanation":"Objeto plural → them."}}},{"id":"3","question":"How do you say \"Te llamo mañana\"?","options":["You I call tomorrow.","I you call tomorrow.","I''ll call you tomorrow.","I''ll you call tomorrow."],"correct":2,"explanation":"The pronoun goes after the verb.","translations":{"es":{"question":"¿Cómo se dice «Te llamo mañana»?","explanation":"El pronombre va después del verbo."}}},{"id":"4","question":"Make a suggestion: walk to the lake together.","options":["Let''s walk to the lake.","We let''s walk to the lake.","Let''s to walk to the lake.","Let walk us to the lake."],"correct":0,"explanation":"Let''s + base verb.","translations":{"es":{"question":"Haz una sugerencia: caminar juntos al lago.","explanation":"Let''s + verbo base."}}},{"id":"5","question":"Complete: \"Do you know Mr. Park? I like ___ a lot.\"","options":["her","him","he","his"],"correct":1,"explanation":"Mr. Park (a man) as an object → him.","translations":{"es":{"question":"Completa: «Do you know Mr. Park? I like ___ a lot.»","explanation":"Mr. Park (hombre) como objeto → him."}}},{"id":"6","question":"Complete: \"Can you take a picture of ___?\" (you and your cousin)","options":["us","ours","we","our"],"correct":0,"explanation":"We → us (object).","translations":{"es":{"question":"Completa: «Can you take a picture of ___?» (tú y tu prima)","explanation":"We → us (objeto)."}}},{"id":"7","question":"A long seat in a park is a…","options":["bench","path","bridge","fountain"],"correct":0,"explanation":"Bench = banca.","translations":{"es":{"question":"Un asiento largo en un parque es una…","explanation":"Bench = banca."}}},{"id":"8","question":"Choose the negative suggestion.","options":["Let''s don''t take the bus.","Let''s not take the bus.","Let''s no take the bus.","Don''t let''s taking the bus."],"correct":1,"explanation":"Negative: Let''s not + verb.","translations":{"es":{"question":"Elige la sugerencia negativa.","explanation":"Negativo: Let''s not + verbo."}}}]}'::jsonb, 3),
  ('story', 'Central Park', '{"text":"On Sunday, Elena says, \"Let''s go for a walk in Central Park.\" The park is enormous. There are paths, bridges, a big lake and many benches. \"Look at them!\" says Carmen. Two squirrels are running up a tree. Elena laughs. \"There are thousands of them here.\" They walk for an hour. Elena shows her the famous fountain and a statue of Alice in Wonderland. A young woman with a camera passes by. \"Excuse me, can you take a picture of us?\" asks Carmen. \"Sure! Smile!\" After two hours, Carmen is tired. \"Let''s sit on that bench,\" she says. \"And let''s not walk back. Let''s take a taxi!\" Elena takes her hand. \"Carmen, I''m so happy you''re here. Twenty years is too long.\" \"I know. I missed you,\" says Carmen. \"I missed you too.\"","translation":"El domingo, Elena dice: «Vamos a dar un paseo por Central Park.» El parque es enorme. Hay senderos, puentes, un lago grande y muchas bancas. «¡Míralas!», dice Carmen. Dos ardillas suben corriendo por un árbol. Elena se ríe. «Aquí hay miles.» Caminan una hora. Elena le enseña la famosa fuente y una estatua de Alicia en el País de las Maravillas. Pasa una joven con una cámara. «Disculpe, ¿nos puede tomar una foto?», pregunta Carmen. «¡Claro! ¡Sonrían!» Después de dos horas, Carmen está cansada. «Sentémonos en esa banca», dice. «Y no regresemos caminando. ¡Tomemos un taxi!» Elena le toma la mano. «Carmen, estoy tan feliz de que estés aquí. Veinte años es demasiado tiempo.» «Lo sé. Te extrañé», dice Carmen. «Yo también te extrañé.»","translations":{"es":"El domingo, Elena dice: «Vamos a dar un paseo por Central Park.» El parque es enorme. Hay senderos, puentes, un lago grande y muchas bancas. «¡Míralas!», dice Carmen. Dos ardillas suben corriendo por un árbol. Elena se ríe. «Aquí hay miles.» Caminan una hora. Elena le enseña la famosa fuente y una estatua de Alicia en el País de las Maravillas. Pasa una joven con una cámara. «Disculpe, ¿nos puede tomar una foto?», pregunta Carmen. «¡Claro! ¡Sonrían!» Después de dos horas, Carmen está cansada. «Sentémonos en esa banca», dice. «Y no regresemos caminando. ¡Tomemos un taxi!» Elena le toma la mano. «Carmen, estoy tan feliz de que estés aquí. Veinte años es demasiado tiempo.» «Lo sé. Te extrañé», dice Carmen. «Yo también te extrañé.»"},"highlighted_words":["Let''s go for a walk","paths","bridges","lake","benches","Look at them","squirrels","fountain","statue","can you take a picture of us","tired","Let''s sit on that bench","let''s not walk back","I missed you"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Let''s","go","for","a","walk","in","the","park"],"translation":"Vamos a dar un paseo por el parque.","translations":{"es":"Vamos a dar un paseo por el parque."}},{"words":["Can","you","take","a","picture","of","us"],"translation":"¿Nos puede tomar una foto?","translations":{"es":"¿Nos puede tomar una foto?"}},{"words":["I","will","call","you","tomorrow"],"translation":"Te llamo mañana.","translations":{"es":"Te llamo mañana."}},{"words":["Let''s","sit","on","that","bench"],"translation":"Sentémonos en esa banca.","translations":{"es":"Sentémonos en esa banca."}},{"words":["Do","you","know","him"],"translation":"¿Lo conoces?","translations":{"es":"¿Lo conoces?"}},{"words":["Elena","showed","us","the","lake"],"translation":"Elena nos enseñó el lago.","translations":{"es":"Elena nos enseñó el lago."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Vamos a dar un paseo","translations":{"es":"Vamos a dar un paseo"},"answer":"Let''s go for a walk"},{"prompt":"Espérame","translations":{"es":"Espérame"},"answer":"Wait for me"},{"prompt":"Me encantan","translations":{"es":"Me encantan"},"answer":"I love them"},{"prompt":"¿Nos puede ayudar?","translations":{"es":"¿Nos puede ayudar?"},"answer":"Can you help us"},{"prompt":"Te extrañé","translations":{"es":"Te extrañé"},"answer":"I missed you"},{"prompt":"Sígueme","translations":{"es":"Sígueme"},"answer":"Follow me"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 37: Renting a car
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-37', 'Renting a car', '🚗', 'Rentar un auto', 37, true)
