insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"rent","translation":"rentar / alquilar","translations":{"es":"rentar / alquilar"}},{"id":"2","word":"rental car","translation":"auto rentado","translations":{"es":"auto rentado"}},{"id":"3","word":"driver''s license","translation":"licencia de manejo","translations":{"es":"licencia de manejo"}},{"id":"4","word":"credit card","translation":"tarjeta de crédito","translations":{"es":"tarjeta de crédito"}},{"id":"5","word":"insurance","translation":"seguro","translations":{"es":"seguro"}},{"id":"6","word":"gas","translation":"gasolina","translations":{"es":"gasolina"}},{"id":"7","word":"gas station","translation":"gasolinera","translations":{"es":"gasolinera"}},{"id":"8","word":"tank","translation":"tanque","translations":{"es":"tanque"}},{"id":"9","word":"fill up","translation":"llenar (el tanque)","translations":{"es":"llenar (el tanque)"}},{"id":"10","word":"pick up","translation":"recoger","translations":{"es":"recoger"}},{"id":"11","word":"drop off","translation":"entregar / dejar","translations":{"es":"entregar / dejar"}},{"id":"12","word":"highway","translation":"carretera / autopista","translations":{"es":"carretera / autopista"}},{"id":"13","word":"speed limit","translation":"límite de velocidad","translations":{"es":"límite de velocidad"}},{"id":"14","word":"GPS","translation":"GPS / navegador","translations":{"es":"GPS / navegador"}},{"id":"15","word":"trunk","translation":"cajuela / maletero","translations":{"es":"cajuela / maletero"}},{"id":"16","word":"per day","translation":"por día","translations":{"es":"por día"}},{"id":"17","word":"automatic","translation":"automático","translations":{"es":"automático"}}],"grammar":[{"structure":"need to + verb","example":"You need to show your driver''s license.","en":"Necessity with \"need to\"","es":"Necesidad con «need to»"},{"structure":"need + noun","example":"We need a bigger car.","en":"\"Need\" with things","es":"«Need» con cosas"},{"structure":"How much does it cost to…?","example":"How much does it cost to rent a car for three days?","en":"Asking about prices of services","es":"Preguntar el precio de un servicio"},{"structure":"per day / per week","example":"It''s forty dollars per day.","en":"Rates","es":"Tarifas"},{"structure":"fill up / pick up / drop off","example":"Please fill up the tank before you drop off the car.","en":"Phrasal verbs for renting a car","es":"Verbos frasales para rentar un auto"}],"tips":[{"en":"To rent a car in the US you usually need a driver''s license and a credit card (not cash).","es":"Para rentar un auto en Estados Unidos normalmente necesitas licencia de manejo y tarjeta de crédito (no efectivo)."},{"en":"Most rental cars are automatic. If you want a manual, ask for a \"stick shift\".","es":"La mayoría de los autos de renta son automáticos. Si quieres estándar, pide un «stick shift»."},{"en":"\"Gas\" is gasoline in American English (\"petrol\" in British English). It''s sold by the gallon (≈ 3.8 liters).","es":"«Gas» es gasolina en inglés estadounidense («petrol» en británico). Se vende por galón (≈ 3.8 litros)."},{"en":"Speed limits are in miles per hour (mph): 65 mph is about 105 km/h.","es":"Los límites de velocidad están en millas por hora (mph): 65 mph son unos 105 km/h."},{"en":"Many gas stations are self-service: you pay first at the pump or inside.","es":"Muchas gasolineras son de autoservicio: pagas primero en la bomba o adentro."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to rent a car.","translation":"Quisiera rentar un auto.","translations":{"es":"Quisiera rentar un auto."}},{"phrase":"For how many days?","translation":"¿Por cuántos días?","translations":{"es":"¿Por cuántos días?"}},{"phrase":"How much does it cost per day?","translation":"¿Cuánto cuesta por día?","translations":{"es":"¿Cuánto cuesta por día?"}},{"phrase":"You need to show your driver''s license.","translation":"Necesita mostrar su licencia de manejo.","translations":{"es":"Necesita mostrar su licencia de manejo."}},{"phrase":"Is insurance included?","translation":"¿El seguro está incluido?","translations":{"es":"¿El seguro está incluido?"}},{"phrase":"Is it automatic?","translation":"¿Es automático?","translations":{"es":"¿Es automático?"}},{"phrase":"Where do I pick up the car?","translation":"¿Dónde recojo el auto?","translations":{"es":"¿Dónde recojo el auto?"}},{"phrase":"Please fill up the tank before you return it.","translation":"Por favor, llene el tanque antes de devolverlo.","translations":{"es":"Por favor, llene el tanque antes de devolverlo."}},{"phrase":"We need to get gas.","translation":"Tenemos que poner gasolina.","translations":{"es":"Tenemos que poner gasolina."}},{"phrase":"Put the suitcases in the trunk.","translation":"Pon las maletas en la cajuela.","translations":{"es":"Pon las maletas en la cajuela."}},{"phrase":"What''s the speed limit here?","translation":"¿Cuál es el límite de velocidad aquí?","translations":{"es":"¿Cuál es el límite de velocidad aquí?"}},{"phrase":"Drive safely!","translation":"¡Maneja con cuidado!","translations":{"es":"¡Maneja con cuidado!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"You ___ show your license.\"","options":["need","needs to","needing","need to"],"correct":3,"explanation":"need to + verb.","translations":{"es":{"question":"Completa: «You ___ show your license.»","explanation":"need to + verbo."}}},{"id":"2","question":"To rent a car in the US you usually need…","options":["a passport photo","a visa","only cash","a license and a credit card"],"correct":3,"explanation":"Driver''s license + credit card.","translations":{"es":{"question":"Para rentar un auto en Estados Unidos normalmente necesitas…","explanation":"Licencia de manejo + tarjeta de crédito."}}},{"id":"3","question":"\"Gas\" in American English is…","options":["aceite","aire","gas natural para cocinar","gasolina"],"correct":3,"explanation":"Gas = gasoline.","translations":{"es":{"question":"«Gas» en inglés estadounidense es…","explanation":"Gas = gasolina."}}},{"id":"4","question":"Where do you put suitcases in a car?","options":["in the GPS","on the highway","in the tank","in the trunk"],"correct":3,"explanation":"Trunk = cajuela.","translations":{"es":{"question":"¿Dónde pones las maletas en un auto?","explanation":"Trunk = cajuela."}}},{"id":"5","question":"\"Drop off the car\" means…","options":["buy the car","wash the car","start the car","return/leave the car"],"correct":3,"explanation":"Drop off = entregar, dejar.","translations":{"es":{"question":"«Drop off the car» significa…","explanation":"Drop off = entregar, dejar."}}},{"id":"6","question":"Choose the correct question.","options":["How much cost per day?","How much it costs per day?","How many does it cost per day?","How much does it cost per day?"],"correct":3,"explanation":"How much does it cost…?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"How much does it cost…?"}}},{"id":"7","question":"65 mph is about…","options":["200 km/h","65 km/h","40 km/h","105 km/h"],"correct":3,"explanation":"1 mile ≈ 1.6 km, so 65 mph ≈ 105 km/h.","translations":{"es":{"question":"65 mph son aproximadamente…","explanation":"1 milla ≈ 1.6 km, así que 65 mph ≈ 105 km/h."}}},{"id":"8","question":"The tank is almost empty. You say:","options":["We need to drop off the gas.","We need to speed limit.","We need a trunk.","We need to get gas."],"correct":3,"explanation":"Get gas = poner gasolina.","translations":{"es":{"question":"El tanque está casi vacío. Dices:","explanation":"Get gas = poner gasolina."}}}]}'::jsonb, 3),
  ('story', 'Autumn Colors', '{"text":"Elena''s son, David, wants to show Carmen the autumn colors outside the city. \"We need to rent a car,\" he says. At the rental office, he asks, \"How much does it cost to rent a car for one day?\" \"Fifty dollars per day, with insurance.\" \"Is it automatic?\" \"Yes. You need to show your driver''s license and a credit card.\" David picks up the car, and they put a picnic basket in the trunk. On the highway, Carmen looks out of the window. The trees are red, orange and yellow. \"Beautiful! In San Diego the trees don''t change color like this.\" After an hour, a light comes on. \"We need to get gas,\" says David. At the gas station, Carmen buys coffee for everybody. In the evening they drop off the car with a full tank. \"Thank you, David. Today I saw the most beautiful trees of my life.\"","translation":"El hijo de Elena, David, quiere enseñarle a Carmen los colores del otoño fuera de la ciudad. «Necesitamos rentar un auto», dice. En la oficina de renta pregunta: «¿Cuánto cuesta rentar un auto por un día?» «Cincuenta dólares por día, con seguro.» «¿Es automático?» «Sí. Necesita mostrar su licencia de manejo y una tarjeta de crédito.» David recoge el auto y ponen una canasta de picnic en la cajuela. En la carretera, Carmen mira por la ventana. Los árboles están rojos, anaranjados y amarillos. «¡Precioso! En San Diego los árboles no cambian de color así.» Después de una hora, se prende una luz. «Tenemos que poner gasolina», dice David. En la gasolinera, Carmen compra café para todos. En la tarde entregan el auto con el tanque lleno. «Gracias, David. Hoy vi los árboles más bonitos de mi vida.»","translations":{"es":"El hijo de Elena, David, quiere enseñarle a Carmen los colores del otoño fuera de la ciudad. «Necesitamos rentar un auto», dice. En la oficina de renta pregunta: «¿Cuánto cuesta rentar un auto por un día?» «Cincuenta dólares por día, con seguro.» «¿Es automático?» «Sí. Necesita mostrar su licencia de manejo y una tarjeta de crédito.» David recoge el auto y ponen una canasta de picnic en la cajuela. En la carretera, Carmen mira por la ventana. Los árboles están rojos, anaranjados y amarillos. «¡Precioso! En San Diego los árboles no cambian de color así.» Después de una hora, se prende una luz. «Tenemos que poner gasolina», dice David. En la gasolinera, Carmen compra café para todos. En la tarde entregan el auto con el tanque lleno. «Gracias, David. Hoy vi los árboles más bonitos de mi vida.»"},"highlighted_words":["We need to rent a car","How much does it cost","per day","insurance","automatic","driver''s license","credit card","picks up","trunk","highway","We need to get gas","gas station","drop off","full tank"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","to","rent","a","car"],"translation":"Quisiera rentar un auto.","translations":{"es":"Quisiera rentar un auto."}},{"words":["How","much","does","it","cost","per","day"],"translation":"¿Cuánto cuesta por día?","translations":{"es":"¿Cuánto cuesta por día?"}},{"words":["You","need","to","show","your","license"],"translation":"Necesita mostrar su licencia.","translations":{"es":"Necesita mostrar su licencia."}},{"words":["We","need","to","get","gas"],"translation":"Tenemos que poner gasolina.","translations":{"es":"Tenemos que poner gasolina."}},{"words":["Put","the","suitcases","in","the","trunk"],"translation":"Pon las maletas en la cajuela.","translations":{"es":"Pon las maletas en la cajuela."}},{"words":["Is","insurance","included","in","the","price"],"translation":"¿El seguro está incluido en el precio?","translations":{"es":"¿El seguro está incluido en el precio?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Necesito rentar un auto","translations":{"es":"Necesito rentar un auto"},"answer":"I need to rent a car"},{"prompt":"¿Es automático?","translations":{"es":"¿Es automático?"},"answer":"Is it automatic"},{"prompt":"¿Cuánto cuesta?","translations":{"es":"¿Cuánto cuesta?"},"answer":"How much does it cost"},{"prompt":"Necesitamos gasolina","translations":{"es":"Necesitamos gasolina"},"answer":"We need gas"},{"prompt":"Maneja con cuidado","translations":{"es":"Maneja con cuidado"},"answer":"Drive safely"},{"prompt":"¿Dónde recojo el auto?","translations":{"es":"¿Dónde recojo el auto?"},"answer":"Where do I pick up the car"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 38: At the restaurant
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-38', 'At the restaurant', '🍽️', 'En el restaurante', 38, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"waiter","translation":"mesero","translations":{"es":"mesero"}},{"id":"2","word":"waitress","translation":"mesera","translations":{"es":"mesera"}},{"id":"3","word":"menu","translation":"menú / carta","translations":{"es":"menú / carta"}},{"id":"4","word":"order","translation":"pedir / pedido","translations":{"es":"pedir / pedido"}},{"id":"5","word":"appetizer","translation":"entrada","translations":{"es":"entrada"}},{"id":"6","word":"main course","translation":"plato fuerte","translations":{"es":"plato fuerte"}},{"id":"7","word":"dessert","translation":"postre","translations":{"es":"postre"}},{"id":"8","word":"check","translation":"cuenta","translations":{"es":"cuenta"}},{"id":"9","word":"tip","translation":"propina","translations":{"es":"propina"}},{"id":"10","word":"to-go box","translation":"recipiente para llevar","translations":{"es":"recipiente para llevar"}},{"id":"11","word":"spicy","translation":"picante","translations":{"es":"picante"}},{"id":"12","word":"medium","translation":"término medio","translations":{"es":"término medio"}},{"id":"13","word":"well done","translation":"bien cocido","translations":{"es":"bien cocido"}},{"id":"14","word":"allergic","translation":"alérgico","translations":{"es":"alérgico"}},{"id":"15","word":"refill","translation":"rellenar / otro (bebida)","translations":{"es":"rellenar / otro (bebida)"}},{"id":"16","word":"napkin","translation":"servilleta","translations":{"es":"servilleta"}},{"id":"17","word":"fork","translation":"tenedor","translations":{"es":"tenedor"}}],"grammar":[{"structure":"I''ll have…","example":"I''ll have the chicken soup, please.","en":"Ordering food","es":"Pedir comida"},{"structure":"Would you like…? / What would you like?","example":"What would you like to drink?","en":"The waiter''s questions","es":"Las preguntas del mesero"},{"structure":"Could we have…?","example":"Could we have the check, please?","en":"Asking for things politely","es":"Pedir cosas con amabilidad"},{"structure":"some for offers","example":"Would you like some more bread?","en":"\"Some\" in offers (even in questions)","es":"«Some» en ofrecimientos (aunque sea pregunta)"},{"structure":"without / with / on the side","example":"A salad without onions, with the dressing on the side.","en":"Special requests","es":"Pedidos especiales"}],"tips":[{"en":"In the US you ask for \"the check\" (la cuenta). The waiter usually won''t bring it until you ask, or brings it when you finish.","es":"En Estados Unidos se pide «the check» (la cuenta). El mesero normalmente no la trae hasta que la pides, o la trae al terminar."},{"en":"Tipping 15–20% is expected in restaurants with table service.","es":"En restaurantes con servicio a la mesa se espera una propina del 15 al 20%."},{"en":"Water is free: \"Can I have a glass of water, please?\" Refills of soft drinks are often free too.","es":"El agua es gratis: «Can I have a glass of water, please?». Rellenar el refresco también suele ser gratis."},{"en":"Portions are big. Ask for \"a to-go box\" to take the rest home.","es":"Las porciones son grandes. Pide «a to-go box» para llevarte lo que sobre."},{"en":"If you have an allergy, say: \"I''m allergic to…\" — restaurants take it seriously.","es":"Si tienes una alergia, di: «I''m allergic to…»: los restaurantes lo toman en serio."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"A table for two, please.","translation":"Una mesa para dos, por favor.","translations":{"es":"Una mesa para dos, por favor."}},{"phrase":"Can I see the menu?","translation":"¿Puedo ver el menú?","translations":{"es":"¿Puedo ver el menú?"}},{"phrase":"Are you ready to order?","translation":"¿Están listos para ordenar?","translations":{"es":"¿Están listos para ordenar?"}},{"phrase":"I''ll have the salmon, please.","translation":"Para mí el salmón, por favor.","translations":{"es":"Para mí el salmón, por favor."}},{"phrase":"What would you like to drink?","translation":"¿Qué les gustaría tomar?","translations":{"es":"¿Qué les gustaría tomar?"}},{"phrase":"Is it spicy?","translation":"¿Pica?","translations":{"es":"¿Pica?"}},{"phrase":"Without onions, please.","translation":"Sin cebolla, por favor.","translations":{"es":"Sin cebolla, por favor."}},{"phrase":"I''m allergic to nuts.","translation":"Soy alérgica a las nueces.","translations":{"es":"Soy alérgica a las nueces."}},{"phrase":"Would you like some dessert?","translation":"¿Les gustaría postre?","translations":{"es":"¿Les gustaría postre?"}},{"phrase":"Could we have the check, please?","translation":"¿Nos trae la cuenta, por favor?","translations":{"es":"¿Nos trae la cuenta, por favor?"}},{"phrase":"Can I get a to-go box?","translation":"¿Me da un recipiente para llevar?","translations":{"es":"¿Me da un recipiente para llevar?"}},{"phrase":"Everything was delicious.","translation":"Todo estuvo delicioso.","translations":{"es":"Todo estuvo delicioso."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you order food?","options":["I will the chicken.","I''ll have the chicken, please.","Chicken for me give.","I''m having chicken, please."],"correct":1,"explanation":"\"I''ll have…\" is the natural way to order.","translations":{"es":{"question":"¿Cómo pides comida?","explanation":"«I''ll have…» es la forma natural de pedir."}}},{"id":"2","question":"You finished eating and want to pay. You say:","options":["Could we have the tip?","Could we have the check, please?","Could we have the menu?","Could we have the bill to go?"],"correct":1,"explanation":"In the US: the check.","translations":{"es":{"question":"Terminaste de comer y quieres pagar. Dices:","explanation":"En Estados Unidos: the check."}}},{"id":"3","question":"In a US restaurant with table service, the usual tip is…","options":["15–20%","50%","1 dollar total","0%"],"correct":0,"explanation":"15–20% is standard.","translations":{"es":{"question":"En un restaurante de Estados Unidos con servicio a la mesa, la propina habitual es…","explanation":"Lo normal es 15–20%."}}},{"id":"4","question":"You can''t eat nuts. You say:","options":["I''m allergic to nuts.","Nuts are allergic.","I have allergic nuts.","I''m allergy nuts."],"correct":0,"explanation":"I''m allergic to + food.","translations":{"es":{"question":"No puedes comer nueces. Dices:","explanation":"I''m allergic to + alimento."}}},{"id":"5","question":"The sweet course at the end of a meal is…","options":["main course","dessert","appetizer","desert"],"correct":1,"explanation":"Dessert (double s) = postre. Desert = desierto.","translations":{"es":{"question":"El plato dulce al final de la comida es…","explanation":"Dessert (doble s) = postre. Desert = desierto."}}},{"id":"6","question":"Complete: \"Would you like ___ more bread?\"","options":["some","many","a","any"],"correct":0,"explanation":"In offers we use \"some\", even in questions.","translations":{"es":{"question":"Completa: «Would you like ___ more bread?»","explanation":"En ofrecimientos se usa «some», aunque sea pregunta."}}},{"id":"7","question":"You can''t finish your food and want to take it home. You ask for…","options":["a to-go box","the menu","a napkin","a refill"],"correct":0,"explanation":"A to-go box = recipiente para llevar.","translations":{"es":{"question":"No terminas tu comida y quieres llevártela. Pides…","explanation":"A to-go box = recipiente para llevar."}}},{"id":"8","question":"The waiter asks \"Are you ready to order?\" but you need more time. You say:","options":["Everything was delicious.","I''m allergic.","Not yet. Could we have a few more minutes?","Yes, the check please."],"correct":2,"explanation":"\"Not yet\" + polite request for more time.","translations":{"es":{"question":"El mesero pregunta «Are you ready to order?» pero necesitas más tiempo. Dices:","explanation":"«Not yet» + pedir amablemente más tiempo."}}}]}'::jsonb, 3),
  ('story', 'A New York Diner', '{"text":"On her last night in New York, Carmen invites Elena to dinner at an old diner. \"A table for two, please,\" says Carmen. The waitress gives them the menus. \"What would you like to drink?\" \"Two coffees, please.\" Carmen reads the menu slowly. \"Is the chili spicy?\" \"A little,\" says the waitress. \"Okay. I''ll have the chili and a salad without onions.\" Elena orders a turkey sandwich. The portions are enormous! \"Would you like some dessert?\" asks the waitress. \"Apple pie, please. Two forks.\" At the end, Carmen asks, \"Could we have the check, please? And can I get a to-go box?\" She calculates the tip: twenty percent. Elena watches her and smiles. \"You order like a New Yorker now.\" \"Thirty lessons ago I didn''t know how to say ''tenedor''!\"","translation":"En su última noche en Nueva York, Carmen invita a Elena a cenar a un diner antiguo. «Una mesa para dos, por favor», dice Carmen. La mesera les da los menús. «¿Qué les gustaría tomar?» «Dos cafés, por favor.» Carmen lee el menú despacio. «¿El chili pica?» «Un poco», dice la mesera. «Bueno. Para mí el chili y una ensalada sin cebolla.» Elena pide un sándwich de pavo. ¡Las porciones son enormes! «¿Les gustaría postre?», pregunta la mesera. «Pay de manzana, por favor. Dos tenedores.» Al final, Carmen pregunta: «¿Nos trae la cuenta, por favor? ¿Y me da un recipiente para llevar?» Calcula la propina: veinte por ciento. Elena la mira y sonríe. «Ahora pides como una neoyorquina.» «¡Hace treinta lecciones no sabía decir «fork»!»","translations":{"es":"En su última noche en Nueva York, Carmen invita a Elena a cenar a un diner antiguo. «Una mesa para dos, por favor», dice Carmen. La mesera les da los menús. «¿Qué les gustaría tomar?» «Dos cafés, por favor.» Carmen lee el menú despacio. «¿El chili pica?» «Un poco», dice la mesera. «Bueno. Para mí el chili y una ensalada sin cebolla.» Elena pide un sándwich de pavo. ¡Las porciones son enormes! «¿Les gustaría postre?», pregunta la mesera. «Pay de manzana, por favor. Dos tenedores.» Al final, Carmen pregunta: «¿Nos trae la cuenta, por favor? ¿Y me da un recipiente para llevar?» Calcula la propina: veinte por ciento. Elena la mira y sonríe. «Ahora pides como una neoyorquina.» «¡Hace treinta lecciones no sabía decir «fork»!»"},"highlighted_words":["A table for two, please","waitress","menus","What would you like to drink","spicy","I''ll have","without onions","Would you like some dessert","forks","Could we have the check, please","to-go box","tip"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["A","table","for","two","please"],"translation":"Una mesa para dos, por favor.","translations":{"es":"Una mesa para dos, por favor."}},{"words":["I","will","have","the","chicken","soup"],"translation":"Para mí la sopa de pollo.","translations":{"es":"Para mí la sopa de pollo."}},{"words":["Could","we","have","the","check","please"],"translation":"¿Nos trae la cuenta, por favor?","translations":{"es":"¿Nos trae la cuenta, por favor?"}},{"words":["Would","you","like","some","dessert"],"translation":"¿Les gustaría postre?","translations":{"es":"¿Les gustaría postre?"}},{"words":["I","am","allergic","to","nuts"],"translation":"Soy alérgica a las nueces.","translations":{"es":"Soy alérgica a las nueces."}},{"words":["Can","I","get","a","to-go","box"],"translation":"¿Me da un recipiente para llevar?","translations":{"es":"¿Me da un recipiente para llevar?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Una mesa para dos, por favor","translations":{"es":"Una mesa para dos, por favor"},"answer":"A table for two, please"},{"prompt":"¿Puedo ver el menú?","translations":{"es":"¿Puedo ver el menú?"},"answer":"Can I see the menu"},{"prompt":"¿Pica?","translations":{"es":"¿Pica?"},"answer":"Is it spicy"},{"prompt":"La cuenta, por favor","translations":{"es":"La cuenta, por favor"},"answer":"The check, please"},{"prompt":"Todo estuvo delicioso","translations":{"es":"Todo estuvo delicioso"},"answer":"Everything was delicious"},{"prompt":"Sin cebolla, por favor","translations":{"es":"Sin cebolla, por favor"},"answer":"Without onions, please"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 39: Shopping
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-39', 'Shopping', '🛍️', 'De compras', 39, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"store","translation":"tienda","translations":{"es":"tienda"}},{"id":"2","word":"mall","translation":"centro comercial","translations":{"es":"centro comercial"}},{"id":"3","word":"clerk","translation":"dependiente / vendedor","translations":{"es":"dependiente / vendedor"}},{"id":"4","word":"register","translation":"caja","translations":{"es":"caja"}},{"id":"5","word":"receipt","translation":"recibo / ticket","translations":{"es":"recibo / ticket"}},{"id":"6","word":"sale","translation":"oferta / rebaja","translations":{"es":"oferta / rebaja"}},{"id":"7","word":"discount","translation":"descuento","translations":{"es":"descuento"}},{"id":"8","word":"sales tax","translation":"impuesto sobre la venta","translations":{"es":"impuesto sobre la venta"}},{"id":"9","word":"return","translation":"devolver / devolución","translations":{"es":"devolver / devolución"}},{"id":"10","word":"exchange","translation":"cambiar (un producto)","translations":{"es":"cambiar (un producto)"}},{"id":"11","word":"present","translation":"regalo","translations":{"es":"regalo"}},{"id":"12","word":"cash","translation":"efectivo","translations":{"es":"efectivo"}},{"id":"13","word":"too","translation":"demasiado","translations":{"es":"demasiado"}},{"id":"14","word":"enough","translation":"suficiente","translations":{"es":"suficiente"}},{"id":"15","word":"boots","translation":"botas","translations":{"es":"botas"}},{"id":"16","word":"bag","translation":"bolsa","translations":{"es":"bolsa"}},{"id":"17","word":"souvenir shop","translation":"tienda de recuerdos","translations":{"es":"tienda de recuerdos"}}],"grammar":[{"structure":"too + adjective","example":"These boots are too expensive.","en":"\"Too\" = more than you want","es":"«Too» = demasiado"},{"structure":"adjective + enough","example":"This coat isn''t warm enough.","en":"\"Enough\" goes after the adjective","es":"«Enough» (suficiente) va después del adjetivo"},{"structure":"enough + noun","example":"I don''t have enough money.","en":"\"Enough\" goes before the noun","es":"«Enough» va antes del sustantivo"},{"structure":"Do you have this in…?","example":"Do you have this in black?","en":"Asking for another color or size","es":"Pedir otro color o talla"},{"structure":"I''m looking for…","example":"I''m looking for a present for my grandson.","en":"Telling the clerk what you need","es":"Decirle al vendedor qué buscas"}],"tips":[{"en":"\"Too\" has a negative meaning: \"too big\" = it doesn''t work for me. \"Very big\" is just a description.","es":"«Too» tiene sentido negativo: «too big» = no me sirve. «Very big» es solo una descripción."},{"en":"In the US the price on the tag doesn''t include sales tax; it''s added at the register.","es":"En Estados Unidos el precio de la etiqueta no incluye el impuesto (sales tax); se suma en la caja."},{"en":"Keep your receipt: most stores accept returns within 30 days.","es":"Guarda tu recibo: la mayoría de las tiendas aceptan devoluciones en 30 días."},{"en":"Black Friday (after Thanksgiving) has big discounts.","es":"El Black Friday (después del Día de Acción de Gracias) tiene grandes descuentos."},{"en":"\"Cash or card?\" is the usual question at the register. \"Card, please\" is the common answer.","es":"«Cash or card?» es la pregunta habitual en la caja. «Card, please» es la respuesta común."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''m looking for a present.","translation":"Busco un regalo.","translations":{"es":"Busco un regalo."}},{"phrase":"Do you have this in black?","translation":"¿Lo tiene en negro?","translations":{"es":"¿Lo tiene en negro?"}},{"phrase":"It''s too expensive.","translation":"Está demasiado caro.","translations":{"es":"Está demasiado caro."}},{"phrase":"It isn''t big enough.","translation":"No es lo suficientemente grande.","translations":{"es":"No es lo suficientemente grande."}},{"phrase":"I don''t have enough cash.","translation":"No traigo suficiente efectivo.","translations":{"es":"No traigo suficiente efectivo."}},{"phrase":"Is this on sale?","translation":"¿Esto está en oferta?","translations":{"es":"¿Esto está en oferta?"}},{"phrase":"Cash or card?","translation":"¿Efectivo o tarjeta?","translations":{"es":"¿Efectivo o tarjeta?"}},{"phrase":"Card, please.","translation":"Con tarjeta, por favor.","translations":{"es":"Con tarjeta, por favor."}},{"phrase":"Can I have a bag?","translation":"¿Me da una bolsa?","translations":{"es":"¿Me da una bolsa?"}},{"phrase":"Can I return it if it doesn''t fit?","translation":"¿Lo puedo devolver si no le queda?","translations":{"es":"¿Lo puedo devolver si no le queda?"}},{"phrase":"Here''s your receipt.","translation":"Aquí está su recibo.","translations":{"es":"Aquí está su recibo."}},{"phrase":"Could you gift-wrap it?","translation":"¿Me lo envuelve para regalo?","translations":{"es":"¿Me lo envuelve para regalo?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"The shoes cost $300 and you can''t pay that. You say:","options":["They''re enough expensive.","They''re too expensive.","They''re very expensive enough.","They''re expensive too much."],"correct":1,"explanation":"\"Too expensive\" = more than you can pay.","translations":{"es":{"question":"Los zapatos cuestan $300 y no puedes pagarlo. Dices:","explanation":"«Too expensive» = más de lo que puedes pagar."}}},{"id":"2","question":"Choose the correct position of \"enough\".","options":["This coat isn''t enough warm.","This coat isn''t warm enough.","This coat enough isn''t warm.","This coat isn''t warm sufficient."],"correct":1,"explanation":"Adjective + enough: warm enough.","translations":{"es":{"question":"Elige la posición correcta de «enough».","explanation":"Adjetivo + enough: warm enough."}}},{"id":"3","question":"Choose the correct sentence.","options":["I don''t have enough money.","I don''t have money enough.","I haven''t enough of money.","I don''t enough have money."],"correct":0,"explanation":"Enough + noun: enough money.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"Enough + sustantivo: enough money."}}},{"id":"4","question":"You want the same sweater in another color. You ask:","options":["Do you have this in blue?","Do you have blue this?","Have you this blue in?","Is this in blue have?"],"correct":0,"explanation":"Do you have this in + color/size?","translations":{"es":{"question":"Quieres el mismo suéter en otro color. Preguntas:","explanation":"Do you have this in + color/talla?"}}},{"id":"5","question":"The paper that proves what you bought is the…","options":["register","receipt","discount","clerk"],"correct":1,"explanation":"Receipt = recibo (the p is silent).","translations":{"es":{"question":"El papel que demuestra lo que compraste es el…","explanation":"Receipt = recibo (la p no suena)."}}},{"id":"6","question":"In the US, the price on the tag…","options":["is negotiable","always includes the tip","usually doesn''t include sales tax","is in pesos"],"correct":2,"explanation":"Sales tax is added at the register.","translations":{"es":{"question":"En Estados Unidos, el precio de la etiqueta…","explanation":"El impuesto se suma en la caja."}}},{"id":"7","question":"A clerk asks \"Can I help you?\" You need a gift. You say:","options":["Yes, I look present.","Yes, I''m searching a present.","Yes, I''m looking for a present.","Yes, present for looking."],"correct":2,"explanation":"I''m looking for + thing.","translations":{"es":{"question":"Un vendedor pregunta «Can I help you?». Necesitas un regalo. Dices:","explanation":"I''m looking for + cosa."}}},{"id":"8","question":"\"Too\" vs \"very\": which one means it''s a problem?","options":["very","both","too","neither"],"correct":2,"explanation":"\"Too\" means more than is good.","translations":{"es":{"question":"«Too» vs «very»: ¿cuál indica un problema?","explanation":"«Too» significa más de lo conveniente."}}}]}'::jsonb, 3),
  ('story', 'Presents for Everyone', '{"text":"Before she goes home, Carmen wants to buy presents for her family. Elena takes her to a big store. \"Can I help you?\" asks a clerk. \"Yes, I''m looking for a present for my grandson. He''s eight.\" The clerk shows her a New York Yankees cap. \"Do you have this in a smaller size?\" \"Sure, here''s a kids'' size.\" For Laura, Carmen finds beautiful boots, but they are too expensive. \"Is this scarf on sale?\" \"Yes, thirty percent off.\" \"Perfect. Could you gift-wrap it?\" For Mike, a coffee mug that says I ♥ NY. At the register, the total is higher than she thought. \"Oh! The tax.\" \"Cash or card?\" \"Card, please. I don''t have enough cash.\" The clerk gives her the bag and the receipt. \"Keep the receipt. You can return it within thirty days.\" \"Thank you! But I''m sure they''re going to love everything.\"","translation":"Antes de volver a casa, Carmen quiere comprar regalos para su familia. Elena la lleva a una tienda grande. «¿Le puedo ayudar?», pregunta un vendedor. «Sí, busco un regalo para mi nieto. Tiene ocho años.» El vendedor le enseña una gorra de los Yankees de Nueva York. «¿La tiene en una talla más chica?» «Claro, aquí hay una de niño.» Para Laura, Carmen encuentra unas botas preciosas, pero están demasiado caras. «¿Esta bufanda está en oferta?» «Sí, con treinta por ciento de descuento.» «Perfecto. ¿Me la envuelve para regalo?» Para Mike, una taza que dice I ♥ NY. En la caja, el total es más alto de lo que pensaba. «¡Ah! El impuesto.» «¿Efectivo o tarjeta?» «Con tarjeta, por favor. No traigo suficiente efectivo.» El vendedor le da la bolsa y el recibo. «Guarde el recibo. Puede devolverlo en treinta días.» «¡Gracias! Pero estoy segura de que les va a encantar todo.»","translations":{"es":"Antes de volver a casa, Carmen quiere comprar regalos para su familia. Elena la lleva a una tienda grande. «¿Le puedo ayudar?», pregunta un vendedor. «Sí, busco un regalo para mi nieto. Tiene ocho años.» El vendedor le enseña una gorra de los Yankees de Nueva York. «¿La tiene en una talla más chica?» «Claro, aquí hay una de niño.» Para Laura, Carmen encuentra unas botas preciosas, pero están demasiado caras. «¿Esta bufanda está en oferta?» «Sí, con treinta por ciento de descuento.» «Perfecto. ¿Me la envuelve para regalo?» Para Mike, una taza que dice I ♥ NY. En la caja, el total es más alto de lo que pensaba. «¡Ah! El impuesto.» «¿Efectivo o tarjeta?» «Con tarjeta, por favor. No traigo suficiente efectivo.» El vendedor le da la bolsa y el recibo. «Guarde el recibo. Puede devolverlo en treinta días.» «¡Gracias! Pero estoy segura de que les va a encantar todo.»"},"highlighted_words":["presents","store","clerk","I''m looking for a present","Do you have this in a smaller size","boots","too expensive","on sale","Could you gift-wrap it","register","tax","Cash or card","I don''t have enough cash","receipt","return"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","am","looking","for","a","present"],"translation":"Busco un regalo.","translations":{"es":"Busco un regalo."}},{"words":["These","boots","are","too","expensive"],"translation":"Estas botas están demasiado caras.","translations":{"es":"Estas botas están demasiado caras."}},{"words":["Do","you","have","this","in","black"],"translation":"¿Lo tiene en negro?","translations":{"es":"¿Lo tiene en negro?"}},{"words":["I","do","not","have","enough","cash"],"translation":"No traigo suficiente efectivo.","translations":{"es":"No traigo suficiente efectivo."}},{"words":["This","coat","is","not","warm","enough"],"translation":"Este abrigo no es lo bastante abrigador.","translations":{"es":"Este abrigo no es lo bastante abrigador."}},{"words":["Can","I","return","it","if","it","does","not","fit"],"translation":"¿Lo puedo devolver si no le queda?","translations":{"es":"¿Lo puedo devolver si no le queda?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Está demasiado caro","translations":{"es":"Está demasiado caro"},"answer":"It is too expensive"},{"prompt":"¿Esto está en oferta?","translations":{"es":"¿Esto está en oferta?"},"answer":"Is this on sale"},{"prompt":"Con tarjeta, por favor","translations":{"es":"Con tarjeta, por favor"},"answer":"Card, please"},{"prompt":"Busco un regalo","translations":{"es":"Busco un regalo"},"answer":"I am looking for a present"},{"prompt":"¿Me da una bolsa?","translations":{"es":"¿Me da una bolsa?"},"answer":"Can I have a bag"},{"prompt":"Aquí está su recibo","translations":{"es":"Aquí está su recibo"},"answer":"Here is your receipt"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 40: A night out
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-40', 'A night out', '🪩', 'Una salida de noche', 40, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"night out","translation":"salida de noche","translations":{"es":"salida de noche"}},{"id":"2","word":"musical","translation":"musical","translations":{"es":"musical"}},{"id":"3","word":"show","translation":"espectáculo","translations":{"es":"espectáculo"}},{"id":"4","word":"club","translation":"club / antro","translations":{"es":"club / antro"}},{"id":"5","word":"bar","translation":"bar","translations":{"es":"bar"}},{"id":"6","word":"lights","translation":"luces","translations":{"es":"luces"}},{"id":"7","word":"crowd","translation":"multitud","translations":{"es":"multitud"}},{"id":"8","word":"invite","translation":"invitar","translations":{"es":"invitar"}},{"id":"9","word":"invitation","translation":"invitación","translations":{"es":"invitación"}},{"id":"10","word":"accept","translation":"aceptar","translations":{"es":"aceptar"}},{"id":"11","word":"suggest","translation":"sugerir","translations":{"es":"sugerir"}},{"id":"12","word":"hang out","translation":"pasar el rato","translations":{"es":"pasar el rato"}},{"id":"13","word":"fun","translation":"divertido / diversión","translations":{"es":"divertido / diversión"}},{"id":"14","word":"exciting","translation":"emocionante","translations":{"es":"emocionante"}},{"id":"15","word":"applause","translation":"aplauso","translations":{"es":"aplauso"}},{"id":"16","word":"midnight","translation":"medianoche","translations":{"es":"medianoche"}},{"id":"17","word":"subway","translation":"metro","translations":{"es":"metro"}}],"grammar":[{"structure":"Why don''t we + verb?","example":"Why don''t we go to a show?","en":"Making suggestions","es":"Hacer sugerencias"},{"structure":"How about + verb-ing / noun?","example":"How about seeing a musical? How about Friday?","en":"Suggestions with \"How about…?\"","es":"Sugerencias con «How about…?» (¿qué tal si…?)"},{"structure":"That sounds great! / I''d love to.","example":"A musical? That sounds great!","en":"Accepting invitations","es":"Aceptar invitaciones"},{"structure":"I''d love to, but…","example":"I''d love to, but I''m busy that night.","en":"Refusing politely","es":"Rechazar con amabilidad"},{"structure":"Shall we…?","example":"Shall we meet at seven?","en":"Arranging details (a little formal)","es":"Acordar detalles (un poco formal)"}],"tips":[{"en":"\"I''d love to, but…\" is the kindest way to say no to an invitation.","es":"«I''d love to, but…» es la forma más amable de rechazar una invitación."},{"en":"\"How about\" is followed by -ing or a noun: How about going…? How about Saturday?","es":"«How about» va seguido de -ing o de un sustantivo: How about going…? How about Saturday?"},{"en":"Broadway shows often sell cheaper same-day tickets at the TKTS booth in Times Square.","es":"Los espectáculos de Broadway suelen vender boletos más baratos para el mismo día en la taquilla TKTS de Times Square."},{"en":"\"Hang out\" means to spend relaxed time with friends.","es":"«Hang out» significa pasar el rato con amigos."},{"en":"In the US, many bars require you to show ID, even if you look older than 21.","es":"En Estados Unidos, muchos bares te piden identificación aunque parezcas mayor de 21."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Why don''t we go out tonight?","translation":"¿Por qué no salimos esta noche?","translations":{"es":"¿Por qué no salimos esta noche?"}},{"phrase":"How about a Broadway show?","translation":"¿Qué tal un espectáculo de Broadway?","translations":{"es":"¿Qué tal un espectáculo de Broadway?"}},{"phrase":"That sounds great!","translation":"¡Suena genial!","translations":{"es":"¡Suena genial!"}},{"phrase":"I''d love to!","translation":"¡Me encantaría!","translations":{"es":"¡Me encantaría!"}},{"phrase":"I''d love to, but I''m tired.","translation":"Me encantaría, pero estoy cansada.","translations":{"es":"Me encantaría, pero estoy cansada."}},{"phrase":"Shall we meet at seven?","translation":"¿Nos vemos a las siete?","translations":{"es":"¿Nos vemos a las siete?"}},{"phrase":"Let''s take the subway.","translation":"Vamos en metro.","translations":{"es":"Vamos en metro."}},{"phrase":"What a fun night!","translation":"¡Qué noche tan divertida!","translations":{"es":"¡Qué noche tan divertida!"}},{"phrase":"The show was exciting.","translation":"El espectáculo fue emocionante.","translations":{"es":"El espectáculo fue emocionante."}},{"phrase":"Do you want to hang out on Saturday?","translation":"¿Quieres salir el sábado?","translations":{"es":"¿Quieres salir el sábado?"}},{"phrase":"Maybe next time.","translation":"Quizás la próxima vez.","translations":{"es":"Quizás la próxima vez."}},{"phrase":"Thanks for inviting me!","translation":"¡Gracias por invitarme!","translations":{"es":"¡Gracias por invitarme!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"How about ___ to a concert?\"","options":["to go","go","goes","going"],"correct":3,"explanation":"How about + verb-ing.","translations":{"es":{"question":"Completa: «How about ___ to a concert?»","explanation":"How about + verbo-ing."}}},{"id":"2","question":"Choose the correct suggestion.","options":["Why not we eat out?","Why don''t eat we out?","Why we don''t eat out?","Why don''t we eat out?"],"correct":3,"explanation":"Why don''t we + verb?","translations":{"es":{"question":"Elige la sugerencia correcta.","explanation":"Why don''t we + verbo?"}}},{"id":"3","question":"You can''t go, but you want to be polite. You say:","options":["That sounds great!","I don''t want.","No.","I''d love to, but I''m busy."],"correct":3,"explanation":"\"I''d love to, but…\" refuses politely.","translations":{"es":{"question":"No puedes ir, pero quieres ser amable. Dices:","explanation":"«I''d love to, but…» rechaza con amabilidad."}}},{"id":"4","question":"Someone suggests a musical and you like the idea. You say:","options":["Shall we not?","Maybe next time.","That sounds tired.","That sounds great!"],"correct":3,"explanation":"\"That sounds great!\" accepts with enthusiasm.","translations":{"es":{"question":"Alguien propone un musical y te gusta la idea. Dices:","explanation":"«That sounds great!» acepta con entusiasmo."}}},{"id":"5","question":"\"Hang out\" means…","options":["go to work","leave quickly","hang clothes outside","spend relaxed time together"],"correct":3,"explanation":"Hang out = pasar el rato.","translations":{"es":{"question":"«Hang out» significa…","explanation":"Hang out = pasar el rato."}}},{"id":"6","question":"In New York, the underground train is the…","options":["bus stop","trolley","highway","subway"],"correct":3,"explanation":"Subway = metro.","translations":{"es":{"question":"En Nueva York, el tren subterráneo es el…","explanation":"Subway = metro."}}},{"id":"7","question":"Complete: \"___ we meet at the theater at seven?\"","options":["Will to","Do","Are","Shall"],"correct":3,"explanation":"\"Shall we…?\" suggests or arranges.","translations":{"es":{"question":"Completa: «___ we meet at the theater at seven?»","explanation":"«Shall we…?» propone o acuerda."}}},{"id":"8","question":"After a party, you thank the host. You say:","options":["Thanks for invite me!","Thanks to inviting!","Thank you invited me!","Thanks for inviting me!"],"correct":3,"explanation":"Thanks for + verb-ing.","translations":{"es":{"question":"Después de una fiesta, le das las gracias al anfitrión. Dices:","explanation":"Thanks for + verbo-ing."}}}]}'::jsonb, 3),
  ('story', 'Broadway!', '{"text":"It''s Carmen''s last night in New York. David has an idea. \"Why don''t we go out tonight? How about a Broadway show?\" \"That sounds great!\" says Carmen. Elena laughs. \"I''d love to, but I''m too old for late nights.\" \"Mom, you''re coming!\" says David. They buy cheap tickets for a musical in Times Square. \"Shall we take the subway?\" asks David. \"Yes, let''s take the subway. It''s an adventure!\" Times Square is full of lights and crowds. The musical is exciting: the songs, the dancers, the colors. At the end, there is a long applause and Carmen stands up and claps with everybody. They have hot chocolate before midnight. \"Thanks for inviting me,\" Carmen tells David. \"What a fun night! I want to come back next year.\" Elena smiles. \"Next time, I''m going to San Diego. Why don''t we see the ocean together?\"","translation":"Es la última noche de Carmen en Nueva York. David tiene una idea. «¿Por qué no salimos esta noche? ¿Qué tal un espectáculo de Broadway?» «¡Suena genial!», dice Carmen. Elena se ríe. «Me encantaría, pero ya estoy muy grande para desvelarme.» «¡Mamá, vas a venir!», dice David. Compran boletos baratos para un musical en Times Square. «¿Nos vamos en metro?», pregunta David. «Sí, vamos en metro. ¡Es una aventura!» Times Square está lleno de luces y de gente. El musical es emocionante: las canciones, los bailarines, los colores. Al final hay un largo aplauso y Carmen se pone de pie y aplaude con todos. Toman chocolate caliente antes de medianoche. «Gracias por invitarme», le dice Carmen a David. «¡Qué noche tan divertida! Quiero volver el próximo año.» Elena sonríe. «La próxima vez yo voy a San Diego. ¿Por qué no vemos el mar juntas?»","translations":{"es":"Es la última noche de Carmen en Nueva York. David tiene una idea. «¿Por qué no salimos esta noche? ¿Qué tal un espectáculo de Broadway?» «¡Suena genial!», dice Carmen. Elena se ríe. «Me encantaría, pero ya estoy muy grande para desvelarme.» «¡Mamá, vas a venir!», dice David. Compran boletos baratos para un musical en Times Square. «¿Nos vamos en metro?», pregunta David. «Sí, vamos en metro. ¡Es una aventura!» Times Square está lleno de luces y de gente. El musical es emocionante: las canciones, los bailarines, los colores. Al final hay un largo aplauso y Carmen se pone de pie y aplaude con todos. Toman chocolate caliente antes de medianoche. «Gracias por invitarme», le dice Carmen a David. «¡Qué noche tan divertida! Quiero volver el próximo año.» Elena sonríe. «La próxima vez yo voy a San Diego. ¿Por qué no vemos el mar juntas?»"},"highlighted_words":["Why don''t we go out tonight","How about a Broadway show","That sounds great","I''d love to, but","musical","Shall we take the subway","lights","crowds","exciting","applause","midnight","Thanks for inviting me","What a fun night"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Why","don''t","we","go","out","tonight"],"translation":"¿Por qué no salimos esta noche?","translations":{"es":"¿Por qué no salimos esta noche?"}},{"words":["How","about","seeing","a","musical"],"translation":"¿Qué tal si vemos un musical?","translations":{"es":"¿Qué tal si vemos un musical?"}},{"words":["I","would","love","to","but","I","am","busy"],"translation":"Me encantaría, pero estoy ocupada.","translations":{"es":"Me encantaría, pero estoy ocupada."}},{"words":["Shall","we","meet","at","seven"],"translation":"¿Nos vemos a las siete?","translations":{"es":"¿Nos vemos a las siete?"}},{"words":["Thanks","for","inviting","me"],"translation":"Gracias por invitarme.","translations":{"es":"Gracias por invitarme."}},{"words":["The","show","was","very","exciting"],"translation":"El espectáculo fue muy emocionante.","translations":{"es":"El espectáculo fue muy emocionante."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Suena genial","translations":{"es":"Suena genial"},"answer":"That sounds great"},{"prompt":"¿Qué tal el sábado?","translations":{"es":"¿Qué tal el sábado?"},"answer":"How about Saturday"},{"prompt":"Quizás la próxima vez","translations":{"es":"Quizás la próxima vez"},"answer":"Maybe next time"},{"prompt":"Gracias por invitarme","translations":{"es":"Gracias por invitarme"},"answer":"Thanks for inviting me"},{"prompt":"¿Por qué no vamos a la playa?","translations":{"es":"¿Por qué no vamos a la playa?"},"answer":"Why don''t we go to the beach"},{"prompt":"¡Qué noche tan divertida!","translations":{"es":"¡Qué noche tan divertida!"},"answer":"What a fun night"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 41: Finding a place to live
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-41', 'Finding a place to live', '🔑', 'Buscar dónde vivir', 41, true)
