insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"rent","translation":"renta / rentar","translations":{"es":"renta / rentar"}},{"id":"2","word":"landlord","translation":"casero / arrendador","translations":{"es":"casero / arrendador"}},{"id":"3","word":"tenant","translation":"inquilino","translations":{"es":"inquilino"}},{"id":"4","word":"lease","translation":"contrato de renta","translations":{"es":"contrato de renta"}},{"id":"5","word":"security deposit","translation":"depósito de garantía","translations":{"es":"depósito de garantía"}},{"id":"6","word":"utilities","translation":"servicios (agua, luz, gas)","translations":{"es":"servicios (agua, luz, gas)"}},{"id":"7","word":"furnished","translation":"amueblado","translations":{"es":"amueblado"}},{"id":"8","word":"unfurnished","translation":"sin amueblar","translations":{"es":"sin amueblar"}},{"id":"9","word":"studio","translation":"estudio (departamento de un ambiente)","translations":{"es":"estudio (departamento de un ambiente)"}},{"id":"10","word":"neighborhood","translation":"colonia / vecindario","translations":{"es":"colonia / vecindario"}},{"id":"11","word":"parking","translation":"estacionamiento","translations":{"es":"estacionamiento"}},{"id":"12","word":"laundry room","translation":"cuarto de lavado","translations":{"es":"cuarto de lavado"}},{"id":"13","word":"move in","translation":"mudarse (a un lugar)","translations":{"es":"mudarse (a un lugar)"}},{"id":"14","word":"move out","translation":"mudarse (de un lugar)","translations":{"es":"mudarse (de un lugar)"}},{"id":"15","word":"for","translation":"durante (tiempo)","translations":{"es":"durante (tiempo)"}},{"id":"16","word":"since","translation":"desde","translations":{"es":"desde"}},{"id":"17","word":"sign","translation":"firmar","translations":{"es":"firmar"}}],"grammar":[{"structure":"have / has + past participle + for","example":"Ana has lived in that room for two years.","en":"Present perfect with \"for\" (a period of time)","es":"Presente perfecto con «for» (un periodo de tiempo)"},{"structure":"… since + starting point","example":"I''ve lived here since March.","en":"Present perfect with \"since\" (a starting point)","es":"Presente perfecto con «since» (desde un momento)"},{"structure":"How long have you…?","example":"How long have you lived in San Diego?","en":"Asking about duration up to now","es":"Preguntar cuánto tiempo llevas haciendo algo"},{"structure":"Is … included?","example":"Are utilities included in the rent?","en":"Asking about what the price includes","es":"Preguntar qué incluye el precio"},{"structure":"a … -bedroom apartment","example":"a two-bedroom apartment","en":"Describing apartments","es":"Describir departamentos"}],"tips":[{"en":"Spanish uses the present (\"Vivo aquí desde marzo\"), but English uses the present perfect: \"I''ve lived here since March.\"","es":"El español usa el presente («Vivo aquí desde marzo»), pero el inglés usa el presente perfecto: «I''ve lived here since March.»"},{"en":"\"For\" + amount of time (for two years); \"since\" + moment (since 2020, since Monday).","es":"«For» + cantidad de tiempo (for two years); «since» + momento (since 2020, since Monday)."},{"en":"\"Utilities\" are water, electricity and gas. Ask if they''re included in the rent.","es":"Los «utilities» son agua, luz y gas. Pregunta si están incluidos en la renta."},{"en":"A \"lease\" is the rental contract, usually for 12 months. Read it carefully before you sign.","es":"El «lease» es el contrato de renta, normalmente por 12 meses. Léelo con cuidado antes de firmar."},{"en":"The \"security deposit\" is money you get back when you leave, if the apartment is in good condition.","es":"El «security deposit» es el depósito que te devuelven al irte, si el departamento está en buen estado."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"How long have you lived here?","translation":"¿Cuánto tiempo llevas viviendo aquí?","translations":{"es":"¿Cuánto tiempo llevas viviendo aquí?"}},{"phrase":"I''ve lived here for six months.","translation":"Llevo seis meses viviendo aquí.","translations":{"es":"Llevo seis meses viviendo aquí."}},{"phrase":"She has worked there since 2019.","translation":"Trabaja ahí desde 2019.","translations":{"es":"Trabaja ahí desde 2019."}},{"phrase":"I''m looking for a one-bedroom apartment.","translation":"Busco un departamento de una recámara.","translations":{"es":"Busco un departamento de una recámara."}},{"phrase":"How much is the rent?","translation":"¿Cuánto es la renta?","translations":{"es":"¿Cuánto es la renta?"}},{"phrase":"Are utilities included?","translation":"¿Los servicios están incluidos?","translations":{"es":"¿Los servicios están incluidos?"}},{"phrase":"Is it furnished?","translation":"¿Está amueblado?","translations":{"es":"¿Está amueblado?"}},{"phrase":"Is there parking?","translation":"¿Hay estacionamiento?","translations":{"es":"¿Hay estacionamiento?"}},{"phrase":"When can I move in?","translation":"¿Cuándo me puedo mudar?","translations":{"es":"¿Cuándo me puedo mudar?"}},{"phrase":"How much is the security deposit?","translation":"¿De cuánto es el depósito?","translations":{"es":"¿De cuánto es el depósito?"}},{"phrase":"Can I see the apartment?","translation":"¿Puedo ver el departamento?","translations":{"es":"¿Puedo ver el departamento?"}},{"phrase":"I''d like to read the lease first.","translation":"Quisiera leer el contrato primero.","translations":{"es":"Quisiera leer el contrato primero."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say \"Vivo aquí desde marzo\"?","options":["I''ve lived here since March.","I''ve lived here for March.","I''m living here from March.","I live here since March."],"correct":0,"explanation":"From a past moment until now → present perfect + since.","translations":{"es":{"question":"¿Cómo se dice «Vivo aquí desde marzo»?","explanation":"Desde un momento pasado hasta ahora → presente perfecto + since."}}},{"id":"2","question":"Complete: \"She has worked there ___ ten years.\"","options":["from","for","during since","since"],"correct":1,"explanation":"Amount of time → for.","translations":{"es":{"question":"Completa: «She has worked there ___ ten years.»","explanation":"Cantidad de tiempo → for."}}},{"id":"3","question":"Complete: \"We''ve been friends ___ 2015.\"","options":["since","ago","by","for"],"correct":0,"explanation":"Starting point → since.","translations":{"es":{"question":"Completa: «We''ve been friends ___ 2015.»","explanation":"Punto de inicio → since."}}},{"id":"4","question":"Choose the correct question.","options":["How long have you lived here?","How much time you live here?","How long you have lived here?","How long do you live here?"],"correct":0,"explanation":"How long + have you + past participle?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"How long + have you + participio?"}}},{"id":"5","question":"Water, electricity and gas are called…","options":["leases","utilities","deposits","furniture"],"correct":1,"explanation":"Utilities = servicios.","translations":{"es":{"question":"El agua, la luz y el gas se llaman…","explanation":"Utilities = servicios."}}},{"id":"6","question":"The owner of the apartment you rent is the…","options":["lease","landlord","neighbor","tenant"],"correct":1,"explanation":"Landlord = owner; tenant = the person who rents.","translations":{"es":{"question":"El dueño del departamento que rentas es el…","explanation":"Landlord = dueño; tenant = quien renta."}}},{"id":"7","question":"An apartment with a bed, sofa and table already inside is…","options":["furnished","parking","utilities","unfurnished"],"correct":0,"explanation":"Furnished = amueblado.","translations":{"es":{"question":"Un departamento que ya tiene cama, sofá y mesa está…","explanation":"Furnished = amueblado."}}},{"id":"8","question":"Complete: \"I ___ known Linda for a year.\"","options":["did","am","have","has"],"correct":2,"explanation":"I → have + past participle.","translations":{"es":{"question":"Completa: «I ___ known Linda for a year.»","explanation":"I → have + participio."}}}]}'::jsonb, 3),
  ('story', 'Ana Needs a New Place', '{"text":"Back in San Diego, Ana has a problem. \"I''ve lived in a small room for two years,\" she tells Carmen. \"But my landlord is selling the house. I need a new place.\" Carmen has lived in her apartment since March, and she knows the neighborhood well. \"Let''s look together!\" They visit a one-bedroom apartment near the beach. \"How much is the rent?\" asks Ana. \"Eighteen hundred a month,\" says the landlord. \"Are utilities included?\" \"No, they aren''t. And the security deposit is one month''s rent.\" Ana looks worried. The next apartment is a studio, furnished, with parking and a laundry room. The rent is lower and utilities are included. \"Can I see the lease?\" asks Carmen. She reads every line. \"It looks good, Ana.\" Ana smiles. \"I''ve waited for this for a long time. When can I move in?\"","translation":"De vuelta en San Diego, Ana tiene un problema. «Llevo dos años viviendo en un cuarto pequeño», le cuenta a Carmen. «Pero el casero va a vender la casa. Necesito un lugar nuevo.» Carmen vive en su departamento desde marzo y conoce bien el barrio. «¡Busquemos juntas!» Visitan un departamento de una recámara cerca de la playa. «¿Cuánto es la renta?», pregunta Ana. «Mil ochocientos al mes», dice el casero. «¿Los servicios están incluidos?» «No. Y el depósito es de un mes de renta.» Ana se ve preocupada. El siguiente departamento es un estudio amueblado, con estacionamiento y cuarto de lavado. La renta es más baja y los servicios están incluidos. «¿Puedo ver el contrato?», pregunta Carmen. Lee cada línea. «Se ve bien, Ana.» Ana sonríe. «Llevo mucho tiempo esperando esto. ¿Cuándo me puedo mudar?»","translations":{"es":"De vuelta en San Diego, Ana tiene un problema. «Llevo dos años viviendo en un cuarto pequeño», le cuenta a Carmen. «Pero el casero va a vender la casa. Necesito un lugar nuevo.» Carmen vive en su departamento desde marzo y conoce bien el barrio. «¡Busquemos juntas!» Visitan un departamento de una recámara cerca de la playa. «¿Cuánto es la renta?», pregunta Ana. «Mil ochocientos al mes», dice el casero. «¿Los servicios están incluidos?» «No. Y el depósito es de un mes de renta.» Ana se ve preocupada. El siguiente departamento es un estudio amueblado, con estacionamiento y cuarto de lavado. La renta es más baja y los servicios están incluidos. «¿Puedo ver el contrato?», pregunta Carmen. Lee cada línea. «Se ve bien, Ana.» Ana sonríe. «Llevo mucho tiempo esperando esto. ¿Cuándo me puedo mudar?»"},"highlighted_words":["I''ve lived in a small room for two years","landlord","has lived in her apartment since March","neighborhood","How much is the rent","Are utilities included","security deposit","studio","furnished","parking","laundry room","lease","When can I move in"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["How","long","have","you","lived","here"],"translation":"¿Cuánto tiempo llevas viviendo aquí?","translations":{"es":"¿Cuánto tiempo llevas viviendo aquí?"}},{"words":["I","have","lived","here","since","March"],"translation":"Vivo aquí desde marzo.","translations":{"es":"Vivo aquí desde marzo."}},{"words":["She","has","worked","there","for","ten","years"],"translation":"Lleva diez años trabajando ahí.","translations":{"es":"Lleva diez años trabajando ahí."}},{"words":["Are","utilities","included","in","the","rent"],"translation":"¿Los servicios están incluidos en la renta?","translations":{"es":"¿Los servicios están incluidos en la renta?"}},{"words":["I","am","looking","for","a","furnished","apartment"],"translation":"Busco un departamento amueblado.","translations":{"es":"Busco un departamento amueblado."}},{"words":["When","can","I","move","in"],"translation":"¿Cuándo me puedo mudar?","translations":{"es":"¿Cuándo me puedo mudar?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Llevo dos años viviendo aquí","translations":{"es":"Llevo dos años viviendo aquí"},"answer":"I have lived here for two years"},{"prompt":"¿Cuánto es la renta?","translations":{"es":"¿Cuánto es la renta?"},"answer":"How much is the rent"},{"prompt":"¿Está amueblado?","translations":{"es":"¿Está amueblado?"},"answer":"Is it furnished"},{"prompt":"Me conoce desde 2020","translations":{"es":"Me conoce desde 2020"},"answer":"She has known me since 2020"},{"prompt":"¿Puedo ver el departamento?","translations":{"es":"¿Puedo ver el departamento?"},"answer":"Can I see the apartment"},{"prompt":"¿Hay estacionamiento?","translations":{"es":"¿Hay estacionamiento?"},"answer":"Is there parking"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 42: At the laundromat
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-42', 'At the laundromat', '🧺', 'En la lavandería', 42, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"laundromat","translation":"lavandería (de autoservicio)","translations":{"es":"lavandería (de autoservicio)"}},{"id":"2","word":"laundry","translation":"ropa para lavar / lavado","translations":{"es":"ropa para lavar / lavado"}},{"id":"3","word":"washer","translation":"lavadora","translations":{"es":"lavadora"}},{"id":"4","word":"dryer","translation":"secadora","translations":{"es":"secadora"}},{"id":"5","word":"detergent","translation":"detergente","translations":{"es":"detergente"}},{"id":"6","word":"fabric softener","translation":"suavizante","translations":{"es":"suavizante"}},{"id":"7","word":"quarters","translation":"monedas de 25 centavos","translations":{"es":"monedas de 25 centavos"}},{"id":"8","word":"load","translation":"carga (de ropa)","translations":{"es":"carga (de ropa)"}},{"id":"9","word":"fold","translation":"doblar","translations":{"es":"doblar"}},{"id":"10","word":"iron","translation":"planchar / plancha","translations":{"es":"planchar / plancha"}},{"id":"11","word":"stain","translation":"mancha","translations":{"es":"mancha"}},{"id":"12","word":"shrink","translation":"encoger","translations":{"es":"encoger"}},{"id":"13","word":"out of order","translation":"fuera de servicio","translations":{"es":"fuera de servicio"}},{"id":"14","word":"first","translation":"primero","translations":{"es":"primero"}},{"id":"15","word":"then","translation":"luego / después","translations":{"es":"luego / después"}},{"id":"16","word":"after that","translation":"después de eso","translations":{"es":"después de eso"}},{"id":"17","word":"finally","translation":"finalmente","translations":{"es":"finalmente"}}],"grammar":[{"structure":"First, … Then, … After that, … Finally, …","example":"First, sort the clothes. Then, add the soap.","en":"Sequencing words for instructions","es":"Palabras para ordenar instrucciones"},{"structure":"Imperatives for instructions","example":"Put in the coins. Press start.","en":"Giving step-by-step instructions","es":"Dar instrucciones paso a paso"},{"structure":"Phrasal verbs: put in, take out, turn on, fold up","example":"Take out the clothes and fold them up.","en":"Separable phrasal verbs","es":"Verbos frasales separables"},{"structure":"How does this work?","example":"Excuse me, how does this machine work?","en":"Asking how to use something","es":"Preguntar cómo se usa algo"},{"structure":"It doesn''t work / It''s out of order","example":"This dryer is out of order.","en":"Saying something is broken","es":"Decir que algo no funciona"}],"tips":[{"en":"With pronouns, phrasal verbs separate: \"Take them out\" (not \"Take out them\").","es":"Con pronombres, los verbos frasales se separan: «Take them out» (no «Take out them»)."},{"en":"Many laundromats use quarters (25-cent coins) or a card. Bring coins!","es":"Muchas lavanderías usan monedas de 25 centavos (quarters) o una tarjeta. ¡Lleva monedas!"},{"en":"\"Washer\" washes and \"dryer\" dries. Delicate clothes: \"low heat\" or \"air dry\".","es":"La «washer» lava y la «dryer» seca. Para ropa delicada: «low heat» (calor bajo) o «air dry» (secar al aire)."},{"en":"\"Out of order\" on a sign means the machine is broken.","es":"«Out of order» en un letrero significa que la máquina no sirve."},{"en":"Sequencing words make your English sound organized: first, then, after that, finally.","es":"Las palabras de secuencia hacen que tu inglés suene ordenado: first, then, after that, finally."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"My washing machine is broken.","translation":"Mi lavadora se descompuso.","translations":{"es":"Mi lavadora se descompuso."}},{"phrase":"How does this machine work?","translation":"¿Cómo funciona esta máquina?","translations":{"es":"¿Cómo funciona esta máquina?"}},{"phrase":"First, put in the clothes.","translation":"Primero, mete la ropa.","translations":{"es":"Primero, mete la ropa."}},{"phrase":"Then, add the detergent.","translation":"Luego, pon el detergente.","translations":{"es":"Luego, pon el detergente."}},{"phrase":"After that, insert the quarters.","translation":"Después, mete las monedas.","translations":{"es":"Después, mete las monedas."}},{"phrase":"Finally, press start.","translation":"Finalmente, presiona inicio.","translations":{"es":"Finalmente, presiona inicio."}},{"phrase":"Do you have change for a dollar?","translation":"¿Tiene cambio de un dólar?","translations":{"es":"¿Tiene cambio de un dólar?"}},{"phrase":"This dryer is out of order.","translation":"Esta secadora está fuera de servicio.","translations":{"es":"Esta secadora está fuera de servicio."}},{"phrase":"Take them out and fold them.","translation":"Sácalas y dóblalas.","translations":{"es":"Sácalas y dóblalas."}},{"phrase":"Use cold water for colors.","translation":"Usa agua fría para la ropa de color.","translations":{"es":"Usa agua fría para la ropa de color."}},{"phrase":"My sweater shrank!","translation":"¡Se me encogió el suéter!","translations":{"es":"¡Se me encogió el suéter!"}},{"phrase":"How long does it take?","translation":"¿Cuánto tarda?","translations":{"es":"¿Cuánto tarda?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Put the steps in order: which comes first?","options":["First, put in the clothes.","After that, fold them.","Finally, press start.","Then, take them out."],"correct":0,"explanation":"\"First\" starts the sequence.","translations":{"es":{"question":"Ordena los pasos: ¿cuál va primero?","explanation":"«First» inicia la secuencia."}}},{"id":"2","question":"Choose the correct sentence.","options":["Take out them.","Take them out.","Them take out.","Take out it them."],"correct":1,"explanation":"With a pronoun, it goes in the middle: take them out.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"Con pronombre, va en medio: take them out."}}},{"id":"3","question":"The sign says \"OUT OF ORDER\". It means…","options":["The machine is broken.","The machine is free.","The machine is new.","Wait in line."],"correct":0,"explanation":"Out of order = fuera de servicio.","translations":{"es":{"question":"El letrero dice «OUT OF ORDER». Significa…","explanation":"Out of order = fuera de servicio."}}},{"id":"4","question":"The machine that dries clothes is the…","options":["dryer","washer","iron","detergent"],"correct":0,"explanation":"Dryer = secadora.","translations":{"es":{"question":"La máquina que seca la ropa es la…","explanation":"Dryer = secadora."}}},{"id":"5","question":"Your sweater is smaller after washing. It…","options":["folded","shrank","ironed","stained"],"correct":1,"explanation":"Shrink → shrank = encoger.","translations":{"es":{"question":"Tu suéter quedó más chico después de lavarlo. Se…","explanation":"Shrink → shrank = encoger."}}},{"id":"6","question":"You don''t know how to use a machine. You ask:","options":["How this machine works?","How does work this machine?","How does this machine work?","What machine work?"],"correct":2,"explanation":"How does + subject + work?","translations":{"es":{"question":"No sabes usar una máquina. Preguntas:","explanation":"How does + sujeto + work?"}}},{"id":"7","question":"A 25-cent coin in the US is a…","options":["nickel","dime","quarter","penny"],"correct":2,"explanation":"Quarter = 25¢. Dime = 10¢. Nickel = 5¢. Penny = 1¢.","translations":{"es":{"question":"Una moneda de 25 centavos en Estados Unidos es un…","explanation":"Quarter = 25¢. Dime = 10¢. Nickel = 5¢. Penny = 1¢."}}},{"id":"8","question":"Which word shows the last step?","options":["First","Then","Finally","After that"],"correct":2,"explanation":"Finally = al final.","translations":{"es":{"question":"¿Qué palabra indica el último paso?","explanation":"Finally = al final."}}}]}'::jsonb, 3),
  ('story', 'Saturday at the Laundromat', '{"text":"Carmen''s washing machine is broken, so on Saturday she goes to the laundromat with a big bag of laundry. She has never used one before. A young man is folding his clothes. \"Excuse me, how does this washer work?\" \"It''s easy. First, put in your clothes. Then, add the detergent here. After that, put in eight quarters. Finally, choose cold water and press start.\" \"Thank you! Do you have change for a dollar?\" \"Sure.\" Thirty minutes later, Carmen takes out her clothes and goes to a dryer. But there''s a sign: OUT OF ORDER. She uses the next one. When it finishes, she takes everything out and folds it carefully. Then she sees her favorite sweater. It''s very small now. \"Oh no! My sweater shrank!\" The young man laughs. \"Next time, use low heat. Or give it to your grandson!\"","translation":"La lavadora de Carmen se descompuso, así que el sábado va a la lavandería con una bolsa grande de ropa. Nunca ha usado una. Un joven está doblando su ropa. «Disculpa, ¿cómo funciona esta lavadora?» «Es fácil. Primero, mete tu ropa. Luego, pon el detergente aquí. Después, mete ocho monedas de 25. Finalmente, elige agua fría y presiona inicio.» «¡Gracias! ¿Tienes cambio de un dólar?» «Claro.» Treinta minutos después, Carmen saca su ropa y va a una secadora. Pero hay un letrero: FUERA DE SERVICIO. Usa la de al lado. Cuando termina, lo saca todo y lo dobla con cuidado. Entonces ve su suéter favorito. Ahora está muy chico. «¡Ay, no! ¡Se encogió mi suéter!» El joven se ríe. «La próxima vez usa calor bajo. ¡O regálaselo a tu nieto!»","translations":{"es":"La lavadora de Carmen se descompuso, así que el sábado va a la lavandería con una bolsa grande de ropa. Nunca ha usado una. Un joven está doblando su ropa. «Disculpa, ¿cómo funciona esta lavadora?» «Es fácil. Primero, mete tu ropa. Luego, pon el detergente aquí. Después, mete ocho monedas de 25. Finalmente, elige agua fría y presiona inicio.» «¡Gracias! ¿Tienes cambio de un dólar?» «Claro.» Treinta minutos después, Carmen saca su ropa y va a una secadora. Pero hay un letrero: FUERA DE SERVICIO. Usa la de al lado. Cuando termina, lo saca todo y lo dobla con cuidado. Entonces ve su suéter favorito. Ahora está muy chico. «¡Ay, no! ¡Se encogió mi suéter!» El joven se ríe. «La próxima vez usa calor bajo. ¡O regálaselo a tu nieto!»"},"highlighted_words":["laundromat","laundry","folding","how does this washer work","First","Then","detergent","After that","quarters","Finally","change for a dollar","takes out","dryer","OUT OF ORDER","shrank","low heat"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["How","does","this","machine","work"],"translation":"¿Cómo funciona esta máquina?","translations":{"es":"¿Cómo funciona esta máquina?"}},{"words":["First","put","in","the","clothes"],"translation":"Primero, mete la ropa.","translations":{"es":"Primero, mete la ropa."}},{"words":["Then","add","the","detergent"],"translation":"Luego, pon el detergente.","translations":{"es":"Luego, pon el detergente."}},{"words":["This","dryer","is","out","of","order"],"translation":"Esta secadora está fuera de servicio.","translations":{"es":"Esta secadora está fuera de servicio."}},{"words":["Take","them","out","and","fold","them"],"translation":"Sácalas y dóblalas.","translations":{"es":"Sácalas y dóblalas."}},{"words":["Do","you","have","change","for","a","dollar"],"translation":"¿Tienes cambio de un dólar?","translations":{"es":"¿Tienes cambio de un dólar?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Mi lavadora se descompuso","translations":{"es":"Mi lavadora se descompuso"},"answer":"My washing machine is broken"},{"prompt":"Primero, mete la ropa","translations":{"es":"Primero, mete la ropa"},"answer":"First, put in the clothes"},{"prompt":"Finalmente, presiona inicio","translations":{"es":"Finalmente, presiona inicio"},"answer":"Finally, press start"},{"prompt":"Está fuera de servicio","translations":{"es":"Está fuera de servicio"},"answer":"It is out of order"},{"prompt":"Se me encogió el suéter","translations":{"es":"Se me encogió el suéter"},"answer":"My sweater shrank"},{"prompt":"Usa agua fría","translations":{"es":"Usa agua fría"},"answer":"Use cold water"}]}'::jsonb, 6)
) as v(type, title, content, ord);

