insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"class","translation":"clase","translations":{"es":"clase"}},{"id":"2","word":"course","translation":"curso","translations":{"es":"curso"}},{"id":"3","word":"community college","translation":"colegio comunitario","translations":{"es":"colegio comunitario"}},{"id":"4","word":"student","translation":"estudiante","translations":{"es":"estudiante"}},{"id":"5","word":"classmate","translation":"compañero de clase","translations":{"es":"compañero de clase"}},{"id":"6","word":"homework","translation":"tarea","translations":{"es":"tarea"}},{"id":"7","word":"test","translation":"examen","translations":{"es":"examen"}},{"id":"8","word":"grade","translation":"calificación","translations":{"es":"calificación"}},{"id":"9","word":"notebook","translation":"cuaderno","translations":{"es":"cuaderno"}},{"id":"10","word":"laptop","translation":"computadora portátil","translations":{"es":"computadora portátil"}},{"id":"11","word":"sign up","translation":"inscribirse","translations":{"es":"inscribirse"}},{"id":"12","word":"take a class","translation":"tomar una clase","translations":{"es":"tomar una clase"}},{"id":"13","word":"explain","translation":"explicar","translations":{"es":"explicar"}},{"id":"14","word":"learn","translation":"aprender","translations":{"es":"aprender"}},{"id":"15","word":"while","translation":"mientras","translations":{"es":"mientras"}},{"id":"16","word":"email","translation":"correo electrónico","translations":{"es":"correo electrónico"}},{"id":"17","word":"password","translation":"contraseña","translations":{"es":"contraseña"}}],"grammar":[{"structure":"was / were + verb-ing","example":"I was studying when you called.","en":"Past continuous: an action in progress in the past","es":"Pasado continuo: una acción en progreso en el pasado"},{"structure":"… when + past simple","example":"We were talking when the teacher came in.","en":"An action interrupted by another","es":"Una acción interrumpida por otra"},{"structure":"while + past continuous","example":"While I was reading, Leo was playing.","en":"Two actions at the same time","es":"Dos acciones al mismo tiempo"},{"structure":"What were you doing…?","example":"What were you doing at eight last night?","en":"Questions in the past continuous","es":"Preguntas en pasado continuo"},{"structure":"sign up for / take a class","example":"I signed up for a computer class.","en":"Talking about classes","es":"Hablar de clases"}],"tips":[{"en":"The past continuous is like the Spanish \"estaba + -ando/-iendo\": I was cooking = estaba cocinando.","es":"El pasado continuo es como el español «estaba + -ando/-iendo»: I was cooking = estaba cocinando."},{"en":"Community colleges in the US offer cheap or free classes for adults: English, computers, cooking and more.","es":"Los community colleges en Estados Unidos ofrecen clases baratas o gratis para adultos: inglés, computación, cocina y más."},{"en":"\"Take a class\" = tomar una clase. Don''t say \"make a class\".","es":"«Take a class» = tomar una clase. No se dice «make a class»."},{"en":"It''s normal to ask the teacher questions in class: \"Excuse me, could you explain that again?\"","es":"Es normal hacerle preguntas al maestro en clase: «Excuse me, could you explain that again?»"},{"en":"\"Homework\" is uncountable: \"a lot of homework\", not \"homeworks\".","es":"«Homework» es incontable: «a lot of homework», no «homeworks»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I signed up for a computer class.","translation":"Me inscribí en una clase de computación.","translations":{"es":"Me inscribí en una clase de computación."}},{"phrase":"What were you doing last night?","translation":"¿Qué estabas haciendo anoche?","translations":{"es":"¿Qué estabas haciendo anoche?"}},{"phrase":"I was doing my homework.","translation":"Estaba haciendo mi tarea.","translations":{"es":"Estaba haciendo mi tarea."}},{"phrase":"I was sleeping when you called.","translation":"Estaba dormida cuando llamaste.","translations":{"es":"Estaba dormida cuando llamaste."}},{"phrase":"Could you explain that again?","translation":"¿Podría explicarlo otra vez?","translations":{"es":"¿Podría explicarlo otra vez?"}},{"phrase":"Can I borrow your pen?","translation":"¿Me prestas tu pluma?","translations":{"es":"¿Me prestas tu pluma?"}},{"phrase":"We have a test on Friday.","translation":"Tenemos examen el viernes.","translations":{"es":"Tenemos examen el viernes."}},{"phrase":"I passed the test!","translation":"¡Pasé el examen!","translations":{"es":"¡Pasé el examen!"}},{"phrase":"I forgot my password.","translation":"Olvidé mi contraseña.","translations":{"es":"Olvidé mi contraseña."}},{"phrase":"How do I send an email?","translation":"¿Cómo mando un correo?","translations":{"es":"¿Cómo mando un correo?"}},{"phrase":"It''s never too late to learn.","translation":"Nunca es tarde para aprender.","translations":{"es":"Nunca es tarde para aprender."}},{"phrase":"See you next class!","translation":"¡Nos vemos la próxima clase!","translations":{"es":"¡Nos vemos la próxima clase!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"I ___ TV when the phone rang.\"","options":["am watching","watched","were watching","was watching"],"correct":3,"explanation":"Action in progress (was watching) interrupted by another (rang).","translations":{"es":{"question":"Completa: «I ___ TV when the phone rang.»","explanation":"Acción en progreso (was watching) interrumpida por otra (rang)."}}},{"id":"2","question":"Complete: \"They ___ dinner at eight.\"","options":["was having","were have","having","were having"],"correct":3,"explanation":"They → were + verb-ing.","translations":{"es":{"question":"Completa: «They ___ dinner at eight.»","explanation":"They → were + verbo-ing."}}},{"id":"3","question":"Choose the correct question.","options":["What was you doing?","What you were doing?","What did you doing?","What were you doing?"],"correct":3,"explanation":"What + were + you + verb-ing?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"What + were + you + verbo-ing?"}}},{"id":"4","question":"\"While I was cooking, Leo was playing\" means…","options":["I cooked after Leo played.","Leo played after I cooked.","Nobody did anything.","Both actions happened at the same time."],"correct":3,"explanation":"While = at the same time.","translations":{"es":{"question":"«While I was cooking, Leo was playing» significa…","explanation":"While = al mismo tiempo."}}},{"id":"5","question":"How do you say \"tomar una clase\"?","options":["make a class","drink a class","do a class","take a class"],"correct":3,"explanation":"Take a class.","translations":{"es":{"question":"¿Cómo se dice «tomar una clase»?","explanation":"Take a class."}}},{"id":"6","question":"Choose the correct sentence.","options":["I have a lot of homeworks.","I have many homeworks.","I have a homework lots.","I have a lot of homework."],"correct":3,"explanation":"Homework is uncountable.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"Homework es incontable."}}},{"id":"7","question":"A person in your class is your…","options":["teammate","roommate","landlord","classmate"],"correct":3,"explanation":"Classmate = compañero de clase.","translations":{"es":{"question":"Una persona de tu clase es tu…","explanation":"Classmate = compañero de clase."}}},{"id":"8","question":"Complete: \"She was sleeping ___ the alarm went off.\"","options":["during","for","while","when"],"correct":3,"explanation":"Interruption → when + past simple.","translations":{"es":{"question":"Completa: «She was sleeping ___ the alarm went off.»","explanation":"Interrupción → when + pasado simple."}}}]}'::jsonb, 3),
  ('story', 'Never Too Late', '{"text":"Carmen wants to send emails and video calls to her sisters by herself, so she signs up for a computer class at the community college. On the first day, the teacher, Ms. Lee, asks everybody to create an email account. Carmen was typing her password when the screen went black. \"Oh no! What happened?\" Her classmate, an old man named Walter, laughs. \"You pressed the power button.\" While Ms. Lee was explaining how to restart, Carmen was writing everything in her notebook. At home, Laura calls. \"Mom, what were you doing? I called three times!\" \"I was doing my homework! I was sending my first email!\" On Friday, Carmen sends a photo to her sister Rosa. Rosa answers in five minutes: \"Carmen, you''re a computer expert now!\" Carmen smiles at the screen. It''s never too late to learn.","translation":"Carmen quiere mandar correos y hacer videollamadas a sus hermanas ella sola, así que se inscribe en una clase de computación en el colegio comunitario. El primer día, la maestra, la señora Lee, les pide a todos crear una cuenta de correo. Carmen estaba escribiendo su contraseña cuando la pantalla se puso negra. «¡Ay, no! ¿Qué pasó?» Su compañero de clase, un señor mayor llamado Walter, se ríe. «Apretaste el botón de apagado.» Mientras la señora Lee explicaba cómo reiniciar, Carmen anotaba todo en su cuaderno. En casa, llama Laura. «Mamá, ¿qué estabas haciendo? ¡Te llamé tres veces!» «¡Estaba haciendo mi tarea! ¡Estaba mandando mi primer correo!» El viernes, Carmen le manda una foto a su hermana Rosa. Rosa le contesta en cinco minutos: «¡Carmen, ahora eres experta en computadoras!» Carmen le sonríe a la pantalla. Nunca es tarde para aprender.","translations":{"es":"Carmen quiere mandar correos y hacer videollamadas a sus hermanas ella sola, así que se inscribe en una clase de computación en el colegio comunitario. El primer día, la maestra, la señora Lee, les pide a todos crear una cuenta de correo. Carmen estaba escribiendo su contraseña cuando la pantalla se puso negra. «¡Ay, no! ¿Qué pasó?» Su compañero de clase, un señor mayor llamado Walter, se ríe. «Apretaste el botón de apagado.» Mientras la señora Lee explicaba cómo reiniciar, Carmen anotaba todo en su cuaderno. En casa, llama Laura. «Mamá, ¿qué estabas haciendo? ¡Te llamé tres veces!» «¡Estaba haciendo mi tarea! ¡Estaba mandando mi primer correo!» El viernes, Carmen le manda una foto a su hermana Rosa. Rosa le contesta en cinco minutos: «¡Carmen, ahora eres experta en computadoras!» Carmen le sonríe a la pantalla. Nunca es tarde para aprender."},"highlighted_words":["signs up for a computer class","community college","email","was typing her password when","classmate","While Ms. Lee was explaining","was writing","notebook","what were you doing","I was doing my homework","never too late to learn"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","was","cooking","when","you","called"],"translation":"Estaba cocinando cuando llamaste.","translations":{"es":"Estaba cocinando cuando llamaste."}},{"words":["What","were","you","doing","last","night"],"translation":"¿Qué estabas haciendo anoche?","translations":{"es":"¿Qué estabas haciendo anoche?"}},{"words":["I","signed","up","for","a","computer","class"],"translation":"Me inscribí en una clase de computación.","translations":{"es":"Me inscribí en una clase de computación."}},{"words":["While","I","was","reading","Leo","was","playing"],"translation":"Mientras yo leía, Leo jugaba.","translations":{"es":"Mientras yo leía, Leo jugaba."}},{"words":["Could","you","explain","that","again"],"translation":"¿Podría explicarlo otra vez?","translations":{"es":"¿Podría explicarlo otra vez?"}},{"words":["It","is","never","too","late","to","learn"],"translation":"Nunca es tarde para aprender.","translations":{"es":"Nunca es tarde para aprender."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Estaba haciendo mi tarea","translations":{"es":"Estaba haciendo mi tarea"},"answer":"I was doing my homework"},{"prompt":"¿Qué estabas haciendo?","translations":{"es":"¿Qué estabas haciendo?"},"answer":"What were you doing"},{"prompt":"Olvidé mi contraseña","translations":{"es":"Olvidé mi contraseña"},"answer":"I forgot my password"},{"prompt":"Tenemos examen el viernes","translations":{"es":"Tenemos examen el viernes"},"answer":"We have a test on Friday"},{"prompt":"Ella estaba dormida cuando llegué","translations":{"es":"Ella estaba dormida cuando llegué"},"answer":"She was sleeping when I arrived"},{"prompt":"Pasé el examen","translations":{"es":"Pasé el examen"},"answer":"I passed the test"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 44: The roommate
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-44', 'The roommate', '🛏️', 'La compañera de casa', 44, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"roommate","translation":"compañero/a de casa","translations":{"es":"compañero/a de casa"}},{"id":"2","word":"share","translation":"compartir","translations":{"es":"compartir"}},{"id":"3","word":"mine","translation":"mío / mía","translations":{"es":"mío / mía"}},{"id":"4","word":"yours","translation":"tuyo / suyo","translations":{"es":"tuyo / suyo"}},{"id":"5","word":"his","translation":"suyo (de él)","translations":{"es":"suyo (de él)"}},{"id":"6","word":"hers","translation":"suyo (de ella)","translations":{"es":"suyo (de ella)"}},{"id":"7","word":"ours","translation":"nuestro","translations":{"es":"nuestro"}},{"id":"8","word":"theirs","translation":"suyo (de ellos)","translations":{"es":"suyo (de ellos)"}},{"id":"9","word":"whose","translation":"de quién","translations":{"es":"de quién"}},{"id":"10","word":"chores","translation":"quehaceres","translations":{"es":"quehaceres"}},{"id":"11","word":"dishes","translation":"platos / trastes","translations":{"es":"platos / trastes"}},{"id":"12","word":"trash","translation":"basura","translations":{"es":"basura"}},{"id":"13","word":"messy","translation":"desordenado","translations":{"es":"desordenado"}},{"id":"14","word":"tidy","translation":"ordenado","translations":{"es":"ordenado"}},{"id":"15","word":"noise","translation":"ruido","translations":{"es":"ruido"}},{"id":"16","word":"rules","translation":"reglas","translations":{"es":"reglas"}},{"id":"17","word":"split","translation":"dividir (gastos)","translations":{"es":"dividir (gastos)"}}],"grammar":[{"structure":"mine, yours, his, hers, ours, theirs","example":"This cup is mine. That one is yours.","en":"Possessive pronouns","es":"Pronombres posesivos"},{"structure":"my book → mine","example":"Is this your towel? — No, it''s hers.","en":"Possessive pronoun replaces adjective + noun","es":"El pronombre posesivo reemplaza al adjetivo + sustantivo"},{"structure":"Whose…?","example":"Whose shoes are these?","en":"Asking who something belongs to","es":"Preguntar de quién es algo"},{"structure":"share","example":"We share the kitchen and the bathroom.","en":"Talking about shared spaces","es":"Hablar de espacios compartidos"},{"structure":"Would you mind not + verb-ing?","example":"Would you mind not playing music so late?","en":"Asking someone politely to stop","es":"Pedir con amabilidad que alguien deje de hacer algo"}],"tips":[{"en":"Possessive pronouns never have \"the\" or a noun after them: \"It''s mine\", not \"It''s the mine\".","es":"Los pronombres posesivos nunca llevan «the» ni sustantivo después: «It''s mine», no «It''s the mine»."},{"en":"\"Whose\" (de quién) sounds the same as \"who''s\" (who is). Context helps.","es":"«Whose» (de quién) suena igual que «who''s» (who is). El contexto ayuda."},{"en":"\"Roommate\" means someone you share a home with (not just a room) in American English.","es":"En inglés estadounidense, «roommate» es alguien con quien compartes casa (no solo cuarto)."},{"en":"House rules make living together easier: cleaning days, quiet hours, guests.","es":"Las reglas de la casa facilitan la convivencia: días de limpieza, horas de silencio, visitas."},{"en":"A polite complaint starts softly: \"I hope you don''t mind, but…\"","es":"Una queja amable empieza con suavidad: «I hope you don''t mind, but…» (espero que no te moleste, pero…)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Is this yours?","translation":"¿Esto es tuyo?","translations":{"es":"¿Esto es tuyo?"}},{"phrase":"No, it''s hers.","translation":"No, es de ella.","translations":{"es":"No, es de ella."}},{"phrase":"Whose cup is this?","translation":"¿De quién es esta taza?","translations":{"es":"¿De quién es esta taza?"}},{"phrase":"That shelf is mine.","translation":"Esa repisa es mía.","translations":{"es":"Esa repisa es mía."}},{"phrase":"We share the kitchen.","translation":"Compartimos la cocina.","translations":{"es":"Compartimos la cocina."}},{"phrase":"Let''s split the bills.","translation":"Dividamos las cuentas.","translations":{"es":"Dividamos las cuentas."}},{"phrase":"Whose turn is it to take out the trash?","translation":"¿A quién le toca sacar la basura?","translations":{"es":"¿A quién le toca sacar la basura?"}},{"phrase":"It''s your turn to do the dishes.","translation":"Te toca lavar los trastes.","translations":{"es":"Te toca lavar los trastes."}},{"phrase":"Would you mind not playing music so late?","translation":"¿Te importaría no poner música tan tarde?","translations":{"es":"¿Te importaría no poner música tan tarde?"}},{"phrase":"Sorry, I didn''t know.","translation":"Perdón, no sabía.","translations":{"es":"Perdón, no sabía."}},{"phrase":"Let''s make some house rules.","translation":"Pongamos unas reglas de la casa.","translations":{"es":"Pongamos unas reglas de la casa."}},{"phrase":"No problem, I''ll keep it down.","translation":"No hay problema, le bajo.","translations":{"es":"No hay problema, le bajo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"This phone isn''t mine. It''s ___.\" (Ana''s)","options":["hers","her","her''s","she"],"correct":0,"explanation":"Ana''s phone → hers.","translations":{"es":{"question":"Completa: «This phone isn''t mine. It''s ___.» (de Ana)","explanation":"El teléfono de Ana → hers."}}},{"id":"2","question":"Complete: \"Is this book ___?\" (you)","options":["your","your''s","yours","you"],"correct":2,"explanation":"Possessive pronoun: yours (no apostrophe).","translations":{"es":{"question":"Completa: «Is this book ___?» (tú)","explanation":"Pronombre posesivo: yours (sin apóstrofo)."}}},{"id":"3","question":"How do you ask who something belongs to?","options":["Whom bag is this?","Who bag is this?","Whose bag is this?","Who''s bag this is?"],"correct":2,"explanation":"Whose + noun?","translations":{"es":{"question":"¿Cómo preguntas de quién es algo?","explanation":"Whose + sustantivo?"}}},{"id":"4","question":"Choose the correct sentence.","options":["The red towel is mines.","The red towel is the mine.","The red towel is mine.","The red towel is my."],"correct":2,"explanation":"Mine, without \"the\" or -s.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"Mine, sin «the» ni -s."}}},{"id":"5","question":"Housework like washing dishes and taking out the trash is called…","options":["rules","noise","chores","bills"],"correct":2,"explanation":"Chores = quehaceres.","translations":{"es":{"question":"Las tareas de la casa como lavar trastes y sacar la basura se llaman…","explanation":"Chores = quehaceres."}}},{"id":"6","question":"Your roommate plays loud music at midnight. You ask politely:","options":["Music is mine.","Would you mind not playing music so late?","Stop the music!","You are noise."],"correct":1,"explanation":"Would you mind not + verb-ing? is polite.","translations":{"es":{"question":"Tu compañera pone música fuerte a medianoche. Le pides con amabilidad:","explanation":"Would you mind not + verbo-ing? es amable."}}},{"id":"7","question":"Complete: \"This house isn''t theirs. It''s ___.\" (you and me)","options":["ours","we","our","us"],"correct":0,"explanation":"We → ours.","translations":{"es":{"question":"Completa: «This house isn''t theirs. It''s ___.» (tú y yo)","explanation":"We → ours."}}},{"id":"8","question":"\"Let''s split the bills\" means…","options":["Let''s hide the bills.","Let''s pay half each.","Let''s not pay.","Let''s tear the bills."],"correct":1,"explanation":"Split = divide between people.","translations":{"es":{"question":"«Let''s split the bills» significa…","explanation":"Split = dividir entre personas."}}}]}'::jsonb, 3),
  ('story', 'Whose Turn Is It?', '{"text":"Ana loves her new studio, but the rent is high. So she decides to share it with a roommate: Sofía, a nursing student from Colombia. The first week is wonderful. They cook together and split the bills. But in the second week, problems begin. \"Sofía, whose dishes are these?\" \"Oh, they''re mine. Sorry!\" \"And whose turn is it to take out the trash?\" \"Yours, I think…\" \"No, it''s yours!\" At night, Sofía studies with music. Ana can''t sleep. She asks Carmen for advice. \"Talk to her kindly,\" says Carmen. \"And make some house rules together.\" That evening Ana says, \"Sofía, I hope you don''t mind, but would you mind not playing music after ten?\" \"Of course! Sorry, I didn''t know.\" They write the rules on a paper on the fridge. At the bottom, Sofía writes: \"Rule number 10: the chocolate in the fridge is ours.\"","translation":"A Ana le encanta su nuevo estudio, pero la renta es alta. Así que decide compartirlo con una compañera: Sofía, una estudiante de enfermería de Colombia. La primera semana es maravillosa. Cocinan juntas y dividen las cuentas. Pero la segunda semana empiezan los problemas. «Sofía, ¿de quién son estos trastes?» «Ay, son míos. ¡Perdón!» «¿Y a quién le toca sacar la basura?» «A ti, creo…» «¡No, te toca a ti!» En la noche, Sofía estudia con música. Ana no puede dormir. Le pide consejo a Carmen. «Háblale con amabilidad», dice Carmen. «Y pongan unas reglas de la casa juntas.» Esa tarde Ana dice: «Sofía, espero que no te moleste, pero ¿te importaría no poner música después de las diez?» «¡Claro! Perdón, no sabía.» Escriben las reglas en un papel en el refrigerador. Al final, Sofía escribe: «Regla número 10: el chocolate del refri es nuestro.»","translations":{"es":"A Ana le encanta su nuevo estudio, pero la renta es alta. Así que decide compartirlo con una compañera: Sofía, una estudiante de enfermería de Colombia. La primera semana es maravillosa. Cocinan juntas y dividen las cuentas. Pero la segunda semana empiezan los problemas. «Sofía, ¿de quién son estos trastes?» «Ay, son míos. ¡Perdón!» «¿Y a quién le toca sacar la basura?» «A ti, creo…» «¡No, te toca a ti!» En la noche, Sofía estudia con música. Ana no puede dormir. Le pide consejo a Carmen. «Háblale con amabilidad», dice Carmen. «Y pongan unas reglas de la casa juntas.» Esa tarde Ana dice: «Sofía, espero que no te moleste, pero ¿te importaría no poner música después de las diez?» «¡Claro! Perdón, no sabía.» Escriben las reglas en un papel en el refrigerador. Al final, Sofía escribe: «Regla número 10: el chocolate del refri es nuestro.»"},"highlighted_words":["share","roommate","split the bills","whose dishes are these","they''re mine","whose turn is it to take out the trash","Yours","it''s yours","house rules","would you mind not playing music","Sorry, I didn''t know","ours"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Whose","cup","is","this"],"translation":"¿De quién es esta taza?","translations":{"es":"¿De quién es esta taza?"}},{"words":["This","shelf","is","mine","and","that","one","is","yours"],"translation":"Esta repisa es mía y esa es tuya.","translations":{"es":"Esta repisa es mía y esa es tuya."}},{"words":["We","share","the","kitchen","and","the","bathroom"],"translation":"Compartimos la cocina y el baño.","translations":{"es":"Compartimos la cocina y el baño."}},{"words":["It","is","your","turn","to","do","the","dishes"],"translation":"Te toca lavar los trastes.","translations":{"es":"Te toca lavar los trastes."}},{"words":["Let''s","split","the","bills"],"translation":"Dividamos las cuentas.","translations":{"es":"Dividamos las cuentas."}},{"words":["Would","you","mind","not","playing","music","so","late"],"translation":"¿Te importaría no poner música tan tarde?","translations":{"es":"¿Te importaría no poner música tan tarde?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Esto es tuyo?","translations":{"es":"¿Esto es tuyo?"},"answer":"Is this yours"},{"prompt":"Es mío","translations":{"es":"Es mío"},"answer":"It is mine"},{"prompt":"¿De quién es esta bolsa?","translations":{"es":"¿De quién es esta bolsa?"},"answer":"Whose bag is this"},{"prompt":"Compartimos el departamento","translations":{"es":"Compartimos el departamento"},"answer":"We share the apartment"},{"prompt":"Te toca a ti","translations":{"es":"Te toca a ti"},"answer":"It is your turn"},{"prompt":"El auto es de ellos","translations":{"es":"El auto es de ellos"},"answer":"The car is theirs"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 45: Love and marriage
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-45', 'Love and marriage', '💍', 'El amor y el matrimonio', 45, true)
  returning id
