insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"love","translation":"amor / amar","translations":{"es":"amor / amar"}},{"id":"2","word":"boyfriend","translation":"novio","translations":{"es":"novio"}},{"id":"3","word":"girlfriend","translation":"novia","translations":{"es":"novia"}},{"id":"4","word":"engaged","translation":"comprometido","translations":{"es":"comprometido"}},{"id":"5","word":"wedding","translation":"boda","translations":{"es":"boda"}},{"id":"6","word":"bride","translation":"novia (en la boda)","translations":{"es":"novia (en la boda)"}},{"id":"7","word":"groom","translation":"novio (en la boda)","translations":{"es":"novio (en la boda)"}},{"id":"8","word":"ring","translation":"anillo","translations":{"es":"anillo"}},{"id":"9","word":"anniversary","translation":"aniversario","translations":{"es":"aniversario"}},{"id":"10","word":"get married","translation":"casarse","translations":{"es":"casarse"}},{"id":"11","word":"married","translation":"casado","translations":{"es":"casado"}},{"id":"12","word":"divorced","translation":"divorciado","translations":{"es":"divorciado"}},{"id":"13","word":"widow","translation":"viuda","translations":{"es":"viuda"}},{"id":"14","word":"promise","translation":"promesa / prometer","translations":{"es":"promesa / prometer"}},{"id":"15","word":"couple","translation":"pareja","translations":{"es":"pareja"}},{"id":"16","word":"toast","translation":"brindis","translations":{"es":"brindis"}},{"id":"17","word":"won''t","translation":"no (futuro: will not)","translations":{"es":"no (futuro: will not)"}}],"grammar":[{"structure":"will + verb (promises)","example":"I will always love you.","en":"\"Will\" for promises","es":"«Will» para promesas"},{"structure":"will + verb (predictions)","example":"They will be very happy together.","en":"\"Will\" for predictions","es":"«Will» para predicciones"},{"structure":"won''t + verb","example":"I won''t forget this day.","en":"Negative: will not → won''t","es":"Negativo: will not → won''t"},{"structure":"get married / be married / marry someone","example":"They got married in 1994. She married Tom.","en":"Verbs for marriage","es":"Verbos para el matrimonio"},{"structure":"I think … will…","example":"I think it will be a beautiful party.","en":"Opinions about the future","es":"Opiniones sobre el futuro"}],"tips":[{"en":"\"Marry\" doesn''t take \"with\": \"She married Tom\" (not \"married with Tom\").","es":"«Marry» no lleva «with»: «She married Tom» (no «married with Tom»)."},{"en":"\"Get married\" is the action (casarse); \"be married\" is the state (estar casado).","es":"«Get married» es la acción (casarse); «be married» es el estado (estar casado)."},{"en":"\"Won''t\" sounds like \"want\" but longer: won''t = will not.","es":"«Won''t» suena parecido a «want» pero más largo: won''t = will not."},{"en":"At American weddings, guests often give gifts from a \"registry\" — a list the couple makes.","es":"En las bodas estadounidenses los invitados suelen regalar algo de una «registry»: una lista que hace la pareja."},{"en":"\"Congratulations!\" is the word for weddings, anniversaries and engagements.","es":"«Congratulations!» es la palabra para bodas, aniversarios y compromisos."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Congratulations!","translation":"¡Felicidades!","translations":{"es":"¡Felicidades!"}},{"phrase":"When did you get married?","translation":"¿Cuándo se casaron?","translations":{"es":"¿Cuándo se casaron?"}},{"phrase":"We got married in 1994.","translation":"Nos casamos en 1994.","translations":{"es":"Nos casamos en 1994."}},{"phrase":"Happy anniversary!","translation":"¡Feliz aniversario!","translations":{"es":"¡Feliz aniversario!"}},{"phrase":"I will always love you.","translation":"Siempre te voy a amar.","translations":{"es":"Siempre te voy a amar."}},{"phrase":"I promise I''ll be there.","translation":"Te prometo que voy a estar ahí.","translations":{"es":"Te prometo que voy a estar ahí."}},{"phrase":"I won''t forget this day.","translation":"No voy a olvidar este día.","translations":{"es":"No voy a olvidar este día."}},{"phrase":"They make a lovely couple.","translation":"Hacen una pareja muy linda.","translations":{"es":"Hacen una pareja muy linda."}},{"phrase":"Let''s make a toast!","translation":"¡Hagamos un brindis!","translations":{"es":"¡Hagamos un brindis!"}},{"phrase":"To the happy couple!","translation":"¡Por la feliz pareja!","translations":{"es":"¡Por la feliz pareja!"}},{"phrase":"I think they''ll be very happy.","translation":"Creo que van a ser muy felices.","translations":{"es":"Creo que van a ser muy felices."}},{"phrase":"Are you married?","translation":"¿Estás casado/a?","translations":{"es":"¿Estás casado/a?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence.","options":["She married to Tom.","She married with Tom.","She married Tom.","She got married Tom."],"correct":2,"explanation":"\"Marry\" takes no preposition.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"«Marry» no lleva preposición."}}},{"id":"2","question":"Complete: \"I promise I ___ call you every day.\"","options":["am","do","will","going"],"correct":2,"explanation":"Promises → will.","translations":{"es":{"question":"Completa: «I promise I ___ call you every day.»","explanation":"Promesas → will."}}},{"id":"3","question":"What is the short form of \"will not\"?","options":["wont''","willn''t","won''t","wil''nt"],"correct":2,"explanation":"will not → won''t.","translations":{"es":{"question":"¿Cuál es la forma corta de «will not»?","explanation":"will not → won''t."}}},{"id":"4","question":"Your friends got married 25 years ago today. You say:","options":["Happy anniversary!","Get well soon!","Happy birthday!","Good luck!"],"correct":0,"explanation":"Anniversary = aniversario.","translations":{"es":{"question":"Tus amigos se casaron hace 25 años hoy. Dices:","explanation":"Anniversary = aniversario."}}},{"id":"5","question":"\"Be married\" means…","options":["estar comprometido","estar casado","casarse (el día de la boda)","estar divorciado"],"correct":1,"explanation":"Be married = the state; get married = the event.","translations":{"es":{"question":"«Be married» significa…","explanation":"Be married = el estado; get married = el evento."}}},{"id":"6","question":"Complete: \"I think it ___ rain tomorrow.\" (prediction)","options":["does","will","is","can to"],"correct":1,"explanation":"Predictions with \"I think\" → will.","translations":{"es":{"question":"Completa: «I think it ___ rain tomorrow.» (predicción)","explanation":"Predicciones con «I think» → will."}}},{"id":"7","question":"A woman whose husband has died is a…","options":["widow","fiancée","bride","divorced"],"correct":0,"explanation":"Widow = viuda.","translations":{"es":{"question":"Una mujer cuyo esposo murió es…","explanation":"Widow = viuda."}}},{"id":"8","question":"At a wedding party, someone raises a glass and says…","options":["Get well soon!","To the happy couple!","Have a good flight!","No spoilers!"],"correct":1,"explanation":"A toast: To the happy couple!","translations":{"es":{"question":"En una boda, alguien levanta su copa y dice…","explanation":"Un brindis: To the happy couple!"}}}]}'::jsonb, 3),
  ('story', 'Thirty Years Together', '{"text":"Grace and Tom are celebrating their thirtieth wedding anniversary. They invite Carmen to the party at the bakery. There are flowers, music and, of course, a big cake. \"When did you get married?\" Carmen asks Grace. \"In 1994. Tom was so nervous he forgot the ring!\" Tom laughs. \"But I didn''t forget the most important thing: my promise.\" He takes Grace''s hand in front of everybody. \"Grace, thirty years ago I said I will always love you. Today I promise again: I will always love you, and I won''t forget your birthday… this year.\" Everybody laughs and claps. Linda raises her glass. \"Let''s make a toast! To the happy couple!\" Carmen thinks of her husband, Jorge. They were married for thirty-two years. She smiles. \"I think he was here tonight too,\" she says quietly to Linda.","translation":"Grace y Tom celebran su trigésimo aniversario de bodas. Invitan a Carmen a la fiesta en la panadería. Hay flores, música y, claro, un pastel grande. «¿Cuándo se casaron?», le pregunta Carmen a Grace. «En 1994. ¡Tom estaba tan nervioso que olvidó el anillo!» Tom se ríe. «Pero no olvidé lo más importante: mi promesa.» Toma la mano de Grace frente a todos. «Grace, hace treinta años dije que siempre te iba a amar. Hoy lo prometo otra vez: siempre te voy a amar, y no voy a olvidar tu cumpleaños… este año.» Todos se ríen y aplauden. Linda levanta su copa. «¡Hagamos un brindis! ¡Por la feliz pareja!» Carmen piensa en su esposo, Jorge. Estuvieron casados treinta y dos años. Sonríe. «Creo que él también estuvo aquí esta noche», le dice en voz baja a Linda.","translations":{"es":"Grace y Tom celebran su trigésimo aniversario de bodas. Invitan a Carmen a la fiesta en la panadería. Hay flores, música y, claro, un pastel grande. «¿Cuándo se casaron?», le pregunta Carmen a Grace. «En 1994. ¡Tom estaba tan nervioso que olvidó el anillo!» Tom se ríe. «Pero no olvidé lo más importante: mi promesa.» Toma la mano de Grace frente a todos. «Grace, hace treinta años dije que siempre te iba a amar. Hoy lo prometo otra vez: siempre te voy a amar, y no voy a olvidar tu cumpleaños… este año.» Todos se ríen y aplauden. Linda levanta su copa. «¡Hagamos un brindis! ¡Por la feliz pareja!» Carmen piensa en su esposo, Jorge. Estuvieron casados treinta y dos años. Sonríe. «Creo que él también estuvo aquí esta noche», le dice en voz baja a Linda."},"highlighted_words":["wedding anniversary","When did you get married","ring","promise","I will always love you","I won''t forget","Let''s make a toast","To the happy couple","husband","married"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","will","always","love","you"],"translation":"Siempre te voy a amar.","translations":{"es":"Siempre te voy a amar."}},{"words":["They","got","married","in","1994"],"translation":"Se casaron en 1994.","translations":{"es":"Se casaron en 1994."}},{"words":["I","promise","I","will","be","there"],"translation":"Te prometo que voy a estar ahí.","translations":{"es":"Te prometo que voy a estar ahí."}},{"words":["I","will","not","forget","this","day"],"translation":"No voy a olvidar este día.","translations":{"es":"No voy a olvidar este día."}},{"words":["I","think","they","will","be","very","happy"],"translation":"Creo que van a ser muy felices.","translations":{"es":"Creo que van a ser muy felices."}},{"words":["Let''s","make","a","toast","to","the","couple"],"translation":"Hagamos un brindis por la pareja.","translations":{"es":"Hagamos un brindis por la pareja."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Feliz aniversario","translations":{"es":"Feliz aniversario"},"answer":"Happy anniversary"},{"prompt":"Felicidades","translations":{"es":"Felicidades"},"answer":"Congratulations"},{"prompt":"Te llamaré mañana","translations":{"es":"Te llamaré mañana"},"answer":"I will call you tomorrow"},{"prompt":"Ella se casó con un médico","translations":{"es":"Ella se casó con un médico"},"answer":"She married a doctor"},{"prompt":"No voy a olvidar","translations":{"es":"No voy a olvidar"},"answer":"I will not forget"},{"prompt":"¿Estás casado?","translations":{"es":"¿Estás casado?"},"answer":"Are you married"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 46: Looking for a job
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-46', 'Looking for a job', '💼', 'Buscar trabajo', 46, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"job","translation":"trabajo / empleo","translations":{"es":"trabajo / empleo"}},{"id":"2","word":"résumé","translation":"currículum","translations":{"es":"currículum"}},{"id":"3","word":"interview","translation":"entrevista","translations":{"es":"entrevista"}},{"id":"4","word":"experience","translation":"experiencia","translations":{"es":"experiencia"}},{"id":"5","word":"skills","translation":"habilidades","translations":{"es":"habilidades"}},{"id":"6","word":"apply","translation":"postularse / solicitar","translations":{"es":"postularse / solicitar"}},{"id":"7","word":"application","translation":"solicitud","translations":{"es":"solicitud"}},{"id":"8","word":"hire","translation":"contratar","translations":{"es":"contratar"}},{"id":"9","word":"salary","translation":"salario","translations":{"es":"salario"}},{"id":"10","word":"per hour","translation":"por hora","translations":{"es":"por hora"}},{"id":"11","word":"full-time","translation":"tiempo completo","translations":{"es":"tiempo completo"}},{"id":"12","word":"shift","translation":"turno","translations":{"es":"turno"}},{"id":"13","word":"reliable","translation":"confiable","translations":{"es":"confiable"}},{"id":"14","word":"hardworking","translation":"trabajador","translations":{"es":"trabajador"}},{"id":"15","word":"references","translation":"referencias","translations":{"es":"referencias"}},{"id":"16","word":"available","translation":"disponible","translations":{"es":"disponible"}},{"id":"17","word":"employer","translation":"empleador","translations":{"es":"empleador"}}],"grammar":[{"structure":"I have + past participle (experience)","example":"I have worked with children. I''ve taught for thirty years.","en":"Present perfect to talk about experience","es":"Presente perfecto para hablar de experiencia"},{"structure":"present perfect vs. past simple","example":"I''ve worked in a bakery. I worked there in 2020.","en":"Experience (no date) vs. finished time (with date)","es":"Experiencia (sin fecha) vs. tiempo terminado (con fecha)"},{"structure":"Have you ever + past participle?","example":"Have you ever worked as a cashier?","en":"Interview questions about experience","es":"Preguntas de entrevista sobre experiencia"},{"structure":"I''m good at + noun / verb-ing","example":"I''m good at cooking and organizing.","en":"Talking about skills","es":"Hablar de habilidades"},{"structure":"I''m interested in + noun / verb-ing","example":"I''m interested in working part-time.","en":"Showing interest","es":"Mostrar interés"}],"tips":[{"en":"If you say when (in 2020, last year), use the past simple. If you don''t say when, use the present perfect.","es":"Si dices cuándo (in 2020, last year), usa el pasado simple. Si no dices cuándo, usa el presente perfecto."},{"en":"A \"résumé\" (or resume) is your CV in the US. It''s usually one page, without a photo.","es":"El «résumé» (o resume) es tu currículum en Estados Unidos. Suele ser de una página y sin foto."},{"en":"In interviews, Americans expect you to talk positively about yourself. It''s not arrogance; it''s normal.","es":"En las entrevistas en Estados Unidos se espera que hables bien de ti. No es arrogancia; es lo normal."},{"en":"Send a short thank-you email after an interview. It makes a good impression.","es":"Manda un correo breve de agradecimiento después de una entrevista. Causa buena impresión."},{"en":"\"Hire\" = contratar; \"fire\" = despedir. Careful, they sound similar!","es":"«Hire» = contratar; «fire» = despedir. ¡Cuidado, suenan parecido!"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to apply for the job.","translation":"Quisiera postularme para el trabajo.","translations":{"es":"Quisiera postularme para el trabajo."}},{"phrase":"Here is my résumé.","translation":"Aquí está mi currículum.","translations":{"es":"Aquí está mi currículum."}},{"phrase":"Tell me about yourself.","translation":"Hábleme de usted.","translations":{"es":"Hábleme de usted."}},{"phrase":"Have you ever worked in a store?","translation":"¿Ha trabajado alguna vez en una tienda?","translations":{"es":"¿Ha trabajado alguna vez en una tienda?"}},{"phrase":"Yes, I have. I worked at a pharmacy for three years.","translation":"Sí. Trabajé en una farmacia tres años.","translations":{"es":"Sí. Trabajé en una farmacia tres años."}},{"phrase":"I''ve worked with customers before.","translation":"Ya he trabajado con clientes.","translations":{"es":"Ya he trabajado con clientes."}},{"phrase":"I''m good at solving problems.","translation":"Soy buena resolviendo problemas.","translations":{"es":"Soy buena resolviendo problemas."}},{"phrase":"I''m very reliable and hardworking.","translation":"Soy muy confiable y trabajadora.","translations":{"es":"Soy muy confiable y trabajadora."}},{"phrase":"When can you start?","translation":"¿Cuándo puede empezar?","translations":{"es":"¿Cuándo puede empezar?"}},{"phrase":"I''m available on weekends.","translation":"Estoy disponible los fines de semana.","translations":{"es":"Estoy disponible los fines de semana."}},{"phrase":"How much is the salary?","translation":"¿Cuánto es el sueldo?","translations":{"es":"¿Cuánto es el sueldo?"}},{"phrase":"Thank you for your time.","translation":"Gracias por su tiempo.","translations":{"es":"Gracias por su tiempo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence (no specific time).","options":["I work with children since years.","I worked with children never.","I''ve worked with children.","I''ve worked with children in 2015."],"correct":2,"explanation":"Experience without a date → present perfect.","translations":{"es":{"question":"Elige la oración correcta (sin tiempo específico).","explanation":"Experiencia sin fecha → presente perfecto."}}},{"id":"2","question":"Choose the correct sentence (with a date).","options":["I have work at a hotel in 2018.","I worked at a hotel in 2018.","I''m working at a hotel in 2018.","I''ve worked at a hotel in 2018."],"correct":1,"explanation":"A finished date (in 2018) → past simple.","translations":{"es":{"question":"Elige la oración correcta (con fecha).","explanation":"Con fecha terminada (in 2018) → pasado simple."}}},{"id":"3","question":"Complete: \"I''m good ___ cooking.\"","options":["at","for","on","in"],"correct":0,"explanation":"good at + noun / verb-ing.","translations":{"es":{"question":"Completa: «I''m good ___ cooking.»","explanation":"good at + sustantivo / verbo-ing."}}},{"id":"4","question":"Complete: \"I''m interested ___ this position.\"","options":["in","at","for","on"],"correct":0,"explanation":"interested in.","translations":{"es":{"question":"Completa: «I''m interested ___ this position.»","explanation":"interested in."}}},{"id":"5","question":"\"Hire\" means…","options":["renunciar","contratar","jubilarse","despedir"],"correct":1,"explanation":"Hire = contratar; fire = despedir.","translations":{"es":{"question":"«Hire» significa…","explanation":"Hire = contratar; fire = despedir."}}},{"id":"6","question":"A one-page document with your work experience is your…","options":["license","résumé","lease","receipt"],"correct":1,"explanation":"Résumé = currículum.","translations":{"es":{"question":"Un documento de una página con tu experiencia laboral es tu…","explanation":"Résumé = currículum."}}},{"id":"7","question":"The interviewer says \"Tell me about yourself.\" A good start is:","options":["I''m a hardworking person with ten years of experience…","I don''t know myself.","What do you want?","No."],"correct":0,"explanation":"Talk positively about your experience and qualities.","translations":{"es":{"question":"El entrevistador dice «Tell me about yourself.». Un buen inicio es:","explanation":"Habla en positivo de tu experiencia y cualidades."}}},{"id":"8","question":"Short answer: \"Have you ever managed a team?\" (yes)","options":["Yes, I am.","Yes, I have.","Yes, I managed.","Yes, I did."],"correct":1,"explanation":"Short answer: Yes, I have.","translations":{"es":{"question":"Respuesta corta: «Have you ever managed a team?» (sí)","explanation":"Respuesta corta: Yes, I have."}}}]}'::jsonb, 3),
  ('story', 'Ana''s Interview', '{"text":"Ana has an interview for a job at a hotel front desk. She''s nervous, so Carmen helps her practice. \"Okay, I''m the manager,\" says Carmen. \"Tell me about yourself.\" \"Well, I''m from Brazil. I''ve lived in San Diego for three years. I''ve worked as a receptionist before.\" \"Where did you work?\" \"I worked at a dental office from 2021 to 2023.\" \"Have you ever worked at a hotel?\" \"No, I haven''t. But I''ve helped many customers, and I''m good at solving problems.\" \"Do you speak other languages?\" \"Yes! Portuguese, Spanish and English.\" Carmen claps. \"Hired!\" The next day, Ana goes to the real interview. She answers every question with a smile. In the evening she calls Carmen. \"They asked me ''When can you start?'' I start on Monday!\" \"Congratulations! I knew it.\"","translation":"Ana tiene una entrevista para un trabajo en la recepción de un hotel. Está nerviosa, así que Carmen la ayuda a practicar. «Bueno, yo soy la gerente», dice Carmen. «Hábleme de usted.» «Pues, soy de Brasil. Llevo tres años viviendo en San Diego. Ya he trabajado como recepcionista.» «¿Dónde trabajó?» «Trabajé en un consultorio dental de 2021 a 2023.» «¿Ha trabajado alguna vez en un hotel?» «No. Pero he atendido a muchos clientes y soy buena resolviendo problemas.» «¿Habla otros idiomas?» «¡Sí! Portugués, español e inglés.» Carmen aplaude. «¡Contratada!» Al día siguiente, Ana va a la entrevista de verdad. Responde cada pregunta con una sonrisa. En la noche llama a Carmen. «Me preguntaron «¿Cuándo puede empezar?» ¡Empiezo el lunes!» «¡Felicidades! Lo sabía.»","translations":{"es":"Ana tiene una entrevista para un trabajo en la recepción de un hotel. Está nerviosa, así que Carmen la ayuda a practicar. «Bueno, yo soy la gerente», dice Carmen. «Hábleme de usted.» «Pues, soy de Brasil. Llevo tres años viviendo en San Diego. Ya he trabajado como recepcionista.» «¿Dónde trabajó?» «Trabajé en un consultorio dental de 2021 a 2023.» «¿Ha trabajado alguna vez en un hotel?» «No. Pero he atendido a muchos clientes y soy buena resolviendo problemas.» «¿Habla otros idiomas?» «¡Sí! Portugués, español e inglés.» Carmen aplaude. «¡Contratada!» Al día siguiente, Ana va a la entrevista de verdad. Responde cada pregunta con una sonrisa. En la noche llama a Carmen. «Me preguntaron «¿Cuándo puede empezar?» ¡Empiezo el lunes!» «¡Felicidades! Lo sabía.»"},"highlighted_words":["interview","Tell me about yourself","I''ve lived in San Diego for three years","I''ve worked as a receptionist before","I worked at a dental office","Have you ever worked at a hotel","No, I haven''t","I''m good at solving problems","Hired","When can you start"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","to","apply","for","the","job"],"translation":"Quisiera postularme para el trabajo.","translations":{"es":"Quisiera postularme para el trabajo."}},{"words":["Have","you","ever","worked","in","a","store"],"translation":"¿Ha trabajado alguna vez en una tienda?","translations":{"es":"¿Ha trabajado alguna vez en una tienda?"}},{"words":["I","have","worked","with","customers","before"],"translation":"Ya he trabajado con clientes.","translations":{"es":"Ya he trabajado con clientes."}},{"words":["I","am","good","at","solving","problems"],"translation":"Soy buena resolviendo problemas.","translations":{"es":"Soy buena resolviendo problemas."}},{"words":["I","worked","at","a","pharmacy","in","2020"],"translation":"Trabajé en una farmacia en 2020.","translations":{"es":"Trabajé en una farmacia en 2020."}},{"words":["When","can","you","start"],"translation":"¿Cuándo puede empezar?","translations":{"es":"¿Cuándo puede empezar?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Aquí está mi currículum","translations":{"es":"Aquí está mi currículum"},"answer":"Here is my résumé"},{"prompt":"He trabajado en un hotel","translations":{"es":"He trabajado en un hotel"},"answer":"I have worked in a hotel"},{"prompt":"Soy muy confiable","translations":{"es":"Soy muy confiable"},"answer":"I am very reliable"},{"prompt":"Estoy disponible los fines de semana","translations":{"es":"Estoy disponible los fines de semana"},"answer":"I am available on weekends"},{"prompt":"Gracias por su tiempo","translations":{"es":"Gracias por su tiempo"},"answer":"Thank you for your time"},{"prompt":"Soy buena para cocinar","translations":{"es":"Soy buena para cocinar"},"answer":"I am good at cooking"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 47: At work
with m as (
