insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"coworker","translation":"compañero de trabajo","translations":{"es":"compañero de trabajo"}},{"id":"2","word":"manager","translation":"gerente","translations":{"es":"gerente"}},{"id":"3","word":"customer","translation":"cliente","translations":{"es":"cliente"}},{"id":"4","word":"break","translation":"descanso","translations":{"es":"descanso"}},{"id":"5","word":"shift","translation":"turno","translations":{"es":"turno"}},{"id":"6","word":"clock in","translation":"registrar entrada","translations":{"es":"registrar entrada"}},{"id":"7","word":"clock out","translation":"registrar salida","translations":{"es":"registrar salida"}},{"id":"8","word":"apron","translation":"delantal / mandil","translations":{"es":"delantal / mandil"}},{"id":"9","word":"uniform","translation":"uniforme","translations":{"es":"uniforme"}},{"id":"10","word":"must","translation":"deber (obligación fuerte)","translations":{"es":"deber (obligación fuerte)"}},{"id":"11","word":"mustn''t","translation":"no deber (prohibido)","translations":{"es":"no deber (prohibido)"}},{"id":"12","word":"in charge of","translation":"a cargo de","translations":{"es":"a cargo de"}},{"id":"13","word":"task","translation":"tarea","translations":{"es":"tarea"}},{"id":"14","word":"schedule","translation":"horario","translations":{"es":"horario"}},{"id":"15","word":"paycheck","translation":"cheque de pago / sueldo","translations":{"es":"cheque de pago / sueldo"}},{"id":"16","word":"raise","translation":"aumento de sueldo","translations":{"es":"aumento de sueldo"}},{"id":"17","word":"teamwork","translation":"trabajo en equipo","translations":{"es":"trabajo en equipo"}}],"grammar":[{"structure":"must + verb","example":"You must wash your hands before you cook.","en":"Strong rules and obligations","es":"Reglas y obligaciones fuertes"},{"structure":"mustn''t + verb","example":"You mustn''t use your phone at the register.","en":"Prohibition","es":"Prohibición"},{"structure":"mustn''t vs. don''t have to","example":"You mustn''t be late. / You don''t have to wear a tie.","en":"Prohibited vs. not necessary","es":"Prohibido vs. no necesario"},{"structure":"Can I…? / May I…?","example":"May I take a break now?","en":"Asking for permission","es":"Pedir permiso"},{"structure":"I''m in charge of…","example":"I''m in charge of the tamales.","en":"Describing responsibilities","es":"Describir responsabilidades"}],"tips":[{"en":"\"Mustn''t\" = está prohibido. \"Don''t have to\" = no es necesario. They are very different!","es":"«Mustn''t» = está prohibido. «Don''t have to» = no es necesario. ¡Son muy diferentes!"},{"en":"\"May I…?\" is more formal than \"Can I…?\". Both are fine with a boss.","es":"«May I…?» es más formal que «Can I…?». Las dos están bien con un jefe."},{"en":"\"Clock in\" and \"clock out\" mean to register when you start and finish your shift.","es":"«Clock in» y «clock out» significan registrar la entrada y la salida del turno."},{"en":"In US workplaces, people often use first names, even with the boss.","es":"En los trabajos en Estados Unidos es común usar el nombre de pila, incluso con el jefe."},{"en":"If you don''t understand an instruction, ask: \"Just to make sure, you want me to…?\"","es":"Si no entiendes una instrucción, pregunta: «Just to make sure, you want me to…?» (solo para confirmar, ¿quiere que…?)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Welcome to the team!","translation":"¡Bienvenida al equipo!","translations":{"es":"¡Bienvenida al equipo!"}},{"phrase":"You must wear an apron.","translation":"Debes usar mandil.","translations":{"es":"Debes usar mandil."}},{"phrase":"You mustn''t eat behind the counter.","translation":"No debes comer detrás del mostrador.","translations":{"es":"No debes comer detrás del mostrador."}},{"phrase":"You don''t have to come on Sundays.","translation":"No tienes que venir los domingos.","translations":{"es":"No tienes que venir los domingos."}},{"phrase":"May I take my break now?","translation":"¿Puedo tomar mi descanso ahora?","translations":{"es":"¿Puedo tomar mi descanso ahora?"}},{"phrase":"Don''t forget to clock in.","translation":"No olvides registrar tu entrada.","translations":{"es":"No olvides registrar tu entrada."}},{"phrase":"I''m in charge of the morning shift.","translation":"Estoy a cargo del turno de la mañana.","translations":{"es":"Estoy a cargo del turno de la mañana."}},{"phrase":"Just to make sure, you want me to clean the oven?","translation":"Solo para confirmar, ¿quiere que limpie el horno?","translations":{"es":"Solo para confirmar, ¿quiere que limpie el horno?"}},{"phrase":"Can you cover my shift on Friday?","translation":"¿Me cubres el turno del viernes?","translations":{"es":"¿Me cubres el turno del viernes?"}},{"phrase":"Great job today!","translation":"¡Buen trabajo hoy!","translations":{"es":"¡Buen trabajo hoy!"}},{"phrase":"How can I help you?","translation":"¿En qué le puedo ayudar?","translations":{"es":"¿En qué le puedo ayudar?"}},{"phrase":"See you tomorrow, team!","translation":"¡Hasta mañana, equipo!","translations":{"es":"¡Hasta mañana, equipo!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"\"You mustn''t smoke here\" means…","options":["Smoking is prohibited.","You can smoke later.","You don''t need to smoke.","You should smoke."],"correct":0,"explanation":"Mustn''t = prohibited.","translations":{"es":{"question":"«You mustn''t smoke here» significa…","explanation":"Mustn''t = prohibido."}}},{"id":"2","question":"\"You don''t have to wear a tie\" means…","options":["Ties are expensive.","It''s not necessary.","It''s prohibited.","You must wear one."],"correct":1,"explanation":"Don''t have to = not necessary.","translations":{"es":{"question":"«You don''t have to wear a tie» significa…","explanation":"Don''t have to = no es necesario."}}},{"id":"3","question":"Complete: \"You ___ wash your hands before cooking.\" (strong rule)","options":["must","must to","mustn''t","don''t have to"],"correct":0,"explanation":"Strong rule → must + verb.","translations":{"es":{"question":"Completa: «You ___ wash your hands before cooking.» (regla fuerte)","explanation":"Regla fuerte → must + verbo."}}},{"id":"4","question":"The most formal way to ask permission is…","options":["May I take a break?","Can I take break?","Break now?","I take a break, okay?"],"correct":0,"explanation":"\"May I…?\" is formal and polite.","translations":{"es":{"question":"La forma más formal de pedir permiso es…","explanation":"«May I…?» es formal y amable."}}},{"id":"5","question":"When you register the start of your shift, you…","options":["clock out","clock in","get a raise","take a break"],"correct":1,"explanation":"Clock in = start; clock out = finish.","translations":{"es":{"question":"Cuando registras el inicio de tu turno, tú…","explanation":"Clock in = entrada; clock out = salida."}}},{"id":"6","question":"You''re responsible for the bread. You say:","options":["I''m in charge for the bread.","I''m in charge of the bread.","I''m on charge of bread.","I''m charging the bread."],"correct":1,"explanation":"in charge of + noun.","translations":{"es":{"question":"Eres responsable del pan. Dices:","explanation":"in charge of + sustantivo."}}},{"id":"7","question":"More money for the same job is a…","options":["raise","break","paycheck stub","shift"],"correct":0,"explanation":"Raise = aumento de sueldo.","translations":{"es":{"question":"Más dinero por el mismo trabajo es un…","explanation":"Raise = aumento de sueldo."}}},{"id":"8","question":"Complete: \"You ___ come on Sundays. The bakery is closed.\"","options":["must","have to","don''t have to","should"],"correct":2,"explanation":"Not necessary → don''t have to.","translations":{"es":{"question":"Completa: «You ___ come on Sundays. The bakery is closed.»","explanation":"No es necesario → don''t have to."}}}]}'::jsonb, 3),
  ('story', 'First Day at the Bakery', '{"text":"It''s Carmen''s first Saturday at the bakery. Grace gives her an apron and shows her around. \"Welcome to the team! You must wear this apron and you must wash your hands before you cook. You mustn''t use your phone near the ovens.\" \"Do I have to wear a uniform?\" \"No, you don''t have to. Just the apron.\" Carmen''s coworker is Luis, a young baker from Tijuana. \"Don''t forget to clock in,\" he says. \"And you''re in charge of the tamales.\" The morning is busy. Many customers come for coffee and bread. At eleven, Carmen asks, \"Grace, may I take my break now?\" \"Of course. Fifteen minutes.\" At the end of the shift, Grace says, \"Great job today, Carmen! The tamales sold out in two hours.\" Carmen takes off her apron, tired but proud. \"See you next Saturday, team!\"","translation":"Es el primer sábado de Carmen en la panadería. Grace le da un mandil y le enseña el lugar. «¡Bienvenida al equipo! Debes usar este mandil y debes lavarte las manos antes de cocinar. No debes usar el teléfono cerca de los hornos.» «¿Tengo que usar uniforme?» «No, no hace falta. Solo el mandil.» El compañero de trabajo de Carmen es Luis, un joven panadero de Tijuana. «No olvides registrar tu entrada», le dice. «Y tú estás a cargo de los tamales.» La mañana es muy movida. Muchos clientes vienen por café y pan. A las once, Carmen pregunta: «Grace, ¿puedo tomar mi descanso ahora?» «Claro. Quince minutos.» Al final del turno, Grace dice: «¡Buen trabajo hoy, Carmen! Los tamales se acabaron en dos horas.» Carmen se quita el mandil, cansada pero orgullosa. «¡Hasta el próximo sábado, equipo!»","translations":{"es":"Es el primer sábado de Carmen en la panadería. Grace le da un mandil y le enseña el lugar. «¡Bienvenida al equipo! Debes usar este mandil y debes lavarte las manos antes de cocinar. No debes usar el teléfono cerca de los hornos.» «¿Tengo que usar uniforme?» «No, no hace falta. Solo el mandil.» El compañero de trabajo de Carmen es Luis, un joven panadero de Tijuana. «No olvides registrar tu entrada», le dice. «Y tú estás a cargo de los tamales.» La mañana es muy movida. Muchos clientes vienen por café y pan. A las once, Carmen pregunta: «Grace, ¿puedo tomar mi descanso ahora?» «Claro. Quince minutos.» Al final del turno, Grace dice: «¡Buen trabajo hoy, Carmen! Los tamales se acabaron en dos horas.» Carmen se quita el mandil, cansada pero orgullosa. «¡Hasta el próximo sábado, equipo!»"},"highlighted_words":["apron","Welcome to the team","You must wear","you must wash your hands","You mustn''t use your phone","Do I have to wear a uniform","you don''t have to","coworker","clock in","in charge of","customers","may I take my break now","shift","Great job today"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["You","must","wear","an","apron"],"translation":"Debes usar mandil.","translations":{"es":"Debes usar mandil."}},{"words":["You","must","not","use","your","phone","here"],"translation":"No debes usar el teléfono aquí.","translations":{"es":"No debes usar el teléfono aquí."}},{"words":["You","do","not","have","to","come","on","Sundays"],"translation":"No tienes que venir los domingos.","translations":{"es":"No tienes que venir los domingos."}},{"words":["May","I","take","my","break","now"],"translation":"¿Puedo tomar mi descanso ahora?","translations":{"es":"¿Puedo tomar mi descanso ahora?"}},{"words":["I","am","in","charge","of","the","morning","shift"],"translation":"Estoy a cargo del turno de la mañana.","translations":{"es":"Estoy a cargo del turno de la mañana."}},{"words":["Do","not","forget","to","clock","in"],"translation":"No olvides registrar tu entrada.","translations":{"es":"No olvides registrar tu entrada."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Bienvenida al equipo","translations":{"es":"Bienvenida al equipo"},"answer":"Welcome to the team"},{"prompt":"Debes lavarte las manos","translations":{"es":"Debes lavarte las manos"},"answer":"You must wash your hands"},{"prompt":"¿Puedo tomar un descanso?","translations":{"es":"¿Puedo tomar un descanso?"},"answer":"May I take a break"},{"prompt":"Buen trabajo hoy","translations":{"es":"Buen trabajo hoy"},"answer":"Great job today"},{"prompt":"¿En qué le puedo ayudar?","translations":{"es":"¿En qué le puedo ayudar?"},"answer":"How can I help you"},{"prompt":"Estoy a cargo del pan","translations":{"es":"Estoy a cargo del pan"},"answer":"I am in charge of the bread"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 48: At the bank
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-48', 'At the bank', '🏦', 'En el banco', 48, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"bank account","translation":"cuenta bancaria","translations":{"es":"cuenta bancaria"}},{"id":"2","word":"checking account","translation":"cuenta de cheques","translations":{"es":"cuenta de cheques"}},{"id":"3","word":"savings account","translation":"cuenta de ahorros","translations":{"es":"cuenta de ahorros"}},{"id":"4","word":"deposit","translation":"depositar / depósito","translations":{"es":"depositar / depósito"}},{"id":"5","word":"withdraw","translation":"retirar (dinero)","translations":{"es":"retirar (dinero)"}},{"id":"6","word":"ATM","translation":"cajero automático","translations":{"es":"cajero automático"}},{"id":"7","word":"PIN","translation":"NIP / PIN","translations":{"es":"NIP / PIN"}},{"id":"8","word":"debit card","translation":"tarjeta de débito","translations":{"es":"tarjeta de débito"}},{"id":"9","word":"balance","translation":"saldo","translations":{"es":"saldo"}},{"id":"10","word":"fee","translation":"comisión / cargo","translations":{"es":"comisión / cargo"}},{"id":"11","word":"transfer","translation":"transferencia / transferir","translations":{"es":"transferencia / transferir"}},{"id":"12","word":"teller","translation":"cajero (de banco)","translations":{"es":"cajero (de banco)"}},{"id":"13","word":"statement","translation":"estado de cuenta","translations":{"es":"estado de cuenta"}},{"id":"14","word":"loan","translation":"préstamo","translations":{"es":"préstamo"}},{"id":"15","word":"interest","translation":"interés","translations":{"es":"interés"}},{"id":"16","word":"if","translation":"si (condición)","translations":{"es":"si (condición)"}},{"id":"17","word":"unless","translation":"a menos que","translations":{"es":"a menos que"}}],"grammar":[{"structure":"If + present, … will + verb","example":"If you open an account today, you will get a free card.","en":"First conditional: real possibilities","es":"Primer condicional: posibilidades reales"},{"structure":"If + present, … can / should + verb","example":"If you lose your card, you should call the bank.","en":"First conditional with other modals","es":"Primer condicional con otros modales"},{"structure":"unless = if not","example":"You won''t pay a fee unless your balance is low.","en":"\"Unless\"","es":"«Unless» (a menos que)"},{"structure":"I''d like to + bank action","example":"I''d like to open a checking account.","en":"Bank requests","es":"Pedidos en el banco"},{"structure":"No \"will\" after \"if\"","example":"If it rains, I''ll stay home. (not \"If it will rain\")","en":"The present goes after \"if\"","es":"Después de «if» va el presente"}],"tips":[{"en":"Never put \"will\" right after \"if\": \"If I have time, I''ll call you\".","es":"Nunca pongas «will» justo después de «if»: «If I have time, I''ll call you»."},{"en":"A \"checking account\" is for everyday money; a \"savings account\" is for saving.","es":"La «checking account» es la cuenta para el día a día; la «savings account» es para ahorrar."},{"en":"Your PIN is secret. Bank employees will never ask for it.","es":"Tu NIP (PIN) es secreto. Los empleados del banco nunca te lo van a pedir."},{"en":"Many banks have Spanish-speaking staff: ask \"Is there someone who speaks Spanish?\"","es":"Muchos bancos tienen personal que habla español: pregunta «Is there someone who speaks Spanish?»"},{"en":"To send money to Mexico, compare fees: banks, apps and money-transfer services charge differently.","es":"Para mandar dinero a México, compara comisiones: bancos, apps y servicios de envío cobran distinto."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to open an account.","translation":"Quisiera abrir una cuenta.","translations":{"es":"Quisiera abrir una cuenta."}},{"phrase":"What documents do I need?","translation":"¿Qué documentos necesito?","translations":{"es":"¿Qué documentos necesito?"}},{"phrase":"I''d like to deposit this check.","translation":"Quisiera depositar este cheque.","translations":{"es":"Quisiera depositar este cheque."}},{"phrase":"How do I withdraw money?","translation":"¿Cómo retiro dinero?","translations":{"es":"¿Cómo retiro dinero?"}},{"phrase":"What''s my balance?","translation":"¿Cuál es mi saldo?","translations":{"es":"¿Cuál es mi saldo?"}},{"phrase":"Is there a monthly fee?","translation":"¿Hay comisión mensual?","translations":{"es":"¿Hay comisión mensual?"}},{"phrase":"If you keep five hundred dollars, there''s no fee.","translation":"Si mantiene quinientos dólares, no hay comisión.","translations":{"es":"Si mantiene quinientos dólares, no hay comisión."}},{"phrase":"I''d like to send money to Mexico.","translation":"Quisiera mandar dinero a México.","translations":{"es":"Quisiera mandar dinero a México."}},{"phrase":"Please enter your PIN.","translation":"Por favor, ingrese su NIP.","translations":{"es":"Por favor, ingrese su NIP."}},{"phrase":"I lost my debit card.","translation":"Perdí mi tarjeta de débito.","translations":{"es":"Perdí mi tarjeta de débito."}},{"phrase":"If you lose your card, call us right away.","translation":"Si pierde su tarjeta, llámenos de inmediato.","translations":{"es":"Si pierde su tarjeta, llámenos de inmediato."}},{"phrase":"Is there someone who speaks Spanish?","translation":"¿Hay alguien que hable español?","translations":{"es":"¿Hay alguien que hable español?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct first conditional.","options":["If it rain, I will stay home.","If it rains, I stayed home.","If it will rain, I''ll stay home.","If it rains, I''ll stay home."],"correct":3,"explanation":"If + present, will + verb.","translations":{"es":{"question":"Elige el primer condicional correcto.","explanation":"If + presente, will + verbo."}}},{"id":"2","question":"Complete: \"If you ___ your card, call the bank.\"","options":["will lose","losing","lost","lose"],"correct":3,"explanation":"After \"if\" → present: lose.","translations":{"es":{"question":"Completa: «If you ___ your card, call the bank.»","explanation":"Después de «if» → presente: lose."}}},{"id":"3","question":"\"Unless\" means…","options":["when","because","although","if not / a menos que"],"correct":3,"explanation":"Unless = if not.","translations":{"es":{"question":"«Unless» significa…","explanation":"Unless = if not."}}},{"id":"4","question":"The amount of money in your account is the…","options":["PIN","fee","loan","balance"],"correct":3,"explanation":"Balance = saldo.","translations":{"es":{"question":"La cantidad de dinero en tu cuenta es el…","explanation":"Balance = saldo."}}},{"id":"5","question":"Take money out of your account is…","options":["deposit","save","transfer in","withdraw"],"correct":3,"explanation":"Withdraw = retirar. Deposit = depositar.","translations":{"es":{"question":"Sacar dinero de tu cuenta es…","explanation":"Withdraw = retirar. Deposit = depositar."}}},{"id":"6","question":"Someone on the phone says he''s from your bank and asks for your PIN. You should…","options":["give it if he''s polite","send it by text","give half of it","never give it and hang up"],"correct":3,"explanation":"Banks never ask for your PIN.","translations":{"es":{"question":"Alguien por teléfono dice que es de tu banco y te pide el NIP. Debes…","explanation":"Los bancos nunca piden tu NIP."}}},{"id":"7","question":"Complete: \"If you open an account today, you ___ a free card.\"","options":["would got","get will","getting","will get"],"correct":3,"explanation":"Result clause → will + verb.","translations":{"es":{"question":"Completa: «If you open an account today, you ___ a free card.»","explanation":"Resultado → will + verbo."}}},{"id":"8","question":"The account for saving money is a…","options":["checking account","statement","loan","savings account"],"correct":3,"explanation":"Savings account = cuenta de ahorros.","translations":{"es":{"question":"La cuenta para ahorrar dinero es una…","explanation":"Savings account = cuenta de ahorros."}}}]}'::jsonb, 3),
  ('story', 'Carmen''s First Bank Account', '{"text":"Now that Carmen works at the bakery, she needs a bank account for her paychecks. She goes to the bank with her passport and a letter from Grace. \"Good morning. I''d like to open a checking account.\" \"Of course,\" says the woman at the desk. \"If you open it today, you''ll get a free debit card.\" \"Is there a monthly fee?\" \"There''s a ten-dollar fee unless you keep five hundred dollars in the account.\" Carmen thinks. \"And if I want to send money to my sister in Mexico?\" \"You can do it online. If you need help, you can come here and we''ll show you.\" Twenty minutes later, Carmen has her new card. \"Please choose a PIN. Don''t tell anyone.\" \"Not even my grandson?\" The woman laughs. \"Especially not your grandson!\" Carmen leaves the bank feeling very independent.","translation":"Ahora que Carmen trabaja en la panadería, necesita una cuenta bancaria para sus pagos. Va al banco con su pasaporte y una carta de Grace. «Buenos días. Quisiera abrir una cuenta de cheques.» «Claro», dice la mujer del escritorio. «Si la abre hoy, recibirá una tarjeta de débito gratis.» «¿Hay comisión mensual?» «Hay una comisión de diez dólares, a menos que mantenga quinientos dólares en la cuenta.» Carmen piensa. «¿Y si quiero mandar dinero a mi hermana en México?» «Lo puede hacer en línea. Si necesita ayuda, puede venir aquí y le enseñamos.» Veinte minutos después, Carmen tiene su tarjeta nueva. «Por favor, elija un NIP. No se lo diga a nadie.» «¿Ni a mi nieto?» La mujer se ríe. «¡Sobre todo a su nieto no!» Carmen sale del banco sintiéndose muy independiente.","translations":{"es":"Ahora que Carmen trabaja en la panadería, necesita una cuenta bancaria para sus pagos. Va al banco con su pasaporte y una carta de Grace. «Buenos días. Quisiera abrir una cuenta de cheques.» «Claro», dice la mujer del escritorio. «Si la abre hoy, recibirá una tarjeta de débito gratis.» «¿Hay comisión mensual?» «Hay una comisión de diez dólares, a menos que mantenga quinientos dólares en la cuenta.» Carmen piensa. «¿Y si quiero mandar dinero a mi hermana en México?» «Lo puede hacer en línea. Si necesita ayuda, puede venir aquí y le enseñamos.» Veinte minutos después, Carmen tiene su tarjeta nueva. «Por favor, elija un NIP. No se lo diga a nadie.» «¿Ni a mi nieto?» La mujer se ríe. «¡Sobre todo a su nieto no!» Carmen sale del banco sintiéndose muy independiente."},"highlighted_words":["bank account","paychecks","I''d like to open a checking account","If you open it today, you''ll get","debit card","monthly fee","unless","send money","If you need help","PIN"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","to","open","an","account"],"translation":"Quisiera abrir una cuenta.","translations":{"es":"Quisiera abrir una cuenta."}},{"words":["If","you","lose","your","card","call","the","bank"],"translation":"Si pierdes tu tarjeta, llama al banco.","translations":{"es":"Si pierdes tu tarjeta, llama al banco."}},{"words":["Is","there","a","monthly","fee"],"translation":"¿Hay comisión mensual?","translations":{"es":"¿Hay comisión mensual?"}},{"words":["If","it","rains","I","will","stay","home"],"translation":"Si llueve, me quedo en casa.","translations":{"es":"Si llueve, me quedo en casa."}},{"words":["I","would","like","to","deposit","this","check"],"translation":"Quisiera depositar este cheque.","translations":{"es":"Quisiera depositar este cheque."}},{"words":["What","documents","do","I","need"],"translation":"¿Qué documentos necesito?","translations":{"es":"¿Qué documentos necesito?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Quisiera abrir una cuenta","translations":{"es":"Quisiera abrir una cuenta"},"answer":"I would like to open an account"},{"prompt":"¿Cuál es mi saldo?","translations":{"es":"¿Cuál es mi saldo?"},"answer":"What is my balance"},{"prompt":"Perdí mi tarjeta","translations":{"es":"Perdí mi tarjeta"},"answer":"I lost my card"},{"prompt":"Si tengo tiempo, te llamo","translations":{"es":"Si tengo tiempo, te llamo"},"answer":"If I have time, I will call you"},{"prompt":"¿Hay comisión?","translations":{"es":"¿Hay comisión?"},"answer":"Is there a fee"},{"prompt":"Quiero mandar dinero a México","translations":{"es":"Quiero mandar dinero a México"},"answer":"I want to send money to Mexico"}]}'::jsonb, 6)
) as v(type, title, content, ord);

