insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"doctor","translation":"médico","translations":{"es":"médico"}},{"id":"2","word":"nurse","translation":"enfermera","translations":{"es":"enfermera"}},{"id":"3","word":"patient","translation":"paciente","translations":{"es":"paciente"}},{"id":"4","word":"appointment","translation":"cita","translations":{"es":"cita"}},{"id":"5","word":"symptoms","translation":"síntomas","translations":{"es":"síntomas"}},{"id":"6","word":"fever","translation":"fiebre","translations":{"es":"fiebre"}},{"id":"7","word":"cough","translation":"tos","translations":{"es":"tos"}},{"id":"8","word":"sore throat","translation":"dolor de garganta","translations":{"es":"dolor de garganta"}},{"id":"9","word":"dizzy","translation":"mareado","translations":{"es":"mareado"}},{"id":"10","word":"blood pressure","translation":"presión arterial","translations":{"es":"presión arterial"}},{"id":"11","word":"prescription","translation":"receta médica","translations":{"es":"receta médica"}},{"id":"12","word":"pill","translation":"pastilla","translations":{"es":"pastilla"}},{"id":"13","word":"pharmacy","translation":"farmacia","translations":{"es":"farmacia"}},{"id":"14","word":"check-up","translation":"chequeo","translations":{"es":"chequeo"}},{"id":"15","word":"insurance card","translation":"tarjeta del seguro","translations":{"es":"tarjeta del seguro"}},{"id":"16","word":"interpreter","translation":"intérprete","translations":{"es":"intérprete"}},{"id":"17","word":"emergency","translation":"emergencia","translations":{"es":"emergencia"}}],"grammar":[{"structure":"How long have you had…?","example":"How long have you had this cough? — For a week.","en":"Present perfect for symptoms up to now","es":"Presente perfecto para síntomas hasta ahora"},{"structure":"I''ve had … since …","example":"I''ve had a headache since Monday.","en":"Describing how long a problem has lasted","es":"Decir desde cuándo tienes un problema"},{"structure":"should / shouldn''t (advice)","example":"You should rest. You shouldn''t eat spicy food.","en":"The doctor''s advice","es":"Los consejos del médico"},{"structure":"Take … times a day","example":"Take one pill twice a day with food.","en":"Medicine instructions","es":"Instrucciones de medicamentos"},{"structure":"It hurts when I…","example":"It hurts when I walk.","en":"Describing pain more precisely","es":"Describir el dolor con precisión"}],"tips":[{"en":"You have the right to a medical interpreter in most US clinics and hospitals. Ask: \"I need a Spanish interpreter, please.\"","es":"En la mayoría de las clínicas y hospitales de Estados Unidos tienes derecho a un intérprete médico. Pide: «I need a Spanish interpreter, please.»"},{"en":"Bring a list of your medicines and allergies to every appointment.","es":"Lleva a cada cita una lista de tus medicinas y alergias."},{"en":"\"Prescription\" = receta médica. You pick up the medicine at the pharmacy.","es":"«Prescription» = receta médica. La medicina se recoge en la farmacia."},{"en":"In an emergency, call 911. For non-urgent problems, an \"urgent care\" clinic is faster than the ER.","es":"En una emergencia, llama al 911. Para problemas no graves, una clínica de «urgent care» es más rápida que la sala de emergencias."},{"en":"\"Over-the-counter\" medicine is medicine you can buy without a prescription.","es":"Los medicamentos «over-the-counter» son los que se compran sin receta."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I have an appointment at ten.","translation":"Tengo cita a las diez.","translations":{"es":"Tengo cita a las diez."}},{"phrase":"What brings you here today?","translation":"¿Qué la trae por aquí hoy?","translations":{"es":"¿Qué la trae por aquí hoy?"}},{"phrase":"I''ve had a cough for a week.","translation":"Tengo tos desde hace una semana.","translations":{"es":"Tengo tos desde hace una semana."}},{"phrase":"How long have you had this pain?","translation":"¿Desde cuándo tiene este dolor?","translations":{"es":"¿Desde cuándo tiene este dolor?"}},{"phrase":"It hurts when I breathe.","translation":"Me duele cuando respiro.","translations":{"es":"Me duele cuando respiro."}},{"phrase":"I feel dizzy.","translation":"Me siento mareada.","translations":{"es":"Me siento mareada."}},{"phrase":"Are you allergic to any medicine?","translation":"¿Es alérgica a alguna medicina?","translations":{"es":"¿Es alérgica a alguna medicina?"}},{"phrase":"Take one pill twice a day.","translation":"Tome una pastilla dos veces al día.","translations":{"es":"Tome una pastilla dos veces al día."}},{"phrase":"You should rest and drink fluids.","translation":"Debería descansar y tomar líquidos.","translations":{"es":"Debería descansar y tomar líquidos."}},{"phrase":"I need a Spanish interpreter, please.","translation":"Necesito un intérprete de español, por favor.","translations":{"es":"Necesito un intérprete de español, por favor."}},{"phrase":"Here''s your prescription.","translation":"Aquí está su receta.","translations":{"es":"Aquí está su receta."}},{"phrase":"Come back if you don''t feel better.","translation":"Regrese si no se siente mejor.","translations":{"es":"Regrese si no se siente mejor."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct question.","options":["How long have you had this cough?","How long you had this cough?","Since when you have this cough?","How long do you have this cough?"],"correct":0,"explanation":"Duration up to now → present perfect.","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Duración hasta ahora → presente perfecto."}}},{"id":"2","question":"How do you say \"Tengo fiebre desde ayer\"?","options":["I''m having fever since yesterday.","I''ve had a fever since yesterday.","I had a fever for yesterday.","I have a fever since yesterday."],"correct":1,"explanation":"Present perfect + since.","translations":{"es":{"question":"¿Cómo se dice «Tengo fiebre desde ayer»?","explanation":"Presente perfecto + since."}}},{"id":"3","question":"\"Take one pill twice a day\" means…","options":["one pill, two times a day","two pills, twice a day","one pill every two days","two pills, once a day"],"correct":0,"explanation":"Twice = two times.","translations":{"es":{"question":"«Take one pill twice a day» significa…","explanation":"Twice = dos veces."}}},{"id":"4","question":"The paper from the doctor for your medicine is a…","options":["description","subscription","prescription","receipt"],"correct":2,"explanation":"Prescription = receta médica.","translations":{"es":{"question":"El papel del médico para tu medicina es una…","explanation":"Prescription = receta médica."}}},{"id":"5","question":"You don''t understand the doctor well. You can say:","options":["Take two pills.","Here''s your prescription.","I need a Spanish interpreter, please.","I''m dizzy, goodbye."],"correct":2,"explanation":"You can ask for a medical interpreter.","translations":{"es":{"question":"No le entiendes bien al médico. Puedes decir:","explanation":"Puedes pedir un intérprete médico."}}},{"id":"6","question":"The doctor gives advice: rest. Complete: \"You ___ rest.\"","options":["are","don''t have to","should","mustn''t"],"correct":2,"explanation":"Advice → should.","translations":{"es":{"question":"El médico da un consejo: descansar. Completa: «You ___ rest.»","explanation":"Consejo → should."}}},{"id":"7","question":"In a serious emergency in the US, you call…","options":["311","100","911","411"],"correct":2,"explanation":"911 is the emergency number.","translations":{"es":{"question":"En una emergencia grave en Estados Unidos, llamas al…","explanation":"911 es el número de emergencias."}}},{"id":"8","question":"\"I feel dizzy\" means…","options":["Tengo frío.","Me siento mareada.","Estoy aburrida.","Tengo hambre."],"correct":1,"explanation":"Dizzy = mareado.","translations":{"es":{"question":"«I feel dizzy» significa…","explanation":"Dizzy = mareado."}}}]}'::jsonb, 3),
  ('story', 'A Check-up', '{"text":"Carmen has had a cough for two weeks, and sometimes she feels dizzy. Laura makes an appointment at the clinic. \"Good morning. I have an appointment at ten. Here''s my insurance card.\" The nurse checks her blood pressure. \"It''s a little high. The doctor will see you now.\" Dr. Martínez is friendly. \"What brings you here today?\" \"I''ve had a cough since the beginning of the month. And it hurts when I breathe deeply.\" \"Do you have a fever?\" \"No, I don''t.\" \"Are you allergic to any medicine?\" \"Yes, to penicillin.\" The doctor listens to her chest. \"It''s a small infection. Take one pill twice a day for seven days. You should rest, drink fluids and you shouldn''t work this Saturday.\" \"No tamales this week?\" \"No tamales. Doctor''s orders.\" Carmen laughs and coughs at the same time.","translation":"Carmen tiene tos desde hace dos semanas y a veces se siente mareada. Laura le hace una cita en la clínica. «Buenos días. Tengo cita a las diez. Aquí está mi tarjeta del seguro.» La enfermera le toma la presión. «Está un poco alta. El doctor la va a ver ahora.» El doctor Martínez es amable. «¿Qué la trae por aquí hoy?» «Tengo tos desde principios de mes. Y me duele cuando respiro hondo.» «¿Tiene fiebre?» «No.» «¿Es alérgica a alguna medicina?» «Sí, a la penicilina.» El doctor le escucha el pecho. «Es una infección pequeña. Tome una pastilla dos veces al día durante siete días. Debería descansar, tomar líquidos y no debería trabajar este sábado.» «¿Sin tamales esta semana?» «Sin tamales. Órdenes del doctor.» Carmen se ríe y tose al mismo tiempo.","translations":{"es":"Carmen tiene tos desde hace dos semanas y a veces se siente mareada. Laura le hace una cita en la clínica. «Buenos días. Tengo cita a las diez. Aquí está mi tarjeta del seguro.» La enfermera le toma la presión. «Está un poco alta. El doctor la va a ver ahora.» El doctor Martínez es amable. «¿Qué la trae por aquí hoy?» «Tengo tos desde principios de mes. Y me duele cuando respiro hondo.» «¿Tiene fiebre?» «No.» «¿Es alérgica a alguna medicina?» «Sí, a la penicilina.» El doctor le escucha el pecho. «Es una infección pequeña. Tome una pastilla dos veces al día durante siete días. Debería descansar, tomar líquidos y no debería trabajar este sábado.» «¿Sin tamales esta semana?» «Sin tamales. Órdenes del doctor.» Carmen se ríe y tose al mismo tiempo."},"highlighted_words":["has had a cough for two weeks","dizzy","appointment","insurance card","nurse","blood pressure","What brings you here today","I''ve had a cough since","it hurts when I breathe","fever","Are you allergic to any medicine","Take one pill twice a day","You should rest","you shouldn''t work"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","have","had","a","cough","for","a","week"],"translation":"Tengo tos desde hace una semana.","translations":{"es":"Tengo tos desde hace una semana."}},{"words":["How","long","have","you","had","this","pain"],"translation":"¿Desde cuándo tiene este dolor?","translations":{"es":"¿Desde cuándo tiene este dolor?"}},{"words":["It","hurts","when","I","breathe"],"translation":"Me duele cuando respiro.","translations":{"es":"Me duele cuando respiro."}},{"words":["Take","one","pill","twice","a","day"],"translation":"Tome una pastilla dos veces al día.","translations":{"es":"Tome una pastilla dos veces al día."}},{"words":["You","should","rest","and","drink","fluids"],"translation":"Debería descansar y tomar líquidos.","translations":{"es":"Debería descansar y tomar líquidos."}},{"words":["I","need","a","Spanish","interpreter","please"],"translation":"Necesito un intérprete de español, por favor.","translations":{"es":"Necesito un intérprete de español, por favor."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Tengo cita a las diez","translations":{"es":"Tengo cita a las diez"},"answer":"I have an appointment at ten"},{"prompt":"Tengo fiebre desde el lunes","translations":{"es":"Tengo fiebre desde el lunes"},"answer":"I have had a fever since Monday"},{"prompt":"Me siento mareada","translations":{"es":"Me siento mareada"},"answer":"I feel dizzy"},{"prompt":"Soy alérgica a la penicilina","translations":{"es":"Soy alérgica a la penicilina"},"answer":"I am allergic to penicillin"},{"prompt":"Aquí está mi tarjeta del seguro","translations":{"es":"Aquí está mi tarjeta del seguro"},"answer":"Here is my insurance card"},{"prompt":"Me duele cuando camino","translations":{"es":"Me duele cuando camino"},"answer":"It hurts when I walk"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 50: At the post office
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-50', 'At the post office', '✉️', 'En la oficina de correos', 50, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"post office","translation":"oficina de correos","translations":{"es":"oficina de correos"}},{"id":"2","word":"mail","translation":"correo","translations":{"es":"correo"}},{"id":"3","word":"letter","translation":"carta","translations":{"es":"carta"}},{"id":"4","word":"package","translation":"paquete","translations":{"es":"paquete"}},{"id":"5","word":"envelope","translation":"sobre","translations":{"es":"sobre"}},{"id":"6","word":"stamp","translation":"estampilla / timbre","translations":{"es":"estampilla / timbre"}},{"id":"7","word":"address","translation":"dirección","translations":{"es":"dirección"}},{"id":"8","word":"ZIP code","translation":"código postal","translations":{"es":"código postal"}},{"id":"9","word":"sender","translation":"remitente","translations":{"es":"remitente"}},{"id":"10","word":"recipient","translation":"destinatario","translations":{"es":"destinatario"}},{"id":"11","word":"tracking number","translation":"número de rastreo","translations":{"es":"número de rastreo"}},{"id":"12","word":"customs form","translation":"formulario de aduana","translations":{"es":"formulario de aduana"}},{"id":"13","word":"fragile","translation":"frágil","translations":{"es":"frágil"}},{"id":"14","word":"deliver","translation":"entregar","translations":{"es":"entregar"}},{"id":"15","word":"weigh","translation":"pesar","translations":{"es":"pesar"}},{"id":"16","word":"express","translation":"exprés / urgente","translations":{"es":"exprés / urgente"}},{"id":"17","word":"mailbox","translation":"buzón","translations":{"es":"buzón"}}],"grammar":[{"structure":"is / are + past participle","example":"Letters are delivered every day.","en":"Present passive","es":"Voz pasiva en presente"},{"structure":"was / were + past participle","example":"The package was sent on Monday.","en":"Past passive","es":"Voz pasiva en pasado"},{"structure":"will be + past participle","example":"It will be delivered in five days.","en":"Future passive","es":"Voz pasiva en futuro"},{"structure":"passive + by","example":"The box was packed by Leo.","en":"Saying who did the action","es":"Decir quién hizo la acción"},{"structure":"How long will it take to arrive?","example":"How long will it take to get to Mexico?","en":"Asking about delivery time","es":"Preguntar el tiempo de entrega"}],"tips":[{"en":"We use the passive when the action matters more than who does it: \"The package was delivered.\"","es":"Se usa la voz pasiva cuando importa más la acción que quién la hace: «The package was delivered»."},{"en":"The passive often translates to Spanish with \"se\": \"English is spoken here\" = Aquí se habla inglés.","es":"La pasiva suele traducirse al español con «se»: «English is spoken here» = Aquí se habla inglés."},{"en":"For international packages you must fill out a customs form describing what''s inside.","es":"Para paquetes internacionales hay que llenar un formulario de aduana que describa el contenido."},{"en":"A \"tracking number\" lets you follow your package online.","es":"El «tracking number» (número de rastreo) te permite seguir tu paquete en línea."},{"en":"ZIP codes in the US have 5 digits. Always include them in the address.","es":"Los códigos postales (ZIP codes) en Estados Unidos tienen 5 dígitos. Inclúyelos siempre en la dirección."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to send this package to Mexico.","translation":"Quisiera mandar este paquete a México.","translations":{"es":"Quisiera mandar este paquete a México."}},{"phrase":"How much does it cost to send it?","translation":"¿Cuánto cuesta mandarlo?","translations":{"es":"¿Cuánto cuesta mandarlo?"}},{"phrase":"Let me weigh it.","translation":"Déjeme pesarlo.","translations":{"es":"Déjeme pesarlo."}},{"phrase":"You need to fill out this customs form.","translation":"Necesita llenar este formulario de aduana.","translations":{"es":"Necesita llenar este formulario de aduana."}},{"phrase":"What''s inside the package?","translation":"¿Qué hay dentro del paquete?","translations":{"es":"¿Qué hay dentro del paquete?"}},{"phrase":"It''s fragile.","translation":"Es frágil.","translations":{"es":"Es frágil."}},{"phrase":"How long will it take to arrive?","translation":"¿Cuánto tarda en llegar?","translations":{"es":"¿Cuánto tarda en llegar?"}},{"phrase":"It will be delivered in a week.","translation":"Será entregado en una semana.","translations":{"es":"Será entregado en una semana."}},{"phrase":"Here''s your tracking number.","translation":"Aquí está su número de rastreo.","translations":{"es":"Aquí está su número de rastreo."}},{"phrase":"Can I buy some stamps?","translation":"¿Puedo comprar unas estampillas?","translations":{"es":"¿Puedo comprar unas estampillas?"}},{"phrase":"Your package was delivered!","translation":"¡Tu paquete fue entregado!","translations":{"es":"¡Tu paquete fue entregado!"}},{"phrase":"Is this the right ZIP code?","translation":"¿Este es el código postal correcto?","translations":{"es":"¿Este es el código postal correcto?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"The package ___ yesterday.\"","options":["was delivered","were delivered","delivered was","is deliver"],"correct":0,"explanation":"Past passive: was + past participle.","translations":{"es":{"question":"Completa: «The package ___ yesterday.»","explanation":"Pasiva en pasado: was + participio."}}},{"id":"2","question":"Complete: \"Letters ___ every day.\"","options":["are deliver","are delivered","is delivered","delivered are"],"correct":1,"explanation":"Plural present passive: are + past participle.","translations":{"es":{"question":"Completa: «Letters ___ every day.»","explanation":"Pasiva presente en plural: are + participio."}}},{"id":"3","question":"How do you say \"Aquí se habla español\"?","options":["Here is spoke Spanish.","Spanish is spoken here.","Here speaks Spanish.","Spanish speaks here."],"correct":1,"explanation":"The passive: is spoken.","translations":{"es":{"question":"¿Cómo se dice «Aquí se habla español»?","explanation":"La pasiva: is spoken."}}},{"id":"4","question":"Complete: \"It ___ delivered next Monday.\"","options":["will be","will","was","is being will"],"correct":0,"explanation":"Future passive: will be + past participle.","translations":{"es":{"question":"Completa: «It ___ delivered next Monday.»","explanation":"Pasiva futura: will be + participio."}}},{"id":"5","question":"The number to follow your package online is the…","options":["ZIP code","tracking number","PIN","stamp"],"correct":1,"explanation":"Tracking number = número de rastreo.","translations":{"es":{"question":"El número para seguir tu paquete en línea es el…","explanation":"Tracking number = número de rastreo."}}},{"id":"6","question":"The person who sends a letter is the…","options":["recipient","sender","carrier bag","mailbox"],"correct":1,"explanation":"Sender = remitente. Recipient = destinatario.","translations":{"es":{"question":"La persona que manda una carta es el…","explanation":"Sender = remitente. Recipient = destinatario."}}},{"id":"7","question":"Complete: \"The box was packed ___ Leo.\"","options":["by","from","with","of"],"correct":0,"explanation":"Passive + by + who did it.","translations":{"es":{"question":"Completa: «The box was packed ___ Leo.»","explanation":"Pasiva + by + quién lo hizo."}}},{"id":"8","question":"Glasses and plates in a box are…","options":["delivered","express","fragile","heavy-duty"],"correct":2,"explanation":"Fragile = can break easily.","translations":{"es":{"question":"Vasos y platos en una caja son…","explanation":"Fragile = se puede romper fácilmente."}}}]}'::jsonb, 3),
  ('story', 'A Box for Rosa', '{"text":"Rosa''s birthday is in two weeks. Carmen wants to send her a box from San Diego: a scarf, chocolates and a photo of the family. The box is packed by Leo very carefully. At the post office, the clerk weighs it. \"It''s four pounds. Where is it going?\" \"To Guadalajara, Mexico.\" \"You need to fill out this customs form. What''s inside?\" \"A scarf, chocolates and a photo. And the photo frame is fragile.\" \"Okay. With express mail, it will be delivered in five days. With regular mail, two weeks.\" \"Express, please. Her birthday is soon!\" \"Here''s your tracking number.\" Every day Carmen checks it on her phone. On the fifth day, a message appears: \"Your package was delivered.\" That evening, Rosa calls on video, wearing the scarf. \"Carmen! The photo was the best present.\"","translation":"El cumpleaños de Rosa es en dos semanas. Carmen quiere mandarle una caja desde San Diego: una bufanda, chocolates y una foto de la familia. Leo empaca la caja con mucho cuidado. En la oficina de correos, el empleado la pesa. «Son cuatro libras. ¿A dónde va?» «A Guadalajara, México.» «Necesita llenar este formulario de aduana. ¿Qué hay dentro?» «Una bufanda, chocolates y una foto. Y el marco de la foto es frágil.» «Bueno. Por correo exprés, será entregado en cinco días. Por correo normal, dos semanas.» «Exprés, por favor. ¡Su cumpleaños es pronto!» «Aquí está su número de rastreo.» Todos los días Carmen lo revisa en su teléfono. El quinto día aparece un mensaje: «Su paquete fue entregado.» Esa noche, Rosa llama por video con la bufanda puesta. «¡Carmen! La foto fue el mejor regalo.»","translations":{"es":"El cumpleaños de Rosa es en dos semanas. Carmen quiere mandarle una caja desde San Diego: una bufanda, chocolates y una foto de la familia. Leo empaca la caja con mucho cuidado. En la oficina de correos, el empleado la pesa. «Son cuatro libras. ¿A dónde va?» «A Guadalajara, México.» «Necesita llenar este formulario de aduana. ¿Qué hay dentro?» «Una bufanda, chocolates y una foto. Y el marco de la foto es frágil.» «Bueno. Por correo exprés, será entregado en cinco días. Por correo normal, dos semanas.» «Exprés, por favor. ¡Su cumpleaños es pronto!» «Aquí está su número de rastreo.» Todos los días Carmen lo revisa en su teléfono. El quinto día aparece un mensaje: «Su paquete fue entregado.» Esa noche, Rosa llama por video con la bufanda puesta. «¡Carmen! La foto fue el mejor regalo.»"},"highlighted_words":["The box is packed by Leo","post office","weighs","customs form","fragile","express mail","it will be delivered","tracking number","Your package was delivered"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","to","send","this","package"],"translation":"Quisiera mandar este paquete.","translations":{"es":"Quisiera mandar este paquete."}},{"words":["The","letter","was","sent","on","Monday"],"translation":"La carta fue enviada el lunes.","translations":{"es":"La carta fue enviada el lunes."}},{"words":["It","will","be","delivered","in","five","days"],"translation":"Será entregado en cinco días.","translations":{"es":"Será entregado en cinco días."}},{"words":["Spanish","is","spoken","here"],"translation":"Aquí se habla español.","translations":{"es":"Aquí se habla español."}},{"words":["You","need","to","fill","out","this","form"],"translation":"Necesita llenar este formulario.","translations":{"es":"Necesita llenar este formulario."}},{"words":["How","long","will","it","take","to","arrive"],"translation":"¿Cuánto tarda en llegar?","translations":{"es":"¿Cuánto tarda en llegar?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Su paquete fue entregado","translations":{"es":"Su paquete fue entregado"},"answer":"Your package was delivered"},{"prompt":"Es frágil","translations":{"es":"Es frágil"},"answer":"It is fragile"},{"prompt":"¿Puedo comprar unas estampillas?","translations":{"es":"¿Puedo comprar unas estampillas?"},"answer":"Can I buy some stamps"},{"prompt":"Aquí se habla inglés","translations":{"es":"Aquí se habla inglés"},"answer":"English is spoken here"},{"prompt":"Aquí está su número de rastreo","translations":{"es":"Aquí está su número de rastreo"},"answer":"Here is your tracking number"},{"prompt":"La caja fue empacada por mi nieto","translations":{"es":"La caja fue empacada por mi nieto"},"answer":"The box was packed by my grandson"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 51: On a cruise
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-51', 'On a cruise', '🛳️', 'En un crucero', 51, true)
