insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"cruise","translation":"crucero","translations":{"es":"crucero"}},{"id":"2","word":"ship","translation":"barco","translations":{"es":"barco"}},{"id":"3","word":"deck","translation":"cubierta","translations":{"es":"cubierta"}},{"id":"4","word":"cabin","translation":"camarote","translations":{"es":"camarote"}},{"id":"5","word":"port","translation":"puerto","translations":{"es":"puerto"}},{"id":"6","word":"captain","translation":"capitán","translations":{"es":"capitán"}},{"id":"7","word":"crew","translation":"tripulación","translations":{"es":"tripulación"}},{"id":"8","word":"sail","translation":"navegar / zarpar","translations":{"es":"navegar / zarpar"}},{"id":"9","word":"board","translation":"abordar","translations":{"es":"abordar"}},{"id":"10","word":"seasick","translation":"mareado (en barco)","translations":{"es":"mareado (en barco)"}},{"id":"11","word":"life jacket","translation":"chaleco salvavidas","translations":{"es":"chaleco salvavidas"}},{"id":"12","word":"sunset","translation":"puesta de sol","translations":{"es":"puesta de sol"}},{"id":"13","word":"dolphins","translation":"delfines","translations":{"es":"delfines"}},{"id":"14","word":"whale","translation":"ballena","translations":{"es":"ballena"}},{"id":"15","word":"shore excursion","translation":"excursión en tierra","translations":{"es":"excursión en tierra"}},{"id":"16","word":"buffet","translation":"bufé","translations":{"es":"bufé"}},{"id":"17","word":"horizon","translation":"horizonte","translations":{"es":"horizonte"}}],"grammar":[{"structure":"present continuous for future arrangements","example":"We''re leaving on Friday. We''re arriving in Ensenada on Saturday.","en":"Fixed plans with a date or time","es":"Planes fijos con fecha u hora"},{"structure":"going to vs. present continuous","example":"I''m going to relax. / We''re sailing at five.","en":"Intention vs. arrangement","es":"Intención vs. plan acordado"},{"structure":"What are you doing this weekend?","example":"What are you doing on Saturday? — I''m visiting my sister.","en":"Asking about plans","es":"Preguntar por planes"},{"structure":"on board / on deck","example":"There''s a pool on deck.","en":"Expressions on a ship","es":"Expresiones en un barco"},{"structure":"feel seasick","example":"I feel a little seasick.","en":"Talking about seasickness","es":"Hablar del mareo en el barco"}],"tips":[{"en":"The present continuous can talk about the future when the plan is fixed: \"I''m meeting Linda at six.\"","es":"El presente continuo puede hablar del futuro cuando el plan está fijo: «I''m meeting Linda at six.»"},{"en":"Short cruises from San Diego to Ensenada are popular weekend trips.","es":"Los cruceros cortos de San Diego a Ensenada son paseos de fin de semana muy populares."},{"en":"If you get seasick, stay in the middle of the ship and look at the horizon.","es":"Si te mareas, quédate en el centro del barco y mira el horizonte."},{"en":"\"Shore excursion\" is a tour you take when the ship stops at a port.","es":"Una «shore excursion» es un recorrido que haces cuando el barco para en un puerto."},{"en":"\"Bon voyage!\" (from French) is used in English to wish someone a good trip.","es":"«Bon voyage!» (del francés) se usa en inglés para desear buen viaje."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"We''re leaving on Friday.","translation":"Salimos el viernes.","translations":{"es":"Salimos el viernes."}},{"phrase":"What are you doing this weekend?","translation":"¿Qué vas a hacer este fin de semana?","translations":{"es":"¿Qué vas a hacer este fin de semana?"}},{"phrase":"I''m going on a cruise!","translation":"¡Me voy de crucero!","translations":{"es":"¡Me voy de crucero!"}},{"phrase":"Where is our cabin?","translation":"¿Dónde está nuestro camarote?","translations":{"es":"¿Dónde está nuestro camarote?"}},{"phrase":"The ship sails at five.","translation":"El barco zarpa a las cinco.","translations":{"es":"El barco zarpa a las cinco."}},{"phrase":"Let''s go up on deck.","translation":"Subamos a la cubierta.","translations":{"es":"Subamos a la cubierta."}},{"phrase":"I feel a little seasick.","translation":"Estoy un poco mareada.","translations":{"es":"Estoy un poco mareada."}},{"phrase":"Look, dolphins!","translation":"¡Mira, delfines!","translations":{"es":"¡Mira, delfines!"}},{"phrase":"What a beautiful sunset!","translation":"¡Qué puesta de sol tan bonita!","translations":{"es":"¡Qué puesta de sol tan bonita!"}},{"phrase":"We''re arriving in Ensenada tomorrow.","translation":"Llegamos a Ensenada mañana.","translations":{"es":"Llegamos a Ensenada mañana."}},{"phrase":"Are you doing a shore excursion?","translation":"¿Van a hacer una excursión en tierra?","translations":{"es":"¿Van a hacer una excursión en tierra?"}},{"phrase":"Bon voyage!","translation":"¡Buen viaje!","translations":{"es":"¡Buen viaje!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which sentence describes a fixed arrangement?","options":["We''re sailing at five tomorrow.","We sailing tomorrow.","We sail yesterday.","We are sail at five."],"correct":0,"explanation":"Present continuous for arrangements: we''re sailing.","translations":{"es":{"question":"¿Qué oración describe un plan fijo?","explanation":"Presente continuo para planes fijos: we''re sailing."}}},{"id":"2","question":"Choose the correct question about plans.","options":["What you are doing on Saturday?","What are you doing on Saturday?","What do you doing on Saturday?","What are you do on Saturday?"],"correct":1,"explanation":"What + are you + verb-ing?","translations":{"es":{"question":"Elige la pregunta correcta sobre planes.","explanation":"What + are you + verbo-ing?"}}},{"id":"3","question":"Your room on a ship is a…","options":["deck","cabin","port","crew"],"correct":1,"explanation":"Cabin = camarote.","translations":{"es":{"question":"Tu cuarto en un barco es un…","explanation":"Cabin = camarote."}}},{"id":"4","question":"You feel sick because of the movement of the ship. You are…","options":["seasick","homesick","carsick only","sunburned"],"correct":0,"explanation":"Seasick = mareado en el mar.","translations":{"es":{"question":"Te sientes mal por el movimiento del barco. Estás…","explanation":"Seasick = mareado en el mar."}}},{"id":"5","question":"The open floor outside on top of the ship is the…","options":["cabin","deck","buffet","captain"],"correct":1,"explanation":"Deck = cubierta.","translations":{"es":{"question":"El piso exterior en la parte de arriba del barco es la…","explanation":"Deck = cubierta."}}},{"id":"6","question":"All the people who work on a ship are the…","options":["cruise","port","crew","shore"],"correct":2,"explanation":"Crew = tripulación.","translations":{"es":{"question":"Todas las personas que trabajan en un barco son la…","explanation":"Crew = tripulación."}}},{"id":"7","question":"Your friend is going on a trip. You say:","options":["Happy anniversary!","Get well soon!","Bon voyage!","Good night!"],"correct":2,"explanation":"Bon voyage = have a good trip.","translations":{"es":{"question":"Tu amiga se va de viaje. Le dices:","explanation":"Bon voyage = buen viaje."}}},{"id":"8","question":"Complete: \"I''m ___ Linda at six tomorrow.\" (it''s arranged)","options":["met","meet","meeting","to meet"],"correct":2,"explanation":"Arrangement → present continuous: I''m meeting.","translations":{"es":{"question":"Completa: «I''m ___ Linda at six tomorrow.» (está acordado)","explanation":"Plan acordado → presente continuo: I''m meeting."}}}]}'::jsonb, 3),
  ('story', 'Three Days at Sea', '{"text":"Linda has a surprise for Carmen''s birthday: two tickets for a short cruise. \"We''re leaving on Friday at five and we''re arriving in Ensenada on Saturday morning!\" Carmen can''t believe it. \"Ensenada? I''m going to Mexico on a ship!\" On Friday they board the ship. Their cabin is small but it has a round window. \"Let''s go up on deck,\" says Linda. The ship sails out of the port and San Diego gets smaller. At sunset, someone shouts, \"Look, dolphins!\" Ten dolphins are jumping next to the ship. That night, the sea is rough and Carmen feels a little seasick. A member of the crew gives her some crackers. \"Stay in the middle of the ship and look at the horizon.\" On Saturday, they''re doing a shore excursion: fish tacos and a walk by the sea. \"Linda,\" says Carmen, \"this is the best birthday present ever.\"","translation":"Linda tiene una sorpresa para el cumpleaños de Carmen: dos boletos para un crucero corto. «¡Salimos el viernes a las cinco y llegamos a Ensenada el sábado en la mañana!» Carmen no lo puede creer. «¿Ensenada? ¡Voy a ir a México en barco!» El viernes abordan el barco. Su camarote es pequeño, pero tiene una ventana redonda. «Subamos a la cubierta», dice Linda. El barco zarpa del puerto y San Diego se hace más pequeño. En la puesta de sol, alguien grita: «¡Miren, delfines!» Diez delfines saltan junto al barco. Esa noche el mar está agitado y Carmen se marea un poco. Alguien de la tripulación le da unas galletas saladas. «Quédese en el centro del barco y mire el horizonte.» El sábado van a hacer una excursión en tierra: tacos de pescado y un paseo junto al mar. «Linda», dice Carmen, «este es el mejor regalo de cumpleaños de mi vida.»","translations":{"es":"Linda tiene una sorpresa para el cumpleaños de Carmen: dos boletos para un crucero corto. «¡Salimos el viernes a las cinco y llegamos a Ensenada el sábado en la mañana!» Carmen no lo puede creer. «¿Ensenada? ¡Voy a ir a México en barco!» El viernes abordan el barco. Su camarote es pequeño, pero tiene una ventana redonda. «Subamos a la cubierta», dice Linda. El barco zarpa del puerto y San Diego se hace más pequeño. En la puesta de sol, alguien grita: «¡Miren, delfines!» Diez delfines saltan junto al barco. Esa noche el mar está agitado y Carmen se marea un poco. Alguien de la tripulación le da unas galletas saladas. «Quédese en el centro del barco y mire el horizonte.» El sábado van a hacer una excursión en tierra: tacos de pescado y un paseo junto al mar. «Linda», dice Carmen, «este es el mejor regalo de cumpleaños de mi vida.»"},"highlighted_words":["cruise","We''re leaving on Friday","we''re arriving in Ensenada","board the ship","cabin","Let''s go up on deck","sails","port","sunset","dolphins","seasick","crew","horizon","they''re doing a shore excursion"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["We","are","leaving","on","Friday"],"translation":"Salimos el viernes.","translations":{"es":"Salimos el viernes."}},{"words":["What","are","you","doing","this","weekend"],"translation":"¿Qué vas a hacer este fin de semana?","translations":{"es":"¿Qué vas a hacer este fin de semana?"}},{"words":["The","ship","sails","at","five"],"translation":"El barco zarpa a las cinco.","translations":{"es":"El barco zarpa a las cinco."}},{"words":["I","feel","a","little","seasick"],"translation":"Estoy un poco mareada.","translations":{"es":"Estoy un poco mareada."}},{"words":["Let''s","go","up","on","deck"],"translation":"Subamos a la cubierta.","translations":{"es":"Subamos a la cubierta."}},{"words":["We","are","arriving","in","Ensenada","tomorrow"],"translation":"Llegamos a Ensenada mañana.","translations":{"es":"Llegamos a Ensenada mañana."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Me voy de crucero","translations":{"es":"Me voy de crucero"},"answer":"I am going on a cruise"},{"prompt":"¿Dónde está nuestro camarote?","translations":{"es":"¿Dónde está nuestro camarote?"},"answer":"Where is our cabin"},{"prompt":"Mira, delfines","translations":{"es":"Mira, delfines"},"answer":"Look, dolphins"},{"prompt":"¡Qué puesta de sol tan bonita!","translations":{"es":"¡Qué puesta de sol tan bonita!"},"answer":"What a beautiful sunset"},{"prompt":"Salimos mañana","translations":{"es":"Salimos mañana"},"answer":"We are leaving tomorrow"},{"prompt":"Estoy mareada","translations":{"es":"Estoy mareada"},"answer":"I feel seasick"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 52: Traveling by train
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-52', 'Traveling by train', '🚂', 'Viajar en tren', 52, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"train station","translation":"estación de tren","translations":{"es":"estación de tren"}},{"id":"2","word":"platform","translation":"andén","translations":{"es":"andén"}},{"id":"3","word":"track","translation":"vía","translations":{"es":"vía"}},{"id":"4","word":"timetable","translation":"horario","translations":{"es":"horario"}},{"id":"5","word":"conductor","translation":"revisor / conductor del tren","translations":{"es":"revisor / conductor del tren"}},{"id":"6","word":"car","translation":"vagón","translations":{"es":"vagón"}},{"id":"7","word":"leave","translation":"salir / partir","translations":{"es":"salir / partir"}},{"id":"8","word":"arrive","translation":"llegar","translations":{"es":"llegar"}},{"id":"9","word":"catch","translation":"alcanzar / tomar","translations":{"es":"alcanzar / tomar"}},{"id":"10","word":"miss","translation":"perder (el tren)","translations":{"es":"perder (el tren)"}},{"id":"11","word":"on time","translation":"a tiempo","translations":{"es":"a tiempo"}},{"id":"12","word":"delay","translation":"retraso","translations":{"es":"retraso"}},{"id":"13","word":"coast","translation":"costa","translations":{"es":"costa"}},{"id":"14","word":"scenery","translation":"paisaje","translations":{"es":"paisaje"}},{"id":"15","word":"luggage rack","translation":"portaequipajes","translations":{"es":"portaequipajes"}},{"id":"16","word":"stop","translation":"parada","translations":{"es":"parada"}},{"id":"17","word":"round trip","translation":"viaje redondo","translations":{"es":"viaje redondo"}}],"grammar":[{"structure":"What time does … leave / arrive?","example":"What time does the train to Los Angeles leave?","en":"Present simple for timetables","es":"Presente simple para horarios"},{"structure":"at / on / in for time","example":"at 9:15, on Tuesday, in the morning","en":"Prepositions of time (review)","es":"Preposiciones de tiempo (repaso)"},{"structure":"from … to …","example":"The train goes from San Diego to Los Angeles.","en":"Routes","es":"Rutas"},{"structure":"Which platform…?","example":"Which platform does it leave from?","en":"Asking for the platform","es":"Preguntar por el andén"},{"structure":"miss / catch the train","example":"Hurry, or we''ll miss the train!","en":"Catching and missing transport","es":"Alcanzar y perder el transporte"}],"tips":[{"en":"Timetables use the present simple even for the future: \"The train leaves at 9:15 tomorrow.\"","es":"Los horarios usan el presente simple aunque hablen del futuro: «The train leaves at 9:15 tomorrow.»"},{"en":"The train from San Diego to Los Angeles runs along the coast — sit on the left side going north for ocean views.","es":"El tren de San Diego a Los Ángeles va por la costa: siéntate del lado izquierdo yendo al norte para ver el mar."},{"en":"\"Catch\" the train = llegar a tiempo; \"miss\" the train = perderlo.","es":"«Catch» the train = alcanzar el tren; «miss» the train = perderlo."},{"en":"Keep your ticket: the conductor will check it on board.","es":"Guarda tu boleto: el revisor lo va a verificar a bordo."},{"en":"\"All aboard!\" is what the conductor says before the train leaves.","es":"«All aboard!» es lo que dice el revisor antes de que salga el tren (¡todos a bordo!)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What time does the train leave?","translation":"¿A qué hora sale el tren?","translations":{"es":"¿A qué hora sale el tren?"}},{"phrase":"It leaves at nine fifteen.","translation":"Sale a las nueve y cuarto.","translations":{"es":"Sale a las nueve y cuarto."}},{"phrase":"What time does it arrive in Los Angeles?","translation":"¿A qué hora llega a Los Ángeles?","translations":{"es":"¿A qué hora llega a Los Ángeles?"}},{"phrase":"Which platform does it leave from?","translation":"¿De qué andén sale?","translations":{"es":"¿De qué andén sale?"}},{"phrase":"Platform two.","translation":"Andén dos.","translations":{"es":"Andén dos."}},{"phrase":"Is this the train to Los Angeles?","translation":"¿Este es el tren a Los Ángeles?","translations":{"es":"¿Este es el tren a Los Ángeles?"}},{"phrase":"Hurry, we''ll miss the train!","translation":"¡Apúrate, vamos a perder el tren!","translations":{"es":"¡Apúrate, vamos a perder el tren!"}},{"phrase":"We caught it just in time.","translation":"Lo alcanzamos justo a tiempo.","translations":{"es":"Lo alcanzamos justo a tiempo."}},{"phrase":"Tickets, please.","translation":"Boletos, por favor.","translations":{"es":"Boletos, por favor."}},{"phrase":"How many stops are there?","translation":"¿Cuántas paradas hay?","translations":{"es":"¿Cuántas paradas hay?"}},{"phrase":"The scenery is beautiful.","translation":"El paisaje es precioso.","translations":{"es":"El paisaje es precioso."}},{"phrase":"All aboard!","translation":"¡Todos a bordo!","translations":{"es":"¡Todos a bordo!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"The train ___ at 9:15 tomorrow.\" (timetable)","options":["leaves","will leaving","leaving","is leave"],"correct":0,"explanation":"Timetables use the present simple.","translations":{"es":{"question":"Completa: «The train ___ at 9:15 tomorrow.» (horario)","explanation":"Los horarios usan el presente simple."}}},{"id":"2","question":"Choose the correct question.","options":["What time is the train arrive?","What time does the train arrive?","What time does the train arrives?","What time the train arrives?"],"correct":1,"explanation":"What time does + subject + verb (no -s)?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"What time does + sujeto + verbo (sin -s)?"}}},{"id":"3","question":"Complete: \"The train leaves ___ Tuesday ___ the morning.\"","options":["on / at","on / in","at / in","in / on"],"correct":1,"explanation":"on + day, in + part of the day.","translations":{"es":{"question":"Completa: «The train leaves ___ Tuesday ___ the morning.»","explanation":"on + día, in + parte del día."}}},{"id":"4","question":"You arrive after the train left. You…","options":["boarded the train","left the train","missed the train","caught the train"],"correct":2,"explanation":"Miss = perder.","translations":{"es":{"question":"Llegas después de que salió el tren. Tú…","explanation":"Miss = perder."}}},{"id":"5","question":"The place where you wait for the train is the…","options":["gate","deck","platform","track"],"correct":2,"explanation":"Platform = andén.","translations":{"es":{"question":"El lugar donde esperas el tren es el…","explanation":"Platform = andén."}}},{"id":"6","question":"The person who checks tickets on the train is the…","options":["teller","pilot","conductor","captain"],"correct":2,"explanation":"Conductor = revisor.","translations":{"es":{"question":"La persona que revisa los boletos en el tren es el…","explanation":"Conductor = revisor."}}},{"id":"7","question":"\"We caught it just in time\" means…","options":["We arrived very early.","We canceled the trip.","We got on just before it left.","We missed it."],"correct":2,"explanation":"Catch = llegar a tiempo para tomarlo.","translations":{"es":{"question":"«We caught it just in time» significa…","explanation":"Catch = llegar a tiempo para tomarlo."}}},{"id":"8","question":"What do you see from the window: mountains, sea, fields. That''s the…","options":["scenery","luggage","track","timetable"],"correct":0,"explanation":"Scenery = paisaje.","translations":{"es":{"question":"Lo que ves por la ventana: montañas, mar, campos. Eso es el…","explanation":"Scenery = paisaje."}}}]}'::jsonb, 3),
  ('story', 'The Coast Train', '{"text":"Kenji invites Carmen and Leo to visit a Japanese garden in Los Angeles. They take the train. \"What time does the train leave?\" asks Carmen at the station. \"At nine fifteen from platform two,\" says the man at the ticket office. \"And what time does it arrive in Los Angeles?\" \"At twelve oh five.\" It''s nine ten, and they''re still buying coffee. \"Hurry, Grandma, we''ll miss the train!\" They run to platform two. The conductor shouts, \"All aboard!\" They catch it just in time. On the train, Leo sits by the window on the left side. The train goes along the coast, and the scenery is beautiful: the ocean, surfers and small beach towns. \"Tickets, please,\" says the conductor. Carmen shows the tickets. \"How many stops are there?\" \"Eight more. Enjoy the ride!\" Leo presses his face to the window. \"Grandma, this is better than a plane!\"","translation":"Kenji invita a Carmen y a Leo a visitar un jardín japonés en Los Ángeles. Van en tren. «¿A qué hora sale el tren?», pregunta Carmen en la estación. «A las nueve y cuarto, del andén dos», dice el señor de la taquilla. «¿Y a qué hora llega a Los Ángeles?» «A las doce y cinco.» Son las nueve y diez, y todavía están comprando café. «¡Apúrate, abuela, vamos a perder el tren!» Corren al andén dos. El revisor grita: «¡Todos a bordo!» Lo alcanzan justo a tiempo. En el tren, Leo se sienta junto a la ventana, del lado izquierdo. El tren va por la costa y el paisaje es precioso: el mar, surfistas y pueblitos de playa. «Boletos, por favor», dice el revisor. Carmen enseña los boletos. «¿Cuántas paradas hay?» «Ocho más. ¡Disfruten el viaje!» Leo pega la cara a la ventana. «¡Abuela, esto es mejor que el avión!»","translations":{"es":"Kenji invita a Carmen y a Leo a visitar un jardín japonés en Los Ángeles. Van en tren. «¿A qué hora sale el tren?», pregunta Carmen en la estación. «A las nueve y cuarto, del andén dos», dice el señor de la taquilla. «¿Y a qué hora llega a Los Ángeles?» «A las doce y cinco.» Son las nueve y diez, y todavía están comprando café. «¡Apúrate, abuela, vamos a perder el tren!» Corren al andén dos. El revisor grita: «¡Todos a bordo!» Lo alcanzan justo a tiempo. En el tren, Leo se sienta junto a la ventana, del lado izquierdo. El tren va por la costa y el paisaje es precioso: el mar, surfistas y pueblitos de playa. «Boletos, por favor», dice el revisor. Carmen enseña los boletos. «¿Cuántas paradas hay?» «Ocho más. ¡Disfruten el viaje!» Leo pega la cara a la ventana. «¡Abuela, esto es mejor que el avión!»"},"highlighted_words":["What time does the train leave","platform","what time does it arrive","we''ll miss the train","conductor","All aboard","catch it just in time","coast","scenery","Tickets, please","How many stops are there"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["What","time","does","the","train","leave"],"translation":"¿A qué hora sale el tren?","translations":{"es":"¿A qué hora sale el tren?"}},{"words":["It","leaves","from","platform","two"],"translation":"Sale del andén dos.","translations":{"es":"Sale del andén dos."}},{"words":["The","train","arrives","at","twelve"],"translation":"El tren llega a las doce.","translations":{"es":"El tren llega a las doce."}},{"words":["Hurry","or","we","will","miss","the","train"],"translation":"Apúrate o vamos a perder el tren.","translations":{"es":"Apúrate o vamos a perder el tren."}},{"words":["Is","this","the","train","to","Los","Angeles"],"translation":"¿Este es el tren a Los Ángeles?","translations":{"es":"¿Este es el tren a Los Ángeles?"}},{"words":["The","scenery","is","beautiful"],"translation":"El paisaje es precioso.","translations":{"es":"El paisaje es precioso."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿A qué hora sale?","translations":{"es":"¿A qué hora sale?"},"answer":"What time does it leave"},{"prompt":"¿Qué andén es?","translations":{"es":"¿Qué andén es?"},"answer":"Which platform is it"},{"prompt":"Perdimos el tren","translations":{"es":"Perdimos el tren"},"answer":"We missed the train"},{"prompt":"Boletos, por favor","translations":{"es":"Boletos, por favor"},"answer":"Tickets, please"},{"prompt":"El tren sale el lunes","translations":{"es":"El tren sale el lunes"},"answer":"The train leaves on Monday"},{"prompt":"¿Cuántas paradas hay?","translations":{"es":"¿Cuántas paradas hay?"},"answer":"How many stops are there"}]}'::jsonb, 6)
) as v(type, title, content, ord);

