insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"coffee shop","translation":"cafetería","translations":{"es":"cafetería"}},{"id":"2","word":"barista","translation":"barista","translations":{"es":"barista"}},{"id":"3","word":"latte","translation":"café con leche (latte)","translations":{"es":"café con leche (latte)"}},{"id":"4","word":"black coffee","translation":"café negro / americano","translations":{"es":"café negro / americano"}},{"id":"5","word":"decaf","translation":"descafeinado","translations":{"es":"descafeinado"}},{"id":"6","word":"hot chocolate","translation":"chocolate caliente","translations":{"es":"chocolate caliente"}},{"id":"7","word":"iced","translation":"con hielo / frío","translations":{"es":"con hielo / frío"}},{"id":"8","word":"cream","translation":"crema","translations":{"es":"crema"}},{"id":"9","word":"oat milk","translation":"leche de avena","translations":{"es":"leche de avena"}},{"id":"10","word":"muffin","translation":"panquecito / muffin","translations":{"es":"panquecito / muffin"}},{"id":"11","word":"pastry","translation":"pan dulce / pastelito","translations":{"es":"pan dulce / pastelito"}},{"id":"12","word":"to go","translation":"para llevar","translations":{"es":"para llevar"}},{"id":"13","word":"for here","translation":"para tomar aquí","translations":{"es":"para tomar aquí"}},{"id":"14","word":"rather","translation":"preferiría (would rather)","translations":{"es":"preferiría (would rather)"}},{"id":"15","word":"prefer","translation":"preferir","translations":{"es":"preferir"}},{"id":"16","word":"refill","translation":"otra taza / rellenar","translations":{"es":"otra taza / rellenar"}},{"id":"17","word":"lid","translation":"tapa","translations":{"es":"tapa"}}],"grammar":[{"structure":"I''d rather + verb","example":"I''d rather have tea than coffee.","en":"Preferences with \"would rather\"","es":"Preferencias con «would rather» (preferiría)"},{"structure":"prefer + noun / verb-ing + to","example":"I prefer hot drinks to cold drinks.","en":"General preferences with \"prefer\"","es":"Preferencias generales con «prefer»"},{"structure":"Would you rather…?","example":"Would you rather sit inside or outside?","en":"Asking about preferences","es":"Preguntar por preferencias"},{"structure":"Can I get…?","example":"Can I get a large latte with oat milk?","en":"Casual way to order","es":"Forma informal de pedir"},{"structure":"for here or to go","example":"For here or to go? — To go, please.","en":"Eating in or taking away","es":"Para tomar aquí o para llevar"}],"tips":[{"en":"\"I''d rather\" is followed by the base verb, without \"to\": I''d rather stay (not \"I''d rather to stay\").","es":"«I''d rather» va seguido del verbo base, sin «to»: I''d rather stay (no «I''d rather to stay»)."},{"en":"\"Can I get…?\" is the most common way to order at an American coffee shop.","es":"«Can I get…?» es la forma más común de pedir en una cafetería estadounidense."},{"en":"Baristas often ask your name and write it on the cup. They''ll call it when your drink is ready.","es":"Los baristas suelen preguntar tu nombre y escribirlo en el vaso. Lo dicen en voz alta cuando tu bebida está lista."},{"en":"\"Decaf\" means without caffeine.","es":"«Decaf» significa descafeinado."},{"en":"There''s usually a tip jar or a tip option on the screen. Tipping at coffee shops is optional.","es":"Suele haber un frasco o una opción de propina en la pantalla. En las cafeterías la propina es opcional."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Can I get a medium latte, please?","translation":"¿Me da un latte mediano, por favor?","translations":{"es":"¿Me da un latte mediano, por favor?"}},{"phrase":"For here or to go?","translation":"¿Para tomar aquí o para llevar?","translations":{"es":"¿Para tomar aquí o para llevar?"}},{"phrase":"To go, please.","translation":"Para llevar, por favor.","translations":{"es":"Para llevar, por favor."}},{"phrase":"What''s your name?","translation":"¿Cuál es su nombre?","translations":{"es":"¿Cuál es su nombre?"}},{"phrase":"I''d rather have tea.","translation":"Preferiría un té.","translations":{"es":"Preferiría un té."}},{"phrase":"Would you rather sit inside or outside?","translation":"¿Prefieres sentarte adentro o afuera?","translations":{"es":"¿Prefieres sentarte adentro o afuera?"}},{"phrase":"I prefer coffee without sugar.","translation":"Prefiero el café sin azúcar.","translations":{"es":"Prefiero el café sin azúcar."}},{"phrase":"Is it decaf?","translation":"¿Es descafeinado?","translations":{"es":"¿Es descafeinado?"}},{"phrase":"Could I have a little more milk?","translation":"¿Me podría dar un poco más de leche?","translations":{"es":"¿Me podría dar un poco más de leche?"}},{"phrase":"A latte for Carmen!","translation":"¡Un latte para Carmen!","translations":{"es":"¡Un latte para Carmen!"}},{"phrase":"This one''s on me.","translation":"Este lo invito yo.","translations":{"es":"Este lo invito yo."}},{"phrase":"Can I have a lid?","translation":"¿Me da una tapa?","translations":{"es":"¿Me da una tapa?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Choose the correct sentence.","options":["I''d rather stay home.","I''d rather to stay home.","I''d rather stays home.","I''d rather staying home."],"correct":0,"explanation":"would rather + base verb.","translations":{"es":{"question":"Elige la oración correcta.","explanation":"would rather + verbo base."}}},{"id":"2","question":"Complete: \"I prefer tea ___ coffee.\"","options":["than","to","of","that"],"correct":1,"explanation":"prefer A to B.","translations":{"es":{"question":"Completa: «I prefer tea ___ coffee.»","explanation":"prefer A to B."}}},{"id":"3","question":"Complete: \"I''d rather have tea ___ coffee.\"","options":["to","from","than","that"],"correct":2,"explanation":"would rather A than B.","translations":{"es":{"question":"Completa: «I''d rather have tea ___ coffee.»","explanation":"would rather A than B."}}},{"id":"4","question":"The barista asks \"For here or to go?\". You want to take it with you. You say:","options":["Take, please.","For here, please.","To go, please.","Go, please."],"correct":2,"explanation":"To go = para llevar.","translations":{"es":{"question":"La barista pregunta «For here or to go?». Quieres llevártelo. Dices:","explanation":"To go = para llevar."}}},{"id":"5","question":"Coffee without caffeine is…","options":["iced","latte","decaf","black"],"correct":2,"explanation":"Decaf = descafeinado.","translations":{"es":{"question":"El café sin cafeína es…","explanation":"Decaf = descafeinado."}}},{"id":"6","question":"What''s a casual, common way to order?","options":["Latte you have?","Can I get a latte?","I demand a latte.","Give latte."],"correct":1,"explanation":"\"Can I get…?\" is the standard casual order.","translations":{"es":{"question":"¿Cuál es una forma informal y común de pedir?","explanation":"«Can I get…?» es la forma habitual e informal."}}},{"id":"7","question":"You pay for your friend''s coffee. You say:","options":["This one''s on me.","This one''s a refill.","This one''s for here.","This one''s decaf."],"correct":0,"explanation":"\"It''s on me\" = yo invito.","translations":{"es":{"question":"Pagas el café de tu amiga. Dices:","explanation":"«It''s on me» = yo invito."}}},{"id":"8","question":"Choose the correct question.","options":["Would you rather sit inside or outside?","Would rather you sit inside?","Would you rather to sit inside?","Do you rather sit inside?"],"correct":0,"explanation":"Would you rather + base verb?","translations":{"es":{"question":"Elige la pregunta correcta.","explanation":"Would you rather + verbo base?"}}}]}'::jsonb, 3),
  ('story', 'Carmen''s Coffee Club', '{"text":"Every Thursday, Carmen, Ana, Kenji and Linda meet at a coffee shop near the beach. They call it the Coffee Club. Today it''s Carmen''s turn to order. \"Hi! Can I get a medium latte, a black coffee, a decaf for Linda and… Kenji, what would you like?\" \"I''d rather have tea today. Green tea, please.\" \"And a green tea. For here.\" \"What''s the name?\" \"Carmen.\" A few minutes later the barista calls, \"Drinks for Carmen!\" \"Would you rather sit inside or outside?\" asks Ana. \"Outside,\" says Linda. \"I prefer the sun to the air conditioning.\" They talk about everything: Ana''s new job, Kenji''s garden, Leo''s soccer team. When the bill comes, Carmen says, \"This one''s on me. Last year I couldn''t order a coffee in English. Today I ordered four!\"","translation":"Todos los jueves, Carmen, Ana, Kenji y Linda se reúnen en una cafetería cerca de la playa. Le dicen el Club del Café. Hoy le toca pedir a Carmen. «¡Hola! ¿Me da un latte mediano, un café americano, un descafeinado para Linda y… Kenji, ¿qué quieres?» «Hoy preferiría un té. Té verde, por favor.» «Y un té verde. Para tomar aquí.» «¿A nombre de quién?» «Carmen.» Unos minutos después, el barista dice en voz alta: «¡Bebidas para Carmen!» «¿Prefieren sentarse adentro o afuera?», pregunta Ana. «Afuera», dice Linda. «Prefiero el sol al aire acondicionado.» Hablan de todo: el nuevo trabajo de Ana, el huerto de Kenji, el equipo de fútbol de Leo. Cuando llega la cuenta, Carmen dice: «Esta la invito yo. El año pasado no podía pedir un café en inglés. ¡Hoy pedí cuatro!»","translations":{"es":"Todos los jueves, Carmen, Ana, Kenji y Linda se reúnen en una cafetería cerca de la playa. Le dicen el Club del Café. Hoy le toca pedir a Carmen. «¡Hola! ¿Me da un latte mediano, un café americano, un descafeinado para Linda y… Kenji, ¿qué quieres?» «Hoy preferiría un té. Té verde, por favor.» «Y un té verde. Para tomar aquí.» «¿A nombre de quién?» «Carmen.» Unos minutos después, el barista dice en voz alta: «¡Bebidas para Carmen!» «¿Prefieren sentarse adentro o afuera?», pregunta Ana. «Afuera», dice Linda. «Prefiero el sol al aire acondicionado.» Hablan de todo: el nuevo trabajo de Ana, el huerto de Kenji, el equipo de fútbol de Leo. Cuando llega la cuenta, Carmen dice: «Esta la invito yo. El año pasado no podía pedir un café en inglés. ¡Hoy pedí cuatro!»"},"highlighted_words":["coffee shop","Can I get a medium latte","black coffee","decaf","I''d rather have tea","For here","barista","Would you rather sit inside or outside","I prefer the sun to the air conditioning","This one''s on me"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Can","I","get","a","medium","latte","please"],"translation":"¿Me da un latte mediano, por favor?","translations":{"es":"¿Me da un latte mediano, por favor?"}},{"words":["I","would","rather","have","tea"],"translation":"Preferiría un té.","translations":{"es":"Preferiría un té."}},{"words":["I","prefer","tea","to","coffee"],"translation":"Prefiero el té al café.","translations":{"es":"Prefiero el té al café."}},{"words":["Would","you","rather","sit","inside","or","outside"],"translation":"¿Prefieres sentarte adentro o afuera?","translations":{"es":"¿Prefieres sentarte adentro o afuera?"}},{"words":["For","here","or","to","go"],"translation":"¿Para tomar aquí o para llevar?","translations":{"es":"¿Para tomar aquí o para llevar?"}},{"words":["This","one","is","on","me"],"translation":"Este lo invito yo.","translations":{"es":"Este lo invito yo."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Para llevar, por favor","translations":{"es":"Para llevar, por favor"},"answer":"To go, please"},{"prompt":"Preferiría un té","translations":{"es":"Preferiría un té"},"answer":"I would rather have tea"},{"prompt":"¿Es descafeinado?","translations":{"es":"¿Es descafeinado?"},"answer":"Is it decaf"},{"prompt":"Prefiero el café sin azúcar","translations":{"es":"Prefiero el café sin azúcar"},"answer":"I prefer coffee without sugar"},{"prompt":"¿Me da una tapa?","translations":{"es":"¿Me da una tapa?"},"answer":"Can I have a lid"},{"prompt":"¿Me da un chocolate caliente?","translations":{"es":"¿Me da un chocolate caliente?"},"answer":"Can I get a hot chocolate"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 54: At the phone store
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-54', 'At the phone store', '📱', 'En la tienda de celulares', 54, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"smartphone","translation":"teléfono inteligente","translations":{"es":"teléfono inteligente"}},{"id":"2","word":"screen","translation":"pantalla","translations":{"es":"pantalla"}},{"id":"3","word":"camera","translation":"cámara","translations":{"es":"cámara"}},{"id":"4","word":"battery life","translation":"duración de la batería","translations":{"es":"duración de la batería"}},{"id":"5","word":"storage","translation":"almacenamiento","translations":{"es":"almacenamiento"}},{"id":"6","word":"data","translation":"datos (internet)","translations":{"es":"datos (internet)"}},{"id":"7","word":"plan","translation":"plan (de telefonía)","translations":{"es":"plan (de telefonía)"}},{"id":"8","word":"prepaid","translation":"prepago","translations":{"es":"prepago"}},{"id":"9","word":"contract","translation":"contrato","translations":{"es":"contrato"}},{"id":"10","word":"case","translation":"funda","translations":{"es":"funda"}},{"id":"11","word":"screen protector","translation":"mica / protector de pantalla","translations":{"es":"mica / protector de pantalla"}},{"id":"12","word":"app","translation":"aplicación","translations":{"es":"aplicación"}},{"id":"13","word":"update","translation":"actualizar / actualización","translations":{"es":"actualizar / actualización"}},{"id":"14","word":"contacts","translation":"contactos","translations":{"es":"contactos"}},{"id":"15","word":"lighter","translation":"más ligero","translations":{"es":"más ligero"}},{"id":"16","word":"cheaper","translation":"más barato","translations":{"es":"más barato"}},{"id":"17","word":"the easiest","translation":"el más fácil","translations":{"es":"el más fácil"}}],"grammar":[{"structure":"Which one…?","example":"Which one is better for photos?","en":"Choosing between options","es":"Elegir entre opciones"},{"structure":"comparatives (review)","example":"This phone is cheaper and lighter than that one.","en":"Comparing two things","es":"Comparar dos cosas"},{"structure":"superlatives (review)","example":"This is the easiest phone to use.","en":"The top of the group","es":"El máximo del grupo"},{"structure":"one / ones","example":"I don''t want the black one. I want the blue one.","en":"Avoiding repetition","es":"Evitar repetir el sustantivo"},{"structure":"easy / hard + to + verb","example":"It''s easy to use.","en":"Describing how easy something is","es":"Describir qué tan fácil es algo"}],"tips":[{"en":"\"One\" replaces a singular noun and \"ones\" a plural: \"the big ones\" = los grandes.","es":"«One» reemplaza un sustantivo singular y «ones» uno plural: «the big ones» = los grandes."},{"en":"A \"plan\" is the monthly contract for calls and data. Prepaid plans don''t need a credit check.","es":"Un «plan» es el contrato mensual de llamadas y datos. Los planes prepagados no revisan tu historial de crédito."},{"en":"\"Data\" is your internet on the phone. \"Unlimited data\" means no limit.","es":"«Data» es tu internet en el celular. «Unlimited data» significa sin límite."},{"en":"Ask the clerk to set up your phone in Spanish and transfer your photos and contacts.","es":"Pídele al vendedor que configure tu teléfono en español y pase tus fotos y contactos."},{"en":"Compare at least two options before you sign a contract.","es":"Compara al menos dos opciones antes de firmar un contrato."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''m looking for a new phone.","translation":"Busco un celular nuevo.","translations":{"es":"Busco un celular nuevo."}},{"phrase":"Which one is better for photos?","translation":"¿Cuál es mejor para fotos?","translations":{"es":"¿Cuál es mejor para fotos?"}},{"phrase":"This one has a bigger screen.","translation":"Este tiene la pantalla más grande.","translations":{"es":"Este tiene la pantalla más grande."}},{"phrase":"That one is cheaper.","translation":"Ese es más barato.","translations":{"es":"Ese es más barato."}},{"phrase":"Which is the easiest to use?","translation":"¿Cuál es el más fácil de usar?","translations":{"es":"¿Cuál es el más fácil de usar?"}},{"phrase":"How long does the battery last?","translation":"¿Cuánto dura la batería?","translations":{"es":"¿Cuánto dura la batería?"}},{"phrase":"Is there a prepaid plan?","translation":"¿Hay plan de prepago?","translations":{"es":"¿Hay plan de prepago?"}},{"phrase":"Does it include unlimited data?","translation":"¿Incluye datos ilimitados?","translations":{"es":"¿Incluye datos ilimitados?"}},{"phrase":"Can you move my photos and contacts?","translation":"¿Me puede pasar mis fotos y contactos?","translations":{"es":"¿Me puede pasar mis fotos y contactos?"}},{"phrase":"Can you set it up in Spanish?","translation":"¿Me lo puede configurar en español?","translations":{"es":"¿Me lo puede configurar en español?"}},{"phrase":"I''ll take the blue one.","translation":"Me llevo el azul.","translations":{"es":"Me llevo el azul."}},{"phrase":"I need a case for it.","translation":"Necesito una funda para él.","translations":{"es":"Necesito una funda para él."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"I don''t like the black phone. I prefer the blue ___.\"","options":["it","ones","phone one","one"],"correct":3,"explanation":"\"One\" replaces a singular noun.","translations":{"es":{"question":"Completa: «I don''t like the black phone. I prefer the blue ___.»","explanation":"«One» reemplaza un sustantivo singular."}}},{"id":"2","question":"Complete: \"These cases are nice, but I want the red ___.\"","options":["one","them","it","ones"],"correct":3,"explanation":"\"Ones\" replaces a plural noun.","translations":{"es":{"question":"Completa: «These cases are nice, but I want the red ___.»","explanation":"«Ones» reemplaza un sustantivo plural."}}},{"id":"3","question":"Choose the correct comparative.","options":["This phone is more light than that one.","This phone is lightest than that one.","This phone is light than that one.","This phone is lighter than that one."],"correct":3,"explanation":"light → lighter than.","translations":{"es":{"question":"Elige el comparativo correcto.","explanation":"light → lighter than."}}},{"id":"4","question":"Choose the correct superlative.","options":["It''s easiest phone to use.","It''s the easier phone to use.","It''s the most easy phone to use.","It''s the easiest phone to use."],"correct":3,"explanation":"easy → the easiest.","translations":{"es":{"question":"Elige el superlativo correcto.","explanation":"easy → the easiest."}}},{"id":"5","question":"A cover that protects your phone is a…","options":["storage","update","plan","case"],"correct":3,"explanation":"Case = funda.","translations":{"es":{"question":"Una cubierta que protege tu teléfono es una…","explanation":"Case = funda."}}},{"id":"6","question":"A plan you pay before using, without a credit check, is…","options":["contract only","storage","unlimited","prepaid"],"correct":3,"explanation":"Prepaid = prepago.","translations":{"es":{"question":"Un plan que pagas antes de usarlo, sin revisión de crédito, es…","explanation":"Prepaid = prepago."}}},{"id":"7","question":"Complete: \"It''s easy ___ use.\"","options":["at","of","for","to"],"correct":3,"explanation":"easy + to + verb.","translations":{"es":{"question":"Completa: «It''s easy ___ use.»","explanation":"easy + to + verbo."}}},{"id":"8","question":"You want to choose between two phones. You ask:","options":["Which better one is?","What one is better?","Who is better?","Which one is better?"],"correct":3,"explanation":"Which one…? for choosing between options.","translations":{"es":{"question":"Quieres elegir entre dos teléfonos. Preguntas:","explanation":"Which one…? para elegir entre opciones."}}}]}'::jsonb, 3),
  ('story', 'A New Phone', '{"text":"Carmen''s old phone is very slow, and the battery doesn''t last. Leo goes with her to the phone store. \"I''m looking for a new phone,\" Carmen tells the clerk. \"Something easy to use, with a good camera for photos of my grandson.\" The clerk shows her two phones. \"This one is cheaper and lighter. That one has a bigger screen and the best camera in the store.\" \"Which one is easier to use?\" \"This one. It''s the easiest phone we have.\" Leo whispers, \"Grandma, the one with the big screen is better for video calls with Aunt Rosa.\" Carmen thinks. \"How long does the battery last?\" \"Two days.\" \"Okay. I''ll take the one with the big screen. Can you set it up in Spanish and move my photos and contacts?\" \"Of course.\" At home, Carmen takes her first photo: Leo, smiling, with the new red case he chose.","translation":"El teléfono viejo de Carmen es muy lento y la batería no le dura. Leo la acompaña a la tienda de celulares. «Busco un celular nuevo», le dice Carmen al vendedor. «Algo fácil de usar, con buena cámara para tomarle fotos a mi nieto.» El vendedor le muestra dos teléfonos. «Este es más barato y más ligero. Ese tiene la pantalla más grande y la mejor cámara de la tienda.» «¿Cuál es más fácil de usar?» «Este. Es el teléfono más fácil que tenemos.» Leo le susurra: «Abuela, el de la pantalla grande es mejor para las videollamadas con la tía Rosa.» Carmen piensa. «¿Cuánto dura la batería?» «Dos días.» «Bueno. Me llevo el de la pantalla grande. ¿Me lo puede configurar en español y pasar mis fotos y contactos?» «Claro.» En casa, Carmen toma su primera foto: Leo, sonriendo, con la funda roja nueva que él escogió.","translations":{"es":"El teléfono viejo de Carmen es muy lento y la batería no le dura. Leo la acompaña a la tienda de celulares. «Busco un celular nuevo», le dice Carmen al vendedor. «Algo fácil de usar, con buena cámara para tomarle fotos a mi nieto.» El vendedor le muestra dos teléfonos. «Este es más barato y más ligero. Ese tiene la pantalla más grande y la mejor cámara de la tienda.» «¿Cuál es más fácil de usar?» «Este. Es el teléfono más fácil que tenemos.» Leo le susurra: «Abuela, el de la pantalla grande es mejor para las videollamadas con la tía Rosa.» Carmen piensa. «¿Cuánto dura la batería?» «Dos días.» «Bueno. Me llevo el de la pantalla grande. ¿Me lo puede configurar en español y pasar mis fotos y contactos?» «Claro.» En casa, Carmen toma su primera foto: Leo, sonriendo, con la funda roja nueva que él escogió."},"highlighted_words":["phone store","I''m looking for a new phone","easy to use","camera","This one is cheaper and lighter","That one has a bigger screen","the best camera","Which one is easier to use","the easiest","How long does the battery last","I''ll take the one","contacts","case"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Which","one","is","better","for","photos"],"translation":"¿Cuál es mejor para fotos?","translations":{"es":"¿Cuál es mejor para fotos?"}},{"words":["This","one","is","cheaper","than","that","one"],"translation":"Este es más barato que ese.","translations":{"es":"Este es más barato que ese."}},{"words":["It","is","the","easiest","phone","to","use"],"translation":"Es el teléfono más fácil de usar.","translations":{"es":"Es el teléfono más fácil de usar."}},{"words":["I","will","take","the","blue","one"],"translation":"Me llevo el azul.","translations":{"es":"Me llevo el azul."}},{"words":["How","long","does","the","battery","last"],"translation":"¿Cuánto dura la batería?","translations":{"es":"¿Cuánto dura la batería?"}},{"words":["Can","you","set","it","up","in","Spanish"],"translation":"¿Me lo puede configurar en español?","translations":{"es":"¿Me lo puede configurar en español?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Cuál es más barato?","translations":{"es":"¿Cuál es más barato?"},"answer":"Which one is cheaper"},{"prompt":"Quiero el rojo","translations":{"es":"Quiero el rojo"},"answer":"I want the red one"},{"prompt":"Es fácil de usar","translations":{"es":"Es fácil de usar"},"answer":"It is easy to use"},{"prompt":"Necesito un celular nuevo","translations":{"es":"Necesito un celular nuevo"},"answer":"I need a new phone"},{"prompt":"¿Hay plan de prepago?","translations":{"es":"¿Hay plan de prepago?"},"answer":"Is there a prepaid plan"},{"prompt":"Este tiene mejor cámara","translations":{"es":"Este tiene mejor cámara"},"answer":"This one has a better camera"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 55: At the mall
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-55', 'At the mall', '🛒', 'En el centro comercial', 55, true)
  returning id
