insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"mall","translation":"centro comercial","translations":{"es":"centro comercial"}},{"id":"2","word":"department store","translation":"tienda departamental","translations":{"es":"tienda departamental"}},{"id":"3","word":"directory","translation":"directorio / mapa","translations":{"es":"directorio / mapa"}},{"id":"4","word":"escalator","translation":"escalera eléctrica","translations":{"es":"escalera eléctrica"}},{"id":"5","word":"food court","translation":"zona de comida","translations":{"es":"zona de comida"}},{"id":"6","word":"entrance","translation":"entrada","translations":{"es":"entrada"}},{"id":"7","word":"exit","translation":"salida","translations":{"es":"salida"}},{"id":"8","word":"restroom","translation":"baño (público)","translations":{"es":"baño (público)"}},{"id":"9","word":"department","translation":"departamento / sección","translations":{"es":"departamento / sección"}},{"id":"10","word":"jewelry","translation":"joyería / joyas","translations":{"es":"joyería / joyas"}},{"id":"11","word":"cosmetics","translation":"cosméticos","translations":{"es":"cosméticos"}},{"id":"12","word":"kitchenware","translation":"artículos de cocina","translations":{"es":"artículos de cocina"}},{"id":"13","word":"crowded","translation":"lleno de gente","translations":{"es":"lleno de gente"}},{"id":"14","word":"same","translation":"mismo / igual","translations":{"es":"mismo / igual"}},{"id":"15","word":"different","translation":"diferente","translations":{"es":"diferente"}},{"id":"16","word":"as … as","translation":"tan … como","translations":{"es":"tan … como"}},{"id":"17","word":"parking lot","translation":"estacionamiento","translations":{"es":"estacionamiento"}}],"grammar":[{"structure":"as + adjective + as","example":"This store is as cheap as the market.","en":"Equal comparison","es":"Comparación de igualdad"},{"structure":"not as + adjective + as","example":"The mall isn''t as crowded as on weekends.","en":"\"Less than\" comparison","es":"Comparación de inferioridad (no tan… como)"},{"structure":"the same as / different from","example":"This sweater is the same as mine.","en":"Same and different","es":"Igual y diferente"},{"structure":"Where can I find…?","example":"Where can I find the shoe department?","en":"Asking where things are in a store","es":"Preguntar dónde están las cosas en una tienda"},{"structure":"on the first / second floor","example":"Women''s clothing is on the second floor.","en":"Floors and departments","es":"Pisos y departamentos"}],"tips":[{"en":"\"Not as … as\" is a softer way to say something is less: \"It''s not as expensive as I thought.\"","es":"«Not as … as» es una forma más suave de decir que algo es menos: «It''s not as expensive as I thought» (no es tan caro como pensaba)."},{"en":"\"Department store\" is a big store with many sections: clothes, kitchen, beauty…","es":"Una «department store» es una tienda grande con muchas secciones: ropa, cocina, belleza…"},{"en":"Malls have a \"directory\" (a map) near the entrance.","es":"Los centros comerciales tienen un «directory» (un mapa) cerca de la entrada."},{"en":"\"Food court\" is the area with many fast-food restaurants.","es":"El «food court» es la zona con muchos restaurantes de comida rápida."},{"en":"Many malls have benches and free events for seniors in the mornings, like \"mall walking\".","es":"Muchos centros comerciales tienen bancas y actividades gratis para adultos mayores en las mañanas, como el «mall walking» (caminar dentro del centro comercial)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Where can I find the shoe department?","translation":"¿Dónde encuentro el departamento de zapatos?","translations":{"es":"¿Dónde encuentro el departamento de zapatos?"}},{"phrase":"It''s on the second floor.","translation":"Está en el segundo piso.","translations":{"es":"Está en el segundo piso."}},{"phrase":"Take the escalator.","translation":"Tome la escalera eléctrica.","translations":{"es":"Tome la escalera eléctrica."}},{"phrase":"Where are the restrooms?","translation":"¿Dónde están los baños?","translations":{"es":"¿Dónde están los baños?"}},{"phrase":"Let''s meet at the food court.","translation":"Nos vemos en la zona de comida.","translations":{"es":"Nos vemos en la zona de comida."}},{"phrase":"It''s not as expensive as I thought.","translation":"No es tan caro como pensaba.","translations":{"es":"No es tan caro como pensaba."}},{"phrase":"This one is as good as that one.","translation":"Este es tan bueno como ese.","translations":{"es":"Este es tan bueno como ese."}},{"phrase":"Your bag is the same as mine!","translation":"¡Tu bolsa es igual a la mía!","translations":{"es":"¡Tu bolsa es igual a la mía!"}},{"phrase":"It''s different from the picture.","translation":"Es diferente a la foto.","translations":{"es":"Es diferente a la foto."}},{"phrase":"The mall is very crowded today.","translation":"El centro comercial está muy lleno hoy.","translations":{"es":"El centro comercial está muy lleno hoy."}},{"phrase":"Let''s look at the directory.","translation":"Veamos el directorio.","translations":{"es":"Veamos el directorio."}},{"phrase":"Which exit is closest to the parking lot?","translation":"¿Qué salida está más cerca del estacionamiento?","translations":{"es":"¿Qué salida está más cerca del estacionamiento?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"This store is as cheap ___ the market.\"","options":["like","that","as","than"],"correct":2,"explanation":"as … as.","translations":{"es":{"question":"Completa: «This store is as cheap ___ the market.»","explanation":"as … as."}}},{"id":"2","question":"\"It''s not as big as my house\" means…","options":["It''s very big.","It''s the same size.","It''s smaller than my house.","It''s bigger than my house."],"correct":2,"explanation":"Not as big as = smaller.","translations":{"es":{"question":"«It''s not as big as my house» significa…","explanation":"Not as big as = más pequeño."}}},{"id":"3","question":"Complete: \"Your dress is the same ___ mine.\"","options":["to","as","from","than"],"correct":1,"explanation":"the same as.","translations":{"es":{"question":"Completa: «Your dress is the same ___ mine.»","explanation":"the same as."}}},{"id":"4","question":"Complete: \"This city is different ___ my hometown.\"","options":["from","than of","to as","as"],"correct":0,"explanation":"different from.","translations":{"es":{"question":"Completa: «This city is different ___ my hometown.»","explanation":"different from."}}},{"id":"5","question":"Moving stairs in a mall are the…","options":["directory","escalator","exit","elevator"],"correct":1,"explanation":"Escalator = escalera eléctrica. Elevator = elevador.","translations":{"es":{"question":"Las escaleras que se mueven en el centro comercial son la…","explanation":"Escalator = escalera eléctrica. Elevator = elevador."}}},{"id":"6","question":"A polite word for public bathroom in the US is…","options":["toilet room","restroom","rest area","bedroom"],"correct":1,"explanation":"Restroom is the common polite word.","translations":{"es":{"question":"Una forma educada de decir baño público en Estados Unidos es…","explanation":"Restroom es la palabra educada y común."}}},{"id":"7","question":"Where do you look for a map of the mall?","options":["at the directory","at the parking lot","at the escalator","at the food court"],"correct":0,"explanation":"The directory shows where stores are.","translations":{"es":{"question":"¿Dónde buscas un mapa del centro comercial?","explanation":"El directorio muestra dónde están las tiendas."}}},{"id":"8","question":"How do you ask where something is in a store?","options":["Where can I find the kitchenware?","Where is kitchenware find?","Where find kitchenware?","Where I can find the kitchenware?"],"correct":0,"explanation":"Where can I find…?","translations":{"es":{"question":"¿Cómo preguntas dónde está algo en una tienda?","explanation":"Where can I find…?"}}}]}'::jsonb, 3),
  ('story', 'Mall Walking', '{"text":"Linda has a new idea: mall walking. Every Tuesday morning, before the stores open, a group of seniors walks inside the mall. \"It''s not as hot as walking outside,\" says Linda, \"and there are clean restrooms!\" Carmen likes it. They walk two miles, up the escalators and down again. After the walk, the stores open. Carmen needs a frying pan. \"Where can I find the kitchenware?\" she asks a woman at the department store. \"On the second floor, next to the cosmetics.\" The pan is not as expensive as Carmen thought. At the food court, Linda points at Carmen''s bag. \"Your bag is the same as mine!\" They laugh. \"Same bag, different countries,\" says Carmen. \"But the same Tuesday walks.\" A man from the group joins them. \"Ladies, you walk faster than everybody. Same time next week?\"","translation":"Linda tiene una idea nueva: caminar en el centro comercial. Todos los martes en la mañana, antes de que abran las tiendas, un grupo de adultos mayores camina dentro del centro comercial. «No hace tanto calor como caminar afuera», dice Linda, «¡y hay baños limpios!» A Carmen le gusta. Caminan dos millas, suben por las escaleras eléctricas y vuelven a bajar. Después de caminar, abren las tiendas. Carmen necesita un sartén. «¿Dónde encuentro los artículos de cocina?», le pregunta a una mujer en la tienda departamental. «En el segundo piso, junto a los cosméticos.» El sartén no es tan caro como Carmen pensaba. En la zona de comida, Linda señala la bolsa de Carmen. «¡Tu bolsa es igual a la mía!» Se ríen. «Misma bolsa, distintos países», dice Carmen. «Pero las mismas caminatas de los martes.» Un señor del grupo se les une. «Señoras, ustedes caminan más rápido que todos. ¿Mismo horario la próxima semana?»","translations":{"es":"Linda tiene una idea nueva: caminar en el centro comercial. Todos los martes en la mañana, antes de que abran las tiendas, un grupo de adultos mayores camina dentro del centro comercial. «No hace tanto calor como caminar afuera», dice Linda, «¡y hay baños limpios!» A Carmen le gusta. Caminan dos millas, suben por las escaleras eléctricas y vuelven a bajar. Después de caminar, abren las tiendas. Carmen necesita un sartén. «¿Dónde encuentro los artículos de cocina?», le pregunta a una mujer en la tienda departamental. «En el segundo piso, junto a los cosméticos.» El sartén no es tan caro como Carmen pensaba. En la zona de comida, Linda señala la bolsa de Carmen. «¡Tu bolsa es igual a la mía!» Se ríen. «Misma bolsa, distintos países», dice Carmen. «Pero las mismas caminatas de los martes.» Un señor del grupo se les une. «Señoras, ustedes caminan más rápido que todos. ¿Mismo horario la próxima semana?»"},"highlighted_words":["mall walking","It''s not as hot as","restrooms","escalators","Where can I find the kitchenware","department store","second floor","cosmetics","not as expensive as","food court","the same as mine","different"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["Where","can","I","find","the","shoe","department"],"translation":"¿Dónde encuentro el departamento de zapatos?","translations":{"es":"¿Dónde encuentro el departamento de zapatos?"}},{"words":["It","is","not","as","expensive","as","I","thought"],"translation":"No es tan caro como pensaba.","translations":{"es":"No es tan caro como pensaba."}},{"words":["Your","bag","is","the","same","as","mine"],"translation":"Tu bolsa es igual a la mía.","translations":{"es":"Tu bolsa es igual a la mía."}},{"words":["Let''s","meet","at","the","food","court"],"translation":"Nos vemos en la zona de comida.","translations":{"es":"Nos vemos en la zona de comida."}},{"words":["This","store","is","as","cheap","as","the","market"],"translation":"Esta tienda es tan barata como el mercado.","translations":{"es":"Esta tienda es tan barata como el mercado."}},{"words":["Where","are","the","restrooms"],"translation":"¿Dónde están los baños?","translations":{"es":"¿Dónde están los baños?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"¿Dónde están los baños?","translations":{"es":"¿Dónde están los baños?"},"answer":"Where are the restrooms"},{"prompt":"Está en el segundo piso","translations":{"es":"Está en el segundo piso"},"answer":"It is on the second floor"},{"prompt":"Tome la escalera eléctrica","translations":{"es":"Tome la escalera eléctrica"},"answer":"Take the escalator"},{"prompt":"No es tan grande como mi casa","translations":{"es":"No es tan grande como mi casa"},"answer":"It is not as big as my house"},{"prompt":"El centro comercial está muy lleno","translations":{"es":"El centro comercial está muy lleno"},"answer":"The mall is very crowded"},{"prompt":"Es diferente a la foto","translations":{"es":"Es diferente a la foto"},"answer":"It is different from the picture"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 56: At the hair salon
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-56', 'At the hair salon', '💇', 'En la estética', 56, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"hair salon","translation":"estética / salón de belleza","translations":{"es":"estética / salón de belleza"}},{"id":"2","word":"hairdresser","translation":"estilista","translations":{"es":"estilista"}},{"id":"3","word":"haircut","translation":"corte de pelo","translations":{"es":"corte de pelo"}},{"id":"4","word":"trim","translation":"despuntar / recorte","translations":{"es":"despuntar / recorte"}},{"id":"5","word":"bangs","translation":"fleco","translations":{"es":"fleco"}},{"id":"6","word":"layers","translation":"capas","translations":{"es":"capas"}},{"id":"7","word":"dye","translation":"teñir / tinte","translations":{"es":"teñir / tinte"}},{"id":"8","word":"highlights","translation":"luces / rayitos","translations":{"es":"luces / rayitos"}},{"id":"9","word":"gray hair","translation":"canas","translations":{"es":"canas"}},{"id":"10","word":"blow-dry","translation":"secar con secadora","translations":{"es":"secar con secadora"}},{"id":"11","word":"curly","translation":"rizado","translations":{"es":"rizado"}},{"id":"12","word":"straight","translation":"lacio","translations":{"es":"lacio"}},{"id":"13","word":"wavy","translation":"ondulado","translations":{"es":"ondulado"}},{"id":"14","word":"shorter","translation":"más corto","translations":{"es":"más corto"}},{"id":"15","word":"manicure","translation":"manicura","translations":{"es":"manicura"}},{"id":"16","word":"mirror","translation":"espejo","translations":{"es":"espejo"}},{"id":"17","word":"appointment","translation":"cita","translations":{"es":"cita"}}],"grammar":[{"structure":"get / have + something + past participle","example":"I''m going to get my hair cut. She had her nails done.","en":"Services done by someone else","es":"Servicios que otra persona te hace"},{"structure":"I''d like it + comparative","example":"I''d like it a little shorter.","en":"Explaining what you want","es":"Explicar lo que quieres"},{"structure":"not too…","example":"Not too short, please.","en":"Setting limits","es":"Poner límites"},{"structure":"Could you…? (review)","example":"Could you cut a little more on the sides?","en":"Polite requests to the stylist","es":"Pedidos amables a la estilista"},{"structure":"How would you like…?","example":"How would you like your hair today?","en":"The stylist''s question","es":"La pregunta de la estilista"}],"tips":[{"en":"In English you \"get your hair cut\" (someone cuts it). \"I cut my hair\" means you did it yourself!","es":"En inglés se dice «get your hair cut» (alguien te lo corta). «I cut my hair» significa que tú misma te lo cortaste."},{"en":"Bring a photo of the style you want: it avoids misunderstandings.","es":"Lleva una foto del corte que quieres: evita malentendidos."},{"en":"\"Trim\" is a small cut, just the ends.","es":"«Trim» es un corte pequeño, solo las puntas."},{"en":"Tipping 15–20% is common at hair salons in the US.","es":"En las estéticas de Estados Unidos es común dejar 15–20% de propina."},{"en":"\"Bangs\" are the hair that falls on your forehead (fleco).","es":"«Bangs» es el pelo que cae sobre la frente (el fleco)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''d like to get my hair cut.","translation":"Quisiera cortarme el pelo.","translations":{"es":"Quisiera cortarme el pelo."}},{"phrase":"How would you like it today?","translation":"¿Cómo lo quiere hoy?","translations":{"es":"¿Cómo lo quiere hoy?"}},{"phrase":"Just a trim, please.","translation":"Solo despuntar, por favor.","translations":{"es":"Solo despuntar, por favor."}},{"phrase":"I''d like it a little shorter.","translation":"Lo quiero un poco más corto.","translations":{"es":"Lo quiero un poco más corto."}},{"phrase":"Not too short, please.","translation":"No muy corto, por favor.","translations":{"es":"No muy corto, por favor."}},{"phrase":"Can you cover my gray hair?","translation":"¿Me puede cubrir las canas?","translations":{"es":"¿Me puede cubrir las canas?"}},{"phrase":"Like in this photo.","translation":"Como en esta foto.","translations":{"es":"Como en esta foto."}},{"phrase":"Could you cut my bangs?","translation":"¿Me puede cortar el fleco?","translations":{"es":"¿Me puede cortar el fleco?"}},{"phrase":"I love it!","translation":"¡Me encanta!","translations":{"es":"¡Me encanta!"}},{"phrase":"It looks great on you.","translation":"Se te ve muy bien.","translations":{"es":"Se te ve muy bien."}},{"phrase":"She had her nails done.","translation":"Se hizo las uñas.","translations":{"es":"Se hizo las uñas."}},{"phrase":"Can I make an appointment for next month?","translation":"¿Puedo hacer cita para el próximo mes?","translations":{"es":"¿Puedo hacer cita para el próximo mes?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say \"Me voy a cortar el pelo (en la estética)\"?","options":["I''m going to get my hair cut.","I''m going to cut me the hair.","I''m going to cut my hair myself.","I''m going to hair cut."],"correct":0,"explanation":"Someone else does it → get my hair cut.","translations":{"es":{"question":"¿Cómo se dice «Me voy a cortar el pelo (en la estética)»?","explanation":"Lo hace otra persona → get my hair cut."}}},{"id":"2","question":"Complete: \"She ___ her nails done yesterday.\"","options":["did","had","has","made"],"correct":1,"explanation":"Past: had + object + past participle.","translations":{"es":{"question":"Completa: «She ___ her nails done yesterday.»","explanation":"Pasado: had + objeto + participio."}}},{"id":"3","question":"A small cut, just the ends, is a…","options":["layer","trim","dye","highlight"],"correct":1,"explanation":"Trim = despuntar.","translations":{"es":{"question":"Un corte pequeño, solo las puntas, es un…","explanation":"Trim = despuntar."}}},{"id":"4","question":"The hair over your forehead is your…","options":["bangs","layers","highlights","curls"],"correct":0,"explanation":"Bangs = fleco.","translations":{"es":{"question":"El pelo sobre tu frente es tu…","explanation":"Bangs = fleco."}}},{"id":"5","question":"You want less length. You say:","options":["I''d like it a little longer.","I''d like it a little shorter.","I''d like it more short.","I''d like it shortest."],"correct":1,"explanation":"Comparative: shorter.","translations":{"es":{"question":"Quieres menos largo. Dices:","explanation":"Comparativo: shorter."}}},{"id":"6","question":"Hair that is not curly or wavy is…","options":["gray","straight","dyed","blow-dried"],"correct":1,"explanation":"Straight = lacio.","translations":{"es":{"question":"El pelo que no es rizado ni ondulado es…","explanation":"Straight = lacio."}}},{"id":"7","question":"Your friend has a new haircut. You say:","options":["It looks great on you!","It looks great with you!","It sees great on you!","It''s looking you great!"],"correct":0,"explanation":"\"It looks great on you\" is the natural compliment.","translations":{"es":{"question":"Tu amiga tiene un corte nuevo. Le dices:","explanation":"«It looks great on you» es el cumplido natural."}}},{"id":"8","question":"In the US, the usual tip at a hair salon is…","options":["50%","nothing","15–20%","one dollar"],"correct":2,"explanation":"15–20% is common.","translations":{"es":{"question":"En Estados Unidos, la propina habitual en una estética es…","explanation":"Lo común es 15–20%."}}}]}'::jsonb, 3),
  ('story', 'A New Look', '{"text":"Laura and Mike''s wedding anniversary is next week, and there''s going to be a family dinner. Carmen wants a new look. She goes to a hair salon near the beach. \"Hi! I''d like to get my hair cut.\" \"Sure! How would you like it today?\" says Jasmine, the hairdresser. Carmen shows her a photo. \"Like this, please. A little shorter, but not too short. And can you cover my gray hair?\" \"Of course. Would you like some highlights too?\" Carmen hesitates. \"Highlights? At my age?\" Jasmine smiles. \"Age is just a number!\" One hour later, Carmen looks in the mirror. Her hair is shorter, darker and soft. \"I love it!\" At the dinner, Laura opens her eyes wide. \"Mom! You look amazing! Did you get your hair done?\" Mike adds, \"It looks great on you, Carmen.\" Leo says, \"Grandma, you look like a movie star.\"","translation":"El aniversario de bodas de Laura y Mike es la próxima semana y va a haber una cena familiar. Carmen quiere un cambio de look. Va a una estética cerca de la playa. «¡Hola! Quisiera cortarme el pelo.» «¡Claro! ¿Cómo lo quiere hoy?», dice Jasmine, la estilista. Carmen le enseña una foto. «Así, por favor. Un poco más corto, pero no demasiado. ¿Y me puede cubrir las canas?» «Por supuesto. ¿Quiere también unas luces?» Carmen duda. «¿Luces? ¿A mi edad?» Jasmine sonríe. «¡La edad es solo un número!» Una hora después, Carmen se mira al espejo. Tiene el pelo más corto, más oscuro y suave. «¡Me encanta!» En la cena, Laura abre mucho los ojos. «¡Mamá! ¡Te ves increíble! ¿Fuiste a la estética?» Mike agrega: «Se te ve muy bien, suegra.» Leo dice: «Abuela, pareces estrella de cine.»","translations":{"es":"El aniversario de bodas de Laura y Mike es la próxima semana y va a haber una cena familiar. Carmen quiere un cambio de look. Va a una estética cerca de la playa. «¡Hola! Quisiera cortarme el pelo.» «¡Claro! ¿Cómo lo quiere hoy?», dice Jasmine, la estilista. Carmen le enseña una foto. «Así, por favor. Un poco más corto, pero no demasiado. ¿Y me puede cubrir las canas?» «Por supuesto. ¿Quiere también unas luces?» Carmen duda. «¿Luces? ¿A mi edad?» Jasmine sonríe. «¡La edad es solo un número!» Una hora después, Carmen se mira al espejo. Tiene el pelo más corto, más oscuro y suave. «¡Me encanta!» En la cena, Laura abre mucho los ojos. «¡Mamá! ¡Te ves increíble! ¿Fuiste a la estética?» Mike agrega: «Se te ve muy bien, suegra.» Leo dice: «Abuela, pareces estrella de cine.»"},"highlighted_words":["hair salon","I''d like to get my hair cut","How would you like it today","hairdresser","A little shorter, but not too short","cover my gray hair","highlights","mirror","I love it","Did you get your hair done","It looks great on you"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","would","like","to","get","my","hair","cut"],"translation":"Quisiera cortarme el pelo.","translations":{"es":"Quisiera cortarme el pelo."}},{"words":["Just","a","trim","please"],"translation":"Solo despuntar, por favor.","translations":{"es":"Solo despuntar, por favor."}},{"words":["I","would","like","it","a","little","shorter"],"translation":"Lo quiero un poco más corto.","translations":{"es":"Lo quiero un poco más corto."}},{"words":["Can","you","cover","my","gray","hair"],"translation":"¿Me puede cubrir las canas?","translations":{"es":"¿Me puede cubrir las canas?"}},{"words":["It","looks","great","on","you"],"translation":"Se te ve muy bien.","translations":{"es":"Se te ve muy bien."}},{"words":["She","had","her","nails","done","yesterday"],"translation":"Ayer se hizo las uñas.","translations":{"es":"Ayer se hizo las uñas."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"No muy corto, por favor","translations":{"es":"No muy corto, por favor"},"answer":"Not too short, please"},{"prompt":"Como en esta foto","translations":{"es":"Como en esta foto"},"answer":"Like in this photo"},{"prompt":"Me encanta","translations":{"es":"Me encanta"},"answer":"I love it"},{"prompt":"¿Me puede cortar el fleco?","translations":{"es":"¿Me puede cortar el fleco?"},"answer":"Could you cut my bangs"},{"prompt":"Quiero cortarme el pelo","translations":{"es":"Quiero cortarme el pelo"},"answer":"I want to get my hair cut"},{"prompt":"Se te ve muy bien","translations":{"es":"Se te ve muy bien"},"answer":"It looks great on you"}]}'::jsonb, 6)
) as v(type, title, content, ord);

