insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"jewelry store","translation":"joyería","translations":{"es":"joyería"}},{"id":"2","word":"jeweler","translation":"joyero","translations":{"es":"joyero"}},{"id":"3","word":"necklace","translation":"collar","translations":{"es":"collar"}},{"id":"4","word":"bracelet","translation":"pulsera","translations":{"es":"pulsera"}},{"id":"5","word":"earrings","translation":"aretes","translations":{"es":"aretes"}},{"id":"6","word":"ring","translation":"anillo","translations":{"es":"anillo"}},{"id":"7","word":"watch","translation":"reloj (de pulsera)","translations":{"es":"reloj (de pulsera)"}},{"id":"8","word":"chain","translation":"cadena","translations":{"es":"cadena"}},{"id":"9","word":"pendant","translation":"dije / colgante","translations":{"es":"dije / colgante"}},{"id":"10","word":"gold","translation":"oro","translations":{"es":"oro"}},{"id":"11","word":"silver","translation":"plata","translations":{"es":"plata"}},{"id":"12","word":"diamond","translation":"diamante","translations":{"es":"diamante"}},{"id":"13","word":"pearl","translation":"perla","translations":{"es":"perla"}},{"id":"14","word":"engrave","translation":"grabar","translations":{"es":"grabar"}},{"id":"15","word":"warranty","translation":"garantía","translations":{"es":"garantía"}},{"id":"16","word":"repair","translation":"reparar / reparación","translations":{"es":"reparar / reparación"}},{"id":"17","word":"who / that / which / where","translation":"que / quien / el cual / donde","translations":{"es":"que / quien / el cual / donde"}}],"grammar":[{"structure":"who (people)","example":"The woman who works here is very kind.","en":"Relative clauses with \"who\"","es":"Oraciones de relativo con «who» (personas)"},{"structure":"that / which (things)","example":"I want the necklace that has a small heart.","en":"Relative clauses with \"that\" and \"which\"","es":"Oraciones de relativo con «that» y «which» (cosas)"},{"structure":"where (places)","example":"This is the store where I bought my ring.","en":"Relative clauses with \"where\"","es":"Oraciones de relativo con «where» (lugares)"},{"structure":"made of + material","example":"It''s made of silver.","en":"Talking about materials","es":"Hablar de materiales"},{"structure":"Can I try it on? / Does it come in…?","example":"Does it come in gold?","en":"Asking about jewelry","es":"Preguntar por joyas"}],"tips":[{"en":"\"Who\" is for people, \"that\" for people or things, \"which\" for things. In conversation, \"that\" is the most common.","es":"«Who» es para personas, «that» para personas o cosas, «which» para cosas. Al hablar, «that» es el más común."},{"en":"Relative clauses join two ideas: \"I have a friend. She lives in Texas.\" → \"I have a friend who lives in Texas.\"","es":"Las oraciones de relativo unen dos ideas: «I have a friend. She lives in Texas.» → «I have a friend who lives in Texas.»"},{"en":"\"Engraving\" is writing names or dates on jewelry. Many stores do it for free.","es":"«Engraving» es grabar nombres o fechas en una joya. Muchas tiendas lo hacen gratis."},{"en":"Ask for a \"certificate\" or \"warranty\" when you buy expensive jewelry.","es":"Pide un «certificate» o «warranty» (garantía) cuando compres joyas caras."},{"en":"\"Made of\" tells the material: made of gold, made of silver, made of wood.","es":"«Made of» indica el material: made of gold, made of silver, made of wood."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I''m looking for a necklace for my daughter.","translation":"Busco un collar para mi hija.","translations":{"es":"Busco un collar para mi hija."}},{"phrase":"Is it made of gold or silver?","translation":"¿Es de oro o de plata?","translations":{"es":"¿Es de oro o de plata?"}},{"phrase":"Does it come in gold?","translation":"¿Viene en oro?","translations":{"es":"¿Viene en oro?"}},{"phrase":"Can I try on the earrings?","translation":"¿Me puedo probar los aretes?","translations":{"es":"¿Me puedo probar los aretes?"}},{"phrase":"I want the one that has a heart.","translation":"Quiero el que tiene un corazón.","translations":{"es":"Quiero el que tiene un corazón."}},{"phrase":"Can you engrave a name on it?","translation":"¿Le puede grabar un nombre?","translations":{"es":"¿Le puede grabar un nombre?"}},{"phrase":"Does it have a warranty?","translation":"¿Tiene garantía?","translations":{"es":"¿Tiene garantía?"}},{"phrase":"Can you repair this watch?","translation":"¿Me puede reparar este reloj?","translations":{"es":"¿Me puede reparar este reloj?"}},{"phrase":"This is the store where I bought my ring.","translation":"Esta es la tienda donde compré mi anillo.","translations":{"es":"Esta es la tienda donde compré mi anillo."}},{"phrase":"The man who helped me was very kind.","translation":"El señor que me atendió fue muy amable.","translations":{"es":"El señor que me atendió fue muy amable."}},{"phrase":"It''s a gift for someone who is very special.","translation":"Es un regalo para alguien muy especial.","translations":{"es":"Es un regalo para alguien muy especial."}},{"phrase":"Could you wrap it, please?","translation":"¿Me lo envuelve, por favor?","translations":{"es":"¿Me lo envuelve, por favor?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"The woman ___ works here is very kind.\"","options":["what","where","which","who"],"correct":3,"explanation":"People → who.","translations":{"es":{"question":"Completa: «The woman ___ works here is very kind.»","explanation":"Personas → who."}}},{"id":"2","question":"Complete: \"I want the necklace ___ has a heart.\"","options":["where","what","who","that"],"correct":3,"explanation":"Things → that / which.","translations":{"es":{"question":"Completa: «I want the necklace ___ has a heart.»","explanation":"Cosas → that / which."}}},{"id":"3","question":"Complete: \"This is the store ___ I bought my ring.\"","options":["who","what","which","where"],"correct":3,"explanation":"Places → where.","translations":{"es":{"question":"Completa: «This is the store ___ I bought my ring.»","explanation":"Lugares → where."}}},{"id":"4","question":"How do you ask about the material?","options":["Is it gold made?","Is it made from of gold?","Is it make of gold?","Is it made of gold?"],"correct":3,"explanation":"made of + material.","translations":{"es":{"question":"¿Cómo preguntas por el material?","explanation":"made of + material."}}},{"id":"5","question":"Jewelry you wear on your ears is…","options":["bracelets","rings","necklaces","earrings"],"correct":3,"explanation":"Earrings = aretes.","translations":{"es":{"question":"La joya que usas en las orejas son…","explanation":"Earrings = aretes."}}},{"id":"6","question":"Writing a name on a ring is…","options":["repairing","wrapping","polishing","engraving"],"correct":3,"explanation":"Engrave = grabar.","translations":{"es":{"question":"Escribir un nombre en un anillo es…","explanation":"Engrave = grabar."}}},{"id":"7","question":"Join the sentences: \"I have a friend. She lives in Texas.\"","options":["I have a friend she who lives in Texas.","I have a friend which lives in Texas.","I have a friend where lives in Texas.","I have a friend who lives in Texas."],"correct":3,"explanation":"Person → who replaces \"she\".","translations":{"es":{"question":"Une las oraciones: «I have a friend. She lives in Texas.»","explanation":"Persona → who reemplaza a «she»."}}},{"id":"8","question":"A promise that the store will fix the product if it breaks is a…","options":["pendant","receipt","chain","warranty"],"correct":3,"explanation":"Warranty = garantía.","translations":{"es":{"question":"La promesa de que la tienda arreglará el producto si se rompe es una…","explanation":"Warranty = garantía."}}}]}'::jsonb, 3),
  ('story', 'A Heart for Laura', '{"text":"For Laura and Mike''s anniversary, Carmen wants to give her daughter something special. She goes to a small jewelry store downtown. The jeweler is an old man who has worked there for forty years. \"I''m looking for a necklace for my daughter,\" says Carmen. He shows her many chains, pendants and earrings. Carmen points. \"I like the one that has a small heart. Is it made of gold?\" \"No, it''s made of silver. But it comes in gold too.\" \"Silver is perfect. Can you engrave something on the back?\" \"Of course. What would you like?\" Carmen thinks. \"Laura, the daughter who gave me a new life.\" The jeweler looks at her. \"That''s beautiful.\" A week later, at dinner, Laura opens the box and reads the words. She can''t speak; she just hugs her mother. Leo whispers to Mike: \"Dad, why is everybody crying? It''s a happy day!\"","translation":"Para el aniversario de Laura y Mike, Carmen quiere regalarle a su hija algo especial. Va a una joyería pequeña del centro. El joyero es un señor mayor que lleva cuarenta años trabajando ahí. «Busco un collar para mi hija», dice Carmen. Él le muestra muchas cadenas, dijes y aretes. Carmen señala. «Me gusta el que tiene un corazoncito. ¿Es de oro?» «No, es de plata. Pero también viene en oro.» «La plata es perfecta. ¿Le puede grabar algo atrás?» «Claro. ¿Qué le gustaría?» Carmen piensa. «Laura, la hija que me dio una vida nueva.» El joyero la mira. «Qué bonito.» Una semana después, en la cena, Laura abre la caja y lee las palabras. No puede hablar; solo abraza a su madre. Leo le susurra a Mike: «Papá, ¿por qué todos lloran? ¡Es un día feliz!»","translations":{"es":"Para el aniversario de Laura y Mike, Carmen quiere regalarle a su hija algo especial. Va a una joyería pequeña del centro. El joyero es un señor mayor que lleva cuarenta años trabajando ahí. «Busco un collar para mi hija», dice Carmen. Él le muestra muchas cadenas, dijes y aretes. Carmen señala. «Me gusta el que tiene un corazoncito. ¿Es de oro?» «No, es de plata. Pero también viene en oro.» «La plata es perfecta. ¿Le puede grabar algo atrás?» «Claro. ¿Qué le gustaría?» Carmen piensa. «Laura, la hija que me dio una vida nueva.» El joyero la mira. «Qué bonito.» Una semana después, en la cena, Laura abre la caja y lee las palabras. No puede hablar; solo abraza a su madre. Leo le susurra a Mike: «Papá, ¿por qué todos lloran? ¡Es un día feliz!»"},"highlighted_words":["jewelry store","jeweler","who has worked there","necklace","chains","pendants","earrings","the one that has a small heart","made of gold","silver","it comes in gold","engrave","the daughter who gave me a new life"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","am","looking","for","a","necklace"],"translation":"Busco un collar.","translations":{"es":"Busco un collar."}},{"words":["The","man","who","helped","me","was","very","kind"],"translation":"El señor que me atendió fue muy amable.","translations":{"es":"El señor que me atendió fue muy amable."}},{"words":["I","want","the","one","that","has","a","heart"],"translation":"Quiero el que tiene un corazón.","translations":{"es":"Quiero el que tiene un corazón."}},{"words":["This","is","the","store","where","I","bought","my","ring"],"translation":"Esta es la tienda donde compré mi anillo.","translations":{"es":"Esta es la tienda donde compré mi anillo."}},{"words":["Is","it","made","of","gold","or","silver"],"translation":"¿Es de oro o de plata?","translations":{"es":"¿Es de oro o de plata?"}},{"words":["Can","you","engrave","a","name","on","it"],"translation":"¿Le puede grabar un nombre?","translations":{"es":"¿Le puede grabar un nombre?"}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Es de plata","translations":{"es":"Es de plata"},"answer":"It is made of silver"},{"prompt":"¿Tiene garantía?","translations":{"es":"¿Tiene garantía?"},"answer":"Does it have a warranty"},{"prompt":"¿Me puedo probar los aretes?","translations":{"es":"¿Me puedo probar los aretes?"},"answer":"Can I try on the earrings"},{"prompt":"Tengo una amiga que vive en Texas","translations":{"es":"Tengo una amiga que vive en Texas"},"answer":"I have a friend who lives in Texas"},{"prompt":"¿Me puede reparar este reloj?","translations":{"es":"¿Me puede reparar este reloj?"},"answer":"Can you repair this watch"},{"prompt":"¿Me lo envuelve, por favor?","translations":{"es":"¿Me lo envuelve, por favor?"},"answer":"Could you wrap it, please"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 58: The car
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-58', 'The car', '🚙', 'El auto', 58, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"steering wheel","translation":"volante","translations":{"es":"volante"}},{"id":"2","word":"brakes","translation":"frenos","translations":{"es":"frenos"}},{"id":"3","word":"tire","translation":"llanta","translations":{"es":"llanta"}},{"id":"4","word":"flat tire","translation":"llanta ponchada","translations":{"es":"llanta ponchada"}},{"id":"5","word":"engine","translation":"motor","translations":{"es":"motor"}},{"id":"6","word":"headlights","translation":"faros","translations":{"es":"faros"}},{"id":"7","word":"windshield","translation":"parabrisas","translations":{"es":"parabrisas"}},{"id":"8","word":"seat belt","translation":"cinturón de seguridad","translations":{"es":"cinturón de seguridad"}},{"id":"9","word":"break down","translation":"descomponerse","translations":{"es":"descomponerse"}},{"id":"10","word":"tow truck","translation":"grúa","translations":{"es":"grúa"}},{"id":"11","word":"mechanic","translation":"mecánico","translations":{"es":"mecánico"}},{"id":"12","word":"oil change","translation":"cambio de aceite","translations":{"es":"cambio de aceite"}},{"id":"13","word":"driving test","translation":"examen de manejo","translations":{"es":"examen de manejo"}},{"id":"14","word":"stop sign","translation":"señal de alto","translations":{"es":"señal de alto"}},{"id":"15","word":"park","translation":"estacionar","translations":{"es":"estacionar"}},{"id":"16","word":"would","translation":"(condicional) -ría","translations":{"es":"(condicional) -ría"}},{"id":"17","word":"if I were you","translation":"yo que tú / si yo fuera tú","translations":{"es":"yo que tú / si yo fuera tú"}}],"grammar":[{"structure":"If + past simple, … would + verb","example":"If I had a car, I would drive to the beach every day.","en":"Second conditional: imaginary situations","es":"Segundo condicional: situaciones imaginarias"},{"structure":"If I were you, I would…","example":"If I were you, I would take a driving class.","en":"Giving advice with the second conditional","es":"Dar consejos con el segundo condicional"},{"structure":"would / wouldn''t","example":"I wouldn''t drive on the highway at night.","en":"Imaginary results","es":"Resultados imaginarios"},{"structure":"What would you do if…?","example":"What would you do if your car broke down?","en":"Hypothetical questions","es":"Preguntas hipotéticas"},{"structure":"first vs. second conditional","example":"If it rains, I''ll stay. / If I won the lottery, I''d travel.","en":"Real vs. imaginary","es":"Real vs. imaginario"}],"tips":[{"en":"The second conditional uses the past, but it''s about the present or future: \"If I had time\" = si tuviera tiempo.","es":"El segundo condicional usa el pasado, pero habla del presente o futuro: «If I had time» = si tuviera tiempo."},{"en":"\"If I were you\" (with \"were\") is the classic way to give advice.","es":"«If I were you» (con «were») es la forma clásica de dar consejos (yo que tú…)."},{"en":"To drive in California you need a California license after you become a resident. Classes and tests can be taken in Spanish.","es":"Para manejar en California necesitas licencia de California cuando ya eres residente. Las clases y los exámenes se pueden hacer en español."},{"en":"\"Flat tire\" = llanta ponchada. \"Break down\" = descomponerse (el auto).","es":"«Flat tire» = llanta ponchada. «Break down» = descomponerse (el auto)."},{"en":"In the US, you must stop completely at a STOP sign, even if no one is coming.","es":"En Estados Unidos hay que detenerse por completo en un alto (STOP), aunque no venga nadie."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"If I had a car, I''d visit you more often.","translation":"Si tuviera auto, te visitaría más seguido.","translations":{"es":"Si tuviera auto, te visitaría más seguido."}},{"phrase":"If I were you, I''d take a driving class.","translation":"Yo que tú, tomaría una clase de manejo.","translations":{"es":"Yo que tú, tomaría una clase de manejo."}},{"phrase":"What would you do if you won the lottery?","translation":"¿Qué harías si ganaras la lotería?","translations":{"es":"¿Qué harías si ganaras la lotería?"}},{"phrase":"My car broke down.","translation":"Se me descompuso el auto.","translations":{"es":"Se me descompuso el auto."}},{"phrase":"I have a flat tire.","translation":"Tengo una llanta ponchada.","translations":{"es":"Tengo una llanta ponchada."}},{"phrase":"Can you call a tow truck?","translation":"¿Puede llamar a una grúa?","translations":{"es":"¿Puede llamar a una grúa?"}},{"phrase":"The brakes make a strange noise.","translation":"Los frenos hacen un ruido raro.","translations":{"es":"Los frenos hacen un ruido raro."}},{"phrase":"It needs an oil change.","translation":"Necesita cambio de aceite.","translations":{"es":"Necesita cambio de aceite."}},{"phrase":"Fasten your seat belt.","translation":"Abróchate el cinturón.","translations":{"es":"Abróchate el cinturón."}},{"phrase":"Where can I park?","translation":"¿Dónde me puedo estacionar?","translations":{"es":"¿Dónde me puedo estacionar?"}},{"phrase":"I passed my driving test!","translation":"¡Pasé mi examen de manejo!","translations":{"es":"¡Pasé mi examen de manejo!"}},{"phrase":"I wouldn''t drive at night.","translation":"Yo no manejaría de noche.","translations":{"es":"Yo no manejaría de noche."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"If I ___ a car, I would drive to the beach.\"","options":["had","have","would have","will have"],"correct":0,"explanation":"Second conditional: If + past simple.","translations":{"es":{"question":"Completa: «If I ___ a car, I would drive to the beach.»","explanation":"Segundo condicional: If + pasado simple."}}},{"id":"2","question":"Complete: \"If I won the lottery, I ___ travel the world.\"","options":["will","would","did","am"],"correct":1,"explanation":"Result: would + verb.","translations":{"es":{"question":"Completa: «If I won the lottery, I ___ travel the world.»","explanation":"Resultado: would + verbo."}}},{"id":"3","question":"How do you give advice with the second conditional?","options":["If I am you, I rest.","If I were you, I''d rest.","If you were me, you rest.","If I was you, I will rest."],"correct":1,"explanation":"If I were you, I''d + verb.","translations":{"es":{"question":"¿Cómo das un consejo con el segundo condicional?","explanation":"If I were you, I''d + verbo."}}},{"id":"4","question":"Which sentence is imaginary (not real now)?","options":["If I have time, I''ll help.","If it rains, I''ll stay home.","If I lived in Paris, I''d speak French.","If you call me, I''ll answer."],"correct":2,"explanation":"Second conditional = imaginary.","translations":{"es":{"question":"¿Qué oración es imaginaria (no es real ahora)?","explanation":"Segundo condicional = imaginario."}}},{"id":"5","question":"A tire with no air is a…","options":["broken tire","dead tire","flat tire","empty wheel"],"correct":2,"explanation":"Flat tire = llanta ponchada.","translations":{"es":{"question":"Una llanta sin aire es una…","explanation":"Flat tire = llanta ponchada."}}},{"id":"6","question":"The truck that takes your broken car is a…","options":["fire truck","trailer","tow truck","pickup"],"correct":2,"explanation":"Tow truck = grúa.","translations":{"es":{"question":"El camión que se lleva tu auto descompuesto es una…","explanation":"Tow truck = grúa."}}},{"id":"7","question":"\"My car broke down\" means…","options":["My car is clean.","My car is new.","My car stopped working.","I sold my car."],"correct":2,"explanation":"Break down = descomponerse.","translations":{"es":{"question":"«My car broke down» significa…","explanation":"Break down = descomponerse."}}},{"id":"8","question":"At a STOP sign in the US, you must…","options":["stop completely","only stop at night","slow down a little","honk"],"correct":0,"explanation":"A full stop is required.","translations":{"es":{"question":"En un alto (STOP) en Estados Unidos, debes…","explanation":"Es obligatorio detenerse por completo."}}}]}'::jsonb, 3),
  ('story', 'Behind the Wheel', '{"text":"Carmen takes the bus everywhere, but sometimes it''s difficult. \"If I had a car, I would visit Leo more often,\" she tells Mike. Mike is a mechanic, so he has an idea. \"If I were you, I''d take a driving class. And I have an old car that I don''t use.\" \"Me? Driving in California? At my age?\" \"Why not? You can take the test in Spanish.\" Carmen thinks about it for a week. Then she signs up. The first class is scary. The teacher says, \"Hands on the steering wheel. Check the mirrors. Stop completely at the stop sign.\" One day, on a quiet street, they get a flat tire. \"What would you do if this happened and you were alone?\" asks the teacher. \"I would call Mike!\" Two months later, Carmen comes into the house with a big smile. \"I passed my driving test!\" Leo runs to her. \"Grandma, can you drive me to soccer now?\" \"Of course. But fasten your seat belt!\"","translation":"Carmen va en autobús a todas partes, pero a veces es difícil. «Si tuviera auto, visitaría a Leo más seguido», le dice a Mike. Mike es mecánico, así que tiene una idea. «Yo que usted, tomaría una clase de manejo. Y tengo un auto viejo que no uso.» «¿Yo? ¿Manejar en California? ¿A mi edad?» «¿Por qué no? Puede hacer el examen en español.» Carmen lo piensa una semana. Luego se inscribe. La primera clase da miedo. El maestro dice: «Las manos en el volante. Revise los espejos. Deténgase por completo en el alto.» Un día, en una calle tranquila, se les poncha una llanta. «¿Qué haría si le pasara esto y estuviera sola?», pregunta el maestro. «¡Llamaría a Mike!» Dos meses después, Carmen entra a la casa con una gran sonrisa. «¡Pasé mi examen de manejo!» Leo corre hacia ella. «Abuela, ¿ahora me puedes llevar al fútbol?» «Claro. ¡Pero abróchate el cinturón!»","translations":{"es":"Carmen va en autobús a todas partes, pero a veces es difícil. «Si tuviera auto, visitaría a Leo más seguido», le dice a Mike. Mike es mecánico, así que tiene una idea. «Yo que usted, tomaría una clase de manejo. Y tengo un auto viejo que no uso.» «¿Yo? ¿Manejar en California? ¿A mi edad?» «¿Por qué no? Puede hacer el examen en español.» Carmen lo piensa una semana. Luego se inscribe. La primera clase da miedo. El maestro dice: «Las manos en el volante. Revise los espejos. Deténgase por completo en el alto.» Un día, en una calle tranquila, se les poncha una llanta. «¿Qué haría si le pasara esto y estuviera sola?», pregunta el maestro. «¡Llamaría a Mike!» Dos meses después, Carmen entra a la casa con una gran sonrisa. «¡Pasé mi examen de manejo!» Leo corre hacia ella. «Abuela, ¿ahora me puedes llevar al fútbol?» «Claro. ¡Pero abróchate el cinturón!»"},"highlighted_words":["If I had a car, I would visit","mechanic","If I were you, I''d take a driving class","steering wheel","mirrors","stop sign","flat tire","What would you do if","I would call Mike","I passed my driving test","fasten your seat belt"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["If","I","had","a","car","I","would","visit","you"],"translation":"Si tuviera auto, te visitaría.","translations":{"es":"Si tuviera auto, te visitaría."}},{"words":["If","I","were","you","I","would","rest"],"translation":"Yo que tú, descansaría.","translations":{"es":"Yo que tú, descansaría."}},{"words":["What","would","you","do","if","you","won","the","lottery"],"translation":"¿Qué harías si ganaras la lotería?","translations":{"es":"¿Qué harías si ganaras la lotería?"}},{"words":["My","car","broke","down","on","the","highway"],"translation":"Se me descompuso el auto en la carretera.","translations":{"es":"Se me descompuso el auto en la carretera."}},{"words":["I","have","a","flat","tire"],"translation":"Tengo una llanta ponchada.","translations":{"es":"Tengo una llanta ponchada."}},{"words":["I","passed","my","driving","test"],"translation":"Pasé mi examen de manejo.","translations":{"es":"Pasé mi examen de manejo."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Se me descompuso el auto","translations":{"es":"Se me descompuso el auto"},"answer":"My car broke down"},{"prompt":"Yo que tú, lo llamaría","translations":{"es":"Yo que tú, lo llamaría"},"answer":"If I were you, I would call him"},{"prompt":"Si tuviera tiempo, te ayudaría","translations":{"es":"Si tuviera tiempo, te ayudaría"},"answer":"If I had time, I would help you"},{"prompt":"¿Dónde me puedo estacionar?","translations":{"es":"¿Dónde me puedo estacionar?"},"answer":"Where can I park"},{"prompt":"Necesita cambio de aceite","translations":{"es":"Necesita cambio de aceite"},"answer":"It needs an oil change"},{"prompt":"Abróchate el cinturón","translations":{"es":"Abróchate el cinturón"},"answer":"Fasten your seat belt"}]}'::jsonb, 6)
) as v(type, title, content, ord);

