insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"lawyer","translation":"abogado","translations":{"es":"abogado"}},{"id":"2","word":"legal aid","translation":"asesoría legal gratuita","translations":{"es":"asesoría legal gratuita"}},{"id":"3","word":"paperwork","translation":"trámites / papeleo","translations":{"es":"trámites / papeleo"}},{"id":"4","word":"document","translation":"documento","translations":{"es":"documento"}},{"id":"5","word":"form","translation":"formulario","translations":{"es":"formulario"}},{"id":"6","word":"fill out","translation":"llenar (un formulario)","translations":{"es":"llenar (un formulario)"}},{"id":"7","word":"signature","translation":"firma","translations":{"es":"firma"}},{"id":"8","word":"copy","translation":"copia","translations":{"es":"copia"}},{"id":"9","word":"deadline","translation":"fecha límite","translations":{"es":"fecha límite"}},{"id":"10","word":"appointment letter","translation":"carta de cita","translations":{"es":"carta de cita"}},{"id":"11","word":"residency","translation":"residencia","translations":{"es":"residencia"}},{"id":"12","word":"notary public","translation":"notario público (no es abogado)","translations":{"es":"notario público (no es abogado)"}},{"id":"13","word":"advice","translation":"consejo / asesoría","translations":{"es":"consejo / asesoría"}},{"id":"14","word":"said","translation":"dijo","translations":{"es":"dijo"}},{"id":"15","word":"told","translation":"le dijo / me dijo","translations":{"es":"le dijo / me dijo"}},{"id":"16","word":"asked","translation":"preguntó / pidió","translations":{"es":"preguntó / pidió"}},{"id":"17","word":"approved","translation":"aprobado","translations":{"es":"aprobado"}}],"grammar":[{"structure":"said (that) + past","example":"She said, \"I am tired.\" → She said (that) she was tired.","en":"Reported speech with \"said\"","es":"Estilo indirecto con «said»"},{"structure":"told + person + (that)…","example":"The lawyer told me (that) the papers were ready.","en":"Reported speech with \"told\"","es":"Estilo indirecto con «told»"},{"structure":"will → would, can → could","example":"\"I will call you.\" → He said he would call me.","en":"Changes in reported speech","es":"Cambios en el estilo indirecto"},{"structure":"asked if / asked me to…","example":"She asked if I had my passport. She asked me to sign here.","en":"Reporting questions and requests","es":"Reportar preguntas y pedidos"},{"structure":"need to + fill out / sign / bring","example":"You need to fill out this form and sign it.","en":"Paperwork verbs","es":"Verbos de trámites"}],"tips":[{"en":"\"Say\" doesn''t need a person: \"She said that…\". \"Tell\" needs one: \"She told me that…\".","es":"«Say» no necesita persona: «She said that…». «Tell» sí la necesita: «She told me that…»."},{"en":"Many cities have free legal aid and community centers that help immigrants with paperwork in Spanish.","es":"Muchas ciudades tienen asesoría legal gratuita y centros comunitarios que ayudan a los inmigrantes con trámites en español."},{"en":"Be careful with \"notarios\": in the US a \"notary public\" is NOT a lawyer and can''t give legal advice.","es":"Cuidado con los «notarios»: en Estados Unidos un «notary public» NO es abogado y no puede dar asesoría legal."},{"en":"Always keep copies of every document you sign or send.","es":"Guarda siempre copias de cada documento que firmes o envíes."},{"en":"\"Fill out a form\" = llenar un formulario. \"Sign\" = firmar. \"Date\" = poner la fecha.","es":"«Fill out a form» = llenar un formulario. «Sign» = firmar. «Date» = poner la fecha."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"I need help with some paperwork.","translation":"Necesito ayuda con unos trámites.","translations":{"es":"Necesito ayuda con unos trámites."}},{"phrase":"Do you offer free legal aid?","translation":"¿Ofrecen asesoría legal gratuita?","translations":{"es":"¿Ofrecen asesoría legal gratuita?"}},{"phrase":"What documents do I need to bring?","translation":"¿Qué documentos necesito traer?","translations":{"es":"¿Qué documentos necesito traer?"}},{"phrase":"Please fill out this form.","translation":"Por favor, llene este formulario.","translations":{"es":"Por favor, llene este formulario."}},{"phrase":"Sign here and here.","translation":"Firme aquí y aquí.","translations":{"es":"Firme aquí y aquí."}},{"phrase":"When is the deadline?","translation":"¿Cuál es la fecha límite?","translations":{"es":"¿Cuál es la fecha límite?"}},{"phrase":"Can I have a copy, please?","translation":"¿Me da una copia, por favor?","translations":{"es":"¿Me da una copia, por favor?"}},{"phrase":"The lawyer said it was simple.","translation":"La abogada dijo que era sencillo.","translations":{"es":"La abogada dijo que era sencillo."}},{"phrase":"She told me to wait for a letter.","translation":"Me dijo que esperara una carta.","translations":{"es":"Me dijo que esperara una carta."}},{"phrase":"He asked if I had my passport.","translation":"Me preguntó si tenía mi pasaporte.","translations":{"es":"Me preguntó si tenía mi pasaporte."}},{"phrase":"My application was approved!","translation":"¡Aprobaron mi solicitud!","translations":{"es":"¡Aprobaron mi solicitud!"}},{"phrase":"Is there someone who speaks Spanish?","translation":"¿Hay alguien que hable español?","translations":{"es":"¿Hay alguien que hable español?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Report: \"I am tired,\" Laura said.","options":["Laura said she was tired.","Laura said she is tiring.","Laura told she was tired.","Laura said I was tired."],"correct":0,"explanation":"am → was; I → she.","translations":{"es":{"question":"Repórtalo: «I am tired», dijo Laura.","explanation":"am → was; I → she."}}},{"id":"2","question":"Complete: \"The lawyer ___ me that the papers were ready.\"","options":["said","told","says","spoke"],"correct":1,"explanation":"\"Told\" + person.","translations":{"es":{"question":"Completa: «The lawyer ___ me that the papers were ready.»","explanation":"«Told» + persona."}}},{"id":"3","question":"Complete: \"She ___ that she would call me.\"","options":["told","asked me","said","talked"],"correct":2,"explanation":"\"Said\" without a person.","translations":{"es":{"question":"Completa: «She ___ that she would call me.»","explanation":"«Said» sin persona."}}},{"id":"4","question":"Report: \"I will help you,\" he said.","options":["He said I would help you.","He said he will helped me.","He said he would help me.","He told he would help."],"correct":2,"explanation":"will → would.","translations":{"es":{"question":"Repórtalo: «I will help you», dijo él.","explanation":"will → would."}}},{"id":"5","question":"Report the question: \"Do you have your passport?\"","options":["He asked do I have my passport.","He said if I had passport.","He asked if I had my passport.","He asked I had my passport?"],"correct":2,"explanation":"Yes/no questions → asked if + past.","translations":{"es":{"question":"Reporta la pregunta: «Do you have your passport?»","explanation":"Preguntas de sí/no → asked if + pasado."}}},{"id":"6","question":"In the US, a \"notary public\"…","options":["is a judge","is not a lawyer and can''t give legal advice","is a lawyer","can represent you in court"],"correct":1,"explanation":"A notary only certifies signatures.","translations":{"es":{"question":"En Estados Unidos, un «notary public»…","explanation":"Un notary solo certifica firmas."}}},{"id":"7","question":"The last day to send a document is the…","options":["deadline","copy","signature","form"],"correct":0,"explanation":"Deadline = fecha límite.","translations":{"es":{"question":"El último día para entregar un documento es la…","explanation":"Deadline = fecha límite."}}},{"id":"8","question":"\"Fill out this form\" means…","options":["llene este formulario","tire este formulario","firme este formulario","copie este formulario"],"correct":0,"explanation":"Fill out = llenar.","translations":{"es":{"question":"«Fill out this form» significa…","explanation":"Fill out = llenar."}}}]}'::jsonb, 3),
  ('story', 'The Letter', '{"text":"Carmen wants to stay in the United States near her family, so she needs to do some paperwork. Linda tells her about a community center that offers free legal aid. A lawyer named Ms. Ortiz meets her. \"What documents do I need to bring?\" asks Carmen. Ms. Ortiz gives her a list and a form. \"Please fill out this form. Sign here and here. The deadline is next month.\" At dinner, Laura asks, \"What did the lawyer say?\" \"She said it was a long process, but not difficult. She told me to keep copies of everything. And she asked if I had a letter from you.\" \"Of course I''ll write it, Mom.\" Months pass. One afternoon, a letter arrives. Carmen''s hands are shaking. Leo reads it aloud slowly: \"Your application… has been… approved.\" Carmen sits down and cries. Leo hugs her. \"Grandma, you said you would stay. Now it''s true!\"","translation":"Carmen quiere quedarse en Estados Unidos cerca de su familia, así que necesita hacer unos trámites. Linda le habla de un centro comunitario que ofrece asesoría legal gratuita. La atiende una abogada, la licenciada Ortiz. «¿Qué documentos necesito traer?», pregunta Carmen. La licenciada Ortiz le da una lista y un formulario. «Por favor, llene este formulario. Firme aquí y aquí. La fecha límite es el próximo mes.» En la cena, Laura pregunta: «¿Qué dijo la abogada?» «Dijo que era un proceso largo, pero no difícil. Me dijo que guardara copias de todo. Y me preguntó si tenía una carta tuya.» «Claro que te la escribo, mamá.» Pasan los meses. Una tarde llega una carta. A Carmen le tiemblan las manos. Leo la lee en voz alta, despacio: «Su solicitud… ha sido… aprobada.» Carmen se sienta y llora. Leo la abraza. «Abuela, dijiste que te ibas a quedar. ¡Ahora es verdad!»","translations":{"es":"Carmen quiere quedarse en Estados Unidos cerca de su familia, así que necesita hacer unos trámites. Linda le habla de un centro comunitario que ofrece asesoría legal gratuita. La atiende una abogada, la licenciada Ortiz. «¿Qué documentos necesito traer?», pregunta Carmen. La licenciada Ortiz le da una lista y un formulario. «Por favor, llene este formulario. Firme aquí y aquí. La fecha límite es el próximo mes.» En la cena, Laura pregunta: «¿Qué dijo la abogada?» «Dijo que era un proceso largo, pero no difícil. Me dijo que guardara copias de todo. Y me preguntó si tenía una carta tuya.» «Claro que te la escribo, mamá.» Pasan los meses. Una tarde llega una carta. A Carmen le tiemblan las manos. Leo la lee en voz alta, despacio: «Su solicitud… ha sido… aprobada.» Carmen se sienta y llora. Leo la abraza. «Abuela, dijiste que te ibas a quedar. ¡Ahora es verdad!»"},"highlighted_words":["paperwork","legal aid","lawyer","What documents do I need to bring","fill out this form","Sign here","deadline","She said it was","She told me to keep copies","she asked if I had","approved","you said you would stay"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","need","help","with","some","paperwork"],"translation":"Necesito ayuda con unos trámites.","translations":{"es":"Necesito ayuda con unos trámites."}},{"words":["Please","fill","out","this","form"],"translation":"Por favor, llene este formulario.","translations":{"es":"Por favor, llene este formulario."}},{"words":["She","said","that","it","was","simple"],"translation":"Dijo que era sencillo.","translations":{"es":"Dijo que era sencillo."}},{"words":["The","lawyer","told","me","to","wait"],"translation":"La abogada me dijo que esperara.","translations":{"es":"La abogada me dijo que esperara."}},{"words":["He","asked","if","I","had","my","passport"],"translation":"Me preguntó si tenía mi pasaporte.","translations":{"es":"Me preguntó si tenía mi pasaporte."}},{"words":["My","application","was","approved"],"translation":"Aprobaron mi solicitud.","translations":{"es":"Aprobaron mi solicitud."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Necesito ayuda con unos trámites","translations":{"es":"Necesito ayuda con unos trámites"},"answer":"I need help with some paperwork"},{"prompt":"Firme aquí, por favor","translations":{"es":"Firme aquí, por favor"},"answer":"Sign here, please"},{"prompt":"¿Cuál es la fecha límite?","translations":{"es":"¿Cuál es la fecha límite?"},"answer":"When is the deadline"},{"prompt":"Dijo que estaba cansada","translations":{"es":"Dijo que estaba cansada"},"answer":"She said she was tired"},{"prompt":"Me dijo que lo llamara","translations":{"es":"Me dijo que lo llamara"},"answer":"He told me to call him"},{"prompt":"¿Me da una copia?","translations":{"es":"¿Me da una copia?"},"answer":"Can I have a copy"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- 60: Daily routines
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('en', 'lesson-60', 'Daily routines', '☀️', 'La rutina diaria', 60, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulary', '{"items":[{"id":"1","word":"routine","translation":"rutina","translations":{"es":"rutina"}},{"id":"2","word":"wake up","translation":"despertarse","translations":{"es":"despertarse"}},{"id":"3","word":"get up","translation":"levantarse","translations":{"es":"levantarse"}},{"id":"4","word":"take a shower","translation":"bañarse / ducharse","translations":{"es":"bañarse / ducharse"}},{"id":"5","word":"get dressed","translation":"vestirse","translations":{"es":"vestirse"}},{"id":"6","word":"brush your teeth","translation":"lavarse los dientes","translations":{"es":"lavarse los dientes"}},{"id":"7","word":"have breakfast","translation":"desayunar","translations":{"es":"desayunar"}},{"id":"8","word":"go to work","translation":"ir a trabajar","translations":{"es":"ir a trabajar"}},{"id":"9","word":"take a nap","translation":"tomar una siesta","translations":{"es":"tomar una siesta"}},{"id":"10","word":"do the dishes","translation":"lavar los trastes","translations":{"es":"lavar los trastes"}},{"id":"11","word":"relax","translation":"relajarse","translations":{"es":"relajarse"}},{"id":"12","word":"go to bed","translation":"acostarse","translations":{"es":"acostarse"}},{"id":"13","word":"used to","translation":"solía / antes","translations":{"es":"solía / antes"}},{"id":"14","word":"every morning","translation":"todas las mañanas","translations":{"es":"todas las mañanas"}},{"id":"15","word":"on weekends","translation":"los fines de semana","translations":{"es":"los fines de semana"}},{"id":"16","word":"habit","translation":"hábito","translations":{"es":"hábito"}},{"id":"17","word":"busy","translation":"ocupado","translations":{"es":"ocupado"}}],"grammar":[{"structure":"present simple + frequency (review)","example":"I usually get up at six. I always have coffee first.","en":"Routines and habits","es":"Rutinas y hábitos"},{"structure":"get up / wake up / go to bed","example":"I wake up at six and get up at six fifteen.","en":"Routine verbs","es":"Verbos de la rutina"},{"structure":"before / after + verb-ing","example":"After having breakfast, I walk on the beach.","en":"Ordering actions","es":"Ordenar acciones"},{"structure":"used to + verb","example":"I used to live in Guadalajara. Now I live in San Diego.","en":"Past habits that changed","es":"Hábitos del pasado que cambiaron (solía)"},{"structure":"Tenses together (review)","example":"I have lived here for a year, I''m learning English, and I''ll keep studying.","en":"Present perfect, present continuous and future together","es":"Presente perfecto, presente continuo y futuro juntos"}],"tips":[{"en":"\"Wake up\" = abrir los ojos; \"get up\" = levantarse de la cama.","es":"«Wake up» = despertarse; «get up» = levantarse de la cama."},{"en":"\"Used to\" talks about the past that is no longer true: \"I used to be shy.\"","es":"«Used to» habla de un pasado que ya no es así: «I used to be shy» (antes era tímida)."},{"en":"After \"before\" and \"after\", use verb + -ing: \"before going to bed\".","es":"Después de «before» y «after», usa verbo + -ing: «before going to bed»."},{"en":"A routine is the best friend of learning: ten minutes of English every day is better than two hours once a week.","es":"La rutina es la mejor amiga del aprendizaje: diez minutos de inglés diarios valen más que dos horas una vez por semana."},{"en":"You''ve finished the course — congratulations! Keep practicing with movies, songs, MarIA and your neighbors.","es":"Terminaste el curso, ¡felicidades! Sigue practicando con películas, canciones, MarIA y tus vecinos."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"What time do you usually get up?","translation":"¿A qué hora te levantas normalmente?","translations":{"es":"¿A qué hora te levantas normalmente?"}},{"phrase":"I wake up at six every morning.","translation":"Me despierto a las seis todas las mañanas.","translations":{"es":"Me despierto a las seis todas las mañanas."}},{"phrase":"First, I have a cup of coffee.","translation":"Primero, me tomo una taza de café.","translations":{"es":"Primero, me tomo una taza de café."}},{"phrase":"After breakfast, I walk on the beach.","translation":"Después del desayuno, camino por la playa.","translations":{"es":"Después del desayuno, camino por la playa."}},{"phrase":"I work at the bakery on Saturdays.","translation":"Trabajo en la panadería los sábados.","translations":{"es":"Trabajo en la panadería los sábados."}},{"phrase":"I take a nap after lunch.","translation":"Tomo una siesta después de comer.","translations":{"es":"Tomo una siesta después de comer."}},{"phrase":"I practice English every day.","translation":"Practico inglés todos los días.","translations":{"es":"Practico inglés todos los días."}},{"phrase":"I used to be very shy.","translation":"Antes era muy tímida.","translations":{"es":"Antes era muy tímida."}},{"phrase":"Before going to bed, I read.","translation":"Antes de acostarme, leo.","translations":{"es":"Antes de acostarme, leo."}},{"phrase":"I go to bed at ten.","translation":"Me acuesto a las diez.","translations":{"es":"Me acuesto a las diez."}},{"phrase":"My days are busy but happy.","translation":"Mis días son ocupados pero felices.","translations":{"es":"Mis días son ocupados pero felices."}},{"phrase":"I''ll never stop learning.","translation":"Nunca voy a dejar de aprender.","translations":{"es":"Nunca voy a dejar de aprender."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"\"Wake up\" or \"get up\": what do you do first?","options":["take a nap","go to bed","get up","wake up"],"correct":3,"explanation":"First you wake up (open your eyes), then you get up (leave the bed).","translations":{"es":{"question":"«Wake up» o «get up»: ¿qué haces primero?","explanation":"Primero te despiertas (wake up) y luego te levantas (get up)."}}},{"id":"2","question":"Complete: \"After ___ breakfast, I walk on the beach.\"","options":["had","to have","have","having"],"correct":3,"explanation":"After + verb-ing.","translations":{"es":{"question":"Completa: «After ___ breakfast, I walk on the beach.»","explanation":"After + verbo-ing."}}},{"id":"3","question":"Complete: \"I ___ live in Guadalajara. Now I live in San Diego.\"","options":["use to","was use to","am used","used to"],"correct":3,"explanation":"Past habit that changed → used to.","translations":{"es":{"question":"Completa: «I ___ live in Guadalajara. Now I live in San Diego.»","explanation":"Hábito pasado que cambió → used to."}}},{"id":"4","question":"Choose the correct position of \"usually\".","options":["I go to bed usually ten.","I go usually to bed at ten.","Usually I to bed go at ten.","I usually go to bed at ten."],"correct":3,"explanation":"Frequency adverb before the main verb.","translations":{"es":{"question":"Elige la posición correcta de «usually».","explanation":"El adverbio de frecuencia va antes del verbo principal."}}},{"id":"5","question":"Which sentence uses the present perfect?","options":["I will live here.","I lived here last year.","I am living here now.","I have lived here for a year."],"correct":3,"explanation":"have + past participle = present perfect.","translations":{"es":{"question":"¿Qué oración usa el presente perfecto?","explanation":"have + participio = presente perfecto."}}},{"id":"6","question":"A short sleep in the afternoon is a…","options":["routine","shower","habit","nap"],"correct":3,"explanation":"Take a nap = tomar una siesta.","translations":{"es":{"question":"Un sueño corto en la tarde es una…","explanation":"Take a nap = tomar una siesta."}}},{"id":"7","question":"Complete: \"Leo ___ his teeth every night.\"","options":["brushs","brush","brushing","brushes"],"correct":3,"explanation":"He + verb ending in -sh → -es: brushes.","translations":{"es":{"question":"Completa: «Leo ___ his teeth every night.»","explanation":"He + verbo terminado en -sh → -es: brushes."}}},{"id":"8","question":"What''s the best habit for learning a language?","options":["Only before a trip","Two hours once a month","Never speaking","A little practice every day"],"correct":3,"explanation":"Daily practice works best.","translations":{"es":{"question":"¿Cuál es el mejor hábito para aprender un idioma?","explanation":"La práctica diaria es lo que mejor funciona."}}}]}'::jsonb, 3),
  ('story', 'One Year Later', '{"text":"It has been a year since Carmen arrived in San Diego. Her days are busy now. She wakes up at six every morning, but she gets up at six fifteen — first, a cup of coffee on her balcony. After having breakfast, she walks on the beach with Linda. On Mondays and Wednesdays she goes to English class, and on Thursdays she meets the Coffee Club. On Saturdays she works at the bakery, where her tamales always sell out. In the afternoon she usually picks up Leo from school — now she drives! After lunch she sometimes takes a short nap. In the evening she video calls her sisters in Guadalajara. Before going to bed, she reads a book in English, ten pages every night. \"I used to be very shy,\" she wrote in her last homework. \"I used to think English was impossible. Now I have friends, a job and a new home. I''m still learning, and I will never stop.\"","translation":"Ha pasado un año desde que Carmen llegó a San Diego. Ahora sus días están llenos. Se despierta a las seis todas las mañanas, pero se levanta a las seis y cuarto: primero, una taza de café en su balcón. Después de desayunar, camina por la playa con Linda. Los lunes y miércoles va a su clase de inglés, y los jueves se reúne con el Club del Café. Los sábados trabaja en la panadería, donde sus tamales siempre se acaban. En la tarde normalmente recoge a Leo de la escuela: ¡ahora maneja! Después de comer a veces toma una siestita. En la noche hace videollamada con sus hermanas en Guadalajara. Antes de acostarse, lee un libro en inglés, diez páginas cada noche. «Antes era muy tímida», escribió en su última tarea. «Antes pensaba que el inglés era imposible. Ahora tengo amigos, un trabajo y un hogar nuevo. Sigo aprendiendo, y nunca voy a dejar de hacerlo.»","translations":{"es":"Ha pasado un año desde que Carmen llegó a San Diego. Ahora sus días están llenos. Se despierta a las seis todas las mañanas, pero se levanta a las seis y cuarto: primero, una taza de café en su balcón. Después de desayunar, camina por la playa con Linda. Los lunes y miércoles va a su clase de inglés, y los jueves se reúne con el Club del Café. Los sábados trabaja en la panadería, donde sus tamales siempre se acaban. En la tarde normalmente recoge a Leo de la escuela: ¡ahora maneja! Después de comer a veces toma una siestita. En la noche hace videollamada con sus hermanas en Guadalajara. Antes de acostarse, lee un libro en inglés, diez páginas cada noche. «Antes era muy tímida», escribió en su última tarea. «Antes pensaba que el inglés era imposible. Ahora tengo amigos, un trabajo y un hogar nuevo. Sigo aprendiendo, y nunca voy a dejar de hacerlo.»"},"highlighted_words":["It has been a year","She wakes up at six every morning","gets up","After having breakfast","goes to English class","usually picks up","takes a short nap","Before going to bed","I used to be very shy","I''m still learning","I will never stop"]}'::jsonb, 4),
  ('arrange', 'Build sentences', '{"sentences":[{"words":["I","wake","up","at","six","every","morning"],"translation":"Me despierto a las seis todas las mañanas.","translations":{"es":"Me despierto a las seis todas las mañanas."}},{"words":["After","breakfast","I","walk","on","the","beach"],"translation":"Después del desayuno camino por la playa.","translations":{"es":"Después del desayuno camino por la playa."}},{"words":["I","usually","take","a","nap","after","lunch"],"translation":"Normalmente tomo una siesta después de comer.","translations":{"es":"Normalmente tomo una siesta después de comer."}},{"words":["I","used","to","be","very","shy"],"translation":"Antes era muy tímida.","translations":{"es":"Antes era muy tímida."}},{"words":["Before","going","to","bed","I","read","a","book"],"translation":"Antes de acostarme leo un libro.","translations":{"es":"Antes de acostarme leo un libro."}},{"words":["I","will","never","stop","learning"],"translation":"Nunca voy a dejar de aprender.","translations":{"es":"Nunca voy a dejar de aprender."}}]}'::jsonb, 5),
  ('translate', 'Translate into English', '{"items":[{"prompt":"Me levanto a las seis","translations":{"es":"Me levanto a las seis"},"answer":"I get up at six"},{"prompt":"Me acuesto a las diez","translations":{"es":"Me acuesto a las diez"},"answer":"I go to bed at ten"},{"prompt":"Practico inglés todos los días","translations":{"es":"Practico inglés todos los días"},"answer":"I practice English every day"},{"prompt":"Antes vivía en México","translations":{"es":"Antes vivía en México"},"answer":"I used to live in Mexico"},{"prompt":"Me baño en la mañana","translations":{"es":"Me baño en la mañana"},"answer":"I take a shower in the morning"},{"prompt":"Mis días son ocupados pero felices","translations":{"es":"Mis días son ocupados pero felices"},"answer":"My days are busy but happy"}]}'::jsonb, 6)
) as v(type, title, content, ord);
